window.DATA = {"built_at": "2026-11-22", "problems": {"scale_ingestion": "Ingesting at scale", "realtime": "Real-time & streaming", "cdc_sync": "CDC & data sync", "late_data": "Late & out-of-order data", "cost": "Cost reduction", "performance": "Query performance", "quality": "Data quality & incidents", "lineage_catalog": "Discovery, lineage & catalog", "platform": "Building a data platform", "migration": "Migration & modernization", "modeling": "Data modeling & metrics", "governance_privacy": "Governance, privacy & compliance", "ml_data": "Data for ML & AI", "storage_formats": "Storage & table formats"}, "post_types": ["case_study", "postmortem", "deep_dive", "open_source", "opinion", "announcement"], "questions": [{"q": "Design a real-time analytics pipeline", "problems": ["realtime", "scale_ingestion"]}, {"q": "Ingest billions of events a day from apps and services", "problems": ["scale_ingestion"]}, {"q": "Keep a warehouse in sync with production databases", "problems": ["cdc_sync"]}, {"q": "Handle late-arriving data and backfills", "problems": ["late_data"]}, {"q": "Design a data lake / lakehouse", "problems": ["storage_formats"]}, {"q": "Cut the cost of a data platform", "problems": ["cost"]}, {"q": "Make slow analytical queries fast", "problems": ["performance"]}, {"q": "Catch bad data before it reaches dashboards", "problems": ["quality"]}, {"q": "Build a self-serve data platform for many teams", "problems": ["platform", "lineage_catalog"]}, {"q": "Migrate off a legacy data system without downtime", "problems": ["migration"]}, {"q": "Design a metrics layer / experimentation data model", "problems": ["modeling"]}, {"q": "Delete user data on request (GDPR) across the platform", "problems": ["governance_privacy"]}, {"q": "Design a feature store or training-data pipeline", "problems": ["ml_data"]}], "posts": [{"url": "https://stripe.com/blog/ledger-stripe-system-for-tracking-and-validating-money-movement", "company": "Stripe", "industry": "fintech", "title": "Ledger: Stripe\u2019s system for tracking and validating money movement", "date": "2024-02-16", "primary_problem": "quality", "problems": ["lineage_catalog", "late_data"], "post_type": "case_study", "level": "advanced", "stack": ["Presto"], "scale": "5 billion events per day; 300 million transactions over Black Friday to Cyber Monday; $18.6B total payment volume", "key_decisions": ["Model all producer systems as an immutable, double-entry fund-flow log so correctness can be checked by zero-balance clearing accounts, trading off upfront modeling effort for a general proof-of-correctness approach", "Use explicit completeness checks and statistical arrival-time models per account type, accepting that ledger may diverge from upstream data and must be reconciled", "Fix bad data by reverting and reprocessing events through a reviewed, two-phase migration tool with DQ impact reports, since the ledger cannot be mutated in place"], "summary": "Stripe describes Ledger, an immutable double-entry event log that models payment-system behavior as fund flows between accounts, and a Data Quality platform built on it that scores clearing, timeliness and completeness. The post emphasizes alerting, tracing ownership of issues to root causes, and reviewing bulk data corrections as a CI-like process.", "interview_angle": "How would you design a system that proves financial data is complete and correct across many upstream systems with different latencies, without allowing in-place mutation of the record?", "score": 1.7799, "hn_points": 135, "hn_comments": 39}, {"url": "https://netflixtechblog.com/data-movement-in-netflix-studio-via-data-mesh-3fddcceb1059", "company": "Netflix", "industry": "media", "title": "Data Movement in Netflix Studio via Data Mesh", "date": "2021-07-26", "primary_problem": "cdc_sync", "problems": ["platform", "storage_formats"], "post_type": "case_study", "level": "advanced", "stack": ["Data Mesh", "Iceberg", "MySQL", "PostgreSQL", "GraphQL", "Trino", "Delta Lake", "Node.js", "Jenkins", "Titus", "Airtable", "Google Sheets", "Tableau"], "scale": "Genesis powers 240+ trackers; Lego peaked at 300+ trackers", "key_decisions": ["Configuration-driven pipelines via a managed CDC platform cut lead time for new pipelines but limit custom logic to the provided processor types", "Consumer-schema compatibility checks auto-propagate additive changes and pause pipelines on breaking changes, trading automation for safety", "Append-only Iceberg sink with a read-side latest-record view and daily compaction keeps writes simple but adds view cost and maintenance jobs"], "summary": "Netflix Studio moved from batch ETL and hand-built streaming jobs to Data Mesh, a configuration-driven CDC pipeline platform that enriches change events via GraphQL and lands them in Iceberg tables. The post also covers end-to-end schema evolution, hourly audits with synthetic heartbeat events, and Genesis, a YAML-based semantic layer that generates SQL for hundreds of partner trackers.", "interview_angle": "How would you design a CDC pipeline platform that supports schema evolution without breaking downstream consumers, and how would you verify end-to-end completeness between source databases and the warehouse?", "score": 1.7604, "hn_points": 15, "hn_comments": 0}, {"url": "https://netflixtechblog.com/incremental-processing-using-netflix-maestro-and-apache-iceberg-b8ba072ddeeb", "company": "Netflix", "industry": "media", "title": "Incremental Processing using Netflix Maestro and Apache Iceberg", "date": "2023-11-20", "primary_problem": "cost", "problems": ["late_data", "platform"], "post_type": "case_study", "level": "advanced", "stack": ["Netflix Maestro", "Iceberg", "Spark"], "scale": "Pipeline runtime cut from about 10.5 hours to about 1 hour (~10% of resources); over 80% cost reduction in the sample two-stage pipeline", "key_decisions": ["Capture changes as a lightweight Iceberg table that references new data files from snapshots instead of copying data, trading some metadata complexity for very low storage and copy cost", "Replace lookback-window reprocessing with change-driven incremental processing, which cuts compute but requires users to rewrite writes as MERGE INTO and handle change ranges", "Build IPS as an extension of the existing Maestro orchestrator (new trigger and step type) rather than a standalone library, which lowers onboarding cost across thousands of workflows but ties the feature to Maestro"], "summary": "Netflix describes Incremental Processing Service (IPS), built on Maestro and Iceberg, which processes only new or changed data rather than rerunning lookback windows. The approach uses lightweight change-capture tables that reference new Iceberg data files without copying them, and reports roughly a 90% drop in pipeline runtime on a sample two-stage pipeline.", "interview_angle": "How would you replace a fixed lookback window that reprocesses 14 days of data with an approach that only handles late-arriving changes, and what table-level mechanism would you use to identify those changes without duplicating storage?", "score": 1.7346, "hn_points": 1, "hn_comments": 0}, {"url": "https://eng.lyft.com/druid-deprecation-and-clickhouse-adoption-at-lyft-120af37651fd", "company": "Lyft", "industry": "mobility", "title": "Druid Deprecation and ClickHouse Adoption at Lyft", "date": "2023-11-29", "primary_problem": "migration", "problems": ["realtime", "performance"], "post_type": "case_study", "level": "advanced", "stack": ["ClickHouse", "Druid", "Kafka", "Flink", "Kinesis", "Trino", "Airflow", "S3", "Amazon MSK", "ZooKeeper", "Altinity Kubernetes Operator", "Mode"], "scale": "Up to 2 billion records/day from Kafka; ~600 million rows/day from Flink; more than 25 TB read and written monthly", "key_decisions": ["Consolidated sub-second analytics onto ClickHouse and sunset Druid, trading the migration effort for lower operational complexity and cost", "Chose ClickHouse's destination-side deduplication over stream-side dedupe to support per-entity mutability windows, at the cost of running a different engine", "Used a tiered traffic shift (1% to 100%) with row-count and latency comparisons to de-risk migration, at the cost of running both systems in parallel for longer"], "summary": "Lyft explains why it retired Apache Druid for sub-second analytics and consolidated on ClickHouse, citing operational burden, a steep onboarding curve, and cost. The post covers the benchmarking, staged migration, ClickHouse query tuning with sorting keys, skip indices and projections, and the ingestion pipelines and pain points that followed.", "interview_angle": "How would you choose between two sub-second OLAP engines for near real-time analytics, and how would you migrate live dashboards without breaking latency or correctness SLAs?", "score": 1.7171, "hn_points": 7, "hn_comments": 0}, {"url": "https://netflixtechblog.com/optimizing-data-warehouse-storage-7b94a48fdcbe", "company": "Netflix", "industry": "media", "title": "Optimizing data warehouse storage", "date": "2020-12-21", "primary_problem": "storage_formats", "problems": ["cost", "performance"], "post_type": "case_study", "level": "advanced", "stack": ["Iceberg", "S3", "Spark", "Redis", "Java", "Spring Boot", "Keystone", "Hive"], "scale": "Hundreds of PB in the warehouse on S3, with petabytes ingested daily", "key_decisions": ["Event-driven, just-in-time optimization instead of periodic blind runs: saves scan cost but requires maintaining per-partition state and rolling stats", "Partition Entropy (MSE of file sizes) as an early-pruning signal: skips work on healthy partitions but uses approximate formulas that must handle deletes and edge cases", "Minimum-replacement packing (Knuth/Plass for ordered files, First Fit Decreasing otherwise): limits rewritten files at the cost of extra algorithmic complexity and run time"], "summary": "Netflix describes AutoOptimize, a service that automatically merges, sorts and compacts files in its Iceberg-based warehouse as data lands, split into a decision service and a pool of Spark actors. The file-merge deep dive explains how partition file-size entropy, minimum-replacement bin packing and a weighted reliable priority queue cut scans, rewrites and compute while shrinking file counts.", "interview_angle": "How would you design an automatic small-file compaction service for a petabyte-scale lakehouse that avoids rescanning unchanged partitions and prioritizes tables across tenants?", "score": 1.716, "hn_points": 4, "hn_comments": 1}, {"url": "https://netflixtechblog.com/behind-the-scenes-evolving-netflixs-ads-event-pipeline-for-live-part-ii-826ebf9ad9fb", "company": "Netflix", "industry": "media", "title": "Behind the Scenes: Evolving Netflix\u2019s Ads Event Pipeline for Live \u2014 Part II", "date": "2026-08-17", "primary_problem": "realtime", "problems": ["scale_ingestion", "late_data"], "post_type": "case_study", "level": "advanced", "stack": ["Flink", "Spark", "Maestro", "Kafka", "Netflix Key-Value store"], "scale": "Hundreds of thousands of events per second in a single AWS region during load tests; live audiences up to tens of millions of concurrent viewers", "key_decisions": ["Replaced the synchronous Metadata Registry write on the ad-serving path with a fire-and-forget log plus a Flink streaming join, removing a critical-path dependency at the cost of holding state and handling unmatched events", "Chose a 60-minute in-stream join window and routed the long tail of late events to an hourly Spark batch backfill, bounding Flink state at the cost of a second recovery path", "Routed cross-region client events to the region owning the serving response instead of replicating all responses globally, trading extra hops for lower storage and compute cost"], "summary": "Netflix rebuilt its Ads Event Publisher as a stateful Flink job that joins client ad events to serving responses in-stream, removing a synchronous database write from ad serving. The post covers the 60-minute join window, cross-region routing, in-stream dedup, a late-event batch recovery path, and a parallel-run cutover audited against the legacy pipeline.", "interview_angle": "How would you redesign an ad-event enrichment path so that a must-succeed lookup write is no longer on the serving critical path, and how would you handle events that arrive after the join window?", "score": 1.7051, "hn_points": 0, "hn_comments": 0}, {"url": "https://shopify.engineering/lessons-learned-apache-airflow-scale", "company": "Shopify", "industry": "ecommerce", "title": "Lessons Learned From Running Apache Airflow at Scale", "date": "2022-05-23", "primary_problem": "platform", "problems": ["scale_ingestion", "cost"], "post_type": "case_study", "level": "advanced", "stack": ["Airflow", "Kubernetes", "Celery", "MySQL", "Google Cloud Storage", "NFS", "GCSFuse", "dbt", "Iceberg", "Trino"], "scale": "10,000+ DAGs in largest environment; ~400 concurrent tasks; 150,000+ runs per day", "key_decisions": ["Mounting an in-cluster NFS volume synced from GCS instead of GCSFuse: faster file reads for schedulers and workers, but adds a sync component to operate", "Enforcing a 28-day metadata retention policy: keeps the metadata database and UI responsive and upgrades faster, but removes long-range history such as long backfills", "Using deterministic randomized cron schedules for generated DAGs: smooths load spikes, but restricts the set of possible schedule intervals"], "summary": "Shopify describes operating Airflow at very high DAG and run volume on Kubernetes, covering slow DAG file access on cloud storage, metadata bloat, ownership tracing, and resource contention. They share the fixes they built: an NFS layer synced from GCS, a retention job, manifest-based DAG policies, randomized schedules, and pools, priority weights and isolated Celery queues.", "interview_angle": "How would you design a multi-tenant orchestration platform for thousands of pipelines so that one team's workload cannot starve others, and how would you keep the scheduler and metadata database healthy as history grows?", "score": 1.7041, "hn_points": 285, "hn_comments": 182}, {"url": "https://netflixtechblog.com/the-evolution-of-cassandra-data-movement-at-netflix-6e13329c80a1", "company": "Netflix", "industry": "media", "title": "The Evolution of Cassandra Data Movement at Netflix", "date": "2026-05-18", "primary_problem": "migration", "problems": ["cdc_sync", "cost"], "post_type": "case_study", "level": "advanced", "stack": ["Cassandra", "Iceberg", "Spark", "S3", "Maestro", "Cassandra Analytics"], "scale": "About 1,200 data movements per day, roughly 3 PB transferred from Cassandra to Iceberg", "key_decisions": ["Read SSTable backups directly from S3 instead of composing metadata from several services, trading the old multi-system view for a single source of truth tied to backup storage", "Build a layered engine that outputs standard Spark DataFrames so each data abstraction gets its own connector, at the cost of more shared-layer complexity", "Migrate via shadow runs with row-level set comparison plus a Maestro Decider step that falls back to the legacy connector, keeping downstream contracts identical at the cost of running two systems in parallel"], "summary": "Netflix replaced its Casspactor engine, which moved Cassandra data into Iceberg, with a layered engine that reads backups straight from S3 and produces Spark DataFrames. The migration was made low-risk by shadow-running both systems with row-level diffs, adding dashboards and alerts, and using a Decider step in Maestro that falls back to the legacy connector on failure.", "interview_angle": "How would you move a mission-critical bulk export pipeline off a legacy system with zero downstream changes? Discuss shadow validation, row-level reconciliation, and a controlled fallback path.", "score": 1.6925, "hn_points": 0, "hn_comments": 0}, {"url": "https://tech.instacart.com/adopting-dbt-as-the-data-transformation-tool-at-instacart-36c74bc407df", "company": "Instacart", "industry": "marketplace", "title": "Adopting dbt as the Data Transformation Tool at Instacart", "date": "2023-08-17", "primary_problem": "platform", "problems": ["cost", "modeling"], "post_type": "case_study", "level": "intermediate", "stack": ["dbt", "Airflow", "Snowflake", "Buildkite", "S3", "Amazon ECS", "Terraform", "GitHub", "Amundsen"], "scale": "5 million tables and 10+ PB in Snowflake; 3000+ dbt models, 400 DAGs, 100 users", "key_decisions": ["Standardize on dbt plus Airflow instead of three fragmented transformation tools: gains consistency and modularity but requires a year of migration and onboarding effort.", "Generate Airflow DAGs from dbt manifest.json: per-model task granularity enables parallelism and cheaper retries, at the cost of depending on dbt metadata and a custom DAG generator.", "Route dbt models to tiered Snowflake warehouses by size, defaulting to medium: cuts cold-start overhead (20-40% extra cost) but shifts tuning responsibility onto model owners who must reassign heavy queries."], "summary": "Instacart standardized its Snowflake transformation layer on dbt orchestrated by Airflow, replacing three-plus legacy tools. The post explains per-team dbt targets across local, dev and prod, DAG generation from manifest.json, query tagging for cost attribution, and routing models to tiered warehouses to cut cold-start and spill costs.", "interview_angle": "How would you design a self-serve transformation platform for hundreds of teams on a cloud warehouse, covering environment isolation, dependency-driven orchestration, and per-workload compute sizing to control cost?", "score": 1.6836, "hn_points": 0, "hn_comments": 0}, {"url": "https://engineering.grab.com/enabling-near-realtime-data-analytics", "company": "Grab", "industry": "mobility", "title": "Enabling near real-time data analytics on the data lake", "date": "2024-02-23", "primary_problem": "storage_formats", "problems": ["realtime", "cdc_sync"], "post_type": "case_study", "level": "advanced", "stack": ["Hudi", "Flink", "Spark", "Kafka", "Parquet", "Avro", "Debezium", "Flink CDC", "MySQL", "Hive metastore", "Trino"], "scale": "Minute-level data latency; 10-15 minute checkpoint interval for low-throughput sources", "key_decisions": ["Merge On Read for high-throughput Kafka sources: fast Avro log writes with Spark compaction into Parquet, at the cost of extra compaction components to run", "Copy On Write for low-throughput sources: simpler single-writer design, but latency is bounded by the checkpoint interval (about 10-15 minutes)", "Bucket Index over Flink State Index: simpler and stateless, but bucket count is fixed and caps Flink parallelism, so consistent hashing is planned"], "summary": "Grab moved its data lake from Hive/Parquet batch refreshes to Apache Hudi so analysts see data within minutes rather than after scheduled batch delays. The design picks MOR or COW tables per source type, with Flink ingesting Kafka and MySQL binlog streams and Spark handling compaction.", "interview_angle": "How would you make a data lake support frequent upserts and minute-level freshness from both Kafka and CDC sources, and how do you choose between MOR and COW tables and the index type?", "score": 1.6692, "hn_points": 1, "hn_comments": 0}, {"url": "https://engineering.grab.com/experimentation-platform-data-pipeline", "company": "Grab", "industry": "mobility", "title": "A Lean and Scalable Data Pipeline to Capture Large Scale Events and Support Experimentation Platform", "date": "2019-01-16", "primary_problem": "scale_ingestion", "problems": ["storage_formats", "platform"], "post_type": "case_study", "level": "advanced", "stack": ["Spark", "Hive", "Airflow", "AWS EMR", "S3", "Apache ORC", "Parquet", "YARN", "HDFS", "Terraform", "GitLab CI", "Datadog", "Ganglia"], "scale": "About 400,000 events/sec ingested; over 2.5 PB processed in 3.5 months; 500 TB stored on S3", "key_decisions": ["Partition data by event type and ingestion time so queries scan only needed slices, trading some write-side complexity for cheaper reads and easier reprocessing and ACLs", "Use ORC with Snappy instead of Parquet, gaining 12.5% to 80% performance and storage benefits in tests, but relying on a less universally supported format", "Run independent EMR clusters per availability zone orchestrated by Airflow with retries and canary rollouts, accepting duplicated infrastructure cost in exchange for high availability since EMR lacked hot standby"], "summary": "Grab describes a batch event pipeline built on Spark, Hive, and Airflow that ingests hundreds of thousands of events per second into S3 for its experimentation platform. The post focuses on partitioning by event type and time, choosing ORC, achieving availability across EMR clusters per zone, and fixing master and HDFS bottlenecks at scale.", "interview_angle": "How would you design a lean batch pipeline that ingests hundreds of thousands of events per second into a data lake while serving analysts, data scientists, and experimentation workloads with different latency SLAs and high availability on managed clusters?", "score": 1.6665, "hn_points": 1, "hn_comments": 0}, {"url": "https://netflixtechblog.com/making-failure-diagnosis-reliable-with-pensive-ai-6b0811a1c015", "company": "Netflix", "industry": "media", "title": "Making Failure Diagnosis Reliable with Pensive AI", "date": "2026-10-26", "primary_problem": "quality", "problems": ["platform", "cost"], "post_type": "case_study", "level": "advanced", "stack": ["Titus", "Spark", "Trino", "Druid", "Maestro", "Data Portal", "GraphQL", "WebSocket", "S3", "Braintrust", "Java", "Slack", "MCP"], "scale": "~100,000 workload failures on peak days; ~7 million job-failure classifications over three months", "key_decisions": ["Use an LLM only to pick start and end line numbers in numbered logs, so output stays short and displayed text comes straight from the source log; trade-off is the model can still pick a wrong span.", "Run error extraction always-on at low latency and cost, while full AI debugging runs on demand and is cached per step attempt; trade-off is that unopened failures get no deep diagnosis and cache entries expire after 90 days.", "Archive logs to S3 without overwrite so evals are repeatable, and gate merges and promotions on inclusion and precision thresholds; trade-off is extra storage and evaluation pipeline maintenance."], "summary": "Netflix extended its Pensive failure-diagnosis system with AI that extracts relevant error spans from workload logs and offers on-demand root-cause debugging, covering failures that rule-based extraction previously labeled unknown. The post covers the bounded extraction design, a backward-compatible data contract, cached and streamed debugging responses, and evaluation harnesses wired into CI and production.", "interview_angle": "How would you add LLM-based log triage to a data platform with about 100k daily job failures while keeping latency under a hard timeout, controlling inference cost, and keeping results reproducible and evaluable?", "score": 1.6664, "hn_points": 2, "hn_comments": 0}, {"url": "https://engineering.grab.com/data-mesh-part-2-the-foundational-tools-behind-certification", "company": "Grab", "industry": "mobility", "title": "Data Mesh at Grab (Part II): The foundational tools behind certification", "date": "2026-04-30", "primary_problem": "quality", "problems": ["lineage_catalog", "governance_privacy"], "post_type": "case_study", "level": "advanced", "stack": ["DataHub", "Kafka", "Airflow", "Temporal", "Hive", "GraphQL", "Slack"], "scale": "Hundreds of thousands of datasets, streams, attributes and metrics; P80 dataset count down over 58% in one year", "key_decisions": ["Build certification as an event-driven engine on DataHub Actions so state updates continuously, at the cost of more moving parts than a manual checklist", "Trigger data-quality tests on pipeline completion via Lighthouse events instead of cron alignment, trading extra integration with pipeline monitoring for fewer false-positive freshness alerts", "Store only references (identifier and version) to rules in the Data Contract Registry, keeping contracts lightweight and avoiding config drift, but requiring resolution calls to rule-owning systems"], "summary": "Grab describes three internal platforms that make its data mesh certification work: Hubble (a DataHub-based catalog with an event-driven certification engine), Genchi (data quality observability), and a Data Contract Registry holding versioned producer-consumer contracts. The post explains how pipeline-completion events drive test runs and how contracts link to enforceable health endpoints.", "interview_angle": "How would you design a certification system for a data mesh so that dataset trust state updates automatically as upstream quality, ownership and contracts change?", "score": 1.6641, "hn_points": 0, "hn_comments": 0}, {"url": "https://monzo.com/blog/how-we-use-incremental-modelling-to-handle-billions-of-events-every-day", "company": "Monzo", "industry": "fintech", "title": "How we use incremental modelling to handle billions of events every day", "date": "2024-05-29", "primary_problem": "cost", "problems": ["performance", "late_data"], "post_type": "case_study", "level": "intermediate", "stack": ["dbt", "BigQuery", "Looker", "Jinja"], "scale": ">3 billion events per day, >3000 microservices", "key_decisions": ["Use incremental dbt materialisations so each run processes only new data, trading extra modelling complexity for roughly 80% faster runs and about 60% lower BigQuery cost", "Generate base event models and custom materialisations automatically, which standardises incremental logic but means maintaining in-house tooling inside an extended dbt", "Schedule weekend full refreshes and lookback windows to correct drift from late or out-of-order events, accepting periodic extra compute spend for reliability"], "summary": "Monzo describes how it runs incremental dbt models over billions of daily analytics events in BigQuery to cut landing times and costs. The post covers code generation, custom materialisations for slowly changing dimensions, blue-green reconciliation, and scheduled full refreshes that correct drift from late-arriving events.", "interview_angle": "How would you keep an incremental pipeline correct when events arrive late or out of order, and when would you pay for periodic full rebuilds to correct drift?", "score": 1.6594, "hn_points": 0, "hn_comments": 0}, {"url": "https://monzo.com/blog/2021/10/14/an-introduction-to-monzos-data-stack", "company": "Monzo", "industry": "fintech", "title": "An introduction to Monzo's data stack", "date": "2021-10-14", "primary_problem": "platform", "problems": ["performance", "cost"], "post_type": "case_study", "level": "intermediate", "stack": ["Kafka", "NSQ", "BigQuery", "dbt", "Looker", "Airflow", "Fivetran", "Google Cloud Composer", "Google Cloud Storage", "Cassandra", "Sanic", "GitHub", "Docker", "Feast", "DataHub", "Amundsen", "Marquez"], "scale": "Over 4700 dbt models, ~600k lines of SQL, some BigQuery tables ~60 TB rebuilt daily", "key_decisions": ["Streaming backend events via a shared firehose into append-only BigQuery tables with a payload column, trading schema enforcement for flexibility and JSON extraction later", "Forking dbt in 2019 and running it in a Docker container for fast feature delivery, trading upstream-merge maintenance for speed; plan to refactor into plugins and upgrade", "Using a dbt upstream-prod feature to read unchanged upstream tables from production, cutting dev build cost and time, at the expense of custom tooling to maintain"], "summary": "Monzo describes its modern data stack: backend events flow through Kafka and NSQ into BigQuery, are modelled with a heavily customised dbt project, orchestrated by Airflow, and surfaced in Looker. The post candidly covers pain points such as slow dbt runs, long CI times, weak metadata discovery and unowned Looker, along with the planned fixes.", "interview_angle": "How would you design a self-serve analytics platform for a fintech with thousands of dbt models, balancing developer speed (dev environments that reuse production upstreams) against warehouse cost and data ownership?", "score": 1.658, "hn_points": 1, "hn_comments": 0}, {"url": "https://engineering.grab.com/our-journey-to-apache-iceberg-adoption", "company": "Grab", "industry": "mobility", "title": "Scaling Grab's Data Lake: Our journey to Apache Iceberg adoption", "date": "2026-07-10", "primary_problem": "storage_formats", "problems": ["migration", "performance"], "post_type": "case_study", "level": "advanced", "stack": ["Iceberg", "Hive Metastore", "Hive Parquet", "Spark", "Trino", "S3", "Delta Lake", "Hudi", "OpenLineage", "Apache XTable"], "scale": "Petabytes of data across billions of S3 objects", "key_decisions": ["Adopt Iceberg as default table format over Hive Parquet, gaining ACID and metadata benefits but requiring incremental, priority-based migration of a lake queried by many engines", "Build UnifiedSparkCatalog that hides format differences with auto-detection and lazy catalog init, trading added catalog complexity for no prefix-based queries and seamless format migrations", "Name the catalog spark_catalog and reuse existing catalog instances, which keeps Hive DML paths and OpenLineage working but constrains how the catalog can be named and registered"], "summary": "Grab describes moving its data lake from Hive Parquet tables to Apache Iceberg to fix metastore latency, small files, and missing ACID support. They report large gains in query runtime, S3 API cost, and compute usage, and open-source a UnifiedSparkCatalog that routes Spark queries to the right format without format-specific table prefixes.", "interview_angle": "How would you migrate a multi-engine data lake from Hive tables to an open table format without breaking downstream consumers, and how would you keep table references stable across format changes?", "score": 1.6552, "hn_points": 0, "hn_comments": 0}, {"url": "https://eng.lyft.com/trino-open-source-infrastructure-upgrading-at-lyft-83f26b099fa", "company": "Lyft", "industry": "mobility", "title": "Trino: Open Source Infrastructure Upgrading at Lyft", "date": "2022-05-10", "primary_problem": "platform", "problems": ["performance", "quality"], "post_type": "postmortem", "level": "advanced", "stack": ["Trino", "Hive", "S3", "Java"], "scale": "250K queries and 50PB processed per day", "key_decisions": ["Upgrade on a six-month cadence versus tracking every community release: fewer disruptive fleet-wide upgrades but growing version debt", "Pick a release with critical features and avoid the newest build, accepting the risk of unfound regressions in exchange for stability", "Replay read-only production queries in batch mode on old and new versions to compare p50/p75/p99 wall time, trading replay fidelity for a controlled comparison"], "summary": "Lyft upgraded its company-wide Trino fleet from version 359 to 365 and found wall-time regressions introduced in 360 and 365. The team used staged testing, batch query replay, and Java profiling on coordinators to isolate a synchronized scheduler change and a slow authentication library, and both were patched upstream.", "interview_angle": "How would you safely roll out a new version of a shared query engine to a large fleet, and what tests would catch performance regressions before production users see them?", "score": 1.6538, "hn_points": 28, "hn_comments": 0}, {"url": "https://engineering.grab.com/one-click-data-ingestion-platform-with-apache-flink", "company": "Grab", "industry": "mobility", "title": "The Hugo evolution: Engineering Grab's unified, one-click data ingestion platform with Apache Flink", "date": "2026-05-22", "primary_problem": "platform", "problems": ["cdc_sync", "scale_ingestion"], "post_type": "case_study", "level": "advanced", "stack": ["Flink", "Flink CDC", "Kafka", "Kafka Connect", "Spark", "Hive", "MySQL", "Confluent Schema Registry", "Protobuf", "Avro", "Go", "S3"], "scale": "Kafka onboarding ~6 min, MySQL CDC onboarding ~3 min; new pipelines in last year exceed previous five years combined", "key_decisions": ["Replaced Kafka Connect and the Sprinkler Go S3 writer with Flink, cutting four components to two under one control plane, at the cost of migrating existing pipelines and owning Flink operations", "Read MySQL binlog directly with Flink CDC instead of routing through a Kafka hop, removing an intermediary but coupling ingestion to database binlog configuration", "Fetch Protobuf schemas dynamically from Confluent Schema Registry at startup rather than hardcoding mappings, reducing schema drift but still requiring manual restarts for schema changes"], "summary": "Grab describes Hugo, its self-service data ingestion platform, which unified previously fragmented onboarding for MySQL CDC and Kafka pipelines into a one-click workflow built on Apache Flink. The redesign retired Kafka Connect and an in-house Go S3 writer, using schema registry lookups and automated Spark compaction to bring onboarding down to minutes.", "interview_angle": "How would you design a self-service ingestion platform that onboards both CDC and Kafka sources into a data lake with automated schema handling and minimal user configuration?", "score": 1.6503, "hn_points": 0, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/how-cloudflare-analyzes-1m-dns-queries-per-second", "company": "Cloudflare", "industry": "infra", "title": "How Cloudflare analyzes 1M DNS queries per second", "date": "2017-05-10", "primary_problem": "scale_ingestion", "problems": ["performance", "storage_formats"], "post_type": "case_study", "level": "advanced", "stack": ["ClickHouse", "Kafka", "Spark", "HDFS", "Parquet", "Druid", "Superset", "Grafana", "Go", "Cap'n Proto", "ZooKeeper"], "scale": "Millions of DNS queries per second; trillions of log rows per month; ~150 bytes per log message", "key_decisions": ["Log only telemetry fields rather than full DNS payloads at the edge, cutting storage cost but losing the ability to inspect raw messages later", "Choose ClickHouse over Druid because Druid needed hundreds of nodes, accepting the cost of building ingestion tooling for a smaller community", "Use materialized views that compute aggregation states during insert, trading higher storage per row (HLL state) for flexible time resolution and dropping the separate stream processors"], "summary": "Cloudflare describes how it built DNS analytics by streaming edge query logs through Kafka into ClickHouse, which was chosen over Druid for cost reasons. The post explains how MergeTree sorting and sparse indexing shape table design, and how incremental materialized views replaced separate stream aggregation.", "interview_angle": "How would you ingest and analyze millions of events per second for both raw drill-down and fast aggregated dashboards, given that aggregating high-cardinality keys yields little row reduction?", "score": 1.648, "hn_points": 180, "hn_comments": 6}, {"url": "https://engineering.grab.com/data-mesh-at-grab-part-three", "company": "Grab", "industry": "mobility", "title": "Data Mesh at Grab (Part III): Operationalizing data reliability with automated DPIs", "date": "2026-08-28", "primary_problem": "quality", "problems": ["lineage_catalog", "platform"], "post_type": "case_study", "level": "advanced", "stack": ["Kinabalu", "Hugo", "Genchi", "Hubble", "Airflow", "Hive", "S3"], "scale": "86.9% of DPI incidents auto-resolved; more than 95% of DPIs raised automatically; automated DPI MTTR 6x faster", "key_decisions": ["Automate DPI lifecycle from contract breaches with minimal human-in-the-loop, trading some alert sensitivity for lower noise via triage and deduplication", "Use a small four-category Data Health API error taxonomy (upstream, platform, job, data) so the orchestrator stays decoupled from platform internals, at the cost of coarser diagnostics", "Auto-resolve routine failures (retries, waits, custom resolvers) with post-fix verification and escalate data corruption or code defects to humans, trading automation coverage for safety"], "summary": "Grab describes how its Kinabalu orchestrator turns certified data contract breaches into Data Production Issues (DPIs), with triage, deduplication, and ownership routing based on a shared Data Health API. It also covers Hugo's diagnosis and auto-resolution pipeline, which reports 86.9% of DPIs auto-resolved and a faster MTTR for automated DPIs.", "interview_angle": "How would you design an automated data incident workflow that detects contract breaches, routes ownership to the right team by root cause, and safely auto-heals common pipeline failures while escalating risky ones?", "score": 1.6444, "hn_points": 0, "hn_comments": 0}, {"url": "https://eng.lyft.com/wheres-my-data-a-unique-encounter-with-flink-streaming-s-kinesis-connector-6da3b11b164a", "company": "Lyft", "industry": "mobility", "title": "Where\u2019s My Data \u2014 A Unique Encounter with Flink Streaming\u2019s Kinesis Connector", "date": "2023-08-14", "primary_problem": "realtime", "problems": ["scale_ingestion", "quality"], "post_type": "postmortem", "level": "advanced", "stack": ["Flink", "Kinesis", "S3", "Kubernetes"], "scale": "80 GB/min average, parallelism 1800", "key_decisions": ["Handling idle shards by excluding them from global watermark calculation keeps alignment moving but risks watermark regressions and deadlocks when a shard stalls under throttling", "Restarting without a savepoint (hard reset) restored throughput quickly but skipped unread data and caused loss on one shard that aged out of Kinesis retention", "Splitting one large persistence job into smaller jobs and adding per-shard produce-vs-consume monitoring reduces blast radius and detects stalled shards sooner, at the cost of more jobs to operate"], "summary": "Lyft traces a recurring throughput collapse in a 1800-parallelism Flink job reading Kinesis to a deadlock in the Flink Kinesis Consumer's watermark alignment, triggered when CPU throttling moved the global watermark backward and marked one subtask idle. The fix involved upstream Flink changes, per-shard monitoring, and splitting the job, while a hard reset caused partial data loss after a shard aged out of retention.", "interview_angle": "How would you detect and prevent a silent stall in one partition of a high-parallelism streaming consumer, and what trade-offs come with restarting without state to recover?", "score": 1.643, "hn_points": 0, "hn_comments": 0}, {"url": "https://eng.lyft.com/from-big-data-to-better-data-ensuring-data-quality-with-verity-a996b49343f6", "company": "Lyft", "industry": "mobility", "title": "From Big Data to Better Data: Ensuring Data Quality with Verity", "date": "2023-10-03", "primary_problem": "quality", "problems": ["lineage_catalog", "platform"], "post_type": "case_study", "level": "advanced", "stack": ["Hive", "Kafka", "Flink", "Airflow", "Flyte", "Trino", "SQS", "DynamoDB", "PagerDuty", "Slack", "Spark"], "scale": "Millions of events per second logged; 2,500 Hive tables; 140,000 data quality validations per week; 70+ teams", "key_decisions": ["Decoupled check execution into SQS-backed Scheduler, API, Executor and Notifier services so each scales independently and a failure does not block the others, at the cost of more moving parts to operate", "Ran scheduled checks outside the orchestrator so they still alert when Airflow or Flyte is down, trading duplicated scheduling logic for reliable alerting", "Separate Check Queue and Executor per traffic group (e.g. Airflow-blocking vs CLI) for isolation, accepting extra infrastructure per group in exchange for protecting blocking checks from noisy traffic"], "summary": "Lyft describes Verity, an in-house data quality platform that lets producers and consumers define YAML check contracts for Hive warehouse tables and runs them via Airflow, Flyte, scheduled cron, or a CLI. The architecture uses SQS queues, separate executors, DynamoDB result storage and a notifier to keep checks reliable and isolated, and it reports large reductions in production data incidents.", "interview_angle": "How would you design a data quality framework for a shared warehouse that blocks bad data before promotion, yet keeps alerting working when the orchestrator fails and isolates heavy checks from urgent ones?", "score": 1.6393, "hn_points": 0, "hn_comments": 0}, {"url": "https://netflixtechblog.com/stop-answering-the-same-question-twice-interval-aware-caching-for-druid-at-netflix-scale-22fadc9b840e", "company": "Netflix", "industry": "media", "title": "Stop Answering the Same Question Twice: Interval-Aware Caching for Druid at Netflix Scale", "date": "2026-04-06", "primary_problem": "performance", "problems": ["cost", "realtime"], "post_type": "case_study", "level": "advanced", "stack": ["Druid", "Cassandra", "KVDAL", "SHA-256"], "scale": "Up to 15M events/sec ingest, over 10 trillion rows, 82% of real user queries get at least a partial cache hit", "key_decisions": ["Accept up to 5s staleness on freshest data in exchange for much lower query load on Druid", "Use age-based exponential TTLs so recent buckets refresh fast while settled history lingers up to 1 hour", "Use a map-of-maps keyed by query hash (without interval) and time buckets, with an external intercepting proxy at the Druid Router to avoid client changes"], "summary": "Netflix built an experimental interval-aware caching service in front of Apache Druid that splits rolling-window time-series query results into granularity-aligned buckets cached with age-based exponential TTLs. The cache serves settled history and only queries Druid for the freshest slice, cutting Druid query volume by about a third and improving P90 latency by about 66% in an experiment.", "interview_angle": "How would you reduce query load from many overlapping rolling-window dashboards on a real-time OLAP store while keeping data staleness bounded and correctness acceptable?", "score": 1.6346, "hn_points": 4, "hn_comments": 0}, {"url": "https://netflixtechblog.com/evolution-of-ml-fact-store-5941d3231762", "company": "Netflix", "industry": "media", "title": "Evolution of ML Fact Store", "date": "2022-04-26", "primary_problem": "ml_data", "problems": ["performance", "quality"], "post_type": "case_study", "level": "advanced", "stack": ["Iceberg", "Spark", "Keystone", "EVCache", "Parquet", "S3", "gRPC"], "scale": "Several hundred million rows per training query; training uses several weeks of facts; more than 95% of data issues identified early", "key_decisions": ["Simplified the fact logging client to asynchronously write protobuf batches to Keystone, trading away early storage and query optimizations for a simpler write path that leaves room for query-side tuning", "Denormalized facts into a single nested Parquet Iceberg table to eliminate Spark shuffle failures from multi-table joins, accepting larger storage footprint", "Added an EVCache key-value layer with member-id indices for low-latency lookups, trading higher cost per byte and limited retained data against much faster queries than Iceberg scans"], "summary": "Netflix describes how its Axion fact store, used to regenerate ML features offline for training and experiments, evolved from a storage-optimized logger and normalized Iceberg tables to a denormalized Parquet layout plus an EVCache index for fast member-level lookups. It also outlines a three-pronged data quality system (trend aggregations, consistent sampling, random sampling) that caught over 95% of data issues early.", "interview_angle": "How would you design an offline feature store that supports fast, temporally accurate regeneration of training data when queries select a tiny fraction of a huge table, and how would you balance storage cost against query latency?", "score": 1.6341, "hn_points": 1, "hn_comments": 0}, {"url": "https://netflixtechblog.com/how-and-why-netflix-built-a-real-time-distributed-graph-part-1-ingesting-and-processing-data-80113e124acc", "company": "Netflix", "industry": "media", "title": "How and Why Netflix Built a Real-Time Distributed Graph: Part 1 \u2014 Ingesting and Processing Data\u2026", "date": "2025-10-17", "primary_problem": "realtime", "problems": ["scale_ingestion", "platform"], "post_type": "case_study", "level": "advanced", "stack": ["Kafka", "Flink", "Apache Avro", "Iceberg"], "scale": "Topics up to ~1M messages/sec each; more than 5M graph node and edge records/sec written to Data Mesh", "key_decisions": ["Chose Flink stream processing over batch warehouse processing to keep a graph current with member actions, trading operational complexity for low latency", "Moved from one monolithic Flink job to a 1:1 job-per-Kafka-topic model, accepting more jobs and topics in exchange for per-topic tuning and stability", "Buffer and deduplicate node/edge updates in a short configurable window before publishing, reducing downstream write volume at the cost of slight added latency"], "summary": "Netflix describes the ingestion and processing layer of its Real-Time Distributed Graph, where Kafka topics of member interaction events are consumed by Flink jobs that enrich, transform and deduplicate them into graph nodes and edges. The post explains why they split a single job into per-topic jobs for stability and persist topics to Iceberg so data can be backfilled after Kafka retention expires.", "interview_angle": "How would you design a streaming pipeline that turns high-volume heterogeneous events into entity and relationship records, balancing job stability, dedup windows and replay/backfill via a log plus lakehouse archive?", "score": 1.6319, "hn_points": 2, "hn_comments": 0}, {"url": "https://eng.lyft.com/lyfts-feature-store-architecture-optimization-and-evolution-7835f8962b99", "company": "Lyft", "industry": "mobility", "title": "Lyft\u2019s Feature Store: Architecture, Optimization, and Evolution", "date": "2026-01-06", "primary_problem": "ml_data", "problems": ["platform", "performance"], "post_type": "case_study", "level": "advanced", "stack": ["Hive", "Spark", "Airflow", "Astronomer", "DynamoDB", "Valkey", "OpenSearch", "Flink", "Kafka", "Kinesis", "Amundsen", "Flyte", "Golang", "Python", "EKS", "ElastiCache"], "scale": "Over 60 internal users; batch feature family grew 12% YoY; production service callers up ~25% YoY; aggregate R/W activity up over a trillion operations", "key_decisions": ["Generate production-ready Airflow DAGs from SQL plus JSON config so feature authors avoid pipeline code, trading flexibility for consistency and faster iteration", "Write features to both offline Hive tables and an online DynamoDB-backed store with a Valkey cache, trading extra cache cost and consistency work for ultra-low-latency reads", "Raise cache TTLs and trim payloads and retry policies to cut P95 read latency by a third, accepting staler metadata and higher storage cost"], "summary": "Lyft describes its Feature Store as a platform of batch, online, and streaming components, with batch features generated from Spark SQL into Airflow DAGs and streaming features ingested through Flink. It explains how the dsfeatures serving layer uses DynamoDB, a Valkey cache and OpenSearch for embeddings, and reports latency and reliability work plus growth in usage.", "interview_angle": "Design a feature store serving both offline training and online low-latency inference: how would you keep offline and online copies consistent, and where would you put caching to cut tail latency?", "score": 1.6294, "hn_points": 2, "hn_comments": 0}, {"url": "https://engineering.grab.com/plumbing-at-scale", "company": "Grab", "industry": "mobility", "title": "Plumbing At Scale", "date": "2020-01-06", "primary_problem": "realtime", "problems": ["platform", "scale_ingestion"], "post_type": "case_study", "level": "advanced", "stack": ["Kafka", "Go", "Kubernetes", "AWS EKS", "ScyllaDB", "Horizontal Pod Autoscaler", "Cluster Autoscaler"], "scale": "Over 300 billion events a week; terabytes of data ingress per hour", "key_decisions": ["Built a custom Go stream processing framework (filter, map, window, join, dedup) instead of adopting Flink, trading feature completeness for tighter integration with the Go backend ecosystem", "Ran each pipeline as an isolated Kubernetes deployment, gaining compute isolation and independent lifecycles at the cost of some noisy-neighbour risk on shared nodes", "Mapped pipeline priority classes to Spot vs on-demand instances so latency-tolerant work runs cheaper, accepting disruptions when Spot nodes are reclaimed"], "summary": "Grab's Coban team describes an event sourcing platform and a Go-based stream processing framework running hundreds of pipelines on Kubernetes over Kafka, handling over 300 billion events a week. The post covers the framework's capabilities (windowing, joins, replay, rewind), multi-cluster redundancy, and using Spot instances for latency-tolerant workloads.", "interview_angle": "How would you design a multi-tenant streaming platform where teams self-serve pipelines with tunable latency, cost and failure-handling trade-offs on Kubernetes?", "score": 1.6294, "hn_points": 3, "hn_comments": 0}, {"url": "https://engineering.grab.com/data-first-sla-always", "company": "Grab", "industry": "mobility", "title": "Data First, SLA Always", "date": "2019-08-01", "primary_problem": "cdc_sync", "problems": ["realtime", "scale_ingestion"], "post_type": "case_study", "level": "advanced", "stack": ["MySQL", "Debezium", "Kafka", "Spark Structured Streaming", "Spark", "Redis", "Airflow", "YARN", "Datadog", "PagerDuty", "Presto", "S3"], "scale": "Hundreds of MySQL tables streamed across 60 Spark streaming jobs; data beyond the petabyte threshold", "key_decisions": ["Used Debezium binlog CDC on Kafka instead of timestamp-window batch queries, removing load on source MySQL and the need for an updated column, at the cost of running more streaming infrastructure", "Stored Spark checkpoints externally in Redis keyed by topic with partition offsets, with timestamped paths, avoiding fragile local state but adding a dependency on Redis availability", "Kept hourly compaction for downstream tables, favoring consistency (waiting for complete hours) over availability, which adds latency to downstream results"], "summary": "Grab's Data Engineering team built Trailblazer, a Spark Structured Streaming application that captures MySQL binlogs via Debezium and Kafka and lands them in the data lake, replacing fragile timestamp-based batch ingestion. Downstream tables are materialised by hourly compaction jobs, with monitoring on job liveness, offset divergence and hourly count checks.", "interview_angle": "How would you replace timestamp-window batch extraction from production MySQL with CDC at scale, and how would you make streaming jobs recoverable and observable (checkpoints, deduplication, completeness before downstream consumption)?", "score": 1.6279, "hn_points": 0, "hn_comments": 0}, {"url": "https://engineering.grab.com/real-time-data-ingestion", "company": "Grab", "industry": "mobility", "title": "Real-time data ingestion in Grab", "date": "2022-03-14", "primary_problem": "cdc_sync", "problems": ["realtime", "scale_ingestion"], "post_type": "case_study", "level": "advanced", "stack": ["MySQL", "Aurora", "DynamoDB", "Kafka", "Debezium", "Kafka Connect", "AWS Lambda", "S3", "Protobuf", "Golang", "Elasticsearch"], "scale": "Thousands of hourly pipelines; hundreds of teams consuming; database reads reduced by 90% for one search use case", "key_decisions": ["Use log-based CDC (Debezium for MySQL/Aurora binlog, Lambda triggers for DynamoDB streams) instead of SQL polling, cutting read load on shared databases but adding operational complexity for connectors and stream retention.", "Pick Debezium over Maxwell and Canal for its native Kafka Connect integration, accepting coupling to the Connect framework.", "Choose Lambda over an existing open-source DynamoDB Kafka Connector because Lambda concurrency scales with shard traffic, whereas the connector used a single thread for all shards and lagged during write spikes."], "summary": "Grab describes a real-time ingestion platform that streams row-level changes from MySQL, Aurora and DynamoDB into Kafka, then lands them in the S3-based data lake every minute. The post explains why log-based capture beats repeated SQL extracts and double-writes from services, and lists use cases including pipeline offloading, DR replication and audit trails.", "interview_angle": "Design a change-data-capture pipeline for multiple heterogeneous operational databases feeding a data lake: how would you capture changes without loading production, preserve ordering across partitioned stores, and handle schema evolution?", "score": 1.6263, "hn_points": 0, "hn_comments": 0}, {"url": "https://netflixtechblog.com/ontology-driven-observability-building-an-end-to-end-knowledge-graph-at-netflix-scale-421392cf5adf", "company": "Netflix", "industry": "media", "title": "Ontology-Driven Observability: Building an End-to-End Knowledge Graph at Netflix Scale", "date": "2026-10-16", "primary_problem": "lineage_catalog", "problems": ["modeling", "realtime"], "post_type": "case_study", "level": "advanced", "stack": ["RDF", "OWL", "SHACL", "SPARQL", "QuipuDB", "redb", "Rust", "Turtle", "Atlas", "Spinnaker", "PagerDuty", "incident.io", "Slack"], "scale": "2 billion requests/day; 38 million logging events/second; roughly 49,000 catalog entries", "key_decisions": ["Model entities against one authoritative catalog (about 49,000 software entries) and refuse unvalidated strings as applications, trading coverage for graph accuracy", "Constrain LLM outputs to a fixed predicate vocabulary so stochastic extraction yields deterministic triples, at the cost of expressiveness", "Run enrichers sequentially with best-effort external calls, trading wall-clock time and some degradation for no race conditions and resilience"], "summary": "Netflix describes an RDF-based Observability Ontology stored in a homegrown quad store that links telemetry, alerts, deployments, incidents and incident chat into one queryable knowledge graph. The graph feeds a correlation engine and an agentic root-cause analysis system, cutting the context-gathering part of investigations.", "interview_angle": "How would you design a metadata graph that unifies entities across siloed operational tools so that both humans and LLM agents can run cross-system root-cause queries reliably?", "score": 1.6214, "hn_points": 131, "hn_comments": 32}, {"url": "https://engineering.grab.com/real-time-data-quality-monitoring", "company": "Grab", "industry": "mobility", "title": "Real-time data quality monitoring: Kafka stream contracts with syntactic and semantic test", "date": "2025-11-26", "primary_problem": "quality", "problems": ["realtime", "platform"], "post_type": "case_study", "level": "advanced", "stack": ["Kafka", "Flink SQL", "S3", "Slack", "LLM"], "scale": "100+ critical Kafka topics monitored", "key_decisions": ["Run data quality tests as a long-running FlinkSQL job on each topic under its own consumer group, so monitoring does not affect other consumers, at the cost of operating another stateful streaming service", "Express semantic rules as user-defined field-level rules compiled into inverse SQL queries that surface violating records, trading expressiveness for simple, enforceable checks", "Use LLM-generated semantic rule recommendations from schema and anonymized samples to cut setup effort, accepting that suggested rules need human review and may be wrong"], "summary": "Grab built Coban, a platform where Kafka stream owners define data contracts combining schemas and field-level semantic rules. A FlinkSQL-based Test Runner checks topics in real time, routes bad records to Kafka and S3, and alerts owners through Genchi and Slack, covering 100+ critical topics.", "interview_angle": "How would you design real-time data quality checks on a high-volume Kafka topic that catch both schema-level deserialization failures and field-level semantic violations, while alerting owners and keeping the checks isolated from downstream consumers?", "score": 1.6207, "hn_points": 0, "hn_comments": 0}, {"url": "https://www.capitalone.com/tech/cloud/aws-apache-flink", "company": "Capital One", "industry": "fintech", "title": "AWS KDA - Building a real time streaming app | Capital One", "date": "2023-01-18", "primary_problem": "realtime", "problems": ["migration", "scale_ingestion"], "post_type": "case_study", "level": "intermediate", "stack": ["Flink", "PyFlink", "AWS Kinesis Data Analytics", "Kafka", "Aurora", "Spark", "Maven"], "scale": "Petabytes of financial transactions processed (no specific throughput stated)", "key_decisions": ["Chose Flink on KDA over Spark batch jobs for lower latency and less cluster maintenance, accepting a less mature Python API and higher development cost", "Consumed Kafka as raw bytes and decoded with a custom Python UDF because Flink's Avro format could not handle the custom data types, trading extra code for compatibility", "Bundled SSL certificates via an AWS-provided custom Kafka connector and a single uber jar, since KDA accepts only one jar and task nodes cannot receive files directly"], "summary": "Capital One's Card Tech team built a proof of concept that replaces lagging hourly Spark batch jobs with streaming pipelines using PyFlink on AWS Kinesis Data Analytics, reading from Kafka and writing to Aurora. The post walks through source and sink DDL, a decoding UDF, packaging with an uber jar, and the workarounds needed for SSL certificates and missing librdkafka on KDA nodes.", "interview_angle": "How would you move a Kafka-to-database pipeline from hourly batch to near-real-time, and what trade-offs would you weigh between a managed streaming service and a self-managed Spark cluster?", "score": 1.6197, "hn_points": 0, "hn_comments": 0}, {"url": "https://engineering.grab.com/the-complete-stream-processing-journey-on-flinksql", "company": "Grab", "industry": "mobility", "title": "The complete stream processing journey on FlinkSQL", "date": "2025-06-12", "primary_problem": "realtime", "problems": ["platform", "performance"], "post_type": "case_study", "level": "advanced", "stack": ["Flink", "FlinkSQL", "Zeppelin", "Kafka", "Hive Metastore"], "scale": "Ad-hoc query first results cut from 5 minutes to 1 minute; pipelines deployable within 10 minutes", "key_decisions": ["Replaced per-user Zeppelin clusters with a shared FlinkSQL gateway cluster: faster session start (5 to 1 minute) and easier Flink upgrades, but shared resources and task managers provisioned ad hoc add some lead time.", "Added a custom control plane and headless REST APIs over the gateway: simplifies sessions, auth and result paging for internal platforms, at the cost of maintaining an extra service layer.", "Exposed Kafka topics as tables via Hive Metastore and config-driven SQL pipeline deployment: lowers barrier for analysts and speeds deployment, but limits flexibility compared with hand-written Flink jobs."], "summary": "Grab replaced its per-user Zeppelin notebook setup for Flink with a shared FlinkSQL gateway, wrapped by a custom control plane, REST APIs and a query UI. They also added a config-driven path that turns SQL into deployed Flink pipelines, cutting time to first results and time to production.", "interview_angle": "How would you give analysts interactive SQL access to a Kafka stream without spinning up a cluster per user, and how would you take that ad-hoc SQL into a production pipeline?", "score": 1.6191, "hn_points": 0, "hn_comments": 0}, {"url": "https://netflixtechblog.com/evolving-from-rule-based-classifier-machine-learning-powered-auto-remediation-in-netflix-data-039d5efd115b", "company": "Netflix", "industry": "media", "title": "Evolving from Rule-based Classifier: Machine Learning Powered Auto Remediation in Netflix Data\u2026", "date": "2024-03-04", "primary_problem": "platform", "problems": ["cost", "quality"], "post_type": "case_study", "level": "advanced", "stack": ["Spark", "Metaflow", "Netflix Maestro", "Ax", "MLP"], "scale": "Hundreds of thousands of workflows and millions of jobs per day; about 600 memory configuration errors per month; about 50% of failures unclassified", "key_decisions": ["Keep the rule-based classifier as a first pass and add an ML service as a second pass, trading some added complexity for deterministic per-error-class behavior and automated remediation", "Use a multi-output MLP predicting retry success and retry cost jointly, with feature hashing for high-cardinality job metadata, favoring fast online inference over a more complex model", "Use Bayesian optimization over Spark memory and core configs with a conservative policy to disable retries, trading some savings for a lower risk of hurting users who always want retries; GPU acceleration was added to cut optimizer timeouts"], "summary": "Netflix extended its rule-based error classifier (Pensive) with an ML service (Nightingale) that recommends Spark memory configurations or disables retries for memory-config and unclassified job failures, with the recommendations applied automatically through a configuration service. In production it remediated about 56% of memory configuration errors and cut related compute cost by roughly half.", "interview_angle": "How would you automate remediation of failed big data jobs at scale, balancing retry success probability against compute cost while keeping a deterministic fallback for known error classes?", "score": 1.6106, "hn_points": 16, "hn_comments": 0}, {"url": "https://netflixtechblog.com/3-psyberg-automated-end-to-end-catch-up-260fbe366fe2", "company": "Netflix", "industry": "media", "title": "Psyberg: Automated end to end catch up", "date": "2023-11-15", "primary_problem": "late_data", "problems": ["migration", "cost"], "post_type": "case_study", "level": "advanced", "stack": ["Iceberg", "Spark", "Psyberg"], "scale": "Spark cores reduced by 90%; 30 tables and 13 workflows onboarded to incremental processing", "key_decisions": ["Isolate Psyberg's incremental-processing logic from core ETL so the same pattern covers stateless and stateful pipelines, at the cost of an extra framework layer to maintain", "Use a high-watermark plus session metadata to process only new or late partitions instead of fixed lookback windows, trading added metadata complexity for far less recomputation", "Derive dimension processing range from the least-common min and max hours across upstream fact tables, so partial hours are never published, at the cost of waiting for the slowest source"], "summary": "Netflix describes Psyberg, a framework that tracks high watermarks and session metadata so pipelines catch up automatically on late-arriving data, both for fact tables and downstream dimensions. Using Write-Audit-Publish on Iceberg, they report a 90% drop in Spark cores versus fixed lookback windows and zero manual catchups since rollout.", "interview_angle": "How would you design incremental processing that handles late-arriving events across chained fact and dimension tables without reprocessing fixed lookback windows or publishing partial hours?", "score": 1.609, "hn_points": 0, "hn_comments": 0}, {"url": "https://netflixtechblog.com/automating-rds-postgres-to-aurora-postgres-migration-261ca045447f", "company": "Netflix", "industry": "media", "title": "Automating RDS Postgres to Aurora Postgres Migration", "date": "2026-02-12", "primary_problem": "migration", "problems": ["cdc_sync", "platform"], "post_type": "case_study", "level": "advanced", "stack": ["Amazon RDS PostgreSQL", "Amazon Aurora PostgreSQL", "PostgreSQL logical replication slots", "Envoy", "AWS DMS", "eBPF flowlogs"], "scale": "Fleet of nearly 400 PostgreSQL clusters; about 10 minutes average write downtime at cutover", "key_decisions": ["Chose Aurora read-replica replication over snapshot restore: more setup complexity in exchange for much shorter write downtime at cutover", "Blocked writes at the infrastructure layer by detaching security groups and rebooting RDS, avoiding credential access but accepting a slower quiescence than app-level pausing", "Dropped and recreated CDC replication slots around cutover: avoids stalled WAL retention and wrong-endpoint consumers, but forces a full REFRESH backfill for downstream consumers"], "summary": "Netflix describes an automated self-service workflow to migrate RDS PostgreSQL clusters to Aurora PostgreSQL using an Aurora read replica, quiescence via security group detachment, WAL-based lag validation, and proxy-level cutover through its Data Access Layer. The post also covers handling CDC replication slots during migration, a real partner-platform migration, and rollback options at each phase.", "interview_angle": "How would you design a zero-data-loss, low-downtime database migration across hundreds of clusters without giving the migration tool application credentials, and how do you handle logical replication slots and CDC consumers during cutover?", "score": 1.6071, "hn_points": 0, "hn_comments": 0}, {"url": "https://monzo.com/blog/a-meshy-approach-to-data", "company": "Monzo", "industry": "fintech", "title": "A \u201cmeshy\u201d approach to Data: Enabling 100+ teams to build Data Models", "date": "2026-04-22", "primary_problem": "modeling", "problems": ["platform", "quality"], "post_type": "case_study", "level": "advanced", "stack": ["dbt", "Modelgen", "CI/CD"], "scale": "12,000+ dbt models, 100+ contributing teams", "key_decisions": ["Four-layer object-oriented model structure (landing, normalised, logical, presentation) trades upfront restructuring effort for consistent, predictable modelling across teams", "Governed interfaces for cross-team sharing make only normalised/logical models shareable, trading some flexibility for stable contracts between domains", "Generating models via an in-house CLI from short YAML configs reduces hand-written SQL but depends on consistent upstream event formats from microservices"], "summary": "Monzo restructured its dbt warehouse of over 12,000 models across 100+ teams into four layered business-object models, with formal interfaces for cross-team data sharing. Modelgen generates models from short YAML descriptions and CI-enforced data standards check quality on every pull request, reportedly yielding about 40% cost reduction and 25% faster landing times in migrated domains so far.", "interview_angle": "How would you let hundreds of teams contribute to one shared warehouse without central bottlenecks while keeping cost, performance and cross-domain dependencies under control?", "score": 1.6051, "hn_points": 0, "hn_comments": 0}, {"url": "https://stripe.com/blog/how-we-built-it-real-time-analytics-for-stripe-billing", "company": "Stripe", "industry": "fintech", "title": "How we built it: Real-time analytics for Stripe Billing", "date": "2025-09-16", "primary_problem": "realtime", "problems": ["cdc_sync", "performance"], "post_type": "case_study", "level": "advanced", "stack": ["Flink", "Spark", "Pinot"], "scale": "Billions of historical subscription events; updates visible within 15 minutes; query latency under 300 ms", "key_decisions": ["Use Flink with incremental state instead of re-analyzing full subscription history in batch, trading state management complexity for minute-level freshness", "Generate initial Flink state with a Spark job over historical events, adding a parallel offline pipeline for validation at the cost of maintaining two code paths sharing the same logic", "Adopt Pinot's v2 windowed aggregation engine to drop offline preaggregation, accepting reliance on a newer engine never before used in a user-facing context at this scale"], "summary": "Stripe replaced a 24-hour batch analytics pipeline for Billing subscription metrics with an event-driven system built on Flink state and Pinot's windowed aggregation engine. The design delivers updates within about 15 minutes and sub-300 ms dashboard queries, and it lets customers change metric definitions by reprocessing history while streaming continues.", "interview_angle": "How would you turn a batch subscription-metrics pipeline into a near-real-time system while keeping historical values consistent when a metric definition changes mid-stream?", "score": 1.6035, "hn_points": 1, "hn_comments": 0}, {"url": "https://medium.com/pinterest-engineering/rebuilding-guardian-how-pinterest-upgraded-its-real-time-abuse-platform-to-modern-infrastructure-56e45ee8f471", "company": "Pinterest", "industry": "social", "title": "Rebuilding Guardian: How Pinterest Upgraded Its Real-Time Abuse Platform to Modern Infrastructure\u2026", "date": "2026-11-16", "primary_problem": "realtime", "problems": ["migration", "storage_formats"], "post_type": "case_study", "level": "advanced", "stack": ["StarRocks", "FlinkSQL", "Flink", "Iceberg", "Kafka", "ANTLR4", "Java"], "scale": "O(20K) to O(K) effective indexed columns after stream splitting; up to 30 days of replayable history", "key_decisions": ["Split the unified enriched event stream into narrower event-family substreams, trading an extra pipeline stage for much lower column sparsity and cheaper per-job consumption", "Adopted StarRocks with duplicate key tables, sort keys and Bloom filters for write-heavy real-time investigation queries, accepting a new engine alongside existing analytics systems", "Moved async action evaluation and replay to FlinkSQL on Iceberg, sharing one execution path with templated SQL, instead of maintaining the custom monolithic core"], "summary": "Pinterest rebuilt its real-time abuse-detection platform Guardian from a monolithic in-house system into Guardian V2, separating interactive analytics, async action evaluation and historical replay. The design relies on stream splitting, StarRocks for low-latency investigation queries, and FlinkSQL plus Iceberg for live processing and replay.", "interview_angle": "How would you design a real-time investigation and action system over high-volume events that must also support replay of recent history, and how would you split the data plane so analytics and stream jobs do not share one wide, sparse schema?", "score": 1.6021, "hn_points": 0, "hn_comments": 0}, {"url": "https://shopify.engineering/capturing-every-change-shopify-sharded-monolith", "company": "Shopify", "industry": "ecommerce", "title": "Capturing Every Change From Shopify\u2019s Sharded Monolith", "date": "2021-03-12", "primary_problem": "cdc_sync", "problems": ["scale_ingestion", "realtime"], "post_type": "case_study", "level": "advanced", "stack": ["Debezium", "Kafka", "Kafka Connect", "Kafka Streams", "MySQL", "Google Cloud Storage", "Avro", "Confluent Schema Registry", "Spark", "dbt", "Google Bigtable", "BigQuery", "Redshift", "Kubernetes"], "scale": "400TB+ CDC data in Kafka; ~150 Debezium connectors; ~65,000 records/sec average, 100,000 peak; 100+ MySQL shards; p99 latency under 10 seconds", "key_decisions": ["Chose log-based CDC with Debezium over query-based Longboat extraction, gaining near real-time capture and hard-delete visibility at the cost of operating a new Kafka Connect stack and handling snapshot limitations", "Merged per-shard change topics into one compacted topic per logical table, isolating consumers from sharding at the cost of an extra Kafka Streams hop", "Offloaded records above Kafka's 1 MB limit to GCS with a pointer in Kafka, avoiding broker tuning at the cost of custom serde code and extra access-control and cleanup work"], "summary": "Shopify replaced its batch, query-based Longboat extractor for its sharded MySQL monolith with a log-based CDC platform built on Debezium and Kafka. The post covers topic topology, compaction, schema registry use, snapshot limits, and handling oversized records.", "interview_angle": "How would you replace a query-based batch extractor over many sharded databases with CDC, while capturing hard deletes, preserving intermediate states, and keeping source databases healthy during snapshots?", "score": 1.5983, "hn_points": 10, "hn_comments": 0}, {"url": "https://eng.lyft.com/rerouting-the-stream-how-lyft-moved-to-the-apache-flink-operator-36f20246d250", "company": "Lyft", "industry": "mobility", "title": "Rerouting the Stream: How Lyft Moved to the Apache Flink Kubernetes Operator", "date": "2026-08-31", "primary_problem": "migration", "problems": ["platform", "cost"], "post_type": "case_study", "level": "advanced", "stack": ["Flink", "Kubernetes", "Karpenter", "Jsonnet", "Beam", "Kafka", "Kinesis", "AWS EKS", "S3"], "scale": "Hundreds of critical streaming jobs; over-provisioning cost savings of a few million dollars per year", "key_decisions": ["Translate legacy FlinkApplication specs to the Apache FlinkDeployment CRD at the deploy API boundary instead of rewriting every config library, trading a translation layer for zero developer-facing change", "Migrate incrementally one app at a time with dynamic config and instant rollback to the legacy operator, trading a longer dual-operator period for lower production risk", "Split autotuning and in-place autoscaling into a two-tier model: critical jobs keep in-place autoscaling without restarts, less critical jobs accept restarts for autotuning, trading resource efficiency against downtime"], "summary": "Lyft retired its in-house Flink Kubernetes operator and moved its streaming fleet to the open-source Apache Flink Kubernetes operator, using a translation layer so teams kept their existing configs. Follow-on work covered BlueGreen deploy downtime, in-place autoscaling after a Flink upgrade, autotuning OOM issues with the Python harness, and Karpenter-based node right-sizing.", "interview_angle": "How would you migrate a large fleet of stateful streaming jobs between two Kubernetes operators without downtime or changing developer workflows, and how would you roll it back safely?", "score": 1.598, "hn_points": 0, "hn_comments": 0}, {"url": "https://engineering.grab.com/zero-traffic-cost", "company": "Grab", "industry": "mobility", "title": "Zero traffic cost for Kafka consumers", "date": "2023-07-07", "primary_problem": "cost", "problems": ["realtime", "platform"], "post_type": "case_study", "level": "advanced", "stack": ["Kafka", "Flink", "Kafka Connect", "AWS", "Cruise Control", "Ansible", "Golang", "ZooKeeper"], "scale": "Cross-AZ traffic reduced by 25% versus December average; cross-AZ traffic had been about half of Kafka platform cost", "key_decisions": ["Enable fetch-from-closest-replica using rack-aware replica selection across three AZs, trading cross-AZ transfer cost for up to 500ms extra end-to-end latency, so latency-sensitive use cases keep fetching from leaders", "Upgrade legacy Kafka clusters straight to 3.1 in three staged steps (ZooKeeper, rolling broker upgrade with pinned inter-broker protocol, then protocol bump) to keep the rollout online without disruption", "Hide the feature behind the internal Go SDK and auto-detected AZ IDs so users only set an environment variable, accepting that broker demotion during rotations no longer cleanly isolates consumers and load can skew across AZs"], "summary": "Grab's Coban team cut cross-AZ data transfer costs for Kafka by letting consumers fetch from the replica in their own availability zone rather than the partition leader. The change required rack-aware broker and client configuration, an upgrade to Kafka 3.1, and SDK support, and it yielded a 25% drop in cross-AZ traffic at the cost of higher latency and new operational caveats.", "interview_angle": "How would you reduce cross-AZ network costs for a large multi-consumer streaming platform without breaking availability, and what latency and maintenance trade-offs would you accept?", "score": 1.5978, "hn_points": 0, "hn_comments": 0}, {"url": "https://engineering.grab.com/scaling-like-a-boss-with-presto", "company": "Grab", "industry": "mobility", "title": "Scaling Like a Boss with Presto", "date": "2017-05-01", "primary_problem": "performance", "problems": ["platform", "storage_formats"], "post_type": "case_study", "level": "intermediate", "stack": ["Redshift", "S3", "Presto", "Spark", "Hive metastore", "AWS EMR", "Parquet", "Avro", "MySQL", "Amazon Kinesis", "Zeppelin", "RDS"], "scale": "Roughly 1500-2000 canned report requests per day; 2 billion record table benchmarked", "key_decisions": ["Offload analytics from Redshift to an S3 data lake with Presto over Parquet, trading Redshift's tuned distribution/sort keys for elastic, isolated clusters sharing one storage layer", "Switch storage format from Avro to Parquet because Presto lacked Avro support, giving up Avro's Redshift compatibility", "Partition data by hour and enforce query rules (filter on partition columns, order joins largest to smallest, keep non-equijoins out of ON), accepting that ad-hoc full scans stay slower than Redshift"], "summary": "Grab's Redshift-based analytics struggled with growing concurrent and peaky workloads, so they built an S3 data lake with hourly partitioned Parquet files processed by Spark and queried through multiple Presto clusters sharing a Hive metastore. The move gave roughly a 400% improvement at the 90th percentile and removed workload-manager wait times, though Redshift still won on full-table ad-hoc scans.", "interview_angle": "How would you redesign an analytics store that is bottlenecked by concurrent peaky queries: separate storage from compute, use multiple isolated query clusters over one shared metastore, and what query and partition rules keep the engine fast?", "score": 1.5963, "hn_points": 0, "hn_comments": 0}, {"url": "https://netflixtechblog.com/a-tale-of-two-flink-autoscalers-e9f6a1b1492b", "company": "Netflix", "industry": "media", "title": "A Tale of Two Flink Autoscalers", "date": "2026-08-21", "primary_problem": "cost", "problems": ["platform", "realtime"], "post_type": "case_study", "level": "advanced", "stack": ["Flink", "Mantis", "Atlas", "Temporal", "Kafka", "Spring Boot", "Kubernetes"], "scale": "More than 30,000 Flink jobs across multiple AWS regions; autoscaler handles jobs up to 3,000 subtasks", "key_decisions": ["Adopting the open-source Flink Autoscaler over the in-house Mantis-based scaler: gains operator-level scaling of stateful DAGs but requires maintaining a fork and integration work", "Running one durable Temporal workflow per job instead of a batch loop: isolates failures and blast radius at the cost of more runtime orchestration", "Targeting 0.45 utilization instead of the community default 0.7: sacrifices some efficiency for fewer, calmer rescales and stability"], "summary": "Netflix describes replacing its homegrown external, container-metric-based Flink autoscaler with the Apache Flink Autoscaler, which estimates per-operator true processing rates and scales each vertex independently. They cover the integration work (Temporal per-job workflows, realizer safety checks, forward-chaining preservation, JobManager metric-collection fixes) and report a 58% compute reduction for one team.", "interview_angle": "How would you design an autoscaler for thousands of streaming jobs that avoids cluster-wide scaling, respects stateful operator dependencies, and isolates failures per job?", "score": 1.596, "hn_points": 1, "hn_comments": 0}, {"url": "https://stripe.com/blog/shepherd-how-stripe-adapted-chronon-to-scale-ml-feature-development", "company": "Stripe", "industry": "fintech", "title": "Shepherd: How Stripe adapted Chronon to scale ML feature development", "date": "2024-04-15", "primary_problem": "ml_data", "problems": ["realtime", "performance"], "post_type": "case_study", "level": "advanced", "stack": ["Chronon", "Flink", "Spark", "Iceberg", "Airflow", "Hive", "memcache", "Python"], "scale": "Hundreds of TB of raw data; training sets with billions of rows and thousands of features; p99 feature freshness of 150ms", "key_decisions": ["Split the KV store into a low-cost write-once bulk store and a pricier memcache-based store for write-heavy serving, trading cost against per-tier complexity", "Use Flink for streaming feature updates to reach low freshness, at the cost of porting Spark SQL map/filter expressions to Flink", "Pre-aggregate feature state into tiles in Flink instead of storing raw events, trading extra write-side state for lower serving latency on high-volume features"], "summary": "Stripe adapted Airbnb's open-source Chronon feature platform into Shepherd, an ML feature engineering system covering offline training data, streaming updates, and online serving. The post explains how they tuned the KV store, moved streaming to Flink with tiled preaggregation, and integrated with their Airflow orchestration and Iceberg-based warehouse, which backed a fraud model with over 200 features.", "interview_angle": "How would you design a feature store that serves both low-latency online lookups and large offline training datasets, and how would you balance freshness against serving latency?", "score": 1.5938, "hn_points": 3, "hn_comments": 0}, {"url": "https://tech.instacart.com/building-a-flink-self-serve-platform-on-kubernetes-at-scale-c11ef19aef10", "company": "Instacart", "industry": "marketplace", "title": "Building a Flink Self-Serve Platform on Kubernetes at Scale", "date": "2023-04-18", "primary_problem": "platform", "problems": ["realtime", "cost"], "post_type": "case_study", "level": "advanced", "stack": ["Flink", "Kubernetes", "Amazon EKS", "Amazon EMR", "Kafka", "Karpenter", "FluxCD", "Datadog", "Amazon ECR", "NGINX", "Flink Kubernetes Operator"], "scale": "Over 2 trillion events per year; 50+ product teams onboarded; 500 Flink ingestion pipelines; about 75 EMR clusters replaced", "key_decisions": ["Replace per-cluster EMR Flink deployments with a multi-tenant Kubernetes platform, gaining isolation and self-serve onboarding at the cost of learning and operating Kubernetes", "Wrap Flink deployments in a custom Kubernetes CRD and controller so users get one endpoint for onboarding, trading controller maintenance for much faster provisioning", "Use Karpenter just-in-time nodes instead of multiple managed node groups, improving bin packing and cost but depending on a newer node-management component"], "summary": "Instacart moved its Flink streaming platform from many EMR clusters to Kubernetes on EKS, using the Flink K8s operator, a custom CRD controller, GitOps deployment and Karpenter. The change cut onboarding from a week to minutes, removed many critical alerts, and lowered infrastructure cost.", "interview_angle": "How would you design a self-serve streaming platform for many teams so that users never touch cluster infrastructure, while keeping per-job isolation, failure recovery and cost under control?", "score": 1.5905, "hn_points": 0, "hn_comments": 0}, {"url": "https://engineering.grab.com/ml-predictive-autoscaling-for-flink", "company": "Grab", "industry": "mobility", "title": "Machine-learning predictive autoscaling for Flink", "date": "2025-10-30", "primary_problem": "cost", "problems": ["realtime", "performance"], "post_type": "case_study", "level": "advanced", "stack": ["Flink", "Flink SQL", "Kafka", "Kubernetes", "Flink Adaptive Scheduler"], "scale": "Flink applications grew 2.5x in a year; autoscaler deployed to over 50% of applicable production apps; >35% cloud cost savings on those apps", "key_decisions": ["Chose predictive vertical CPU scaling over reactive horizontal HPA scaling, trading model-training effort for fewer restart spikes and no parallelism limits from Kafka partitions", "Used source topic throughput as the regression input instead of CPU, so the model is independent of Flink's own behaviour and avoids feedback loops from restart-inflated CPU readings", "Forecast workload with a periodically retrained time-series model and apply safety adjustments before resizing, trading some responsiveness for stability and fewer restarts"], "summary": "Grab built a Predictive Resource Advisor that forecasts Kafka-sourced Flink workloads and sets TaskManager CPU ahead of demand, replacing reactive HPA scaling that caused restart spikes and scale-out/scale-in spirals. The approach, rolled out to over half of applicable production apps, reported over 35% cloud cost savings and fewer disruptions.", "interview_angle": "How would you design autoscaling for a stateful stream processor so that scaling events (which force checkpoint restarts and reprocessing) do not cause the system to degrade further?", "score": 1.5863, "hn_points": 0, "hn_comments": 0}, {"url": "https://engineering.grab.com/kafka-on-kubernetes", "company": "Grab", "industry": "mobility", "title": "Kafka on Kubernetes: Reloaded for fault tolerance", "date": "2023-12-26", "primary_problem": "platform", "problems": ["realtime", "storage_formats"], "post_type": "case_study", "level": "advanced", "stack": ["Kafka", "Kubernetes", "Strimzi", "Amazon EKS", "Amazon EC2", "AWS Node Termination Handler", "AWS Load Balancer Controller", "Amazon EBS", "Karpenter", "Cruise Control", "ZooKeeper"], "scale": "600 partition leaders migrated in about 60 seconds per cluster; 3-replica topics; one Kafka cluster per EKS cluster", "key_decisions": ["Switched Kafka storage from NVMe instance store to EBS gp3 volumes so data survives node rotation, trading lower raw I/O performance for reattachment, cheaper storage and faster resync", "Used AWS Node Termination Handler in queue-processor mode with a 180-second graceful termination period so partition leaders migrate before brokers stop, at the cost of extra spare capacity and ASG lifecycle hook handling", "Dynamically registered pod IPs into NLB target groups via the Load Balancer Controller with a pod readiness gate, accepting faster health checks and tighter AZ constraints (one ASG per AZ) to keep rolling updates reliable"], "summary": "Grab's Coban platform describes how it made self-managed Kafka on Kubernetes (via Strimzi) tolerate unexpected broker node terminations without manual intervention. The fix combines graceful broker shutdown on node drain, automatic NLB target-group updates, and moving from instance-store NVMe to EBS volumes that can be reattached to replacement nodes.", "interview_angle": "How would you make a stateful streaming cluster survive node replacement and maintenance without manual intervention? Discuss graceful leader migration, storage reattachment across AZs, and load balancer target sync.", "score": 1.5803, "hn_points": 0, "hn_comments": 0}, {"url": "https://medium.com/pinterest-engineering/metrics-board-building-an-agent-ready-metrics-layer-2c8fefe68756", "company": "Pinterest", "industry": "social", "title": "Metrics Board: Building an Agent-ready Metrics Layer", "date": "2026-10-06", "primary_problem": "platform", "problems": ["quality", "lineage_catalog"], "post_type": "case_study", "level": "advanced", "stack": ["Airflow", "Spark", "Presto", "sqlglot", "DataHub", "Superset", "StarRocks", "Git", "Helium", "MCP"], "scale": "Petabyte-scale data lake; nearly 150 new metrics created per month; hundreds of producers", "key_decisions": ["Keep the metric layer thin: accept any SQL and ask for temporal and dimension metadata instead of enforcing a full semantic model, trading consistency for coverage across many table types", "Compile each metric into its own Airflow DAG so schedules, retries and failures are isolated, at the cost of many more DAGs to operate", "Publish metadata integrations at commit time and data integrations after each compute run, so catalog entries exist before data does but BI and warehouse exports wait for fresh results"], "summary": "Pinterest built Metrics Board, a metrics platform where each metric is a YAML spec in Git that drives scheduled Airflow computation, quality checks (rule-based and ML anomaly detection), and automatic publishing to DataHub, Helium, Superset and StarRocks. The post also covers a grading system for metrics and dashboard tiers that set retention and query routing, plus an MCP server for analytics agents.", "interview_angle": "How would you design a metrics platform where metric definitions are code-reviewed, computed on schedule, validated for anomalies, and published to catalog and BI tools without per-tool manual wiring?", "score": 1.5793, "hn_points": 0, "hn_comments": 0}, {"url": "https://engineering.grab.com/improving-hugo-stability", "company": "Grab", "industry": "mobility", "title": "Improving Hugo stability and addressing oncall challenges through automation", "date": "2025-03-20", "primary_problem": "quality", "problems": ["platform", "lineage_catalog"], "post_type": "case_study", "level": "advanced", "stack": ["Airflow", "Kafka", "Spark", "Flink", "Genchi", "Kinabalu"], "scale": "Over 4,000 data ingestion pipelines onboarded to Hugo", "key_decisions": ["Automate diagnosis from engine and platform signals instead of parsing Spark or Airflow logs, trading some diagnostic depth for much faster triage", "Auto-resolve known transient failures with retry and backoff, accepting risk of repeated retries on errors that are not actually transient", "Parallelise diagnosis per signal type (thousands of processes for failures, Kafka partition count for SLA and quality signals), trading higher infrastructure load for lower latency during error surges"], "summary": "Grab describes how its Hugo data ingestion platform reduced on-call toil by collecting failure, SLA and data quality signals, diagnosing root causes and auto-resolving transient failures. The system stores diagnoses in an RCA table and exposes health status through an API and a dashboard for users and downstream platforms.", "interview_angle": "How would you design an automated triage system for thousands of ingestion pipelines that classifies failures, auto-retries transient ones, and gives owners actionable root-cause context without manual log digging?", "score": 1.5791, "hn_points": 0, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/building-jetflow-a-framework-for-flexible-performant-data-pipelines-at-cloudflare", "company": "Cloudflare", "industry": "infra", "title": "Building Jetflow: a framework for flexible, performant data pipelines at Cloudflare", "date": "2025-07-23", "primary_problem": "performance", "problems": ["scale_ingestion", "cost"], "post_type": "case_study", "level": "advanced", "stack": ["Go", "Arrow", "Parquet", "ClickHouse", "PostgreSQL", "pgx", "ch-go", "Kafka", "BigQuery", "Spark", "YAML"], "scale": "141 billion rows/day ingested; 2-5 million rows/s per database connection", "key_decisions": ["Split the pipeline into consumer, transformer and loader stages with a shared Arrow in-memory format, trading a custom type system for stage interoperability", "Use deterministic partitions plus non-deterministic batches so retries can clean up exactly one partition, trading extra config concepts for idempotency", "Bypass generic database/sql scanning and row-based drivers in favour of columnar ClickHouse blocks and raw pgx bytes, trading driver convenience for throughput and lower GC pressure"], "summary": "Cloudflare's BI team built Jetflow, a Go framework that ingests thousands of tables (about 141 billion rows per day) from Postgres, ClickHouse, SaaS APIs and others into a petabyte-scale data lake. Its staged, config-driven design using Arrow as the internal format yielded large gains in throughput and memory efficiency over the legacy ELT system.", "interview_angle": "How would you design a high-throughput, idempotent ingestion framework that supports many source systems with retries, schema inference and low memory use?", "score": 1.5783, "hn_points": 6, "hn_comments": 0}, {"url": "https://netflixtechblog.com/timeseries-tiered-storage-journey-kafka-flink-streams-to-native-cassandra-cold-reads-e59d597c9d60", "company": "Netflix", "industry": "media", "title": "TimeSeries Tiered Storage Journey: Kafka/Flink Streams to Native Cassandra Cold Reads", "date": "2026-08-03", "primary_problem": "cost", "problems": ["storage_formats", "performance"], "post_type": "case_study", "level": "advanced", "stack": ["Kafka", "Flink", "Cassandra", "S3", "Parquet", "EVCache"], "scale": "Multiple petabytes per dataset; over 15 PB compressed in Cassandra cold storage; up to 1,250 cold reads per second globally (streaming tier)", "key_decisions": ["Streaming hot data into S3 Parquet via Kafka/Flink plus daily compaction: cheap object-store reads with small row groups and Bloom filters, but adds streaming infrastructure, data transfer cost and on-call burden", "Reading Cassandra backups in S3 directly through pluggable backup memtables and a custom ROCS compaction strategy: avoids a second copy and transfer costs, but makes reads CPU-heavy and requires immutability and backup-completeness checks", "Running cold reads on a separate, smaller Cassandra cluster pointed at the hot cluster's backups: isolates S3-backed read spikes from the hot path at the cost of extra topology to maintain"], "summary": "Netflix describes two ways to move older TimeSeries data from dense Cassandra hot storage to cheaper S3: first a Kafka/Flink pipeline that writes compacted Parquet files to S3, then a native design that serves reads straight from Cassandra backups via a custom compaction strategy and pluggable memtables. The second approach stores over 15 PB in cold tier and cuts attached storage while keeping p99 reads under roughly 500 ms.", "interview_angle": "How would you design a tiered storage system that keeps recent time-series data on fast disks and serves older data from object storage with bounded tail latency, and how would you decide between a separate streaming copy and reusing existing backups?", "score": 1.5778, "hn_points": 0, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/dns-targeted-zone-builds", "company": "Cloudflare", "industry": "infra", "title": "How we halved DNS build delay and cut memory use by 85%", "date": "2026-11-02", "primary_problem": "performance", "problems": ["realtime", "cost"], "post_type": "case_study", "level": "advanced", "stack": ["Kafka", "Quicksilver", "PostgreSQL", "Cloudflare Developer Platform", "Cloudflare Workers", "Durable Objects"], "scale": "About 700 DNS record changes per second plus about 100 other events; zones with over 20 million records; peak memory cut from 79 GiB to 12 GiB", "key_decisions": ["Targeted build planner rebuilds only the DNS names and metadata proven affected, trading planning complexity for far less work per change", "Fall back to full zone builds whenever the smaller build cannot be proven byte-for-byte equivalent, accepting slower builds for uncertain events", "Unified scheduler merges queued work per zone and uses soft Kafka offset commits, trading repeated replay after restarts for never losing a change"], "summary": "Cloudflare rebuilt its DNS propagation Zone Builder so that zone setting and record changes trigger the smallest provably safe rebuild instead of a full zone rebuild. The result was an 85% drop in peak memory and roughly halved median delay from DNS change to Quicksilver write.", "interview_angle": "How would you design an incremental rebuild pipeline that decides the minimum safe recomputation for each change, and what fallback and verification strategy would you use to guarantee output equivalence with a full rebuild?", "score": 1.5767, "hn_points": 200, "hn_comments": 80}, {"url": "https://blog.cloudflare.com/our-unified-data-platform", "company": "Cloudflare", "industry": "infra", "title": "How we built Cloudflare's data platform and an AI agent on top of it", "date": "2026-05-28", "primary_problem": "platform", "problems": ["governance_privacy", "lineage_catalog"], "post_type": "case_study", "level": "advanced", "stack": ["Trino", "Iceberg", "R2", "R2 Data Catalog", "DataHub", "ClickHouse", "PostgreSQL", "Kafka", "BigQuery", "Cloudflare Workers", "Cloudflare Workflows", "Durable Objects", "D1", "Workers AI", "Cloudflare Access", "MCP"], "scale": "More than 1 billion events per second; 700M+ events per second through analytics pipeline; 91,760 queries from 324 employees in a measurement period", "key_decisions": ["Default-closed access: new tables stay hidden until an automated PII scan and human review approve them, trading onboarding friction for safer governance", "Single Trino SQL layer over Postgres, ClickHouse and Iceberg on R2, trading engine complexity for avoiding data copies into one system", "Tiered compaction of Iceberg data (per-minute to hourly to daily) to cut storage cost while keeping old data queryable, at the cost of losing raw granularity for older data"], "summary": "Cloudflare built Town Lake, a lakehouse on Trino, Iceberg on R2 and DataHub, with Lifeguard for access control and Skimmer for automated PII detection, so employees can query data across many systems from one place. They also built Skipper, an AI agent on top that turns natural-language questions into grounded SQL, exposed via an MCP server using a code-mode pattern.", "interview_angle": "How would you design a company-wide analytics platform that unifies operational databases, ClickHouse and object storage while keeping PII locked down by default and letting non-SQL users self-serve?", "score": 1.5747, "hn_points": 3, "hn_comments": 4}, {"url": "https://engineering.grab.com/data-ingestion-transformation-product-insights", "company": "Grab", "industry": "mobility", "title": "How We Simplified Our Data Ingestion & Transformation Process", "date": "2019-03-03", "primary_problem": "realtime", "problems": ["scale_ingestion", "platform"], "post_type": "case_study", "level": "intermediate", "stack": ["Kafka", "Spark Streaming", "Go", "Protobuf", "Avro", "ORC", "S3", "TalariaDB", "Presto", "EMR"], "scale": "Hundreds of thousands of events per second; over 1 TB per hour; ~1 minute end-to-end lag", "key_decisions": ["Replaced Spark Streaming with a Go processing service to cut operational burden, trading away Spark's ecosystem for a leaner custom pipeline", "Dropped Avro and the intermediate S3 hop so data converts directly from Protobuf to ORC, reducing lag from 4-13 minutes to about 1 minute but requiring custom partitioning and memory tuning", "Ran old and new pipelines in parallel and validated with Presto EXCEPT queries before cutover, adding temporary duplicate infrastructure cost to ensure correctness"], "summary": "Grab rebuilt its real-time event ingestion path, replacing a Spark Streaming and S3-based pipeline with a simpler Go service that converts Protobuf directly to ORC. The change fixed data loss from S3 eventual consistency, cut lag from 4-13 minutes to about one minute, and reduced on-call load.", "interview_angle": "How would you design a high-throughput event ingestion pipeline that minimizes stages and lag while keeping the old and new pipelines verifiably equivalent during migration?", "score": 1.5734, "hn_points": 0, "hn_comments": 0}, {"url": "https://engineering.grab.com/kafka-connect", "company": "Grab", "industry": "mobility", "title": "How Kafka Connect helps move data seamlessly", "date": "2022-04-06", "primary_problem": "cdc_sync", "problems": ["platform", "scale_ingestion"], "post_type": "case_study", "level": "advanced", "stack": ["Kafka", "Kafka Connect", "Debezium", "MySQL", "MirrorMaker2", "Azure Event Hubs", "Confluent Schema Registry", "Protobuf", "Kubernetes", "Terraform", "S3", "Hudi", "Azure Data Explorer"], "scale": "TB/hour scale data platform (no specific figure given)", "key_decisions": ["Adopt Debezium on Kafka Connect for MySQL CDC so services write only to the database instead of dual-writing to Kafka, trading operational coupling for connector management overhead", "Run MirrorMaker2 as per-connector Kafka Connect deployments managed via Terraform rather than the bundled MM2 launcher, gaining finer control at the cost of more deployments to operate", "Build a custom Protobuf-to-JSON converter for mirroring into Azure Event Hubs, which avoids changing the Protobuf SerDes standard but requires maintaining in-house conversion code that is not open sourced"], "summary": "Grab's Coban real-time data platform team describes using Kafka Connect to move data in and out of Kafka, covering Debezium-based MySQL CDC, MirrorMaker2 for disaster recovery and cross-region or cross-cloud mirroring, and a custom Protobuf-to-JSON converter for Azure Event Hubs. The post explains how offset changes let CDC connectors survive database migrations and splits.", "interview_angle": "How would you replace dual writes between a database and Kafka with a reliable CDC pipeline, and how would you keep consumer offsets consistent when failing over to a backup cluster?", "score": 1.5718, "hn_points": 0, "hn_comments": 0}, {"url": "https://engineering.grab.com/pinot-partnergateway-tech-blog", "company": "Grab", "industry": "mobility", "title": "Powering Partner Gateway metrics with Apache Pinot", "date": "2025-09-23", "primary_problem": "performance", "problems": ["scale_ingestion", "storage_formats"], "post_type": "case_study", "level": "intermediate", "stack": ["Pinot", "Kafka", "Flink", "Protobuf", "Confluent Schema Registry", "Datadog", "AWS EBS", "Golang"], "scale": "~6.8 billion rows per 30 days; datasets over 150GB; star-tree raised 30-day storage from 192GB to 373GB", "key_decisions": ["Partitioning the Kafka topic by metric name improves locality and pruning but ties partition layout to query patterns", "Adding rounded time columns (Timestamp_1h) speeds hourly and daily aggregations at the cost of extra columns", "Star-tree index cut query latency from seconds to milliseconds but nearly doubled storage (192GB to 373GB), judged worth it versus maintaining an ETL precompute pipeline"], "summary": "Grab's Partner Gateway streams API request metrics through Kafka and Flink into Apache Pinot to power partner-facing time-series dashboards. Aggregation queries over 20 to 30 day windows were timing out, so the team combined metric-based partitioning, hourly rounded time columns, and a star-tree index to bring latencies down to milliseconds at a moderate storage cost.", "interview_angle": "How would you design a low-latency analytics store for API metrics over multi-week windows, and how do you trade query speed against index storage and partitioning choices?", "score": 1.5698, "hn_points": 0, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/http-analytics-for-6m-requests-per-second-using-clickhouse", "company": "Cloudflare", "industry": "infra", "title": "HTTP Analytics for 6M requests per second using ClickHouse", "date": "2018-03-06", "primary_problem": "scale_ingestion", "problems": ["performance", "migration"], "post_type": "case_study", "level": "advanced", "stack": ["ClickHouse", "Kafka", "Go", "PostgreSQL", "Citus", "Flink", "Cap'n Proto"], "scale": "6M HTTP requests per second (peaks ~8M), ~11M rows/s across pipelines, 36 ClickHouse nodes, 60+ billion rows migrated", "key_decisions": ["Replaced the Postgres/Citus aggregation pipeline with ClickHouse, trading a large operational footprint for a simpler system with materialized views doing aggregation", "Stored pre-aggregated minutely/hourly/daily data instead of raw logs for 1 year, because raw storage would cost roughly $1.9M-$28M per year, at the cost of losing flexible ad-hoc query detail", "Tuned index granularity per table (16384 for raw, 32 for aggregates) to cut API latency by about half and triple throughput, at the cost of a larger primary index for big scans"], "summary": "Cloudflare replaced its 2014-era Kafka, Postgres and Citus pipeline that produced HTTP analytics with a ClickHouse-based pipeline handling about 6M requests per second. The post walks through schema iterations using materialized views and SummingMergeTree, custom sumMap aggregation, index granularity tuning, and a one-time 60B-row historical backfill.", "interview_angle": "How would you design a per-customer analytics pipeline at millions of events per second that serves low-latency dashboard queries over a year of history, and when do you pre-aggregate versus keep raw data?", "score": 1.5687, "hn_points": 15, "hn_comments": 0}, {"url": "https://netflixtechblog.com/running-apache-spark-experiments-in-my-sleep-and-on-a-plane-588816b6b5f8", "company": "Netflix", "industry": "media", "title": "Running Apache Spark experiments in my sleep (and on a plane)", "date": "2026-08-31", "primary_problem": "performance", "problems": ["scale_ingestion", "platform"], "post_type": "case_study", "level": "advanced", "stack": ["Spark", "Maestro", "Dataflow", "tmux", "Scala"], "scale": "Tens of billions of hourly client events; full hourly unsampled production data per test run", "key_decisions": ["Run many full-scale Spark experiments in parallel via branch-isolated deployments, trading cluster contention for much faster iteration", "Unbox never-null fields and slim per-event bags, trading schema/field churn for lower executor memory and GC pressure", "Lower only AQE's runtime broadcast threshold to 10 MB instead of disabling broadcast joins globally, trading some join speed for memory headroom"], "summary": "Netflix tuned its member-sessionizer Spark pipeline, which builds viewing sessions from tens of billions of hourly events, by running many full-scale experiments in parallel on branch-isolated deployments with an AI agent handling operational polling and comparison. The root causes of executor OOMs were per-event weight growth inside collect_list bags, Option boxing, and AQE pinning cumulative broadcast tables, and the author concludes that tuning only buys headroom when data shape is unbounded.", "interview_angle": "How would you debug executor OOMs in a skewed sessionization job that only fails at full production scale, and how would you structure experiments to iterate quickly without sampling?", "score": 1.568, "hn_points": 0, "hn_comments": 0}, {"url": "https://netflixtechblog.com/introducing-impressions-at-netflix-e2b67c88c9fb", "company": "Netflix", "industry": "media", "title": "Introducing Impressions at Netflix", "date": "2025-02-15", "primary_problem": "scale_ingestion", "problems": ["realtime", "quality"], "post_type": "case_study", "level": "advanced", "stack": ["Flink", "Kafka", "Iceberg", "Avro"], "scale": "1 to 1.5 million impression events per second, ~1.2KB each, billions daily", "key_decisions": ["Dual-path output: Kafka for low-latency consumers and Iceberg for long-term history, trading duplicated storage paths for both real-time and batch access", "Stateless Flink job filters and enriches raw impressions into an Avro-schema source of truth, keeping processing simple but leaving events unschematized upstream", "Island model deployment with all job dependencies inside one region, improving regional fault isolation at the cost of per-region capacity planning"], "summary": "Netflix describes building a source-of-truth dataset for impressions by extracting impression events from a centralized raw event queue and running a stateless Flink job that filters, enriches, and validates them. The output goes to both Kafka and Apache Iceberg, with column-level quality metrics and alerting, and the post notes future work on schema management, autoscaling, and quality alerting.", "interview_angle": "How would you design a high-volume impression pipeline that serves both real-time consumers and long-term historical analysis, and how would you validate data quality along the way?", "score": 1.5674, "hn_points": 3, "hn_comments": 0}, {"url": "https://tech.instacart.com/zero-downtime-postgresql-cutovers-e6f16090fabf", "company": "Instacart", "industry": "marketplace", "title": "Zero-Downtime PostgreSQL Cutovers", "date": "2023-07-17", "primary_problem": "migration", "problems": ["cdc_sync", "platform"], "post_type": "case_study", "level": "advanced", "stack": ["PostgreSQL", "AWS RDS", "Python", "pgBouncer", "PgCat", "Temporal"], "scale": "Dozens of cutovers over ~1.5 years; downtime cut from about an hour to 5-10 seconds", "key_decisions": ["Use logical replication with an RDS snapshot restore and LSN fast-forward to avoid the slow initial COPY, trading complexity for far shorter setup time on large busy databases", "Cut over with a brief write pause and reverse replication from new primary to old, giving a fast rollback path at the cost of running and later tearing down two fleets", "Route traffic through pgBouncer/PgCat proxies so read replicas and primary can be repointed without disconnecting clients, at the cost of depending on proxy layer config"], "summary": "Instacart describes ZDC, a Python CLI that performs Blue/Green PostgreSQL cutovers using logical replication seeded from RDS snapshots, cutting downtime to roughly 5 to 10 seconds. The tool covers major version upgrades, instance class changes, and in-place table migrations like int-to-bigint, with automated pre-checks, guarded cutover, and fast rollback via reverse replication.", "interview_angle": "How would you perform a near-zero-downtime major version upgrade of a large, write-heavy database while keeping a fast rollback path and avoiding long WAL accumulation during initial replication setup?", "score": 1.5666, "hn_points": 19, "hn_comments": 3}, {"url": "https://engineering.grab.com/llm-powered-data-classification", "company": "Grab", "industry": "mobility", "title": "LLM-powered data classification for data entities at scale", "date": "2024-07-15", "primary_problem": "governance_privacy", "problems": ["lineage_catalog", "ml_data"], "post_type": "case_study", "level": "intermediate", "stack": ["GPT-3.5", "Azure OpenAI", "Kafka"], "scale": "More than 20,000 data entities scanned in first month, about 300-400 per day", "key_decisions": ["Use an LLM with a natural-language prompt and governance-defined tag library instead of training in-house classifiers, trading off determinism and output-format reliability for flexibility and no training data needs", "Run the LLM and a third-party classifier side by side while evaluating, accepting duplicated cost and orchestration complexity for a safer comparison", "Batch column-tagging requests through a queue with rate limiting and token budgeting, trading latency for staying within context and quota limits; predictions still require owner verification before becoming trusted"], "summary": "Grab's Gemini orchestration service uses GPT-3.5 alongside a third-party classifier to auto-tag columns of data entities with PII and business-type tags, using prompts that encode governance rules. Owners verify the predictions, which were published via Kafka and are intended to feed sensitivity tiers, ABAC and dynamic masking.", "interview_angle": "How would you automate sensitive-data classification across tens of thousands of tables and topics, handling LLM context limits, rate quotas, output validation, and human verification loops?", "score": 1.5584, "hn_points": 0, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/scaling-out-postgresql-for-cloudflare-analytics-using-citusdb", "company": "Cloudflare", "industry": "infra", "title": "Scaling out PostgreSQL for CloudFlare Analytics using CitusDB", "date": "2015-04-09", "primary_problem": "scale_ingestion", "problems": ["performance", "platform"], "post_type": "case_study", "level": "intermediate", "stack": ["PostgreSQL", "CitusDB", "Kafka", "Go", "Nginx", "Lua", "Cap'n Proto", "Snappy", "LZ4", "HyperLogLog", "hstore", "ZooKeeper", "Sarama", "lib/pq"], "scale": "Hundreds of TB of log data aggregated daily; millions of requests per second; ~1 million shards; 400% annual traffic growth", "key_decisions": ["Chose CitusDB to scale PostgreSQL horizontally so the team kept SQL and PostgreSQL tooling instead of building application-level sharding, at the cost of depending on a third-party extension vendor", "Used Kafka as a persistent buffer between the edge log shippers and the aggregators, gaining downtime tolerance and multi-consumer access while adding another distributed system to operate", "Pre-aggregated events into 1-minute rollups with 1-hour and 1-day rollups later, trading raw-event detail for fast dashboard queries; HyperLogLog keeps unique counts mergeable across rollups without storing raw IPs"], "summary": "CloudFlare rebuilt its customer analytics backend by moving log aggregation through Kafka and Go aggregators into a sharded CitusDB cluster, keeping PostgreSQL compatibility. The design uses many logical shards with replication for scale-out and failover, and HLL and hstore extensions to keep unique counts and sparse counters efficient.", "interview_angle": "How would you scale an analytics store that must answer sub-second per-customer queries over billions of rows while ingesting hundreds of TB per day, and how do you pick between application-level sharding and a distributed database extension?", "score": 1.5572, "hn_points": 120, "hn_comments": 11}, {"url": "https://netflixtechblog.com/scaling-muse-how-netflix-powers-data-driven-creative-insights-at-trillion-row-scale-aa9ad326fd77", "company": "Netflix", "industry": "media", "title": "Scaling Muse: How Netflix Powers Data-Driven Creative Insights at Trillion-Row Scale", "date": "2025-09-22", "primary_problem": "performance", "problems": ["modeling", "migration"], "post_type": "case_study", "level": "advanced", "stack": ["Druid", "Spark", "Hollow", "Iceberg", "Apache Datasketches", "Spring Boot", "GraphQL", "gRPC", "React", "Jupyter"], "scale": "Trillions of rows per year of impression and playback data", "key_decisions": ["Switched distinct counts to HyperLogLog sketches (logK 17, ~0.8% error) in Druid ingest and Spark ETL, trading a small accuracy loss for much cheaper distinct counting across long date ranges", "Moved high-volume, low-parameter lookups (distinct filter dimensions, all-time metrics) off Druid into in-memory Hollow feeds built from Iceberg tables, trading memory footprint and routing complexity for stable low latency", "Ran legacy and new metric stacks side by side with shadow traffic, offline notebook comparisons, and feature flags per segment, trading temporary duplication for safe rollback and data validation"], "summary": "Netflix's Muse analytics app outgrew its original Spark and Druid design as audience filtering caused a combinatorial explosion in data volume. The team moved distinct counts to HLL sketches, served precomputed aggregates from Hollow in-memory feeds, tuned Druid segments and ingest, and validated the change with a parallel rollout.", "interview_angle": "How would you serve interactive OLAP queries with distinct counts over trillions of rows, and when would you trade exactness for sketches or precompute results into a cache versus querying the OLAP store directly?", "score": 1.5511, "hn_points": 0, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/rewinding-the-exponential", "company": "Cloudflare", "industry": "infra", "title": "Rewinding the exponential: How we keep hardware usage down", "date": "2026-10-13", "primary_problem": "cost", "problems": ["scale_ingestion", "performance"], "post_type": "case_study", "level": "advanced", "stack": ["ClickHouse", "Buftee", "zstd", "LZ4"], "scale": "~2 billion events per second; ~70 GB/s compressed traffic eliminated from backbone", "key_decisions": ["Split the monolithic message schema into product-specific schemas: cut backbone bandwidth 35-40% but accepted duplicated fields across messages", "Switched compression from LZ4 to zstd: roughly 40% less compressed throughput for a CPU cost that was not noticeable in rollout, though CPU was tracked closely", "Moved cross-region replication late (after sampling, via Buftee) and dispatched each event once: removed ~43 GB/s of transit at the cost of new downstream replication and failover logic"], "summary": "Cloudflare's Data team describes several levers used to keep hardware and network costs flat while traffic grows exponentially: schema splitting, zstd compression, shared-ingest load balancing with late replication, sampling at the edge collector, and incremental aggregation across pipeline stages. The post quantifies the savings in backbone bandwidth, CPU and memory, framing them as deferred hardware expansion.", "interview_angle": "How would you reduce network and compute cost of a global log pipeline that is growing faster than hardware capacity, and where in the pipeline should sampling, aggregation and cross-region replication happen?", "score": 1.5402, "hn_points": 3, "hn_comments": 0}, {"url": "https://engineering.grab.com/building-a-spark-observability", "company": "Grab", "industry": "mobility", "title": "Building a Spark observability product with StarRocks: Real-time and historical performance analysis", "date": "2025-03-06", "primary_problem": "realtime", "problems": ["performance", "migration"], "post_type": "case_study", "level": "intermediate", "stack": ["StarRocks", "Kafka", "InfluxDB", "Telegraf", "Grafana", "Superset", "Spark", "S3", "Delta Lake", "Parquet", "Presto", "Golang"], "scale": "Worker metrics captured every 5 seconds; 33-day hot retention in StarRocks", "key_decisions": ["Replaced InfluxDB/Telegraf/Grafana with StarRocks, gaining full SQL and joins and direct Kafka routine-load ingestion, at the cost of running a new analytical database and migrating dashboards.", "Used asynchronous materialised views with partition TTL and selective partition refresh to precompute job-run summaries, trading some data freshness for fast UI queries.", "Kept a 33-day hot window with dynamic partitioning and daily S3 Parquet backups queried later via Delta tables, balancing cluster performance against long-term history access."], "summary": "Grab rebuilt its Spark observability tool Iris on StarRocks, ingesting worker and Spark metrics directly from Kafka and serving both real-time and 30-day historical job analysis from one store. Materialised views pre-join metadata and metrics for the UI, while partitioned retention and S3 backups keep the primary cluster fast.", "interview_angle": "How would you design a near-real-time observability store for high-cardinality job metrics that also supports fast historical queries, retention, and archival to a data lake?", "score": 1.5338, "hn_points": 1, "hn_comments": 1}, {"url": "https://engineering.grab.com/the-journey-of-deploying-apache-airflow-at-Grab", "company": "Grab", "industry": "mobility", "title": "The Journey of Deploying Apache Airflow at Grab", "date": "2020-07-14", "primary_problem": "platform", "problems": ["scale_ingestion", "quality"], "post_type": "case_study", "level": "intermediate", "stack": ["Airflow", "Kubernetes", "Amazon EKS", "Terraform", "Helm", "Redis", "PostgreSQL", "HashiCorp Vault", "ELK stack", "Datadog", "PagerDuty", "GitLab CI/CD", "Presto", "Atlantis", "Celery"], "scale": "Close to 20 Airflow instances, each scheduling 1k to 60k daily jobs, thousands of daily jobs overall", "key_decisions": ["One isolated Airflow instance per team on a shared EKS cluster: strong team isolation and shared infrastructure efficiency, but requires a dedicated platform team and ownership guidelines.", "Single Airflow version supported across all instances with a common base image: lower maintenance overhead, but teams must upgrade in lockstep and only one old version is kept during transitions.", "Infrastructure and instance config managed as Terraform modules with Atlantis, and instances sized into small/medium/large tiers: consistent and reproducible deployments, though every resource change goes through the platform team's code path."], "summary": "Grab's Airflow team consolidated many per-team Airflow installs into a shared scheduling platform that runs close to 20 isolated instances on Kubernetes (EKS). The post covers the design around per-team customised images, Terraform-managed infrastructure, secrets via Vault, logging, Datadog monitoring, and autoscaling workers.", "interview_angle": "How would you design a multi-tenant orchestration platform for many data teams, balancing isolation, shared infrastructure cost, upgrade coordination and per-team dependency customisation?", "score": 1.5333, "hn_points": 0, "hn_comments": 0}, {"url": "https://engineering.grab.com/signals-market-place", "company": "Grab", "industry": "mobility", "title": "Data mesh at Grab part I: Building trust through certification", "date": "2025-08-19", "primary_problem": "lineage_catalog", "problems": ["quality", "platform"], "post_type": "case_study", "level": "intermediate", "stack": ["DataHub"], "scale": "75% of queries hitting certified assets; P80 datasets reduced by over 58%", "key_decisions": ["Assign decentralised ownership to data domains with business and technical owners, trading some central control for accountability and clearer upkeep", "Certify datasets via data contracts covering schema, freshness, completeness and retention, which adds upfront producer effort but gives consumers reliable guarantees", "Use percentage of queries hitting certified assets as the north star metric, which drives adoption but can incentivise certifying popular tables over covering everything"], "summary": "Grab describes its data mesh effort, the Signals Marketplace, which certifies trustworthy datasets through domain ownership, data contracts and automated incident tickets for breached contracts. The campaign reached 75% of queries hitting certified assets and reduced redundant datasets, with the next post covering the Genchi and Hubble tooling.", "interview_angle": "How would you design a data certification program across many decentralised domain teams so that consumers can trust and discover reliable datasets, and how would you measure adoption?", "score": 1.5328, "hn_points": 0, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/migrating-billions-of-records-moving-our-active-dns-database-while-in-use", "company": "Cloudflare", "industry": "infra", "title": "Migrating billions of records: moving our active DNS database while it\u2019s in use", "date": "2024-10-29", "primary_problem": "migration", "problems": ["cdc_sync", "scale_ingestion"], "post_type": "case_study", "level": "advanced", "stack": ["PostgreSQL", "pgLogical", "psql", "Bash", "gRPC"], "scale": "1.7B rows in cf_rec (1.5 TB), 4.3B rows in cf_archived_rec, 3-5M inserts/day into cf_rec, switchover under 2 seconds", "key_decisions": ["Built a trigger-based change capture table and batched transfer service instead of pgLogical, trading replication elegance for auditability and bidirectional switching", "Used a pause-able batched initial copy with per-batch count validation rather than a single multi-hour dump, trading simplicity for resumability and safety", "Routed all writes through a gRPC DNS Records API with a migration manager lock, trading upfront service migration effort for a single cutover point that keeps downtime to seconds"], "summary": "Cloudflare moved its DNS records tables (over a billion rows) from the shared cfdb Postgres cluster to a dedicated dnsdb cluster while live. They used trigger-based change capture, batched transfer with count-based audits, and a gRPC API with a write lock to cut over in about two seconds.", "interview_angle": "How would you migrate a large, write-heavy production table to a new database with near-zero downtime, bidirectional rollback, and verifiable data integrity?", "score": 1.5326, "hn_points": 16, "hn_comments": 0}, {"url": "https://netflixtechblog.com/netflixs-distributed-counter-abstraction-8d0c45eb66b2", "company": "Netflix", "industry": "media", "title": "Netflix\u2019s Distributed Counter Abstraction", "date": "2024-11-12", "primary_problem": "scale_ingestion", "problems": ["realtime", "storage_formats"], "post_type": "deep_dive", "level": "advanced", "stack": ["Cassandra", "EVCache", "Memcached", "Kafka", "Flink", "Kafka Streams", "Redis"], "scale": "About 75K count requests/second globally", "key_decisions": ["Log every counter mutation as an immutable event and aggregate in the background, trading a few seconds of read staleness for accurate, auditable counts and idempotent retries.", "Use an immutable aggregation window (accept limit plus clock-skew margin) so rollups can run without distributed locks, accepting possible duplicate work and transient count fluctuations.", "Keep a best-effort counter on EVCache for cheap, fast approximate counts, rejecting HyperLogLog and Count-Min Sketch because they lack resets, TTLs and simple increment semantics."], "summary": "Netflix describes a distributed counting service built on its TimeSeries abstraction, offering a best-effort EVCache-backed counter and an eventually consistent counter that logs every increment and rolls them up in the background. The design trades a few seconds of read staleness and some duplicate aggregation work for idempotent, auditable counts with single-digit millisecond reads at about 75K requests per second.", "interview_angle": "How would you design a globally distributed counter that supports idempotent retries, resets and auditing while keeping reads fast and avoiding hot-key write contention?", "score": 1.5326, "hn_points": 133, "hn_comments": 71}, {"url": "https://blog.cloudflare.com/log-analytics-using-clickhouse", "company": "Cloudflare", "industry": "infra", "title": "Log analytics using ClickHouse", "date": "2022-09-02", "primary_problem": "storage_formats", "problems": ["scale_ingestion", "performance"], "post_type": "case_study", "level": "advanced", "stack": ["ClickHouse", "Elasticsearch", "Kafka", "Logstash", "Kibana", "Grafana", "Cap'n Proto", "Vector", "ZooKeeper", "clickhouse-keeper"], "scale": "35-45 million HTTP requests/s; 500K-800K failed requests/s logged; 600 bytes to 60 bytes per row after migration", "key_decisions": ["Replaced Elasticsearch with ClickHouse for error logs, trading full-text search flexibility for columnar storage and sparse indexes that cut per-row size about 10x and allowed removing sampling", "Chose a fixed-schema or array-based table layout over schemaless JSON ingestion, limiting flexibility but protecting the cluster from fields explosion by a single noisy application", "Partitioned by hour and used data-skipping bloom filter indexes plus ABR multi-resolution tables, trading storage duplication for faster, approximate dashboard queries"], "summary": "Cloudflare's SRE team moved its request error logging pipeline from sampled Elasticsearch storage to ClickHouse to remove sampling, cut resource use, and speed up dashboards. The post covers ClickHouse schema options, batch sizing, hourly partitioning, skipping indexes, and multi-resolution ABR tables for approximate analytics.", "interview_angle": "How would you design a log analytics store that ingests tens of millions of events per second, keeps every row for weeks, and serves fast aggregate dashboards while controlling schema drift and cost?", "score": 1.5311, "hn_points": 38, "hn_comments": 0}, {"url": "https://stripe.com/blog/online-migrations", "company": "Stripe", "industry": "fintech", "title": "Online migrations at scale", "date": "2017-02-02", "primary_problem": "migration", "problems": ["cdc_sync", "scale_ingestion"], "post_type": "case_study", "level": "advanced", "stack": ["Hadoop", "Scalding", "MapReduce", "Scientist", "Ruby", "Scala"], "scale": "Hundreds of millions of Subscriptions objects", "key_decisions": ["Four-phase dual-write migration (dual write, switch reads, switch writes, remove old data) keeps services live but requires long periods running two stores in parallel.", "Offline Hadoop/Scalding snapshot scans find objects to migrate instead of querying production, trading pipeline complexity for zero production load.", "Scientist read-path experiments compare old and new results in production, catching inconsistencies early at the cost of extra read traffic and custom alerting."], "summary": "Stripe describes how it moved hundreds of millions of Subscriptions objects out of the Customer record into a separate table without downtime. The method is a four-phase dual-write rollout, with offline Hadoop jobs used to find records to backfill and Scientist experiments used to verify reads and writes.", "interview_angle": "How would you migrate a high-volume table to a new data model with zero downtime and no inconsistent reads? Walk through dual writes, backfill strategy, read verification and cleanup.", "score": 1.5306, "hn_points": 268, "hn_comments": 56}, {"url": "https://netflixtechblog.com/the-data-canary-how-netflix-validates-catalog-metadata-18b699d58e36", "company": "Netflix", "industry": "media", "title": "The Data Canary: How Netflix Validates Catalog Metadata", "date": "2026-02-06", "primary_problem": "quality", "problems": ["realtime", "platform"], "post_type": "case_study", "level": "advanced", "stack": ["Netflix chaos platform", "REST"], "scale": "Catalog validation every ~10 minutes; about 0.2% of global traffic routed through validation; issues detected in 2.5-4 minutes", "key_decisions": ["Run a dedicated orchestrator with permanent baseline and canary clusters to validate data output, trading extra infrastructure for isolation and no self-testing", "Use production traffic and Starts Per Second as the signal instead of shadow traffic or technical error metrics, trading some statistical confidence for speed and direct customer-impact detection", "Abort experiments immediately on regression rather than collecting full post-hoc data, accepting weaker statistical confidence to fit the 10-minute publish cycle"], "summary": "Netflix built an automated data canary that validates transformed catalog metadata by running chaos-style experiments on a canary cluster against production traffic before publishing. The system blocks bad data within a single data cycle, detecting injected corruption in 2.5 to 4 minutes.", "interview_angle": "How would you validate transformed data output before publishing it to production consumers within a short refresh window, and which customer-impact metric would you use as the signal?", "score": 1.5305, "hn_points": 0, "hn_comments": 0}, {"url": "https://engineering.grab.com/an-elegant-platform", "company": "Grab", "industry": "mobility", "title": "An elegant platform", "date": "2023-11-30", "primary_problem": "platform", "problems": ["cdc_sync", "lineage_catalog"], "post_type": "case_study", "level": "advanced", "stack": ["Kafka", "Flink", "Kafka Connect", "Apache Zeppelin", "Terraform", "GitLab", "Atlantis", "React", "Go", "MySQL", "DataHub", "backstage.io", "Slack", "S3"], "scale": "About 5000 data streaming resources; monthly active users almost quadrupled; API uptime above 99.95%", "key_decisions": ["Built a three-tier control plane (UI, Go back-end Heimdall, Git-based Khone) so users get ClickOps simplicity while Terraform stays the source of truth, trading extra system complexity for lower entry barrier.", "Made Khone Git repository the only persistent store and let Heimdall cache from it, accepting eventual consistency in exchange for auditability and disaster recovery from Git.", "Kept full per-environment instances of the platform with tight SLOs in staging and production, rather than a shared production control plane, which improves segregation but costs tighter maintenance windows upstream."], "summary": "Grab's Coban team describes moving its real-time data streaming platform from a raw Terraform merge-request workflow to a three-tier control plane with a web UI, a Go back-end and a GitOps storage layer. The design lowers the barrier for self-service Kafka, Flink, CDC and connector resources and exposes resource metadata and lineage to other internal platforms.", "interview_angle": "How would you design a self-service control plane for streaming infrastructure that keeps IaC benefits (audit, DR, consistency) while hiding Terraform from non-expert users?", "score": 1.5203, "hn_points": 1, "hn_comments": 0}, {"url": "https://netflixtechblog.com/1-streamlining-membership-data-engineering-at-netflix-with-psyberg-f68830617dd1", "company": "Netflix", "industry": "media", "title": "Streamlining Membership Data Engineering at Netflix with Psyberg", "date": "2023-11-15", "primary_problem": "late_data", "problems": ["storage_formats", "performance"], "post_type": "case_study", "level": "advanced", "stack": ["Iceberg", "Kafka"], "scale": "", "key_decisions": ["Use Iceberg snapshot and partition metadata to detect changed partitions instead of fixed lookback windows, trading added metadata complexity for far less redundant reprocessing", "Keep a session table and high watermark table per pipeline to track processed event-time and processing-time ranges, which adds state to manage but makes runs independently auditable and recoverable", "Automate late-data handling inside the framework rather than manual backfills, which removes on-call toil but requires the framework to be trusted across all pipelines"], "summary": "Netflix's Membership and Finance data engineering team built Psyberg, an incremental processing framework on Iceberg, to handle late-arriving events in hourly and daily batch pipelines. The post explains the pain of fixed lookback reprocessing and manual backfills, and how Iceberg snapshot and partition metadata plus Psyberg's own session and watermark tables let pipelines detect and reprocess only what changed.", "interview_angle": "How would you design an incremental batch pipeline that handles late-arriving events across hourly partitions without reprocessing the entire lookback window or relying on manual backfills?", "score": 1.519, "hn_points": 2, "hn_comments": 0}, {"url": "https://engineering.grab.com/search-indexing-optimisation", "company": "Grab", "industry": "mobility", "title": "Search indexing optimisation", "date": "2021-09-27", "primary_problem": "cdc_sync", "problems": ["realtime", "performance"], "post_type": "case_study", "level": "advanced", "stack": ["MySQL", "Elasticsearch", "Kafka", "Go"], "scale": "Stream QPS rose from 200 to 800 (peaks 1000+); about 91% DB reads saved and 90% Elasticsearch reads saved", "key_decisions": ["Use MySQL row-based Binlog before/after payloads instead of application-produced events, gaining full capture (including CLI edits) at the cost of depending on a shared CDC system", "Filter events by diffing before/after payloads against Elasticsearch-relevant fields, cutting redundant reads and writes but requiring a maintained field subset", "Merge events in the in-memory buffer and send partial updates, reducing load but making ordering and merge correctness critical; cascade updates routed to a separate partitioned stream to dedupe by ID"], "summary": "Grab's Deliveries search team reworked its MySQL-to-Elasticsearch incremental sync pipeline in their Data Synchronisation Platform, moving from application-emitted notifications to MySQL Binlog-based CDC events. The changes filter irrelevant events, switch to partial document updates, merge buffered events, and isolate cascade updates, cutting database and Elasticsearch read load substantially.", "interview_angle": "How would you keep a search index in sync with a relational source at high write volume without hammering the database? Discuss CDC from the binlog, filtering and partial updates, in-memory deduplication keyed by primary key, and handling fan-out updates from one-to-many relationships.", "score": 1.5174, "hn_points": 0, "hn_comments": 0}, {"url": "https://engineering.grab.com/counter-service-storage-migration", "company": "Grab", "industry": "mobility", "title": "Migrating Counter Service storage: Design choices and learnings", "date": "2026-07-03", "primary_problem": "migration", "problems": ["modeling", "cost"], "post_type": "case_study", "level": "advanced", "stack": ["Aerospike", "Rust", "Cassandra-style wide-column database", "Tokio"], "scale": "Tens of thousands of QPS, about 1 billion requests per day; primary index ~50 GB of ~100 GB usable per node; ~1 TB on disk vs ~3 TB before", "key_decisions": ["Used a concrete facade with enum dispatch and config-driven Single/WithShadow/WithSplit modes instead of a trait with associated types or boxed trait objects, trading some extensibility for zero per-query allocation and simpler runtime backend selection.", "Collapsed row-per-bucket records into one map-valued record per counter, cutting record count by over an order of magnitude and shrinking index memory and disk, at the cost of explicit pruning of stale map entries since record-level TTL no longer fits.", "Kept the in-memory primary index instead of moving it to NVMe, since hot-key contention caused p99 spikes; accepted higher memory-optimized instance cost to avoid that latency risk."], "summary": "Grab migrated its Counter Service, which answers time-windowed fraud counts, from a wide-column database to Aerospike using shadow reads and writes and a config-driven percentage rollout. The biggest gains came from redesigning the schema to store each counter's time series as one map-valued record, which cut storage, index memory and cost, and the team also reduced replication factor from 3 to 2.", "interview_angle": "How would you migrate a high-QPS time-windowed counting store with zero downtime, including dual-write or shadow validation, gradual traffic ramp and rollback, and a schema change that trades record count against per-record size and TTL management?", "score": 1.517, "hn_points": 0, "hn_comments": 0}, {"url": "https://netflixtechblog.com/how-netflix-uses-ebpf-flow-logs-at-scale-for-network-insight-e3ea997dca96", "company": "Netflix", "industry": "media", "title": "How Netflix uses eBPF flow logs at scale for network insight", "date": "2021-06-07", "primary_problem": "scale_ingestion", "problems": ["realtime", "lineage_catalog"], "post_type": "case_study", "level": "advanced", "stack": ["eBPF", "Kafka", "Keystone", "Hive", "Druid", "Atlas", "Lumen"], "scale": "Billions of eBPF flow logs per hour, under 1% CPU and memory per instance", "key_decisions": ["Run a per-instance eBPF sidecar for flow capture, accepting a small resource footprint in exchange for network-level visibility without application changes", "Choose transport protocol (gRPC, HTTPS or UDP) per instance placement, trading uniform behavior for reliability across varied network setups", "Attribute IP addresses to applications in a regional collector using a time-aware identity service, adding a stateful dependency but handling IP reuse as workloads move"], "summary": "Netflix built Flow Exporter, an eBPF-based sidecar that captures TCP flow records near real time with minimal overhead on each instance. A regional Flow Collector enriches those flows with time-aware application identity from Sonar via Kafka, then routes them through Keystone into Hive and Druid for dashboards, forecasting and security analysis.", "interview_angle": "How would you design a pipeline that ingests billions of per-host network events per hour and joins them with a time-varying IP-to-service mapping so that historical attribution stays correct?", "score": 1.5108, "hn_points": 310, "hn_comments": 34}, {"url": "https://medium.com/paypal-tech/leveraging-spark-3-and-nvidias-gpus-to-reduce-cloud-cost-by-up-to-70-for-big-data-pipelines-e0bc02ec4f88", "company": "PayPal", "industry": "fintech", "title": "Leveraging Spark 3 and NVIDIA\u2019s GPUs to Reduce Cloud Cost by up to 70% for Big Data Pipelines", "date": "2024-02-21", "primary_problem": "cost", "problems": ["performance", "platform"], "post_type": "case_study", "level": "advanced", "stack": ["Spark", "Spark RAPIDS", "NVIDIA GPUs", "NVIDIA Tesla T4", "Spark 2", "Spark 3"], "scale": "Hundreds of thousands of Spark jobs per hour; one job reads 9.5 TB input across ~185,000 default partitions", "key_decisions": ["Raised spark.sql.files.maxPartitionBytes to 2GB and enabled AQE with 1GB advisory partition size to get fewer, larger partitions; trade-off is less parallelism per stage in exchange for GPU-friendly compute-bound work and ~30% runtime cut.", "Moved the candidate job from a 140-node CPU cluster to a 30-node GPU cluster with Tesla T4s; trade-off is GPU memory limits forcing low spark.rapids.sql.concurrentGpuTasks (2) and more local SSD and spill storage.", "Doubled local SSDs per node and raised spill storage to 32GB after GPU memory pressure pushed spills to disk; trade-off is extra disk cost, judged minor versus compute savings."], "summary": "PayPal tested whether running Spark jobs on GPUs via the Spark RAPIDS accelerator could cut cloud costs for large SQL and shuffle-heavy workloads. Tuning partition sizes under Spark 3 with AQE and then moving to a smaller T4 GPU cluster reportedly reduced cost by up to about 70%, with memory and spill issues handled by tuning concurrency and disks.", "interview_angle": "How would you cut the cost of a large batch Spark workload without rewriting it? Discuss partition sizing (maxPartitionBytes, AQE advisory size), right-sizing the cluster, and the GPU memory and spill trade-offs of an accelerator.", "score": 1.5099, "hn_points": 8, "hn_comments": 1}, {"url": "https://engineering.grab.com/evaluate-performance-remove-redis-from-scylla-service", "company": "Grab", "industry": "mobility", "title": "Evaluating performance impact of removing Redis-cache from a Scylla-backed service", "date": "2025-04-11", "primary_problem": "performance", "problems": ["cost", "scale_ingestion"], "post_type": "case_study", "level": "advanced", "stack": ["Scylla", "Redis", "Rust", "MySQL", "Hystrix"], "scale": "Tens of thousands of QPS at peak, ~10 lookups per batch request, Scylla cache hit rate rising to ~70%", "key_decisions": ["Removed the Redis cache layer so reads go straight to Scylla, trading an external cache for Scylla's internal cache, which cut ~25% of service cost", "Rolled out the cache removal gradually by configuration ID, using a deterministic operator instead of random percentage rollout, to limit blast radius", "Added a daily daytime major compaction on Scylla to recover latency lost after cache removal, accepting extra background compaction load"], "summary": "Grab evaluated removing a Redis cache in front of a Rust read service backed by Scylla, because 15-minute key truncation caused synchronized cache misses and Scylla QPS spikes. Gradual rollout showed Scylla's own cache absorbed the load, keeping latency stable and cutting cost, with an extra daily compaction job needed to recover latency.", "interview_angle": "How would you design a time-bucketed counter read path so that cache keys don't expire in sync and cause thundering-herd spikes on the backing store, and when is removing a cache layer actually better?", "score": 1.5065, "hn_points": 0, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/18-november-2025-outage", "company": "Cloudflare", "industry": "infra", "title": "Cloudflare outage on November 18, 2025", "date": "2025-11-18", "primary_problem": "quality", "problems": ["platform", "governance_privacy"], "post_type": "postmortem", "level": "advanced", "stack": ["ClickHouse", "Rust", "Pingora", "Workers KV", "Turnstile"], "scale": "Core network outage ~5.5 hours (11:20 to 17:06 UTC); feature file doubled past a 200-feature limit (~60 in use)", "key_decisions": ["Generating the bot feature file via a ClickHouse query over Distributed tables: a metadata-visibility change caused duplicate column rows from another database, which is a trade-off between fine-grained permissions and query-output stability", "Preallocating memory with a hard 200-feature limit for performance: fast and predictable, but an oversized input caused a panic instead of graceful rejection", "Propagating config files globally every few minutes for fast bot-response updates: quick reaction to threats, but a bad file reached every machine at once with no staged rollout or kill switch"], "summary": "Cloudflare's postmortem traces a global outage to a ClickHouse permission change that made a feature-generation query return duplicate column rows, doubling a config file that was then pushed network-wide. The proxy's preallocated feature limit was exceeded, causing panics and 5xx errors until a known-good file was restored.", "interview_angle": "How would you design validation and staged rollout for a generated config file consumed by a fleet, so that a bad upstream query cannot propagate globally in minutes?", "score": 1.5054, "hn_points": 1465, "hn_comments": 916}, {"url": "https://shopify.engineering/reliably-scale-data-platform", "company": "Shopify", "industry": "ecommerce", "title": "How to Reliably Scale Your Data Platform for High Volumes", "date": "2020-12-08", "primary_problem": "scale_ingestion", "problems": ["performance", "platform"], "post_type": "case_study", "level": "advanced", "stack": ["Spark", "dbt", "Parquet", "Kafka", "BigTable", "Google Cloud Storage", "Cloud SQL", "Google Kubernetes Engine", "MySQL", "ProxySQL"], "scale": "880 billion MySQL records and 1.75 trillion Kafka messages per month; ~150% average throughput increase during BFCM", "key_decisions": ["Classify services into tiers by merchant impact so reliability budget goes to Tier 1 and Tier 2 ingestion and processing systems first", "Stress-test ingestion and query services by deliberately shrinking compute headroom or inflating overlap windows, trading engineering time for confidence in failure behavior", "Tune job frequency, overlap intervals and Kubernetes resources for freshness, and pool sizes for latency, accepting extra compute cost for safety margin"], "summary": "Shopify's Data Platform Engineering team describes how it prepared ingestion, processing and query services for Black Friday and Cyber Monday traffic that rose about 150 percent. They ranked services by tier, identified each service's primary objective and tuning levers, ran controlled load tests, and verified that alerts and mitigations were actionable.", "interview_angle": "How would you prepare a batch ingestion pipeline and a low-latency query service for a known traffic spike, and which knobs would you test first to protect freshness and latency SLOs?", "score": 1.5053, "hn_points": 61, "hn_comments": 4}, {"url": "https://engineering.grab.com/trident-real-time-event-processing-at-scale", "company": "Grab", "industry": "mobility", "title": "Trident - Real-time Event Processing at Scale", "date": "2021-01-13", "primary_problem": "realtime", "problems": ["scale_ingestion", "performance"], "post_type": "case_study", "level": "advanced", "stack": ["Kafka", "Redis", "MySQL", "Go"], "scale": "More than 2,000 events per second at peak; billions of events and thousands of campaigns per day; ~half a billion rewards and 2.5 billion messages in October 2020", "key_decisions": ["Matched Kafka partition count to consumer auto-scaling group so every instance gets work, at the cost of coupling partition planning to server scaling config", "Prefiltered campaigns by event type in an in-memory hash map and ordered rule conditions by data-source cost with AND/OR-aware short-circuiting, trading code complexity for much less evaluation work", "Used Redis for 24-hour event deduplication plus MySQL for triggered-action keys, accepting a small window of dedup guarantees in exchange for exactly-once-style processing on top of at-least-once Kafka"], "summary": "Grab's Trident is a real-time IFTTT engine that evaluates billions of events against thousands of campaigns daily to award rewards and send messages. The post covers how it scales through Kafka consumer alignment, rule evaluation optimisations, rate-limiting downstream calls, and MySQL/Redis tuning for hot counters.", "interview_angle": "How would you design a high-throughput event-driven rules engine that must process each event exactly once, stay within downstream rate limits, and keep hot campaign counters from overwhelming the database?", "score": 1.4998, "hn_points": 1, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/squeezing-the-firehose", "company": "Cloudflare", "industry": "infra", "title": "Squeezing the firehose: getting the most from Kafka compression", "date": "2018-03-05", "primary_problem": "cost", "problems": ["scale_ingestion", "performance"], "post_type": "case_study", "level": "advanced", "stack": ["Kafka", "Go", "sarama", "Snappy", "LZ4", "Zstandard", "gzip", "lzbench", "Java"], "scale": "Requests topic up to 100 Gbps and 7.5M requests/s at peak; 4.5x size reduction with zstd", "key_decisions": ["Chose Snappy over gzip for producers because gzip's CPU cost was too high in Go, then moved to zstd level 6 for a better ratio at similar throughput. Trade-off: a non-standard patched Kafka build and clients.", "Benchmarked codecs on real batches rather than trusting synthetic or vendor numbers, after an early test was invalidated by broker-side recompression. Trade-off: extra engineering time for accurate measurements.", "Shifted the bottleneck from disk and network to CPU by compressing, which let them cancel a planned hardware expansion. Trade-off: higher broker and producer CPU use."], "summary": "Cloudflare describes adopting Kafka compression for its log pipelines, progressing from Snappy to a patched zstd implementation after discovering broker-side recompression that skewed early tests. The move cut the HTTP request log topic size by about 4.5x versus uncompressed and let them skip a hardware expansion.", "interview_angle": "How would you cut the storage and network cost of a high-throughput Kafka log pipeline, and how would you validate a codec choice with real data before rolling it out?", "score": 1.492, "hn_points": 2, "hn_comments": 0}, {"url": "https://engineering.zalando.com/posts/2026/03/why-we-ditched-flink-table-api-joins-cutting-state.html", "company": "Zalando", "industry": "ecommerce", "title": "Why We Ditched Flink Table API Joins: Cutting State by 75% with DataStream Unions", "date": "2026-03-03", "primary_problem": "cost", "problems": ["realtime", "performance"], "post_type": "case_study", "level": "advanced", "stack": ["Flink", "Flink SQL", "Table API", "DataStream API", "RocksDB", "AWS Managed Service for Apache Flink", "S3", "Scala"], "scale": "240GB state reduced to 56GB per application", "key_decisions": ["Replaced chained stateful SQL joins with a single keyed KeyedProcessFunction over a unioned stream, trading declarative simplicity for explicit state control", "Stored one compact state object per SKU instead of per-join copies, removing TTLs and keeping last-known values forever, which cuts state but requires manual handling of dedup and out-of-order updates", "Accepted a smaller-than-expected cost gain (13%) since CPU and memory are driven by throughput, not state size; the main win was stability and reduced overscaling"], "summary": "Zalando's Product Offer Enrichment jobs in Flink SQL accumulated about 240GB of RocksDB state from chained joins, causing CPU-saturated snapshots, restart loops and overscaling. Rewriting the pipeline as a unioned DataStream with one keyed processor per SKU cut state to 56GB, shortened snapshots and restarts, and lowered AWS costs by about 13%.", "interview_angle": "How would you design a streaming enrichment join across several streams with different speeds that keeps state bounded and avoids duplicating data per join stage?", "score": 1.4918, "hn_points": 0, "hn_comments": 0}, {"url": "https://eng.lyft.com/evolution-of-streaming-pipelines-in-lyfts-marketplace-74295eaf1eba", "company": "Lyft", "industry": "mobility", "title": "Evolution of Streaming Pipelines in Lyft\u2019s Marketplace", "date": "2022-09-27", "primary_problem": "realtime", "problems": ["scale_ingestion", "platform"], "post_type": "case_study", "level": "advanced", "stack": ["Beam", "Kafka"], "scale": "Tens of millions of events per second for feature generation; end-to-end latency under 1 minute", "key_decisions": ["Moved dynamic pricing from minute-level cronjob DAGs to streaming with Apache Beam, cutting latency and feature development time but adding new framework learning curve", "Split one overloaded pipeline into separate feature-generation and model-execution pipelines so each scales, is isolated and releases independently, at the cost of more moving parts", "Decomposed feature generation into shared ingestion pipelines publishing to Kafka plus feature aggregation pipelines, deprecating ~40% of duplicate features in exchange for centralized ownership and standards"], "summary": "Lyft describes how its marketplace pricing streaming platform evolved from a minute-level cronjob DAG to Apache Beam pipelines, then split feature generation from model execution to fix throughput problems. Later it added YAML-based pipeline authoring and shared Kafka-based feature pipelines to support many teams, with root-cause tooling still in progress.", "interview_angle": "How would you redesign a streaming feature pipeline that has become throughput-bound and hard to operate across many teams, and when should you split one pipeline into independently scaled stages?", "score": 1.489, "hn_points": 0, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/timescaledb-art", "company": "Cloudflare", "industry": "infra", "title": "How TimescaleDB helped us scale analytics and reporting", "date": "2025-07-08", "primary_problem": "performance", "problems": ["cost", "modeling"], "post_type": "case_study", "level": "advanced", "stack": ["PostgreSQL", "TimescaleDB", "ClickHouse", "Kafka", "Kubernetes"], "scale": "~1,000 inserts/sec at DEX scale; billions of rows; 1 to 1 billion row datasets; ~100,000 aggregated rows/sec in ART; 33x compression", "key_decisions": ["Chose PostgreSQL over ClickHouse for an MVP to avoid adding boxes and ingestion complexity, trading away peak OLAP throughput for simplicity", "Used composite B-tree indexes ordered by cardinality with timestamp last, gaining query speed but requiring careful index design", "Adopted TimescaleDB hypertables with columnstore, compression and continuous aggregates, which removed custom cron-based rollups at the cost of extension-specific behavior and needing explicit orderby for sparse indexes"], "summary": "Cloudflare's DEX team started with plain PostgreSQL for device log analytics, then hit performance limits at billions of rows and moved to TimescaleDB for hypertables, columnstore compression, sparse minmax indexes and continuous aggregates. The Zero Trust ART team later reused TimescaleDB as an aggregation layer, tuning ingestion with COPY and relaxed durability settings.", "interview_angle": "How would you design a time-series analytics store for per-device logs with dashboards over 7-day windows, and when would you pick a Postgres extension over a dedicated OLAP engine like ClickHouse?", "score": 1.4883, "hn_points": 4, "hn_comments": 2}, {"url": "https://netflixtechblog.com/introducing-netflix-timeseries-data-abstraction-layer-31552f6326f8", "company": "Netflix", "industry": "media", "title": "Introducing Netflix\u2019s TimeSeries Data Abstraction Layer", "date": "2024-10-08", "primary_problem": "scale_ingestion", "problems": ["performance", "storage_formats"], "post_type": "deep_dive", "level": "advanced", "stack": ["Cassandra", "Elasticsearch", "JDK 21", "ZGC", "Netflix Data Gateway Platform"], "scale": "Up to 10M writes/sec design target; ~15M events/sec peak globally; petabytes stored", "key_decisions": ["Time-slice tables dropped whole for retention instead of row-level TTL: avoids Cassandra tombstone buildup but keeps data longer than strictly needed", "Temporal partitioning plus event buckets to spread bursty writes: prevents hot partitions at the cost of scatter-gather read amplification", "In-memory write coalescing queues for loss-tolerant logging use cases, with durable writes bypassing them: higher throughput but risk of losing events on crash"], "summary": "Netflix describes its TimeSeries Data Abstraction, a layered service over Cassandra (primary storage) and Elasticsearch (secondary index) that stores immutable, high-throughput event data with low-millisecond primary-key reads. The design centers on time-sliced and bucketed partitioning, control-plane-driven per-namespace configuration, and write buffering, with tunable durability and consistency per dataset.", "interview_angle": "How would you design a store for billions of immutable events per day that must support fast point reads, secondary attribute search, and cheap retention expiry without per-row TTLs?", "score": 1.4867, "hn_points": 5, "hn_comments": 0}, {"url": "https://engineering.zalando.com/posts/2026/07/migrating-ad-event-processing-to-flink.html", "company": "Zalando", "industry": "ecommerce", "title": "From Homegrown to Flink: Migrating a Stateful Ad Event Join at Scale", "date": "2026-07-23", "primary_problem": "migration", "problems": ["realtime", "cost"], "post_type": "case_study", "level": "advanced", "stack": ["Flink", "RocksDB", "Kinesis", "Nakadi", "Kubernetes", "Karpenter", "Protobuf", "Java", "AWS"], "scale": "Up to 200MB/s input; join window 15 minutes; ~70 million timer entries; pods reduced from ~20 to 5 on average", "key_decisions": ["Replaced the homegrown in-memory join with Flink plus RocksDB state and 3-minute incremental checkpoints, trading operational complexity for safe autoscaling and no state loss on restarts.", "Chose a custom KeyedCoProcessFunction with point-lookup ValueStates and RocksDB TTL compaction over Flink's interval join, which spent 15-30% CPU on seeks and timer queues, trading built-in convenience for control over efficiency.", "Ran a four-week shadow pipeline and a one-week A/B test before cutover, trading validation time for confidence in billing correctness; also tuned RocksDB and JVM memory overhead, accepting more reserved memory to avoid kernel OOM kills."], "summary": "Zalando's Ad Platform team replaced a homegrown in-memory Java stream join that matched ad auctions with user interactions by migrating it to Apache Flink with RocksDB-backed state and incremental checkpoints. The custom keyed-state join outperformed Flink's interval join, cutting pods from about 20 to 5 on average and EC2 costs roughly in half while keeping match rates and billing outputs equivalent in shadow and A/B testing.", "interview_angle": "How would you design a stateful, time-bounded join of two high-throughput event streams that must survive restarts and autoscaling without losing buffered events, and when would you bypass a framework's built-in join operator?", "score": 1.4864, "hn_points": 0, "hn_comments": 0}, {"url": "https://netflixtechblog.com/elasticsearch-indexing-strategy-in-asset-management-platform-amp-99332231e541", "company": "Netflix", "industry": "media", "title": "Elasticsearch Indexing Strategy in Asset Management Platform (AMP)", "date": "2021-07-13", "primary_problem": "performance", "problems": ["scale_ingestion", "storage_formats"], "post_type": "case_study", "level": "advanced", "stack": ["Elasticsearch", "Cassandra", "Kafka", "Iceberg", "EvCache", "Zookeeper"], "scale": "7 TB indexed data; ~900 indices (~16,200 shards) reduced by time-bucket indexing", "key_decisions": ["Index by creation-time buckets instead of per-asset-type indices: balances shard sizes and removes shard sprawl, but makes updates depend on a cached bucket lookup and split logic.", "Use a fixed nested key/typed-value metadata mapping instead of one field per metadata property: avoids field-count limits and type collisions, at the cost of nested queries that are more complex.", "Keep all versions of an asset in the bucket of its first version and split oversized buckets via dual-write reindexing: keeps updates deterministic without multi-index lookups, but adds operational complexity for splits."], "summary": "Netflix's Asset Management Platform had Elasticsearch performance problems caused by about 900 per-asset-type indices with fixed shard counts, leading to unbalanced shard sizes and hot nodes. They moved to time-bucketed indices sized around 16\u201320GB, a nested key/value metadata mapping, and a split API, which cut average CPU from roughly 70% to 10%.", "interview_angle": "How would you design a search index for millions of heterogeneous asset documents with uneven type sizes, avoiding shard hot spots while keeping updates addressable by id?", "score": 1.4827, "hn_points": 2, "hn_comments": 0}, {"url": "https://shopify.engineering/build-production-grade-workflow-sql-modelling", "company": "Shopify", "industry": "ecommerce", "title": "How to Build a Production Grade Workflow with SQL Modelling", "date": "2020-11-19", "primary_problem": "platform", "problems": ["modeling", "quality"], "post_type": "case_study", "level": "intermediate", "stack": ["dbt", "BigQuery", "Spark", "Pandas", "Great Expectations", "Beam", "Beam SQL"], "scale": "Starscream runs 76,000 jobs and writes 300 TB/day", "key_decisions": ["Adopt dbt on BigQuery for SQL-first reporting pipelines instead of PySpark jobs, trading general-purpose compute for faster iteration on the ~70% of batch jobs that were simple queries", "Split raw source declarations into per-source YAML files and add a base layer, reducing merge conflicts and insulating downstream models from upstream schema changes", "Run unit tests on fixed mock inputs and limit CI to downstream models of changed files, trading BigQuery roundtrip cost for targeted test coverage; validate DAG by materializing views in a temporary dataset instead of full warehouse builds"], "summary": "Shopify built Seamster, a dbt-based SQL modelling workflow on BigQuery, to replace PySpark for simple batch reporting that data scientists were overusing. It adds per-source YAML organization, layered model conventions, a Python unit testing framework on mock inputs, and CI that validates the DAG by building views and enforcing warehouse rules.", "interview_angle": "How would you give analysts a fast, production-safe SQL pipeline workflow on a shared warehouse with many contributors\u2014covering testing, CI validation without full rebuilds, and handling upstream schema changes?", "score": 1.4815, "hn_points": 8, "hn_comments": 0}, {"url": "https://netflixtechblog.com/powering-multimodal-intelligence-for-video-search-3e0020cf1202", "company": "Netflix", "industry": "media", "title": "Powering Multimodal Intelligence for Video Search", "date": "2026-04-03", "primary_problem": "storage_formats", "problems": ["scale_ingestion", "performance"], "post_type": "case_study", "level": "advanced", "stack": ["Cassandra", "Kafka", "Elasticsearch"], "scale": "2,000-hour archive is over 216 million frames; billions of multi-layered data points", "key_decisions": ["Stage raw model annotations in Cassandra first for write durability, then fuse asynchronously via Kafka events so intersection work never blocks ingestion", "Discretize every model's output into fixed one-second buckets keyed by asset and time, which makes cross-model intersection cheap but multiplies record count", "Upsert into Elasticsearch using asset ID plus time bucket as the document key, giving one source of truth per second at the cost of re-indexing on updates; exact k-NN is available but ANN (HNSW) is offered for speed"], "summary": "Netflix describes a pipeline that takes outputs from many specialized video models, persists them in Cassandra, fuses overlapping annotations into per-second temporal buckets via an offline Kafka-triggered job, and indexes the buckets into Elasticsearch for hybrid text and vector search. The design targets sub-second, frame-accurate search across large media archives for editorial teams.", "interview_angle": "How would you design a system that fuses heterogeneous time-aligned model outputs (labels and embeddings) into a queryable index with sub-second latency, and how would you avoid bottlenecking ingestion while doing expensive temporal intersections?", "score": 1.4778, "hn_points": 0, "hn_comments": 0}, {"url": "https://engineering.grab.com/how-built-logging-stack", "company": "Grab", "industry": "mobility", "title": "How We Built a Logging Stack at Grab", "date": "2019-07-31", "primary_problem": "scale_ingestion", "problems": ["cost", "performance"], "post_type": "case_study", "level": "advanced", "stack": ["Elasticsearch", "Kibana", "Logstash", "Datadog", "Ansible", "Lucene"], "scale": "25 TB of logs per day, cluster grew to 400+ nodes, several trillion documents", "key_decisions": ["Chose Elasticsearch with ingest nodes over Logstash to keep the pipeline simpler, at the cost of more cluster nodes and less battle-tested tooling", "Disabled inter-node compression for shard transfers, trading network bandwidth for much faster shard recovery since Lucene segments are already compressed", "Pinned indices per availability zone to avoid cross-AZ traffic, cutting about 30% of cluster cost but reducing cross-zone failover flexibility"], "summary": "Grab replaced scattered, slow log-retrieval methods with a self-run Elasticsearch-based logging platform handling about 25 TB of logs daily. The write-up focuses on operational lessons: field data cache blowups from ID sorting, shard-to-heap ratios driving OOMs, analyser choices that inflated index memory, and cross-AZ traffic costs.", "interview_angle": "How would you design a centralized log search system at tens of TB per day that keeps sub-5-second query latency while controlling heap, shard count and cross-zone network cost?", "score": 1.4765, "hn_points": 1, "hn_comments": 0}, {"url": "https://engineering.grab.com/how-we-store-millions-orders", "company": "Grab", "industry": "mobility", "title": "How we store and process millions of orders daily", "date": "2022-08-15", "primary_problem": "storage_formats", "problems": ["cdc_sync", "cost"], "post_type": "case_study", "level": "intermediate", "stack": ["DynamoDB", "MySQL RDS", "Kafka", "Amazon SQS", "Aurora"], "scale": "Millions of orders per day (up to a million orders per month cited in design goals)", "key_decisions": ["Split OLTP (DynamoDB) from OLAP (MySQL RDS) so analytical queries cannot hurt online order processing, at the cost of eventual consistency between the two stores", "Use DynamoDB sparse GSI and TTL-based retention to keep the hot table small and cheap, with a manual deletion workaround to avoid TTL scanner load on large tables", "Feed OLAP via Kafka with SQS retry and DLQ, handling duplicates with unique keys and out-of-order updates via version timestamps and upserts"], "summary": "Grab describes a dual-store design for its Order Platform: DynamoDB serves strongly consistent transactional lookups while MySQL RDS holds longer-retained data for historical and statistical queries. A Kafka-based ingestion pipeline with SQS fallback keeps the two stores eventually consistent, handling duplicates and out-of-order events.", "interview_angle": "How would you split transactional and analytical order queries across two stores while keeping them consistent, and how would you handle retention and out-of-order events in the sync pipeline?", "score": 1.4732, "hn_points": 2, "hn_comments": 0}, {"url": "https://monzo.com/blog/2019/09/08/why-monzo-wasnt-working-on-july-29th", "company": "Monzo", "industry": "fintech", "title": "We had issues with Monzo on 29th July. Here's what happened, and what we did to fix it.", "date": "2019-09-08", "primary_problem": "quality", "problems": ["platform", "scale_ingestion"], "post_type": "postmortem", "level": "advanced", "stack": ["Cassandra"], "scale": "21-node Cassandra cluster, 6 nodes added in scale-up; replication factor 3", "key_decisions": ["Scaling the cluster by adding six nodes at once vs. one-by-one: faster capacity gain but a bigger blast radius when the bootstrap flag misbehaved", "Setting auto_bootstrap to false for production so replacements restore from backups: faster recovery but new nodes serve reads before holding data", "One large shared Cassandra cluster vs. several smaller ones: simpler operations but a single change can affect every service"], "summary": "Monzo's 2019 incident happened when adding six Cassandra nodes to a production cluster caused new nodes to take on read and write responsibility before they held any data, so customer balances and transactions appeared missing. The post walks through the timeline, the auto_bootstrap misunderstanding, and the plan to add runbooks, better metrics and split the single cluster into smaller ones.", "interview_angle": "How would you safely scale a replicated distributed datastore without serving reads from nodes that have not streamed their data yet, and how would you limit the blast radius of a single cluster change?", "score": 1.4699, "hn_points": 11, "hn_comments": 1}, {"url": "https://netflixtechblog.com/netflix-live-origin-41f1b0ad5371", "company": "Netflix", "industry": "media", "title": "Netflix Live Origin", "date": "2025-12-15", "primary_problem": "realtime", "problems": ["scale_ingestion", "performance"], "post_type": "case_study", "level": "advanced", "stack": ["Cassandra", "EVCache", "Memcached", "nginx", "S3", "EC2", "Open Connect"], "scale": "65 million concurrent streams peak; 100+ Gbps origin read throughput; hundreds of MiB/s cross-region writes", "key_decisions": ["Replaced S3 with a custom KeyValue store on Cassandra (local-quorum writes) plus EVCache write-through cache: gains write availability and read scale, but costs much more than S3.", "Built a multi-pipeline origin that picks the first valid segment from redundant pipelines: improves playback resilience, but adds selection logic and defect metadata handling.", "Prioritized live-edge traffic over DVR traffic with priority rate limiting and cached metadata to reject 404/410 storms: protects the datastore under stress, but low-priority viewers see failures and 503s."], "summary": "Netflix describes its Live Origin, a multi-tenant microservice that sits between cloud live encoding pipelines and the Open Connect CDN, and how it stores and serves segments. The team moved from S3 to a chunked key-value layer on Cassandra with EVCache read caching to meet strict write-availability and read-throughput needs during live events.", "interview_angle": "How would you design a low-latency storage and distribution path for live video segments that must survive AZ failures, handle sudden read storms, and prioritize live-edge traffic over DVR requests?", "score": 1.4688, "hn_points": 2, "hn_comments": 0}, {"url": "https://netflixtechblog.com/data-projects-managing-data-assets-at-netflix-scale-7ca25888591e", "company": "Netflix", "industry": "media", "title": "Data Projects: Managing Data Assets at Netflix Scale", "date": "2026-05-11", "primary_problem": "governance_privacy", "problems": ["platform", "lineage_catalog"], "post_type": "case_study", "level": "advanced", "stack": ["Maestro", "Amazon EMR", "Spark", "AWS IAM"], "scale": "Millions of tables in the data warehouse and tens of thousands of scheduled workloads", "key_decisions": ["Group assets into project containers with grants instead of per-table ACLs, trading per-asset granularity for far easier reorg handling and risk of broader container-level access", "Give workflows a durable team-owned application identity instead of a human OBO credential, trading stronger stability for the need to set up permissions before switching identity", "Auto-attach assets created by a project's identity (gravity), trading implicit ownership for zero-config organization that depends on the platform always tagging creators correctly"], "summary": "Netflix introduces Data Projects, a container that groups tables, workflows and other assets under one manageable unit, paired with a durable synthetic identity that scheduled workloads run as. This replaces fragile per-table ACLs and human-tied workflow identities that broke on org changes and departures.", "interview_angle": "How would you design access control and workload identity for a warehouse with millions of tables when teams are constantly reorganizing and jobs must keep running after an owner leaves?", "score": 1.4678, "hn_points": 0, "hn_comments": 0}, {"url": "https://netflixtechblog.com/orchestrating-data-ml-workflows-at-scale-with-netflix-maestro-aaa2b41b800c", "company": "Netflix", "industry": "media", "title": "Orchestrating Data/ML Workflows at Scale With Netflix Maestro", "date": "2022-10-18", "primary_problem": "platform", "problems": ["scale_ingestion", "performance"], "post_type": "deep_dive", "level": "advanced", "stack": ["Maestro", "Meson", "Conductor", "CockroachDB", "Jupyter", "Metaflow", "Spark", "YAML", "Python", "Java", "AWS"], "scale": "About 70k workflows and 500k jobs per day on the legacy Meson system; new Maestro targets millions of workflow and step instances, with foreach loops of up to 100K steps", "key_decisions": ["Replaced a single-leader orchestrator with stateless, horizontally scalable services fed by distributed queues, trading operational simplicity of one leader for scale-out complexity", "Capped DAG size (about 1K) and added foreach sub-workflows for large iterations, so users can run millions of steps without huge UI-rendered graphs but must learn the loop pattern", "Used signal-based and time-based triggers with exactly-once deduplication, which avoids polling for readiness but adds a signal service to build and maintain"], "summary": "Netflix describes Maestro, its next-generation workflow orchestrator that replaces the overloaded Meson scheduler and runs data and ML pipelines as a managed workflow-as-a-service. The design uses horizontally scalable stateless services, CockroachDB for state, event-driven signals alongside cron triggers, and foreach sub-workflows to handle workflows with very large numbers of steps.", "interview_angle": "How would you design a workflow orchestrator that handles bursty midnight load, backfills spanning hundreds of thousands of tasks, and event-driven triggers without a single-leader bottleneck?", "score": 1.4646, "hn_points": 1, "hn_comments": 0}, {"url": "https://netflixtechblog.com/streaming-sql-in-data-mesh-0d83f5a00d08", "company": "Netflix", "industry": "media", "title": "Streaming SQL in Data Mesh", "date": "2023-11-03", "primary_problem": "platform", "problems": ["realtime", "performance"], "post_type": "case_study", "level": "advanced", "stack": ["Flink", "Flink SQL", "Kafka", "Mantis", "Calcite"], "scale": "", "key_decisions": ["Expose stream processing through a platform-managed Flink SQL processor instead of building many small single-purpose processors; gains expressiveness and fewer jobs and topics, but users lose fine-grained control over operators and state.", "Build a lightweight query validation service using Flink planner internals so errors surface while users edit, avoiding slow post-deploy failures; ties the service to Flink internals.", "Impose guardrails by inspecting the parsed query tree and rejecting unsupported nodes; keeps operations manageable across thousands of use cases but limits what users can express for now."], "summary": "Netflix describes adding a Flink SQL processor to its Data Mesh streaming platform so users can write a single SQL query instead of chaining multiple Flink jobs over Kafka topics. The post covers the interactive query mode, real-time validation, schema inference, and guardrails used to keep the platform operable at scale.", "interview_angle": "How would you let non-experts build streaming transformations on a shared platform while keeping validation fast, operations manageable, and per-job overhead low?", "score": 1.4641, "hn_points": 1, "hn_comments": 0}, {"url": "https://medium.com/airbnb-engineering/the-guest-journey-updated-in-real-time-extending-airbnbs-sequence-recommender-with-chronon-8f1582578553", "company": "Airbnb", "industry": "marketplace", "title": "The guest journey, updated in real time: extending Airbnb\u2019s sequence recommender with Chronon", "date": "2026-09-17", "primary_problem": "realtime", "problems": ["ml_data", "performance"], "post_type": "case_study", "level": "advanced", "stack": ["Chronon", "Transformer"], "scale": "Embedding staleness cut from ~2 days to under 1 minute (updates in 10-30 seconds); +1.67% NDCG offline; ~1/3 percent uncancelled bookings lift online", "key_decisions": ["Push Mode triggers downstream embedding generation on feature commit instead of polling, trading extra event plumbing for much lower latency", "NRT Model Transform runs the sequence encoder inside the streaming flow, avoiding a separate serving path but coupling feature pipelines to model inference", "Built as general Chronon platform capabilities rather than a bespoke pipeline, which adds platform maintenance burden but lets other teams reuse them"], "summary": "Airbnb extended its Chronon feature platform with Push Mode and Near-real-time Model Transform so its Transformer sequence encoder can refresh guest embeddings within seconds of new activity rather than through a nightly batch job. This cut embedding staleness from about two days to under a minute and improved offline NDCG and online bookings.", "interview_angle": "How would you turn a daily batch ML feature refresh into a near-real-time one without duplicating the offline logic, and what trade-offs come with running model inference inside a streaming pipeline?", "score": 1.4626, "hn_points": 0, "hn_comments": 0}, {"url": "https://slack.engineering/from-ssh-to-rest-a-security-driven-modernization-of-slacks-emr-data-pipelines", "company": "Slack", "industry": "saas", "title": "From SSH to REST: A Security-Driven Modernization of Slack\u2019s EMR Data Pipelines", "date": "2026-05-05", "primary_problem": "migration", "problems": ["platform", "governance_privacy"], "post_type": "case_study", "level": "advanced", "stack": ["Airflow", "Amazon EMR", "YARN", "Quarry", "Spark", "Hive", "MapReduce", "Trino", "Snowflake", "Kubernetes", "Livy", "S3"], "scale": "700+ jobs migrated across 8 data regions", "key_decisions": ["Chose YARN Distributed Shell to run arbitrary shell commands in YARN containers over building a custom execution wrapper or adopting Ansible/Salt, trading some awkward setup for reuse of existing YARN REST APIs and auth", "Routed all job submission through the existing Quarry gateway using service tokens instead of SSH keys, centralizing audit logs and job tracking at the cost of making Quarry a critical shared dependency", "Migrated incrementally by operator type through dev, govdev/commdev and prod with a phased OKR-driven rollout, trading a longer timeline for lower risk across 8 regions"], "summary": "Slack replaced 700+ SSH-based Airflow operators that ran jobs on EMR master nodes with REST-based job submission through its Quarry gateway and YARN, eliminating SSH across eight data regions. The migration surfaced hidden issues such as vmem check failures and network segregation dependencies that SSH had been masking.", "interview_angle": "How would you remove direct shell access to a shared Hadoop cluster from an orchestrator at scale without rewriting every job? Discuss REST job submission, YARN containers, auth tokens, and phased multi-region rollout.", "score": 1.4578, "hn_points": 1, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/more-data-more-data", "company": "Cloudflare", "industry": "infra", "title": "More data, more data", "date": "2016-07-12", "primary_problem": "scale_ingestion", "problems": ["realtime", "platform"], "post_type": "case_study", "level": "advanced", "stack": ["Kafka", "Go", "Cap'n Proto", "HDFS", "CitusDB", "PostgreSQL", "Spark Streaming", "Mesos", "Docker", "OpenTSDB", "Grafana", "Prometheus", "Sentry", "Elasticsearch", "Kibana", "nginx"], "scale": "3.6M HTTP logs/s average (peaks 4.5M), 750K DNS logs/s average (peaks 1M), ~360TB raw logs per day, 4.3PB disk across Kafka clusters", "key_decisions": ["Built a Go log forwarder with a plugin architecture so new log types and Kafka endpoints are easy to add, trading off custom maintenance for flexibility", "Used Kafka as the central broker for edge logs, accepting heavy hardware and operational cost because no alternative fit the throughput and durability needs", "Kept CitusDB (sharded PostgreSQL) for aggregated data storage, favoring operational simplicity and easy upgrades over a newer distributed system"], "summary": "Cloudflare's Data Team describes the pipeline that gathers structured HTTP and DNS edge logs from thousands of servers into central Kafka clusters and downstream storage, at millions of events per second. The post reviews what has worked (the Go forwarder, Kafka, Log Share, CitusDB) and what remains to be improved, such as reliability, new analytics, and new pipelines.", "interview_angle": "How would you design a log ingestion pipeline that collects millions of events per second from geographically distributed edge nodes into central storage, and how would you size the Kafka tier and handle failures?", "score": 1.4548, "hn_points": 10, "hn_comments": 0}, {"url": "https://eng.lyft.com/building-a-large-scale-unsupervised-model-anomaly-detection-system-part-1-aca4766a823c", "company": "Lyft", "industry": "mobility", "title": "Building a large scale unsupervised model anomaly detection system \u2014 Part 1", "date": "2023-04-21", "primary_problem": "ml_data", "problems": ["scale_ingestion", "performance"], "post_type": "case_study", "level": "advanced", "stack": ["Spark", "Fugue", "whylogs", "Kubernetes", "Hive", "Python", "protobuf"], "scale": "Hundreds of millions of predictions per day across LyftLearn models", "key_decisions": ["Chose whylogs mergeable profiles so hourly profiles can roll up into daily ones with no shuffle, trading away raw-data flexibility for compact, scalable summaries", "Used Fugue over raw Spark code so one Python profiling function runs at any partition granularity, keeping logic independent of scale but adding an abstraction layer", "Profiled every model's features and predictions into compact binary blobs instead of per-model monitoring logic, reducing the problem to uniform numeric time series at the cost of per-model customization"], "summary": "Lyft describes how LyftLearn profiles model features and predictions from raw JSON inference logs in Hive using whylogs, Spark and Fugue. Mergeable profiles let hourly profiles roll up into daily ones without shuffles, and new models are onboarded automatically. This is part 1 of a series; part 2 covers anomaly detection on the profiles.", "interview_angle": "How would you design a pipeline that computes mergeable summary statistics over high-volume inference logs for thousands of models, so that hourly and daily aggregates can be produced without rescanning raw data?", "score": 1.4529, "hn_points": 17, "hn_comments": 3}, {"url": "https://engineering.grab.com/hubble-data-discovery", "company": "Grab", "industry": "mobility", "title": "Enabling conversational data discovery with LLMs at Grab", "date": "2024-09-26", "primary_problem": "lineage_catalog", "problems": ["modeling", "ml_data"], "post_type": "case_study", "level": "intermediate", "stack": ["Datahub", "Elasticsearch", "GPT-4", "Glean", "Slack"], "scale": "200,000+ tables in data lake; P80 table documentation coverage raised to ~90%; CTR 94%", "key_decisions": ["Tune Elasticsearch ranking (boosting certified and P80 tables, deboosting deprecated ones) rather than replacing search, trading off effort against full semantic capability", "Use GPT-4 to auto-generate table docs and flag them as AI-generated until producers review, trading speed of coverage for doc accuracy risk", "Adopt Glean as a managed enterprise search/LLM layer for HubbleIQ to speed launch, trading customization control for time-to-market"], "summary": "Grab's Hubble team improved data discovery across its 200,000-table lake by tuning Elasticsearch, auto-generating table documentation with GPT-4, and launching HubbleIQ, an LLM chatbot built on Glean and exposed in Slack. Documentation coverage for frequently queried tables rose to about 90%, and survey respondents reporting easy discovery increased by 17 points.", "interview_angle": "How would you design a semantic data discovery system over a very large catalog, and which metadata (docs, tags, usage popularity) would you invest in before adding an LLM layer?", "score": 1.4523, "hn_points": 0, "hn_comments": 0}, {"url": "https://engineering.grab.com/rethinking-streaming-processing-data-exploration", "company": "Grab", "industry": "mobility", "title": "Rethinking Stream Processing: Data Exploration", "date": "2024-01-31", "primary_problem": "realtime", "problems": ["governance_privacy", "platform"], "post_type": "case_study", "level": "advanced", "stack": ["Kafka", "Flink", "Apache Zeppelin", "Protobuf", "Strimzi", "Open Policy Agent", "DataHub", "Hive", "Spark"], "scale": "", "key_decisions": ["Expose Kafka streams to analysts via a Zeppelin notebook with Flink SQL interpreter, trading production-grade governance for earlier, faster exploration", "Generate table DDL automatically from Protobuf schemas instead of hand-maintained definitions, reducing manual effort but depending on schema discipline upstream", "Enforce read-only topic access with OPA policies and mTLS identity plus audit logs, adding security overhead while allowing break-glass revocation"], "summary": "Grab describes letting data analysts query Kafka streams directly through a Zeppelin notebook backed by Flink SQL, so online data can be explored before it lands in the data lake. The post also covers deriving SQL table definitions from Protobuf schemas and controlling read access with OPA policies, mTLS identities and audit trails.", "interview_angle": "How would you let analysts explore a high-volume Kafka topic ad hoc without waiting for data lake ingestion, while enforcing PII masking, per-topic access control and auditing?", "score": 1.4433, "hn_points": 2, "hn_comments": 0}, {"url": "https://netflixtechblog.com/driving-content-delivery-efficiency-through-classifying-cache-misses-ffcf08026b6c", "company": "Netflix", "industry": "media", "title": "Driving Content Delivery Efficiency Through Classifying Cache Misses", "date": "2025-07-02", "primary_problem": "realtime", "problems": ["scale_ingestion", "cost"], "post_type": "case_study", "level": "advanced", "stack": ["Kafka", "AWS"], "scale": "Millions of members and tens of thousands of CDN servers; logs from multiple AWS regions", "key_decisions": ["Consolidate logs from geographically distributed Kafka clusters into a single region with one cross-region transfer, trading consolidation latency for lower duplication and transfer cost versus many-to-many joins", "Enrich and join steering manifest logs with OCA server logs via streaming window-based join, keeping playback requests free of added latency while producing near-real-time miss metrics", "Log full steering decision state so cache misses can be replayed and simulated offline, trading extra log volume for the ability to test scenarios without touching production traffic"], "summary": "Netflix's Open Connect team describes a streaming pipeline that joins steering-service decision logs with CDN appliance server logs to classify bytes served from non-optimal sites as content misses or health misses. The design consolidates cross-region Kafka logs into one region and uses windowed stream joins to compute near-real-time miss metrics that also support offline replay.", "interview_angle": "How would you design a near-real-time pipeline that joins two high-volume log streams produced in different regions, while minimizing cross-region transfer and keeping the producing service's latency unaffected?", "score": 1.4421, "hn_points": 2, "hn_comments": 0}, {"url": "https://engineering.grab.com/cdp-scenarios", "company": "Grab", "industry": "mobility", "title": "How Grab is accelerating growth with real-time personalization using Customer Data Platform scenarios", "date": "2025-12-18", "primary_problem": "realtime", "problems": ["platform", "ml_data"], "post_type": "case_study", "level": "intermediate", "stack": ["Flink", "Kafka", "StarRocks", "DynamoDB", "Scribe"], "scale": "over 1,000 batch user attributes; over 12 live production implementations", "key_decisions": ["Flink-based event-triggered pipelines with geo-fencing rather than daily batch attribute refreshes: lower latency but more stateful streaming infrastructure to operate", "Self-serve GUI for marketers to define Scenarios, trading engineering effort for a more constrained configuration surface", "Dual sinks (DynamoDB-backed feature store and Kafka) so consumers choose between point lookups and streams, at the cost of maintaining two delivery paths"], "summary": "Grab's Customer Data Platform added a \"Scenarios\" capability that reacts to user events and geo-fences in real time, using Flink to join live events with historical attributes in StarRocks and pre-trained models. Outputs are written to Kafka or a DynamoDB-backed feature store so downstream services can personalize experiences within seconds to minutes instead of waiting for daily batch segments.", "interview_angle": "How would you design a real-time personalization pipeline that enriches live events with historical profile data, lets non-engineers define triggers, and serves results with low latency to multiple consumers?", "score": 1.442, "hn_points": 0, "hn_comments": 0}, {"url": "https://netflixtechblog.com/towards-a-reliable-device-management-platform-4f86230ca623", "company": "Netflix", "industry": "media", "title": "Towards a Reliable Device Management Platform", "date": "2021-08-30", "primary_problem": "realtime", "problems": ["scale_ingestion", "performance"], "post_type": "case_study", "level": "advanced", "stack": ["Kafka", "MQTT", "Alpakka-Kafka", "Akka Streams", "Spring Boot", "CockroachDB", "Spring KafkaListener", "EmbeddedKafka"], "scale": "Kafka topic rose from 100 to 900 messages/s (about 840 kB/s) after event sourcing; consumer lag fell from ~60,000 records to near zero outside bursts", "key_decisions": ["Chose Alpakka-Kafka over KafkaListener, Kafka Streams, Flink and others for native Reactive Streams back-pressure, trading a less familiar API for controlled consumption", "Keyed MQTT-to-Kafka bridge records by topic embedding device session ID so each device's updates land on one partition, preserving order but capping parallelism per device", "Switched to batched offset commits (1000 records or 1 second) and idempotent timestamp-conditioned upserts, trading higher commit latency for lower commit overhead and tolerance of reprocessing"], "summary": "Netflix's Partner Infrastructure team replaced a Spring KafkaListener consumer that ingested device-state events into the Cloud Registry with an Alpakka-Kafka pipeline. The switch added back-pressure, which removed a memory and GC blowup and cut consumer lag from around 60,000 records to near zero outside burst windows.", "interview_angle": "How would you build a Kafka consumer that keeps per-device ordering while handling bursty traffic without unbounded in-memory queues, and how would you choose between back-pressure and batched commits?", "score": 1.4416, "hn_points": 3, "hn_comments": 0}, {"url": "https://medium.com/wise-engineering/observability-at-scale-every-byte-counts-80f5e505d710", "company": "Wise", "industry": "fintech", "title": "Observability At Scale\u200a\u2014\u200aEvery Byte Counts", "date": "2026-10-20", "primary_problem": "cost", "problems": ["storage_formats", "performance"], "post_type": "case_study", "level": "advanced", "stack": ["Grafana Loki", "Grafana Mimir", "Grafana Tempo", "Prometheus", "OpenTelemetry Collector", "Fluent Bit", "Cilium", "Kubernetes", "S3", "Snappy", "lz4", "zstd"], "scale": "~50TB/day Loki logs; ~16TB/day to ~5.5TB/day metrics transfer; ~900TB removed from Loki bucket; 40% monthly spend reduction", "key_decisions": ["Switching Loki chunk compression from Snappy to lz4: 40-50% smaller storage and cross-AZ traffic, with a risk of higher CPU and querier memory use that was validated in staged rollout", "Switching OpenTelemetry Collector export compression from gzip to zstd: roughly 40% less data to Tempo, at the cost of a quick change that relied on existing measurement tooling", "Upgrading Prometheus Remote Write v1 to v2: about 66% less network transfer, but requires coordinated Prometheus Operator and kube-prometheus-stack upgrades across clusters"], "summary": "Wise's Observability team cut its monthly telemetry spend by about 40% by challenging default settings across logs, metrics and traces. Changes included lz4 compression for Loki chunks, zstd for OpenTelemetry trace export, Remote Write v2 for Prometheus, a Loki query split interval matched to chunk spans, and a Cilium policy fix that allowed node consolidation.", "interview_angle": "How would you reduce storage and network cost for a petabyte-scale log and trace pipeline without hurting query latency? Discuss compression codec trade-offs, cross-AZ transfer costs, and validating changes with staged rollouts and cost attribution.", "score": 1.4386, "hn_points": 0, "hn_comments": 0}, {"url": "https://netflixtechblog.com/behind-the-scenes-building-a-robust-ads-event-processing-pipeline-e4e86caf9249", "company": "Netflix", "industry": "media", "title": "Behind the Scenes: Building a Robust Ads Event Processing Pipeline", "date": "2025-05-09", "primary_problem": "platform", "problems": ["scale_ingestion", "realtime"], "post_type": "case_study", "level": "advanced", "stack": ["Kafka", "Flink", "Druid"], "scale": "", "key_decisions": ["Centralize ad event collection (decryption, enrichment, ID hashing) in one publisher service, trading an extra hop for a single unified contract that hides upstream telemetry differences from consumers", "Move opaque tokens to a metadata registry holding references instead of full tracking payloads, keeping client-cached tokens small at the cost of a key-value lookup on callback", "Position sessionization and metrics as downstream Flink consumers of the unified stream, with Druid serving real-time metrics backed by an offline correction pass, trading simplicity for eventual accuracy in reporting"], "summary": "Netflix describes how its ads event pipeline evolved from a simple Kafka-based design with a Microsoft ad server into a centralized Ads Event Publisher feeding multiple downstream consumers. The redesign was driven by in-house ad serving, new billing, frequency capping, and reporting needs, plus the desire to keep client tokens small.", "interview_angle": "How would you design a centralized event collection layer that ingests heterogeneous ad telemetry from multiple upstream producers and fans it out to real-time metrics, frequency capping, billing and vendor callbacks with a single data contract?", "score": 1.4382, "hn_points": 2, "hn_comments": 0}, {"url": "https://netflixtechblog.com/netflix-conductor-the-next-chapter-41ad21067649", "company": "Netflix", "industry": "media", "title": "Netflix Conductor: The Next Chapter", "date": "2026-08-21", "primary_problem": "platform", "problems": ["scale_ingestion", "performance"], "post_type": "case_study", "level": "advanced", "stack": ["Conductor", "Cassandra", "Elasticsearch", "Kafka", "Iceberg", "S3", "Timestone", "Dynomite", "DynoQueues", "Titus", "Stratum", "Java", "Gradle"], "scale": "420 million workflows per month; 5-20 million workflows per day; ~200,000 workflow definitions; 30,000 tasks per workflow max", "key_decisions": ["Moved execution data from Dynomite to Cassandra and offloaded large payloads to S3, trading operational simplicity for horizontal elasticity", "Split task state into pending and terminal partitions with application-side reconciliation instead of Cassandra lightweight transactions, avoiding LWT/ordinary write mixing issues at the cost of read-time merge logic", "Made workflow evaluation asynchronous via exclusive queues so only one worker evaluates a workflow at a time, removing lock contention at the cost of added evaluation latency and queue dependence"], "summary": "Netflix describes how its Conductor workflow orchestration engine was rebuilt to handle orders-of-magnitude growth, covering a new Cassandra/Timestone data plane, a partitioned task model, and async evaluation. It also covers run strategies, managed Titus/Stratum tasks, queue-depth-driven thread allocation, and a type-safe Java SDK.", "interview_angle": "How would you design a workflow orchestrator that evaluates millions of workflow runs per month without lock contention, and how would you keep task state consistent under concurrent updates?", "score": 1.436, "hn_points": 0, "hn_comments": 0}, {"url": "https://engineering.grab.com/attribution-platform", "company": "Grab", "industry": "mobility", "title": "The journey of building a comprehensive attribution platform", "date": "2024-02-20", "primary_problem": "realtime", "problems": ["late_data", "cost"], "post_type": "case_study", "level": "advanced", "stack": ["Kafka", "S3", "Redis", "ScyllaDB", "Amazon RDS", "Druid", "Spark", "Coban", "DynamoDB"], "scale": "Attribution latency reduced from 2-3 days to minutes; ~25% reduction in real-time processing costs; discrepancies under 1%", "key_decisions": ["Chose Kappa architecture for near real-time attribution, trading simpler single logic path for stream-only historical reprocessing limits", "Moved to Lambda architecture to add a batch/offline layer for historical context and completeness, at the cost of maintaining two sets of business logic", "Plan to split duties so real-time handles only time-sensitive metrics (like CPO) and batch handles other reporting, reducing dual-logic drift and real-time cost"], "summary": "Grab describes how its ads and promo attribution system evolved from a Kappa streaming design to a Lambda architecture with a batch offline layer. The post covers why stream-only processing struggled with out-of-order events, long attribution windows and multi-touch models, and how splitting real-time and batch responsibilities is meant to cut cost and complexity.", "interview_angle": "How would you design an attribution pipeline that must return near real-time ROAS while still handling late, out-of-order events and long attribution windows? Compare Kappa and Lambda and how you would limit dual-logic drift.", "score": 1.4341, "hn_points": 0, "hn_comments": 0}, {"url": "https://tech.instacart.com/real-time-fraud-detection-with-yoda-and-clickhouse-bd08e9dbe3f4", "company": "Instacart", "industry": "marketplace", "title": "Real-time Fraud Detection with Yoda and ClickHouse", "date": "2024-03-18", "primary_problem": "realtime", "problems": ["cdc_sync", "scale_ingestion"], "post_type": "case_study", "level": "advanced", "stack": ["ClickHouse", "Flink", "Kafka", "PostgreSQL", "Debezium", "Kafka Connect", "Kubernetes"], "scale": "~30 Flink ingestion pipelines; scale in event volume not stated", "key_decisions": ["Chose ClickHouse as the real-time datastore for columnar, write-optimized MergeTree storage, accepting operational overhead versus a general-purpose database", "Built a config-driven YAML Flink ingestion job so analysts can onboard new sources without engineering work, trading flexibility for a more constrained pipeline model", "Used Debezium CDC from Postgres plus an in-house event ingester, and tuned batch flush intervals, TTLs and sort keys, trading data freshness against rule accuracy and performance"], "summary": "Instacart's Yoda fraud platform uses ClickHouse as its real-time datastore, fed by Debezium CDC from Postgres and an in-house event ingester through a config-driven Flink job. Analysts define SQL-based real-time features over short look-back windows to drive rule evaluation and actions such as suspensions.", "interview_angle": "How would you design a low-latency fraud decisioning system that lets non-engineers define features over fresh operational data, and how would you balance ingestion batching, data freshness and query performance?", "score": 1.4322, "hn_points": 0, "hn_comments": 0}, {"url": "https://engineering.grab.com/from-firefighting-to-building", "company": "Grab", "industry": "mobility", "title": "From firefighting to building: How AI agents restored our team\u2019s core productivity", "date": "2026-03-19", "primary_problem": "platform", "problems": ["lineage_catalog", "quality"], "post_type": "case_study", "level": "advanced", "stack": ["FastAPI", "LangGraph", "Redis", "PostgreSQL", "Trino", "Hive", "Delta Lake", "Spark", "Airflow", "GitLab", "Confluence", "Slack"], "scale": "Over 1,000 monthly users, more than 15,000 tables, about 50% of data lake queries", "key_decisions": ["Multi-agent design with specialized agents over one monolithic model: easier to maintain and debug, but adds sequential latency", "Post AI answers immediately marked as unreviewed instead of gating on engineer approval: faster responses at the cost of some unverified answers", "Keep code changes semi-automated via merge requests with human approval: safer for production pipelines but slower than fully autonomous changes"], "summary": "Grab's Analytics Data Warehouse team built a multi-agent AI system on LangGraph that answers routine data questions in Slack and drafts pipeline code changes as merge requests. The system includes SQL guardrails, PII checks, and human review of responses, and the team reports reclaimed engineering time, though no precise metrics are given.", "interview_angle": "How would you design an internal assistant that answers data lineage and quality questions across thousands of tables while guarding against PII exposure and runaway queries?", "score": 1.4298, "hn_points": 0, "hn_comments": 0}, {"url": "https://stripe.com/blog/how-we-built-it-usage-based-billing", "company": "Stripe", "industry": "fintech", "title": "How we built it: Usage-based billing", "date": "2025-01-28", "primary_problem": "realtime", "problems": ["scale_ingestion", "late_data"], "post_type": "case_study", "level": "advanced", "stack": ["Flink"], "scale": "100,000 events per second per business; P95 latency under 30 seconds for time-sensitive operations; about five minutes end-to-end", "key_decisions": ["Asynchronous edge-router ingestion onto an event bus instead of synchronous API processing: higher throughput and lower cost, but failures become delayed and need developer dashboards and webhooks to debug", "Active-active Flink deployment across two regions with shared timestamped event metadata: avoids downtime for billing, at the cost of cross-region consistency and reconciliation work", "Dual-path aggregation with a 30-second in-memory fast path for alerts and a five-minute disk-backed ledger path for late events and financial records: low latency and accuracy together, but two pipelines to keep consistent"], "summary": "Stripe describes how its usage-based billing product handles very high event throughput by ingesting events asynchronously, running Flink in active-active regions, and matching usage streams against pricing streams. The key idea is a dual-path design that gives fast alerts on a memory path while a slower disk-backed ledger handles late events and billing accuracy.", "interview_angle": "How would you design a billing event pipeline that handles 100k events/sec, survives region outages, and still corrects for late or retroactive pricing changes without pausing the stream?", "score": 1.4289, "hn_points": 0, "hn_comments": 0}, {"url": "https://netflixtechblog.com/introducing-netflixs-key-value-data-abstraction-layer-1ea8a0a11b30", "company": "Netflix", "industry": "media", "title": "Introducing Netflix\u2019s Key-Value Data Abstraction Layer", "date": "2024-09-18", "primary_problem": "platform", "problems": ["performance", "scale_ingestion"], "post_type": "deep_dive", "level": "advanced", "stack": ["Cassandra", "EVCache", "DynamoDB", "RocksDB", "gRPC", "Zookeeper"], "scale": "Hundreds of use cases; client-side compression cut payloads 75% in one deployment", "key_decisions": ["Expose a fixed two-level map API over many backing stores, trading away native database features for portability and easier evolution", "Use client-generated monotonic idempotency tokens instead of server-side ones, accepting clock-skew risk in exchange for reliability under network delay", "Paginate by bytes with adaptive limits and early return on SLO risk, trading exact page sizes for predictable latency"], "summary": "Netflix describes its Key-Value Data Abstraction Layer, a service that gives developers a uniform CRUD API over multiple distributed stores such as Cassandra and EVCache. The post covers the two-level map data model, idempotency tokens, chunking of large values, client-side compression, and byte-based adaptive pagination aimed at predictable latency.", "interview_angle": "How would you design a multi-backend key-value access layer that hides storage engine differences while keeping tail latency predictable for pagination and large values?", "score": 1.4272, "hn_points": 93, "hn_comments": 18}, {"url": "https://netflixtechblog.com/cloud-efficiency-at-netflix-f2a142955f83", "company": "Netflix", "industry": "media", "title": "Cloud Efficiency at Netflix", "date": "2024-12-17", "primary_problem": "cost", "problems": ["lineage_catalog", "quality"], "post_type": "case_study", "level": "intermediate", "stack": ["AWS", "Spark"], "scale": "", "key_decisions": ["Centralize inventory, ownership and usage into a shared Foundational Platform Data layer via data contracts with producers, trading upfront coordination for consistency", "Resolve each asset to a single owner or split multi-tenant costs in the analytics layer, trading simplicity for attribution fairness that platform-specific heuristics must handle", "Expose multiple aggregation levels with documented, transparent logic and SLAs, trading a heavier maintenance load for consumer trust and easier pivots when business rules change"], "summary": "Netflix's Platform DSE team describes a two-layer data system that gathers infrastructure inventory, ownership and usage into a common foundational dataset, then builds cost and efficiency attribution metrics on top of it. The post focuses on governance tradeoffs such as where to put customization burden, audits at each pipeline layer, and expanding coverage across platforms.", "interview_angle": "How would you design a cloud cost attribution pipeline that assigns shared infrastructure costs to owning teams, with data contracts from many upstream platform producers?", "score": 1.4265, "hn_points": 46, "hn_comments": 52}, {"url": "https://engineering.grab.com/streamlining-grabs-segmentation-platform", "company": "Grab", "industry": "mobility", "title": "Streamlining Grab's Segmentation Platform with faster creation and lower latency", "date": "2023-08-15", "primary_problem": "storage_formats", "problems": ["performance", "platform"], "post_type": "case_study", "level": "advanced", "stack": ["ScyllaDB", "Spark", "Go", "Roaring Bitmaps", "Object storage"], "scale": "12K read QPS and 36K write QPS on ScyllaDB; 15K peak QPS on SDK membership checks; segments up to million-member sized blobs under 1 MB", "key_decisions": ["Store segments as compressed Roaring Bitmaps in object storage instead of one ScyllaDB row per user, trading write amplification for a blob-fetch-and-decode read path", "Build a client SDK with LRU caching and update watching, trading per-service memory use for sub-millisecond membership checks", "Use Roaring's array, bitmap and run containers to handle sparse and dense segments, trading encoding complexity for much smaller storage than a naive bitmap"], "summary": "Grab's Segmentation Platform moved segment storage from row-per-user rows in ScyllaDB to compressed Roaring Bitmap blobs in object storage, cutting segment creation writes and read latency. A client SDK handles fetching, decoding, caching and refresh, and set operations now run on the fly.", "interview_angle": "How would you store and serve millions of user-set memberships so that bulk segment creation is fast and per-request membership checks stay sub-millisecond, and what trade-offs come with caching at the client?", "score": 1.4261, "hn_points": 0, "hn_comments": 0}, {"url": "https://medium.com/airbnb-engineering/beyond-synthetic-testing-capturing-and-replaying-real-database-workloads-at-airbnb-cea7ee9b1ab2", "company": "Airbnb", "industry": "marketplace", "title": "Beyond synthetic testing: Capturing and replaying real database workloads at Airbnb", "date": "2026-10-06", "primary_problem": "migration", "problems": ["platform", "performance"], "post_type": "case_study", "level": "advanced", "stack": ["MySQL", "ProxySQL", "Kubernetes", "Kafka", "Airbnb internal replay tooling"], "scale": "Hundreds of clusters, millions of QPS", "key_decisions": ["Capture traffic client-agnostically at the ProxySQL layer instead of per-language logging, avoiding app changes but adding a proxy-level dependency", "Bucket processed logs into five-minute windows per cluster and pod, giving fine-grained replay pacing at the cost of more files to manage", "Rewrite INSERTs to pin captured last_insert_id values for cross-engine consistency, trading away testing of the target's native auto-increment behavior"], "summary": "Airbnb replaced its fragmented client-side query logging with a ProxySQL-based capture pipeline that stores per-cluster, time-bucketed query datasets and replays them via a scheduled worker fleet. The system supports load testing at multiples of production rate, compatibility comparison across MySQL versions, and performance debugging, and it was used to guide the MySQL 5.7 to 8.0 upgrade.", "interview_angle": "How would you capture and replay production database traffic offline to load-test a new engine and detect result differences without touching application code?", "score": 1.426, "hn_points": 1, "hn_comments": 0}, {"url": "https://engineering.grab.com/data-gateway", "company": "Grab", "industry": "mobility", "title": "Securing and Managing Multi-cloud Presto Clusters with Grab\u2019s DataGateway", "date": "2020-08-24", "primary_problem": "governance_privacy", "problems": ["platform", "migration"], "post_type": "case_study", "level": "intermediate", "stack": ["Presto", "Kubernetes", "AWS EMR", "AWS EKS", "S3", "Azure"], "scale": "350,000 queries per day over 10,000 tables and up to 1 PB processed daily", "key_decisions": ["Route all Presto traffic through one gateway endpoint so cluster changes (EMR swaps, version upgrades, Azure additions) happen by editing ACLs rather than asking users to change connections; trade-off is the gateway becomes a critical single point of failure and latency hop.", "Enforce schema/table/column ACLs by parsing SQL in a separate parser service compiled per Presto version; trade-off is keeping parsers in sync with each Presto version's grammar.", "Run gateway components as Kubernetes microservices with HPA, splitting auth into its own service so security rules can change without redeploying the API service; trade-off is more moving parts to operate."], "summary": "Grab describes DataGateway, a smart HTTP proxy in front of its Presto clusters that parses SQL to enforce table-level ACLs and routes users to authorised clusters on AWS and Azure. The gateway let Grab migrate about 40 EMR clusters and offer cross-cloud cluster switching without user-facing endpoint changes.", "interview_angle": "How would you design a single query endpoint that enforces fine-grained table and column access across multiple query clusters and clouds while allowing cluster migrations without user disruption?", "score": 1.4258, "hn_points": 0, "hn_comments": 0}, {"url": "https://shopify.engineering/faster-trino-query-execution-infrastructure", "company": "Shopify", "industry": "ecommerce", "title": "Shopify's Path to a Faster Trino Query Execution: Infrastructure", "date": "2021-07-09", "primary_problem": "performance", "problems": ["platform", "scale_ingestion"], "post_type": "case_study", "level": "advanced", "stack": ["Trino", "Kubernetes", "Google GKE", "Trino Gateway", "Airflow", "Datadog", "Kafka", "Google Cloud Storage", "Alluxio", "JSON", "Parquet"], "scale": "15 Gbps and over 300 million rows per second; P95 query latency target under 5 seconds", "key_decisions": ["Split interactive workloads into dedicated clusters (scheduled, ad hoc, experiments, ephemeral) to stop heavy jobs starving user queries, at the cost of more clusters to operate and route", "Cap root resource group hardConcurrencyLimit at 60 to cut coordinator lock contention, trading away some peak parallelism that could otherwise use idle cluster capacity", "Apply recommended JVM recompilation cutoff settings and limit task.max-drivers-per-task to 16 so one query cannot monopolize workers, accepting that the heaviest queries run longer"], "summary": "Shopify tuned its Trino-based interactive query infrastructure to bring P95 query latency down from minutes toward seconds on a large GCS-backed data lake. The fixes came from workload isolation, coordinator concurrency limits, JVM recompilation settings and a per-task driver cap, rather than simply scaling up hardware.", "interview_angle": "How would you keep interactive SQL latency predictable when heavy batch-style and experiment queries share one query engine cluster? Walk through isolation, concurrency limits and per-query resource caps.", "score": 1.4242, "hn_points": 6, "hn_comments": 0}, {"url": "https://eng.lyft.com/gotchas-of-streaming-pipelines-profiling-performance-improvements-301439f46412", "company": "Lyft", "industry": "mobility", "title": "Gotchas of Streaming Pipelines: Profiling & Performance Improvements", "date": "2023-06-06", "primary_problem": "performance", "problems": ["realtime", "scale_ingestion"], "post_type": "deep_dive", "level": "advanced", "stack": ["Flink", "Beam", "Python", "Protobuf", "Pyflame", "flameprof", "Cython"], "scale": "hundreds of thousands of events per second", "key_decisions": ["Profile with flame graphs and Flink dashboard first, instead of guessing at fixes; costs tooling setup but targets the real bottleneck.", "Fix hot shards by choosing a more uniform partition key such as user ID over city or region; a better key takes rework but beats adding compute that cannot fix skew.", "Drop unneeded data and attributes at the start of the pipeline and pass a single protobuf message between operators; trades schema management for less network and serialization work."], "summary": "Lyft describes an iterative process for finding and fixing performance problems in Apache Beam and Flink streaming pipelines. The post ranks common bottlenecks (data skew, large windows, slow external calls, serialization) and lists general tuning tactics such as early data pruning, fewer shuffles, smaller state, and checkpoint tuning.", "interview_angle": "How would you diagnose a streaming job that misses its latency SLA while adding more workers does not help? Walk through profiling, identifying hot keys, and reducing shuffles and state size.", "score": 1.4221, "hn_points": 0, "hn_comments": 0}, {"url": "https://eng.lyft.com/refreshing-the-travel-time-map-behind-lyfts-marketplace-rebuilding-neighborhood-reachability-5be3efbc82ea", "company": "Lyft", "industry": "mobility", "title": "Refreshing the Travel-Time Map Behind Lyft\u2019s Marketplace: Rebuilding Neighborhood Reachability\u2026", "date": "2026-09-10", "primary_problem": "quality", "problems": ["modeling", "platform"], "post_type": "case_study", "level": "advanced", "stack": ["Airflow", "geohash", "Routing Simulation System"], "scale": "Hundreds of regions; nine time-category ETA files per region under development", "key_decisions": ["Use drivable geohashes derived from road-network segments as both a positive signal and a final denylist, trading extra mapping dependency for removal of non-navigable cells like open water", "Relax session-based pruning for established regions and skip it for new regions, trading more coverage for many more origin-destination pairs to process", "Blend historical trip ETAs with simulated ETAs from RSS for sparse pairs, trading simulation cost and fidelity for graceful coverage of the long tail"], "summary": "Lyft rebuilt the Neighborhood Reachability Signal, a precomputed geohash travel-time matrix used by pricing and supply systems, after it had been frozen since 2018\u20132019. The redesign grounded the geohash universe in drivable road data, loosened pruning to close coverage gaps, and exposed new fields so consumers could filter without local patches, with Pricing seeing positive results in a two-week test.", "interview_angle": "How would you design a precomputed travel-time lookup for a marketplace that must cover sparse long-tail pairs, avoid non-drivable cells, and refresh on a schedule without breaking consumers?", "score": 1.421, "hn_points": 0, "hn_comments": 0}, {"url": "https://engineering.grab.com/metasense-v2", "company": "Grab", "industry": "mobility", "title": "Metasense V2: Enhancing, improving and productionisation of LLM powered data governance", "date": "2024-11-14", "primary_problem": "governance_privacy", "problems": ["ml_data", "quality"], "post_type": "case_study", "level": "advanced", "stack": ["LangChain", "LangSmith", "Gemini"], "scale": "20,000+ data entries scanned; 300-400 entities per day", "key_decisions": ["Split one 21-tag PII/non-PII classifier into two smaller models (8 PII tags plus the rest) to reduce per-task load, trading more LLM calls for accuracy", "Cut the classification prompt from about 1,254 to 737 words and split tables over 150 columns, trading some context per call for focus", "Adopt LangChain and LangSmith so data scientists can iterate on prompts and run evaluations, trading some framework dependence for faster experimentation"], "summary": "Grab describes a second iteration of its LLM-based metadata classifier that tags data lake columns with PII sensitivity tiers, now covering most of the data lake. The main fixes were splitting the classifier's task to free model capacity, tightening prompts, and moving prompt experimentation onto LangChain and LangSmith with ongoing misclassification monitoring.", "interview_angle": "How would you design an LLM-based column classification service for a large data lake so it stays accurate as data changes, and how would you split the task and monitor misclassifications?", "score": 1.42, "hn_points": 0, "hn_comments": 0}, {"url": "https://netflixtechblog.com/how-netflix-accurately-attributes-ebpf-flow-logs-afe6d644a3bc", "company": "Netflix", "industry": "media", "title": "How Netflix Accurately Attributes eBPF Flow Logs", "date": "2025-04-08", "primary_problem": "realtime", "problems": ["scale_ingestion", "quality"], "post_type": "deep_dive", "level": "advanced", "stack": ["eBPF", "Kafka", "Go", "AWS", "Netflix Data Mesh"], "scale": "5 million flow records per second; 30 c7i.2xlarge instances; 1% cross-regional flows", "key_decisions": ["Attribute local IPs at the source host using workload identity and eBPF maps, trading agent complexity for accuracy", "Replace discrete IP assignment events with continuous time-range heartbeats from flows, trading a small unattributed fraction for zero misattribution", "Keep attribution state in memory and rebuild on restart, avoiding persistent storage at the cost of a 1-minute disk-buffered delay"], "summary": "Netflix redesigned how its eBPF flow logs map IP addresses to workload identities, moving local attribution to the source host and building per-IP ownership time ranges from flow heartbeats. The new design eliminated misattribution in a two-week Zuul validation, with a 1-minute delay instead of 15 minutes and no persistent state.", "interview_angle": "How would you attribute transient IP addresses to owners in a high-churn cloud environment when change events arrive late, and how do you handle cross-node state and ordering?", "score": 1.4193, "hn_points": 160, "hn_comments": 58}, {"url": "https://stripe.com/blog/how-we-built-it-jurisdiction-resolution-for-stripe-tax", "company": "Stripe", "industry": "fintech", "title": "How we built it: Jurisdiction resolution for Stripe Tax", "date": "2025-07-10", "primary_problem": "performance", "problems": ["modeling", "late_data"], "post_type": "case_study", "level": "advanced", "stack": [], "scale": "166 million US mailing addresses, about 16,000 SPOTs, sub-10 ms p95 matching latency for most states", "key_decisions": ["Precompute jurisdiction regions (SPOTs) offline so online lookup only has to search a small precomputed set, trading storage and rebuild cost for transaction-time latency", "Replace complex polygons with bounding boxes indexed in an STR-built R-tree, then run exact point-in-polygon only on the few remaining candidates; trade-off is extra index structure and rebuild on each update", "Keep time-tagged historical SPOT versions so past transactions can be recalculated accurately; trade-off is growing memory footprint that the team says it is still working to reduce"], "summary": "Stripe describes its jurisdiction resolution system for Stripe Tax, which cleans US tax boundary data into precomputed, time-aware SPOT regions and matches addresses to them at transaction time. The core technique is an R-tree over bounding boxes followed by point-in-polygon checks, which brings matching to milliseconds across tens of thousands of complex polygons.", "interview_angle": "How would you design a low-latency point-in-polygon lookup over many complex geographic regions that also must support historical versions and frequent boundary updates?", "score": 1.4192, "hn_points": 3, "hn_comments": 0}, {"url": "https://engineering.zalando.com/posts/2025/07/direct-data-sharing-using-delta-sharing.html", "company": "Zalando", "industry": "ecommerce", "title": "Direct Data Sharing using Delta Sharing - Introduction: Our Journey to Empower Partners at Zalando", "date": "2025-07-07", "primary_problem": "governance_privacy", "problems": ["platform", "migration"], "post_type": "case_study", "level": "intermediate", "stack": ["Delta Sharing", "Databricks", "Unity Catalog", "Delta Lake", "Pandas", "Spark"], "scale": "200+ datasets, sizes up to 200TB, thousands of partners, >\u20ac5 billion GMV partner platform", "key_decisions": ["Chose Databricks' managed Delta Sharing service over self-hosting the open protocol, trading flexibility for lower operational burden and built-in Unity Catalog governance and audit logging", "Used zero-copy sharing of live Delta tables instead of exporting files via SFTP/CSV, avoiding duplication and sync challenges but tying partners to token-based access", "Started with manual partner onboarding and token distribution in the pilot, accepting non-scalable steps to validate quickly, then turned those steps into platform requirements"], "summary": "Zalando's Partner Tech team replaced fragmented partner data delivery (SFTP, CSV, APIs, email) with Delta Sharing, starting from a pilot and growing into an internal recipient-management platform. The post covers partner segmentation, the choice of managed Delta Sharing with Unity Catalog, and lessons on security and onboarding.", "interview_angle": "How would you design secure, governed external data sharing for thousands of partners with mixed technical skill, avoiding copies of large datasets while keeping audit and access control consistent?", "score": 1.4184, "hn_points": 0, "hn_comments": 0}, {"url": "https://shopify.engineering/complex-data-models-behind-shopify-tax-insights", "company": "Shopify", "industry": "ecommerce", "title": "The Complex Data Models Behind Shopify's Tax Insights Feature", "date": "2023-02-08", "primary_problem": "modeling", "problems": ["performance", "realtime"], "post_type": "case_study", "level": "intermediate", "stack": ["Spark", "dbt", "BigQuery", "Google Cloud Storage", "Google Cloud Bigtable", "SQL"], "scale": "Starscream runs tens of thousands of jobs and writes hundreds of terabytes per day (platform-wide)", "key_decisions": ["Prototype data models in SQL in BigQuery before productionizing, trading an extra step for faster peer review and quicker shipping via dbt instead of translating to PySpark", "Model tax rules in a validity-dated lookup table (valid_from/valid_to) so law changes are handled as data rather than hard-coded logic, at the cost of more complex joins", "Publish the latest merchant-state liability snapshot to Bigtable key-value store keyed by merchant ID for low-latency backend reads, trading away ad-hoc query flexibility for serving speed"], "summary": "Shopify describes how it built the data models behind its Tax Insights feature, which tells merchants when they hit economic nexus for sales tax in each U.S. state. The pipeline prototypes SQL in BigQuery, builds rule-driven and merchant-state-month models with Spark and dbt, and loads the latest snapshot into Bigtable for the admin UI.", "interview_angle": "How would you model time-varying business rules (such as state tax nexus thresholds with different evaluation windows) so they can change without code changes, and then serve the results to an application with low latency?", "score": 1.4161, "hn_points": 3, "hn_comments": 0}, {"url": "https://monzo.com/blog/we-secured-thousands-of-cassandra-clients-to-keep-monzos-data-safe", "company": "Monzo", "industry": "fintech", "title": "We secured thousands of Cassandra clients to keep Monzo's data safe", "date": "2019-12-17", "primary_problem": "governance_privacy", "problems": ["platform", "performance"], "post_type": "case_study", "level": "advanced", "stack": ["Cassandra", "Vault", "Kubernetes", "bcrypt", "S3"], "scale": "300,000 reads per second at peak; over 2300 Cassandra clients; over 500 services", "key_decisions": ["Generate per-ServiceAccount dynamic Vault roles from Kubernetes annotations instead of hand-writing or reconciling roles, trading a custom Vault plugin fork for no duplicated state and no privileged role-writing permissions", "Issue weekly expiring credentials per pod with renewal at about 80% of lifetime, trading more Vault dependency at startup for limited blast radius and better audit logs", "Cut bcrypt rounds from 10 to 4 to avoid CPU spikes on connect storms, relying on 95-bit random passwords to keep brute-force resistance"], "summary": "Monzo replaced Cassandra's shared static passwords and trusted-network model with per-pod, short-lived credentials and per-service authorisation. They did this by having Vault synthesise database roles on demand from Kubernetes ServiceAccount annotations, with a cached lookup and a staged rollout across their clusters.", "interview_angle": "How would you add authentication and least-privilege authorisation to a large shared database with hundreds of services, without making credential issuance a single point of failure or slowing query paths?", "score": 1.4156, "hn_points": 4, "hn_comments": 0}, {"url": "https://engineering.grab.com/blog/12", "company": "Grab", "industry": "mobility", "title": "Grab Tech", "date": "2022-11-24", "primary_problem": "platform", "problems": ["scale_ingestion", "quality"], "post_type": "case_study", "level": "intermediate", "stack": ["Flink", "Iceberg", "Kafka", "Spark", "StarRocks", "Azure Databricks", "Kubernetes", "Airflow", "FlinkSQL"], "scale": "", "key_decisions": ["Build a one-click ingestion platform on Flink so teams can onboard pipelines without bespoke engineering, trading generality for upfront platform investment", "Adopt Apache Iceberg for the data lake to get table-format features over legacy Hive-style storage, at the cost of a migration effort", "Use automated data product indicators and certification to ensure reliability, accepting the overhead of maintaining metadata and checks"], "summary": "This is an index page of Grab Tech engineering blog posts spanning 2016 to 2026, covering many topics from mobile and backend to ML. The data-engineering-relevant items include the Hugo Flink ingestion platform, the Iceberg data lake migration, Data Mesh certification and data reliability work, and real-time Kafka data quality monitoring.", "interview_angle": "How would you design a self-serve, one-click ingestion platform on top of stream processing so that many teams can onboard pipelines safely without custom code?", "score": 1.4154, "hn_points": 0, "hn_comments": 0}, {"url": "https://shopify.engineering/optimizing-apache-flink-applications-tips", "company": "Shopify", "industry": "ecommerce", "title": "7 Tips For Optimizing Apache Flink Applications", "date": "2022-03-08", "primary_problem": "realtime", "problems": ["performance", "scale_ingestion"], "post_type": "deep_dive", "level": "advanced", "stack": ["Flink", "Kubernetes", "Google Kubernetes Engine", "RocksDB", "Google Cloud Storage", "Kafka", "Scala", "Kryo", "Avro", "async-profiler", "VisualVM", "jemalloc", "jeprof", "Eclipse MAT"], "scale": "13 TB sales state; over 8 TB state in one app; tens of billions of messages per backfill", "key_decisions": ["Disable Kryo fallback and switch to Java BigDecimal and Scala enums: stronger type-safety and developer ergonomics traded for a serializer migration effort, yielding about 20% throughput gain", "Key records by partition before the file sink: adds a shuffle, but cuts active buckets per Task Manager by about 90% and avoids heap exhaustion; hour-level sub-partitioning helps with skew", "Use local SSD for RocksDB instead of NFS: faster disk I/O (about 10x processing rate) but local state is lost on instance failure, so recovery relies on checkpoints and savepoints"], "summary": "Shopify shares seven tuning lessons for large stateful Apache Flink pipelines, covering profiling tools, serialization, backfill-versus-steady-state configuration, file sink memory, SSD-backed RocksDB, classloading, and RocksDB native memory. The lessons come from production issues such as Kryo slowdowns, bucket-related heap exhaustion, and Metaspace and block cache memory overruns.", "interview_angle": "How would you size and tune a stateful streaming job that must backfill tens of billions of events quickly and then run with low latency in steady state, while keeping RocksDB state recoverable?", "score": 1.415, "hn_points": 11, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/tcp-resets-timeouts", "company": "Cloudflare", "industry": "infra", "title": "Bringing insights into TCP resets and timeouts to Cloudflare Radar", "date": "2024-09-05", "primary_problem": "scale_ingestion", "problems": ["quality", "lineage_catalog"], "post_type": "case_study", "level": "advanced", "stack": ["ClickHouse", "iptables", "NFLOG", "Cloudflare Radar"], "scale": "60M HTTP requests/s globally; 1 in 10,000 ingress TCP connections sampled", "key_decisions": ["Sample 1 in 10,000 new TCP connections at the kernel level with iptables, trading completeness for pipeline cost and scale", "Log only the first 10 packets per sampled connection and reconstruct flows from one direction, avoiding decryption and reliance on server responses", "Group packets by 5-tuple in 15-minute query windows and exclude near-cutoff flows, accepting truncation and approximate timing in exchange for simple batch analysis"], "summary": "Cloudflare built a passive sampling pipeline that logs the first packets of a sample of new TCP connections, stores them in ClickHouse, and reconstructs connections to classify those that end in reset or timeout before data exchange. The resulting dataset, published on Radar, is used to spot scanning, tampering, and network-specific anomalies.", "interview_angle": "How would you design a sampled packet-level logging pipeline at global scale that reassembles flows from partial, unordered records and aggregates them into near-real-time dashboards?", "score": 1.4149, "hn_points": 68, "hn_comments": 10}, {"url": "https://blog.cloudflare.com/r2-sql-deep-dive", "company": "Cloudflare", "industry": "infra", "title": "R2 SQL: a deep dive into our new distributed query engine", "date": "2025-09-25", "primary_problem": "performance", "problems": ["storage_formats", "platform"], "post_type": "deep_dive", "level": "advanced", "stack": ["Cloudflare R2", "Iceberg", "Parquet", "Apache DataFusion", "Apache Arrow", "Cloudflare Workers", "gRPC"], "scale": "petabytes of data scanned via metadata pruning; no specific figure stated", "key_decisions": ["Multi-layer metadata pruning (partition stats, column stats, Parquet row-group stats) before reading data, trading planning complexity for far fewer bytes read from object storage", "Streaming planning concurrently with execution instead of waiting for a full plan, reducing time-to-first-byte at the cost of more complex coordination", "Ordering work by ORDER BY partition columns so LIMIT queries can stop early, but only supporting ordering on partition key columns for now"], "summary": "Cloudflare describes R2 SQL, a serverless distributed query engine over Iceberg tables in R2 Data Catalog. The planner prunes manifests, files and Parquet row groups using Iceberg and Parquet statistics, streams work units to workers running Apache DataFusion, and stops early for top-N queries.", "interview_angle": "How would you design a serverless query engine over object storage that minimizes bytes read, using table metadata for pruning and streaming work to executors while supporting early termination for ORDER BY ... LIMIT queries?", "score": 1.4146, "hn_points": 9, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/rearchitecting-workers-kv-for-redundancy", "company": "Cloudflare", "industry": "infra", "title": "Redesigning Workers KV for increased availability and faster performance", "date": "2025-08-08", "primary_problem": "migration", "problems": ["quality", "storage_formats"], "post_type": "postmortem", "level": "advanced", "stack": ["Workers KV", "Cloudflare Workers", "Cloudflare R2", "Durable Objects", "KVSP"], "scale": "Hundreds of billions of key-value pairs, petabytes stored, millions of GET requests/s, tens of thousands of PUT/DELETE requests/s, tens of Gbps throughput", "key_decisions": ["Moved from a dual third-party object storage setup to a Cloudflare-owned distributed database (sharded, three-way replicated) with large values routed to R2, trading away provider redundancy for control and lower latency.", "Raced writes to both backends and acknowledged on the first success, with failed writes queued for background reconciliation; this favors latency and availability over strict consistency.", "Reads now race against both backends instead of preferring one, which closes a blind spot in consistency detection but costs more backend requests."], "summary": "Cloudflare rebuilt the storage backend of Workers KV after a June 2025 third-party provider outage, moving from dual external object stores to a self-owned hybrid design. Small values go to a sharded, replicated distributed database via a proxy layer, and objects up to 25 MiB go to R2, with reconciliation and crawlers keeping the two backends consistent.", "interview_angle": "How would you redesign a globally replicated key-value store to remove a single third-party dependency while keeping low latency, handling tiny and large objects differently, and reconciling divergent replicas without strong consistency?", "score": 1.4142, "hn_points": 5, "hn_comments": 0}, {"url": "https://stripe.com/blog/how-stripes-document-databases-supported-99.999-uptime-with-zero-downtime-data-migrations", "company": "Stripe", "industry": "fintech", "title": "How Stripe\u2019s document databases supported 99.999% uptime with zero-downtime data migrations", "date": "2024-06-06", "primary_problem": "migration", "problems": ["cdc_sync", "scale_ingestion"], "post_type": "deep_dive", "level": "advanced", "stack": ["MongoDB", "Kafka", "S3", "Go"], "scale": "5M+ queries/sec, petabytes of data, 2,000+ shards, 1.5 PB migrated in 2023", "key_decisions": ["Sort data by common index attributes before bulk import to raise write throughput 10x, at the cost of an extra sorting step during migration", "Replicate writes from source to target via the oplog streamed through Kafka and S3 rather than reading the source shard directly, protecting user query performance but adding pipeline lag to manage", "Use versioned gating for the traffic switch (bump a version token, drain replication, update routes), keeping the cutover under two seconds at the cost of a custom MongoDB patch"], "summary": "Stripe describes its DocDB Data Movement Platform, which performs online, client-transparent migration of chunks between MongoDB shards to support sharding, bin-packing, and version upgrades. The core pipeline combines bulk import from a snapshot, oplog-based async replication through Kafka and S3, a correctness check, and a sub-two-second versioned traffic switch.", "interview_angle": "How would you move terabyte-scale partitions between live database shards with zero downtime while keeping replication lag and cutover time bounded and the source shard's performance intact?", "score": 1.414, "hn_points": 19, "hn_comments": 4}, {"url": "https://netflixtechblog.com/100x-faster-how-we-supercharged-netflix-maestros-workflow-engine-028e9637f041", "company": "Netflix", "industry": "media", "title": "100X Faster: How We Supercharged Netflix Maestro\u2019s Workflow Engine", "date": "2025-09-29", "primary_problem": "platform", "problems": ["performance", "realtime"], "post_type": "deep_dive", "level": "advanced", "stack": ["Maestro", "Conductor", "Temporal", "Java", "PostgreSQL", "S3", "Spark", "Trino"], "scale": "Over 60,000 active workflows, over a million data processing tasks daily, hundreds of thousands of jobs", "key_decisions": ["Rewrote the internal flow engine instead of upgrading Conductor to 4.0 or adopting Temporal, trading external-library maturity for a simpler design with fewer state stores", "Kept workflow state in per-node memory with flow-group ownership and generation IDs, gaining latency at the cost of more complex partitioning and failover logic", "Rolled out per-workflow cutover with the 10-day timeout as a natural drain, accepting dual-infrastructure cost and configuration drift risk"], "summary": "Netflix rewrote the internal flow engine of its Maestro workflow orchestrator, moving to an in-memory stateful actor model with flow-group partitioning, an internal transactional-outbox-style queue, and generation-ID fencing. The change cut step launch overhead from about 5 seconds to 50 milliseconds across more than 60,000 workflows, and the migration was done by draining workflows from the old engine over time.", "interview_angle": "How would you design a workflow orchestrator that schedules millions of short tasks per day with low latency while guaranteeing a step runs on only one worker at a time and surviving node failures?", "score": 1.4086, "hn_points": 4, "hn_comments": 0}, {"url": "https://eng.lyft.com/building-real-time-machine-learning-foundations-at-lyft-6dd99b385a4e", "company": "Lyft", "industry": "mobility", "title": "Building Real-time Machine Learning Foundations at Lyft", "date": "2023-06-28", "primary_problem": "ml_data", "problems": ["realtime", "platform"], "post_type": "case_study", "level": "advanced", "stack": ["Flink", "PyFlink", "Kafka", "Kinesis", "S3", "Jupyter", "Kubernetes", "Hive"], "scale": "", "key_decisions": ["Use one portable RealtimeMLPipeline interface across notebook, local, staging and production so code is written once, trading some flexibility for lower onboarding friction", "Simulate streaming inputs with warehoused S3 data in non-production environments, since live streams cannot be accessed from notebooks for security reasons, trading fidelity for reproducibility and safety", "Maintain a fork of Apache Flink with a faster release process and custom S3/Hive connectors, trading upstream maintenance burden for iteration speed"], "summary": "Lyft built a common Python interface and tooling so ML developers can define real-time features, real-time learning and event-driven decisions once and run them across notebook, staging and production Flink clusters. The post reports cutting build time for real-time ML apps from weeks to days and covers the stateful-streaming challenges and adoption lessons behind it.", "interview_angle": "How would you give ML engineers a way to build streaming features that behaves the same in prototyping and production, and how would you simulate streaming inputs for backtesting when live streams are unavailable?", "score": 1.4073, "hn_points": 8, "hn_comments": 0}, {"url": "https://engineering.grab.com/iris", "company": "Grab", "industry": "mobility", "title": "Iris - Turning observations into actionable insights for enhanced decision making", "date": "2024-04-03", "primary_problem": "platform", "problems": ["realtime", "cost"], "post_type": "case_study", "level": "intermediate", "stack": ["Spark", "Presto", "Kafka", "Telegraf", "InfluxDB", "Grafana", "S3", "Databricks", "sparkMeasure", "JVM Profiler", "Kubernetes"], "scale": "\"Real-time metrics freshness 5-10 seconds; offline sync hourly to S3 tables\"", "key_decisions": ["Collect metrics non-invasively at the JVM level with JVM Profiler and sparkMeasure listeners, avoiding code changes in user jobs but adding instrumentation overhead", "Route metrics through Kafka to decouple user jobs from the monitoring pipeline, trading an extra component for asynchronous, non-blocking delivery", "Split storage into InfluxDB for low-latency dashboards and a data lake for historical analysis, accepting duplicated paths and hourly offline freshness"], "summary": "Grab describes Iris, an observability platform that captures JVM and Spark job metrics via Kafka into InfluxDB for near-real-time Grafana dashboards and into an S3-backed data lake for historical analysis. The post also covers using these metrics for cost attribution, Databricks cost fairness, and an early K-means model that flags over- or under-provisioned jobs.", "interview_angle": "How would you design a low-overhead metrics pipeline for thousands of Spark jobs that serves both sub-minute dashboards and long-term historical analysis without slowing the jobs it observes?", "score": 1.4072, "hn_points": 0, "hn_comments": 0}, {"url": "https://eng.lyft.com/postgres-aurora-db-major-version-upgrade-with-minimal-downtime-4e26178f07a0", "company": "Lyft", "industry": "mobility", "title": "Postgres Aurora DB major version upgrade with minimal downtime", "date": "2024-03-11", "primary_problem": "migration", "problems": ["cdc_sync", "platform"], "post_type": "case_study", "level": "advanced", "stack": ["PostgreSQL", "Aurora PostgreSQL", "AWS DMS", "Route53", "Envoy", "Kubernetes"], "scale": "~30 TB database, ~400 tables, ~30 min in-place downtime reduced to ~7 min", "key_decisions": ["Chose native logical replication over in-place upgrade (30 min downtime) and DMS (prolonged replication lag after cutover), trading operational complexity for minimal downtime", "Cloned the Aurora cluster for the upgraded target and used dedicated replication slots for heavy-write tables, trading extra storage and setup steps for faster catch-up", "Used an Envoy circuit breaker plus a read-only source DB to halt writes, and Route53 DNS switching to avoid app redeploys, trading a brief 503 window for a lossless cutover"], "summary": "Lyft's payments team upgraded a ~30 TB Aurora PostgreSQL transactions database from v10 to v13 by cloning the cluster, setting up native logical replication from the old primary, and cutting over during a short write freeze. The approach cut downtime from an estimated 30 minutes to about 7 minutes while avoiding the long replication lag that DMS would have caused.", "interview_angle": "How would you upgrade a multi-TB production database across major versions with near-zero data loss and minimal downtime, and how do you verify replication lag reaches zero before cutover?", "score": 1.4066, "hn_points": 0, "hn_comments": 0}, {"url": "https://netflixtechblog.com/auto-diagnosis-and-remediation-in-netflix-data-platform-5bcc52d853d1", "company": "Netflix", "industry": "media", "title": "Auto-Diagnosis and Remediation in Netflix Data Platform", "date": "2022-01-14", "primary_problem": "quality", "problems": ["platform", "realtime"], "post_type": "case_study", "level": "advanced", "stack": ["Spark", "Trino", "Flink", "Kafka", "Druid", "Iceberg", "S3", "Elasticsearch", "Titus", "Atlas", "Keystone"], "scale": "", "key_decisions": ["Regex-based rules engine for error classification keeps diagnosis fast and explainable, but needs continual curation as platform errors change; ML clustering is used to propose new rules that humans then vet.", "Automatic remediation (scaling Flink clusters, extending Kafka retention, auto-retrying transient batch errors) cuts operator toil, but risks acting wrongly, so persistent cases escalate to paging owners.", "Real-time aggregation of diagnosed failures in Druid with per-minute Atlas alerts detects platform-wide incidents quickly, trading some infrastructure cost for faster detection."], "summary": "Netflix describes Pensive, an auto-diagnosis and remediation system covering both batch Spark/Trino workflows and streaming Flink pipelines managed by Keystone. It classifies failures with curated regex rules, aggregates diagnoses in Druid to detect platform-wide incidents, and automatically remediates issues like Flink memory exhaustion or Kafka lag.", "interview_angle": "How would you design an automated failure triage system for a large batch and streaming platform that classifies errors, detects platform-wide incidents quickly, and safely auto-remediates before Kafka retention causes data loss?", "score": 1.4044, "hn_points": 2, "hn_comments": 0}, {"url": "https://www.capitalone.com/tech/cloud/solving-data-management-with-slingshot", "company": "Capital One", "industry": "fintech", "title": "Solving data management from the inside out | Capital One", "date": "2022-09-13", "primary_problem": "cost", "problems": ["platform", "governance_privacy"], "post_type": "case_study", "level": "intermediate", "stack": ["Snowflake"], "scale": "500 TB migrated, 6,000 analysts, millions of queries per day", "key_decisions": ["Built in-house Snowflake cost dashboards and alerts to catch spend spikes early, trading build effort for visibility tailored to internal needs", "Added dynamic warehouse scheduling so compute capacity follows usage peaks and troughs, trading some operational complexity for lower credit consumption", "Centralized governance via templated warehouse requests and approval workflows, assigning warehouse ownership to lines of business to balance central control with federated accountability"], "summary": "Capital One describes how, after moving its data estate to Snowflake, it built internal tools for self-service access, cost monitoring, dynamic warehouse scheduling and automated governance. The post reports a 27% projected cost saving over three years, 50,000 hours of manual effort saved and a 43% drop in cost per query, and explains the productization of these tools as Slingshot.", "interview_angle": "How would you control cloud data warehouse spend across many business units without making a central team the bottleneck? Discuss showback dashboards, warehouse-level ownership, scheduled scaling and approval workflows.", "score": 1.402, "hn_points": 0, "hn_comments": 0}, {"url": "https://eng.lyft.com/full-spectrum-ml-model-monitoring-at-lyft-a4cdaf828e8f", "company": "Lyft", "industry": "mobility", "title": "Full-Spectrum ML Model Monitoring at Lyft", "date": "2022-06-01", "primary_problem": "ml_data", "problems": ["quality", "platform"], "post_type": "case_study", "level": "advanced", "stack": ["Great Expectations", "Spark", "Kubernetes", "Fugue", "Presto"], "scale": "millions of model decisions per day; over 90% of production models have feature validation and score monitoring", "key_decisions": ["Built a custom low-latency validator on top of Great Expectations (0.1ms per row, async) instead of batch validation, trading library reuse for scoring-path latency", "Split monitoring into an online phase (feature validation, score monitoring) for fast onboarding and an offline phase (anomaly detection, performance drift) for deeper diagnosis, trading coverage speed against diagnostic power", "Built in-house rather than buying, to integrate with the ML platform and avoid vendor lock-in, accepting higher engineering cost in an immature market"], "summary": "Lyft's ML platform team built a two-phase model monitoring system covering online feature validation, model score monitoring, scheduled anomaly detection, and offline performance drift detection. They report broad adoption, catching many issues before production, and note that enforcing monitoring for all models requires cultural change and automation.", "interview_angle": "How would you design monitoring for hundreds of ML models served online, balancing per-request latency, delayed ground truth, and false-positive alert fatigue?", "score": 1.4015, "hn_points": 1, "hn_comments": 0}, {"url": "https://netflixtechblog.com/uda-unified-data-architecture-6a6aee261d8d", "company": "Netflix", "industry": "media", "title": "Model Once, Represent Everywhere: UDA (Unified Data Architecture) at Netflix", "date": "2025-06-12", "primary_problem": "modeling", "problems": ["lineage_catalog", "platform"], "post_type": "deep_dive", "level": "advanced", "stack": ["GraphQL", "Avro", "Iceberg", "RDF", "SHACL", "SKOS", "Apache Jena", "SPARQL", "Data Mesh"], "scale": "", "key_decisions": ["Use RDF and SHACL as the knowledge graph foundation, accepting the cost of adapting SHACL and RDF to enterprise schema patterns in exchange for semantic integration", "Define a single metamodel (Upper) and generate GraphQL, Avro, Iceberg and Java schemas from domain models, trading upfront modeling rigor for consistent contracts everywhere", "Adopt a named-graph-first information model with governing models per graph, giving modular team ownership and governance at the cost of more complex dependency resolution"], "summary": "Netflix describes UDA, a knowledge-graph-based unified data architecture where business domain models are defined once and projected into GraphQL, Avro and Iceberg schemas, with mappings linking concepts to physical data containers. It shows two production uses: PDM for controlled vocabularies and Sphere for self-service operational reporting that generates joins by walking the graph.", "interview_angle": "How would you design a metadata layer that keeps business concept definitions consistent across GraphQL services, warehouse tables and event streams, and generates schemas and pipelines from one model?", "score": 1.4, "hn_points": 140, "hn_comments": 103}, {"url": "https://engineering.grab.com/seamless-migration", "company": "Grab", "industry": "mobility", "title": "How we seamlessly migrated high volume real-time streaming traffic from one service to another with zero data loss and duplication", "date": "2024-12-05", "primary_problem": "migration", "problems": ["realtime", "cdc_sync"], "post_type": "case_study", "level": "advanced", "stack": ["Kafka", "DynamoDB", "Go"], "scale": "About 20,000 reads per second across 16 source Kafka streams", "key_decisions": ["Chose a time-based switchover shared across both services over feature flags, trading rollback simplicity for no flag-propagation skew and no duplication during toggles", "Moved stream processing code into a shared monorepo commons package so old and new services run identical logic, at the cost of coupling the two services during migration", "Wrote new output to temporary sink streams and tables first to validate in production before cutting over the real resources, at the cost of extra temporary infrastructure"], "summary": "Grab moved the stream-processing write path of a backend service into a separate service while keeping about 20,000 reads per second flowing from 16 Kafka streams. They used a per-stream scheduled switchover time coded into shared monorepo logic, validated output on temporary sinks, and reported no data loss or duplication over roughly three weeks.", "interview_angle": "How would you migrate a high-throughput Kafka consumer to a new service with no loss or duplication? Discuss feature flags versus coordinated time-based cutover, validation sinks, and rollback risks.", "score": 1.3998, "hn_points": 0, "hn_comments": 0}, {"url": "https://netflixtechblog.com/building-service-topology-at-scale-architecture-challenges-and-lessons-learned-f4b792f3f0d8", "company": "Netflix", "industry": "media", "title": "Building Service Topology at Scale: Architecture, Challenges, and Lessons Learned", "date": "2026-07-13", "primary_problem": "realtime", "problems": ["scale_ingestion", "performance"], "post_type": "deep_dive", "level": "advanced", "stack": ["Kafka", "Server-Sent Events", "Pekko Streams", "gRPC", "Parquet", "Scala", "eBPF"], "scale": "Millions of flow records per second, multi-region Kafka (4 regions), sub-second query latency", "key_decisions": ["Streaming-first ingestion with reactive backpressure: fresher topology (tens of minutes or better) at the cost of harder-to-debug stream graphs", "Three-stage distributed aggregation with redistribution between stages: spreads hot-key load and resolves intermediaries, at the cost of extra network hops and stage complexity", "Replacing gRPC with SSE for inter-stage streaming and using mutable aggregators on the hot path: lower CPU and GC overhead, but gives up some conventions and needs careful review"], "summary": "Netflix describes building a near real-time service dependency graph from eBPF flow logs, IPC metrics and traces, covering streaming architecture, a three-stage aggregation pipeline that resolves network intermediaries, and time-travel topology queries. The post focuses on production fixes for Kafka lag, hot nodes, GC pressure and reactive stream debugging.", "interview_angle": "How would you design a streaming pipeline that aggregates heavily skewed event data (power-law keys) without hot partitions, and how would you support point-in-time queries over the resulting graph?", "score": 1.3991, "hn_points": 2, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/an-overview-of-cloudflares-logging-pipeline", "company": "Cloudflare", "industry": "infra", "title": "An overview of Cloudflare's logging pipeline", "date": "2024-01-08", "primary_problem": "scale_ingestion", "problems": ["quality", "storage_formats"], "post_type": "case_study", "level": "advanced", "stack": ["systemd-journald", "syslog-ng", "Kafka", "Kafka MirrorMaker", "Elasticsearch", "Logstash", "Kibana", "ClickHouse", "Go", "Rust", "C++"], "scale": "Close to 1 million log lines per second; ELK cluster of 90 nodes; 10-node ClickHouse cluster", "key_decisions": ["Dual-shipping each machine's logs to two core data centers for redundancy, at the cost of double network traffic and storage", "Using a log-x dead letter queue with Kafka MirrorMaker to backfill a disconnected region's copy, trading extra complexity for complete logs after transient outages", "Partitioning Kafka by host and service name to preserve per-service ordering, which causes partition imbalance when rates differ across machines"], "summary": "Cloudflare's Observability team describes a multi-stage internal logging pipeline that moves debugging logs from services through journald and syslog-ng into redundant core data centers, buffered in Kafka. The logs are then stored in both an Elasticsearch cluster and a ClickHouse cluster, with a log-x mechanism to keep complete copies despite regional network failures.", "interview_angle": "How would you design a logging pipeline that ingests about a million events per second across globally distributed machines, stays available when a region is disconnected, and still preserves per-source ordering?", "score": 1.3986, "hn_points": 4, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/using-apache-kafka-to-process-1-trillion-messages", "company": "Cloudflare", "industry": "infra", "title": "Using Apache Kafka to process 1 trillion inter-service messages", "date": "2022-07-19", "primary_problem": "platform", "problems": ["scale_ingestion", "realtime"], "post_type": "case_study", "level": "intermediate", "stack": ["Kafka", "Go", "Sarama", "Protobuf", "prototool", "Prometheus", "Grafana", "Salt", "CUE", "Kafka Connect"], "scale": "14 Kafka clusters, ~330 nodes, over 1 trillion messages over eight years", "key_decisions": ["Wrap Sarama in an opinionated Go client (Messagebus-Client) for fast adoption, at the cost of hiding Kafka internals that can cause partition skew", "Use protobuf with a central schema registry and one message type per topic, gaining compatibility and type safety but multiplying low-throughput topics and their partition overhead", "Auto-generate topic and high-lag alerts from a GitOps YAML change, trading per-team alert customization for uniform observability"], "summary": "Cloudflare describes how its Application Services team runs 14 Kafka clusters (about 330 nodes) that carry over a trillion inter-service messages, centered on the general-purpose Messagebus cluster. The post covers the wrapper client, a Kafka Connect-style connector framework, a protobuf schema registry, and GitOps-driven automatic topic creation and lag alerting.", "interview_angle": "How would you design a self-serve event streaming platform for many internal teams, balancing ease of use against hidden Kafka pitfalls like partition skew, and how would you standardize schemas and observability across topics?", "score": 1.3983, "hn_points": 33, "hn_comments": 2}, {"url": "https://engineering.grab.com/pii-masking", "company": "Grab", "industry": "mobility", "title": "PII masking for privacy-grade machine learning", "date": "2023-06-01", "primary_problem": "governance_privacy", "problems": ["realtime", "ml_data"], "post_type": "case_study", "level": "advanced", "stack": ["Protocol Buffers", "Kafka", "Flink", "Scala", "Python", "AWS Macie", "Git"], "scale": "", "key_decisions": ["Tag PII fields in protobuf schemas and enforce it with a CI check on field names, trading some false positives and whitelist overhead for early, self-service enforcement", "Mask PII in a Flink job inside production using keyed HMAC for names and seeded randomness for numbers and dates, so joins and model features stay consistent while raw values never reach staging", "Rely on schema-driven decoding so new PII fields are dropped until the masking job is redeployed, trading a deployment step for fail-closed safety"], "summary": "Grab's streaming team enforces PII masking on ML data pipelines by tagging PII fields in protobuf schemas, validating tags in CI, and running a Flink masking job that mirrors sanitised Kafka streams into staging. The design keeps masked values consistent for model training and notes future work on detection and stronger privacy techniques such as data minimisation and differential privacy.", "interview_angle": "How would you give data engineers production-like data for ML tuning without exposing PII? Walk through schema-level tagging, enforcement in CI, and in-stream masking with deterministic outputs.", "score": 1.3967, "hn_points": 1, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/clickhouse-capacity-estimation-framework", "company": "Cloudflare", "industry": "infra", "title": "ClickHouse Capacity Estimation Framework", "date": "2020-11-05", "primary_problem": "cost", "problems": ["platform", "performance"], "post_type": "case_study", "level": "intermediate", "stack": ["ClickHouse", "Prometheus", "Thanos", "Grafana", "Prophet", "Python", "aiohttp", "Kubernetes"], "scale": "Over 100 nodes in largest cluster, 20+ clusters, ~90M rows/s insertion, ~850T disk across clusters", "key_decisions": ["Forecast only unreplicated bytes per shard instead of total replicated bytes, so topology changes and node replacements do not look like demand drops; trade-off is more complex PromQL and reliance on shard grouping.", "Store forecasts and actuals in ClickHouse rather than Prometheus, because ~300k series of high cardinality would strain Prometheus; trade-off is running an extra storage path for dashboards.", "Pull year-long metrics from Thanos into CSV files via concurrent hourly-chunked requests and append daily; trade-off is file-based storage instead of a proper store, but it avoids repeated slow queries."], "summary": "Cloudflare's Core SRE team automated ClickHouse disk capacity forecasting by pulling table-size metrics from Thanos, correcting for shard topology changes and migrated tables, and fitting Prophet models. Forecasts and actuals are stored in ClickHouse and shown in Grafana so product teams can review them and past predictions can be evaluated.", "interview_angle": "How would you design a capacity forecasting pipeline for a distributed analytics database that must survive node replacements, cluster resharding and table migrations without false trend signals?", "score": 1.3957, "hn_points": 47, "hn_comments": 6}, {"url": "https://monzo.com/blog/from-dashboards-to-data-products-how-we-are-redesigning-analytics-in-monzo", "company": "Monzo", "industry": "fintech", "title": "From Dashboards to Data Products: How We\u2019re Redesigning Analytics in Monzo Customer Operations", "date": "2025-07-11", "primary_problem": "modeling", "problems": ["migration", "cost"], "post_type": "case_study", "level": "intermediate", "stack": ["dbt"], "scale": "", "key_decisions": ["Organise warehouse models around domain entities (DDD) rather than a single catch-all table, trading more models to maintain for clearer boundaries and reuse", "Split the sprawling ~300-column Task model into an event fact, SCD2 episodes model and a lean final-state concept model, trading extra pipeline layers for modularity and lower blast radius", "Attach ownership and product-level guarantees (freshness, uptime, documentation) to each data product, accepting process overhead in exchange for trust and self-serve use"], "summary": "Monzo's Operations collective redesigned its analytics layer by mapping core business entities into domain-driven data products, starting with the Support Task. They replaced a ~300-column dbt task model with a layered set of event, episode and final-state models, partly to prepare for a platform migration and to curb rising warehouse costs.", "interview_angle": "How would you restructure a sprawling, widely-referenced warehouse model into reusable domain-aligned data products without breaking downstream consumers during a platform migration?", "score": 1.3953, "hn_points": 0, "hn_comments": 0}, {"url": "https://shopify.engineering/solving-data-discovery-challenges-shopify", "company": "Shopify", "industry": "ecommerce", "title": "How We\u2019re Solving Data Discovery Challenges at Shopify", "date": "2020-07-21", "primary_problem": "lineage_catalog", "problems": ["governance_privacy", "platform"], "post_type": "case_study", "level": "intermediate", "stack": ["Elasticsearch", "GraphQL", "Apollo", "graph database"], "scale": "Over 30% of Shopify's Data team uses Artifact weekly, with 50%+ monthly retention", "key_decisions": ["Build an in-house discovery tool instead of buying: full control and fit for varied asset types, at the cost of more engineering and technical debt", "Pull metadata from data tools via jobs rather than waiting for each team to build metadata APIs: faster time to market, but more brittle ingestion and a later refactor", "Launch with only the most-queried assets and their downstream reports and dashboards: quicker impact, but many asset types are left out initially"], "summary": "Shopify built Artifact, an internal data discovery and management tool that centralizes metadata, lineage, ownership and usage across its data stack. It uses a metadata ingestion pipeline feeding Elasticsearch for search and a graph database for lineage, with a GraphQL API serving the UI.", "interview_angle": "How would you design a data catalog that ingests metadata from many heterogeneous tools, supports search and upstream/downstream lineage, and balances build versus buy and push versus pull integration?", "score": 1.395, "hn_points": 0, "hn_comments": 0}, {"url": "https://www.capitalone.com/tech/software-engineering/postgresql-partitioning-tips", "company": "Capital One", "industry": "fintech", "title": "3 Tips for Leveraging PostgreSQL Partitioning | Capital One", "date": "2023-04-11", "primary_problem": "performance", "problems": ["storage_formats", "cost"], "post_type": "case_study", "level": "intermediate", "stack": ["PostgreSQL"], "scale": "Several TB archived daily; recent data served within milliseconds 99.9% of the time", "key_decisions": ["Partition by timestamptz in UTC so time-zone shifts do not create duplicate or misplaced rows, at the cost of extra care in the column type choice", "Detach old partitions for archival instead of bulk deletes, avoiding table locks but requiring a separate archive path", "Skip routine VACUUM on partitioned tables to avoid locking, accepting bloat that is capped by keeping only ~90 days of hot data"], "summary": "Capital One's Consumer Identity data team describes how they partition PostgreSQL tables by time to keep recent customer data fast to query. They detach partitions for archival rather than deleting rows and skip routine vacuuming, trading storage bloat for avoiding lock contention on live tables.", "interview_angle": "How would you design time-based partitioning and retention for a high-volume operational database so that reads stay fast while old data is archived without locking live tables?", "score": 1.3934, "hn_points": 0, "hn_comments": 0}, {"url": "https://medium.com/walmartglobaltech/stop-reacting-to-data-problems-heres-the-architecture-that-prevents-them-a274d54f624b", "company": "Walmart", "industry": "retail", "title": "Stop Reacting to Data Problems. Here\u2019s the Architecture That Prevents Them.", "date": "2026-08-25", "primary_problem": "quality", "problems": ["governance_privacy", "lineage_catalog"], "post_type": "case_study", "level": "advanced", "stack": ["Kafka", "Avro", "Schema Registry", "YAML"], "scale": "hundreds of engineering teams, thousands of downstream consumers; first 30 contracts registered", "key_decisions": ["Contracts are immutable once active; changes create new versions, trading agility for auditable history", "Breaking changes gated on explicit approval from every registered consumer, trading speed for coordination and fewer surprises", "Validation runs inside existing ETL engines rather than as a separate service, gaining 40-60% performance at the cost of coupling validation to the pipeline engine"], "summary": "Walmart describes a data contract system with a central YAML-based contract registry, policy engine for governance checks, consumer registration with approval gating for breaking changes, and contract enforcement in both batch ETL and Kafka streams. It also covers an immutable audit trail used as compliance evidence for SOX-regulated data.", "interview_angle": "How would you design a data contract system that lets many producer teams change datasets independently while preventing breaking changes for downstream consumers and producing audit evidence?", "score": 1.393, "hn_points": 0, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/cdnjs-dev-platform-migration", "company": "Cloudflare", "industry": "infra", "title": "Dogfooding at scale: migrating cdnjs to Cloudflare\u2019s Developer Platform", "date": "2026-07-30", "primary_problem": "migration", "problems": ["platform", "storage_formats"], "post_type": "case_study", "level": "intermediate", "stack": ["Cloudflare Workers", "Cloudflare Workflows", "Cloudflare R2", "Cloudflare KV", "Cloudflare Queues", "Cloudflare Containers", "Durable Objects", "D1", "Workers Cache", "GCP Cloud Functions", "Google Cloud Storage", "Pub/Sub", "Git", "GitHub", "DigitalOcean Spaces", "Algolia", "Rust"], "scale": "9 billion requests/day, ~108,000 req/s, 98.6% cache hit rate, 1.1TB+ git repo migrated", "key_decisions": ["Migrated existing KV content to R2 as-is rather than regenerating files, because regenerated minified/compressed outputs had different SRI hashes and would break pinned users; trade-off is copying millions of objects instead of reprocessing.", "Replaced the GitHub repo and split KV/GitHub storage with R2 as single source of truth and KV for metadata only; trade-off is giving up git history/tarball access in exchange for scalable storage, offset by an S3-compatible API for mirrors.", "Built the ingestion pipeline on Workflows with a Durable Object counter for fan-out/fan-in across thousands of per-file children, keeping a Rust compression container for buffer-heavy work; trade-off is in-memory buffering in the container until streaming is supported."], "summary": "cdnjs moved its publishing pipeline and storage from GCP Functions, a git-sync VM and a GitHub repo onto Cloudflare's Developer Platform, with R2 as the source of truth and Workflows orchestrating ingestion. The migration hit subrequest and step limits that were raised platform-wide, and the team copied existing content between accounts sharded through Queues.", "interview_angle": "How would you replace a chain of object-storage-triggered functions and a dual-write store (KV plus git) with a durable orchestrated pipeline and a single source of truth, while keeping published content byte-identical for consumers?", "score": 1.3926, "hn_points": 5, "hn_comments": 0}, {"url": "https://netflixtechblog.com/ready-to-go-sample-data-pipelines-with-dataflow-17440a9e141d", "company": "Netflix", "industry": "media", "title": "Ready-to-go sample data pipelines with Dataflow", "date": "2022-12-04", "primary_problem": "platform", "problems": ["quality", "storage_formats"], "post_type": "deep_dive", "level": "intermediate", "stack": ["Dataflow", "Spark", "Scala", "sparklyr", "R", "Iceberg", "Maestro", "Metacat"], "scale": "About 19,000 rows loaded daily into the sample output table", "key_decisions": ["Generate fully working sample workflows from a CLI template so new pipelines start with DDL, metadata, WAP, audits and unit tests, trading flexibility for consistency", "Use the same business logic across Spark SQL, PySpark, Scala and sparklyr so language differences are easy to compare, at the cost of less domain-specific examples", "Put DDL inside the workflow and gate writes with blocking audits under Write-Audit-Publish, so bad data is not published but each run takes longer"], "summary": "Netflix describes Dataflow sample workflows, a CLI feature that generates a runnable batch pipeline template with DDL, metadata registration, Write-Audit-Publish steps, data audits, high-water-mark updates and unit tests. The same top-100-titles-per-country example is provided in several languages to show how standard project layout and defaults speed onboarding and enforce best practices.", "interview_angle": "How would you give hundreds of engineers a standard, tested batch pipeline scaffold that includes schema, data quality gates, and downstream notification, while still allowing different languages?", "score": 1.3907, "hn_points": 0, "hn_comments": 0}, {"url": "https://netflixtechblog.com/dynamically-splitting-wide-partitions-in-cassandra-for-time-series-workloads-0eded064f456", "company": "Netflix", "industry": "media", "title": "Dynamic Repartitioning for Time Series Workloads", "date": "2026-06-03", "primary_problem": "performance", "problems": ["scale_ingestion", "storage_formats"], "post_type": "deep_dive", "level": "advanced", "stack": ["Cassandra", "Kafka", "gRPC"], "scale": "Petabytes of temporal event data; wide partitions growing to 500MB+", "key_decisions": ["Detect wide partitions on the read path rather than the write path, accepting brief sub-optimal reads in exchange for not taxing the majority of non-wide data", "Restrict splitting to immutable partitions first to reduce complexity, leaving mutable-partition splitting for later", "Keep original wide partitions as fallbacks and validate splits with checksums and shadow-mode comparisons, trading extra storage for operational safety"], "summary": "Netflix's TimeSeries abstraction on Cassandra suffered from wide partitions that caused high read latency and timeouts for some IDs. They added a per-ID asynchronous pipeline that detects wide partitions during reads, splits them into smaller partitions with checkpointed planning and checksum validation, and routes reads via Bloom filters, cutting tail latencies from seconds to around 200 ms.", "interview_angle": "How would you fix hot or wide partitions in a distributed time-series store without downtime? Discuss detection, background re-partitioning with checkpoints, validation, and transparent read routing.", "score": 1.3895, "hn_points": 0, "hn_comments": 0}, {"url": "https://engineering.grab.com/optimally-scaling-kafka-consumer-applications", "company": "Grab", "industry": "mobility", "title": "Optimally Scaling Kafka Consumer Applications", "date": "2020-10-13", "primary_problem": "cost", "problems": ["scale_ingestion", "platform"], "post_type": "case_study", "level": "advanced", "stack": ["Kafka", "Kubernetes", "AWS EKS", "Golang", "Horizontal Pod Autoscaler", "Vertical Pod Autoscaler", "Cluster Proportional Autoscaler"], "scale": "close to 400 billion events per week", "key_decisions": ["Switched from HPA to VPA with a fixed pod count matching topic partitions, cutting resource usage vs requested by about 45% but giving up fast reactive scaling", "Mapped pipeline priority classes to On-Demand vs Spot node groups, saving cost on non-critical workloads at the risk of preemption", "Added low-priority overprovisioned noop pods sized by a cluster proportional autoscaler, trading idle capacity for faster rescheduling and deploys"], "summary": "Grab describes how its Coban stream processing platform, which runs Kafka consumer pods on Kubernetes, moved from HPA to VPA with a fixed pod count tied to partition count to reduce wasted resources. It also uses priority classes across On-Demand and Spot nodes and overprovisioned placeholder pods to balance cost against availability.", "interview_angle": "How would you scale a Kafka consumer fleet so that per-pod partition load stays balanced while cutting over-provisioned compute, and what trade-offs come with spot instances and overprovisioning?", "score": 1.384, "hn_points": 0, "hn_comments": 0}, {"url": "https://engineering.grab.com/data-observability", "company": "Grab", "industry": "mobility", "title": "Ensuring data reliability and observability in risk systems", "date": "2024-04-23", "primary_problem": "quality", "problems": ["realtime", "lineage_catalog"], "post_type": "case_study", "level": "intermediate", "stack": ["Flink", "Flink SQL", "Datadog", "Slack", "JSON"], "scale": "", "key_decisions": ["Use Flink SQL to flatten heterogeneous nested JSON from many services into a uniform schema before observing it, trading upfront transformation work for consistent metrics across sources", "Compute counters in 5-minute tumbling windows and push them to Datadog, favouring near real-time alerting over exact per-event detection", "Group monitors per service stream with Datadog anomaly detection and route to Slack, trading some alert granularity for a simpler monitoring load and faster triage"], "summary": "Grab built a real-time data observability layer for GrabDefence, its risk management platform, by using Flink SQL to flatten and aggregate heterogeneous JSON streams into windowed metrics. These metrics are pushed to Datadog, where per-stream monitors with anomaly detection alert the data team via Slack, cutting detection time from days to hours.", "interview_angle": "How would you design real-time data quality monitoring over many heterogeneous upstream JSON feeds, and how do you keep alerts actionable as the number of monitored data points grows?", "score": 1.3836, "hn_points": 2, "hn_comments": 0}, {"url": "https://www.capitalone.com/tech/cloud/aws-dms-and-sql-server-replication", "company": "Capital One", "industry": "fintech", "title": "SQL Server Replication Best Practices: AWS RDS | Capital One", "date": "2021-08-19", "primary_problem": "cdc_sync", "problems": ["migration", "performance"], "post_type": "case_study", "level": "intermediate", "stack": ["AWS DMS", "Amazon RDS", "SQL Server", "Amazon CloudWatch", "Amazon EC2"], "scale": "4 RDS instances across two regions; row mismatch of ~100K rows observed", "key_decisions": ["Use AWS DMS CDC-based replication to build cross-region replicas, since RDS SQL Server 2012 lacked native cross-region read replicas; trade-off is operational complexity and lag.", "Size replication instances and isolate large-database tasks on multi-AZ servers; trade-off is higher infrastructure cost for reliability.", "Disable backups, triggers, CDC and foreign keys on target during full load and re-enable for ongoing replication; trade-off is temporary loss of integrity checks during load."], "summary": "Capital One moved a SQL Server database from EC2 to Amazon RDS and needed cross-region replication that RDS did not natively support for that version, so they used AWS DMS. The post shares practical lessons on sizing replication instances, preparing source and target, monitoring row counts, and tuning LOB settings after they saw row mismatches across regions.", "interview_angle": "How would you replicate a relational database across regions for DR when the managed service lacks native cross-region replicas, and how would you detect and fix row-count drift between source and target?", "score": 1.3814, "hn_points": 0, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/how-we-make-sense-of-too-much-data", "company": "Cloudflare", "industry": "infra", "title": "Over 700 million events/second: How we make sense of too much data", "date": "2025-01-27", "primary_problem": "scale_ingestion", "problems": ["quality", "cost"], "post_type": "deep_dive", "level": "advanced", "stack": ["Go", "ClickHouse", "GraphQL"], "scale": "706M events/second at peak, 107 GiB/s compressed, 100x growth since 2018", "key_decisions": ["Downsample in a controlled way at each pipeline stage (source, Logfwdr buffer, Logreceiver multi-resolution topics) instead of letting uncontrolled drops create gaps, trading sample precision for pipeline availability.", "Use max-min fair buffer sharing with weighted streams and merge low-resolution batches under load, accepting extra recompression cost avoided by also downsampling fresh data ('bottomless buffers').", "Estimate SUM, COUNT and AVG from sampled rows with the Horvitz-Thompson estimator and Bonferroni-combined confidence intervals, which requires random sampling; systematic sampling introduced bias that was fixed by shuffling before sampling."], "summary": "Cloudflare describes how its logging and analytics pipeline, now ingesting about 706M events per second, degrades gracefully by deliberately downsampling data at several stages when overloaded. The post explains how Horvitz-Thompson estimators and confidence bands recover trustworthy aggregates from sampled data, and how a systematic-sampling bug produced biased estimates until random shuffling was added.", "interview_angle": "How would you design a high-volume log pipeline that stays available under overload, and how would you let downstream analytics quantify the error introduced by dropping or sampling data?", "score": 1.381, "hn_points": 13, "hn_comments": 1}, {"url": "https://eng.lyft.com/smooth-cruiser-at-lyft-built-for-safety-and-transparency-b6a461e16f2a", "company": "Lyft", "industry": "mobility", "title": "Smooth Cruiser at Lyft: Built for Safety and Transparency", "date": "2026-11-17", "primary_problem": "scale_ingestion", "problems": ["performance", "ml_data"], "post_type": "case_study", "level": "intermediate", "stack": ["Airflow", "DynamoDB"], "scale": "Rush hours produce roughly 135 GB of raw telemetry per hour (about 2-3 GB per minute); billions of detected events processed daily", "key_decisions": ["Score each driver relative to local road- and time-specific norms rather than fixed universal thresholds, trading simplicity for fairer context-aware scores", "Use a rolling window of the last 100 rides within 12 months, balancing responsiveness against stability of the score", "Serve scores from DynamoDB, decoupled from the daily Airflow processing pipeline, so app reads stay fast and scale independently of batch compute"], "summary": "Lyft describes the data platform behind Smooth Cruiser, which turns raw phone telemetry from drivers into a daily safety score. The pipeline uses ML-detected harsh driving events, contextual normalization against local road and time norms, peer clustering by market, and an Airflow-orchestrated ETL with scores served from DynamoDB.", "interview_angle": "How would you design a daily pipeline that ingests high-volume mobile sensor telemetry, enriches it with location-based baselines, and serves per-user aggregates with low latency to an app?", "score": 1.3806, "hn_points": 0, "hn_comments": 0}, {"url": "https://tech.instacart.com/geo-based-ab-testing-and-difference-in-difference-analysis-in-instacart-catalog-2ba05e744a3f", "company": "Instacart", "industry": "marketplace", "title": "Geo-based AB Testing and Difference-in-Difference Analysis in Instacart Catalog", "date": "2022-06-02", "primary_problem": "modeling", "problems": ["platform", "performance"], "post_type": "case_study", "level": "advanced", "stack": ["Snowflake", "Airflow", "Periscope", "Python", "linearmodels"], "scale": "~1000 delivery zones; hundreds of daily catalog ETLs over billions of product attributes", "key_decisions": ["Randomize by delivery zone instead of duplicating the full catalog per experiment: far cheaper and scalable, but introduces cross-zone contamination and fewer effective units", "Use two-way fixed effects Difference-in-Difference with zone-clustered standard errors: handles non-linear seasonality and heterogeneity, but relies on a parallel-trends assumption that must be validated", "Match zones with PCA plus a greedy nearest-neighbor algorithm and an equivalence test, then automate via daily feature ETLs and a weekly experiment ETL behind a web UI: reduces manual data science effort, at the cost of prototype-level maturity"], "summary": "Instacart's Catalog team built a geo-based A/B testing system that randomizes delivery zones so that upstream catalog ETL changes reach treated zones without duplicating the whole catalog. The analysis uses a two-way fixed-effects Difference-in-Difference model with clustered standard errors, zone matching, and automated daily and weekly pipelines.", "interview_angle": "How would you A/B test an upstream data transformation that feeds many downstream consumers without duplicating the full dataset per experiment? Discuss randomization unit choice, contamination, and DiD validation.", "score": 1.3739, "hn_points": 0, "hn_comments": 0}, {"url": "https://medium.com/wise-engineering/grafana-mimir-compaction-from-bottleneck-to-savings-b26c6b0125a6", "company": "Wise", "industry": "fintech", "title": "Grafana Mimir Compaction: From Bottleneck to Savings", "date": "2025-01-15", "primary_problem": "storage_formats", "problems": ["cost", "performance"], "post_type": "postmortem", "level": "advanced", "stack": ["Grafana Mimir", "Thanos", "S3", "Grafana"], "scale": "About 6 million metric samples per second across tenants; roughly 250k blocks during the incident", "key_decisions": ["Scaled up CPU and memory for the compactor rather than only tuning configuration, trading higher compute spend for faster backlog clearance", "Tuned compactor configuration parameters in staging first, then promoted to production, accepting slower iteration in exchange for lower risk", "Kept Mimir over tuning Thanos, accepting a migration cost in exchange for simpler operations and multi-tenancy"], "summary": "Wise found that its Grafana Mimir compactor was falling behind on a very large tenant, leaving over 250k uncompacted blocks in S3 and making metadata sync take about 9 hours. After adding compute and tuning compaction settings, they cut storage, cross-AZ transfer and query latency, though the reported percentages are not independently broken down.", "interview_angle": "How would you diagnose a compaction backlog in a time-series block store where a single tenant dominates, and which metrics and alerts would catch block-count growth before it hurts query latency and storage cost?", "score": 1.3737, "hn_points": 0, "hn_comments": 0}, {"url": "https://tech.instacart.com/simplifying-large-scale-llm-processing-across-instacart-with-maple-63df4508d5be", "company": "Instacart", "industry": "marketplace", "title": "Simplifying Large-Scale LLM Processing across Instacart with Maple", "date": "2025-08-27", "primary_problem": "platform", "problems": ["scale_ingestion", "cost"], "post_type": "case_study", "level": "advanced", "stack": ["Temporal", "Parquet", "PyArrow", "S3", "Python", "orjson"], "scale": "Tens of millions of prompts per job-set; batches of 40-50K prompts; ~2.6 prompts/sec average", "key_decisions": ["Moved task storage from the database to S3 Parquet files, trading query flexibility for cheaper, faster bulk load/save of large inputs", "Used Temporal durable execution so long-running batch jobs resume without losing work, at the cost of adopting another orchestration system", "Chose per-failure-type retry policies (infinite for expired/rate-limited, capped for refused, opt-in image checks) to balance completion against wasted spend"], "summary": "Instacart built Maple, an internal service that takes CSV or Parquet files of prompts, splits them into provider batch jobs, handles upload, polling, retries and result merging, and tracks cost per team. The post shares throughput statistics from about 580 batches and lessons on moving storage to S3 Parquet, streaming processing, and handling task-level failures.", "interview_angle": "How would you design a bulk processing service that pushes millions of records through a rate-limited external API with batch limits, retries and cost attribution?", "score": 1.3737, "hn_points": 0, "hn_comments": 0}, {"url": "https://tech.instacart.com/red-means-stop-green-means-go-a-look-into-quality-assessment-in-instacarts-knowledge-graph-9ceeb3f1be24", "company": "Instacart", "industry": "marketplace", "title": "Red Means Stop. Green Means Go: A Look into Quality Assessment in Instacart\u2019s Knowledge Graph", "date": "2021-09-08", "primary_problem": "quality", "problems": ["lineage_catalog", "ml_data"], "post_type": "case_study", "level": "advanced", "stack": ["SPARQL", "QUDT", "ETL pipelines"], "scale": "millions of facts in the Instacart Knowledge Graph; scale not quantified", "key_decisions": ["Chose simple unit-test scoring (red/yellow/green) over ML-based cleaning for explainability and ease of implementation, at the cost of sophistication", "Ran outlier detection per taxonomy class rather than catalog-wide, trading extra grouping logic for context-aware accuracy", "Stored reliability tiers as separate named graphs so consumers can query by threshold, trading some storage and modeling simplicity for easy filtering"], "summary": "Instacart describes a reliability scoring system for its Knowledge Graph that runs unit tests (outlier detection, logical rules, embedding-based clustering, provenance checks) over staged graph data and labels each fact green, yellow, or red. Scores are written back to the graph as named graphs and failure logs are aggregated to find error hotspots and feed back to data providers.", "interview_angle": "How would you design a data quality scoring layer for a continuously rebuilt knowledge graph that must gate downstream publishing and remain explainable to data providers?", "score": 1.3733, "hn_points": 0, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/introducing-quicksilver-configuration-distribution-at-internet-scale", "company": "Cloudflare", "industry": "infra", "title": "Introducing Quicksilver: Configuration Distribution at Internet Scale", "date": "2020-03-30", "primary_problem": "cdc_sync", "problems": ["migration", "quality"], "post_type": "case_study", "level": "advanced", "stack": ["Kyoto Tycoon", "LMDB", "Prometheus", "Grafana", "Snappy", "PostgreSQL", "systemd", "PagerDuty"], "scale": "2.5 trillion reads/day, 30 million writes/day, over 90,000 database instances across thousands of servers, config propagated to 200 cities in seconds", "key_decisions": ["Replaced Kyoto Tycoon with a custom replicated KV store to fix write-lock read latency, weak replication and no HA, at the cost of building and owning a new system", "Chose LMDB for reads-optimized, append-only, crash-proof storage with concurrent multi-process access and running snapshots, trading away write throughput and causing fragmentation issues", "Used a sequence-numbered transaction log with batched 500ms writes, per-database IDs and handshake checks to detect lost updates and misconfigured replication, accepting log-in-database fragmentation"], "summary": "Cloudflare explains why its Kyoto Tycoon-based configuration store stopped scaling: write-induced read latency, unsafe disabled fsync, weak replication that could silently lose entries, and no zero-downtime upgrades. It describes Quicksilver, a replacement built on LMDB with sequenced transaction logs, batched writes and monotonic replication checks that distributes configuration globally.", "interview_angle": "How would you design a globally replicated configuration store for edge nodes that must keep serving reads during partitions, detect lost updates, and upgrade without downtime?", "score": 1.373, "hn_points": 50, "hn_comments": 7}, {"url": "https://monzo.com/blog/2022/12/15/building-an-extension-framework-for-dbt", "company": "Monzo", "industry": "fintech", "title": "Building an extension framework for dbt", "date": "2022-12-15", "primary_problem": "platform", "problems": ["migration", "performance"], "post_type": "deep_dive", "level": "advanced", "stack": ["dbt", "Airflow", "Python", "Go"], "scale": "~6.9k dbt models, ~150 regular contributors", "key_decisions": ["Replace a long-lived dbt fork with an extension framework of separate packages hooking into explicit internal points: lower upgrade pain than a fork, but coupling to private dbt internals and extra maintenance of multiple packages.", "Use dbt's internal objects (parsed manifest, DAG, selectors) instead of Jinja: far more capable and less code to write, but Jinja was simpler to deploy and less tied to internals.", "Rejected rewriting the tool in Go after it added a second tool to maintain; kept the Python base and invested in modular extensions and patches."], "summary": "Monzo explains how their heavily forked dbt, which had fallen far behind upstream and slowed compilation, was replaced by an extension framework. Custom commands and behaviour patches now live as separate Python packages that hook into explicitly defined dbt internals, making upgrades easier to manage.", "interview_angle": "How would you let many teams customise a widely used transformation tool without maintaining a diverging fork, and what trade-offs come with depending on private internals?", "score": 1.3719, "hn_points": 2, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/transformers-on-logpush", "company": "Cloudflare", "industry": "infra", "title": "Filter, reshape, and redact logs before export with Transformers", "date": "2026-10-12", "primary_problem": "platform", "problems": ["scale_ingestion", "governance_privacy"], "post_type": "case_study", "level": "advanced", "stack": ["Apache DataFusion", "Apache Arrow", "Go", "Rust", "cgo", "Cap'n Proto", "NDJSON", "Cloudflare Workers", "R2", "Kubernetes", "Buftee", "Bufstream"], "scale": "More than 1 billion events per second ingested; Logpush delivers more than 110 million records per second", "key_decisions": ["Run SQL transforms in-process inside the delivery service instead of calling a remote Cloudflare Worker, trading isolation and flexibility for fewer network hops and higher throughput", "Embed Apache DataFusion (Rust) and bridge to Go via Arrow IPC over a C ABI, which keeps batches columnar but adds serialization and FFI ownership complexity", "Fail closed on transform errors by retrying with backoff and disabling persistently failing jobs, prioritizing data correctness over delivery progress"], "summary": "Cloudflare added SQL-based Transformers to its Logpush export pipeline so customers can filter, redact and reshape logs before delivery. The engine runs in-process in the Go delivery service using Apache DataFusion over Arrow batches, with fail-closed semantics when a transform cannot run.", "interview_angle": "How would you add in-flight filtering and redaction to a high-throughput log export pipeline without adding a network hop or risking unredacted data leaking to destinations?", "score": 1.3715, "hn_points": 0, "hn_comments": 0}, {"url": "https://eng.lyft.com/gotchas-of-stream-processing-data-skewness-cfba58eb45d4", "company": "Lyft", "industry": "mobility", "title": "Gotchas of Stream Processing: Data Skewness", "date": "2021-02-16", "primary_problem": "realtime", "problems": ["performance", "scale_ingestion"], "post_type": "deep_dive", "level": "advanced", "stack": ["Beam", "Flink", "Kinesis", "Protocol Buffers", "Python"], "scale": "~3 million geohashes per minute, ~400 billion features per day", "key_decisions": ["Aggressively filter and trim events and attributes early to cut data transfer, at the cost of losing fields that might be needed later", "Use two-stage distributed aggregation (geohash then region) to spread heavy work, at the cost of an extra network shuffle", "Salt hot geohash keys with random suffixes to spread load, then remove salt and re-key downstream, at the cost of added complexity in the join step"], "summary": "Lyft's Marketplace team describes how data skew in Flink/Beam streaming pipelines shows up as uneven CPU, backpressure and latency, and how they diagnosed it with Flink metrics, the dashboard, and ad-hoc logging. They outline fixes including early filtering, two-stage aggregation, key salting, and explicit reshuffling, presented as the first installment of a series on streaming gotchas.", "interview_angle": "How would you detect and fix hot keys in a keyed streaming aggregation, for example when one city or region produces most of the events? Discuss salting, two-phase aggregation, and when a reshuffle helps or hurts.", "score": 1.3674, "hn_points": 0, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/clickhouse-query-plan-contention", "company": "Cloudflare", "industry": "infra", "title": "Our billing pipeline was suddenly slow. The culprit was a hidden bottleneck in ClickHouse", "date": "2026-05-14", "primary_problem": "performance", "problems": ["storage_formats", "cost"], "post_type": "deep_dive", "level": "advanced", "stack": ["ClickHouse", "ZooKeeper"], "scale": "Over 100 PB across a few dozen clusters; 2+ PiB in Ready-Analytics; millions of rows/sec ingestion; part count grew from 30k to 160k per replica", "key_decisions": ["Changed partition key from (day) to (namespace, day) to allow per-namespace retention, at the cost of many more data parts that hurt query planning", "Switched the planner's mutex from exclusive to shared lock: a simple concurrency fix, but readers still serialize on list copies", "Cached a shared read-only copy of the parts list instead of copying per query: saves CPU/memory churn but requires regenerating the cache on every part-set change"], "summary": "Cloudflare's billing aggregation queries in ClickHouse slowed after a partitioning change that added per-namespace granularity, multiplying data parts. Flame graphs using \"Real\" traces revealed that query planning was bottlenecked on a mutex and list copying rather than CPU or I/O, and three patches (shared lock, shared cached parts list, binary search by namespace) restored performance.", "interview_angle": "How would you design per-tenant retention in a shared OLAP table without exploding part counts, and how would you diagnose a query slowdown when CPU, I/O and rows scanned all look normal?", "score": 1.3657, "hn_points": 6, "hn_comments": 0}, {"url": "https://engineering.zalando.com/posts/2017/07/complex-event-generation-for-business-process-monitoring-using-apache-flink.html", "company": "Zalando", "industry": "ecommerce", "title": "Zalando Engineering Blog - Complex Event Generation for Business Process Monitoring using Apache Flink", "date": "2017-07-13", "primary_problem": "realtime", "problems": ["late_data", "performance"], "post_type": "case_study", "level": "advanced", "stack": ["Flink", "Kafka"], "scale": "Kafka topics retain 30 days of events; reprocessing limited to about 2 days per 1GB TaskManager", "key_decisions": ["Use event-time tumbling windows with custom triggers instead of Flink CEP, trading library convenience for full control over firing logic when iterating on patterns", "Buffer and order events in window state via watermark progression, which guarantees correct last-event timestamps but grows memory with the time span being processed", "Filter out early events during reprocessing rather than replay full 30-day Kafka history, because memory use scales with the event-time interval and caused OOM beyond about 2 days"], "summary": "Zalando describes a Flink job that turns streams of ORDER_CREATED and PARCEL_SHIPPED events into complex business-process events such as ALL_PARCELS_SHIPPED or THRESHOLD_EXCEEDED, using event-time windows, watermarks and custom triggers. The post focuses on the costs of ordering events in state, mismatched topic read rates, expired Kafka data causing incorrect early outputs, and reprocessing limits from memory pressure.", "interview_angle": "How would you generate a complex event when all N related events for a key must arrive within a time window, and how would you reprocess historical data without running out of memory?", "score": 1.3653, "hn_points": 0, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/cloudflare-incident-on-november-14-2024-resulting-in-lost-logs", "company": "Cloudflare", "industry": "infra", "title": "Cloudflare incident on November 14, 2024, resulting in lost logs", "date": "2024-11-26", "primary_problem": "quality", "problems": ["scale_ingestion", "platform"], "post_type": "postmortem", "level": "advanced", "stack": ["Go", "Cloudflare Logpush", "Cloudflare R2"], "scale": "About 4.5 trillion event logs/day sent to customers; 45 PB/day uncompressed through Logreceiver; 600M batches/day; Buftee buffers rose from ~1M to 40M", "key_decisions": ["Fail-open failsafe in Logfwdr forwarded all customers' logs when config was blank, trading data completeness for protection against config loss; this fail-open path was never load-tested at current scale", "Per-customer buffers in Buftee avoid head-of-line blocking and allow per-customer encryption and deletion, but each buffer costs resources, so a buffer explosion overwhelms the cluster", "Buftee's overload protection existed but was not configured; the team plans regular overload tests alongside existing cut tests and alerts on misconfigurations"], "summary": "A bad generated configuration made Logfwdr fall back to a fail-open path that forwarded logs for all customers, which made Buftee create roughly 40 times more per-customer buffers than it was provisioned for. Lost about 55% of Logpush logs over roughly 3.5 hours because cascade-protection settings in Buftee were never enabled and the fail-open path had not been tested at current scale.", "interview_angle": "How would you design a log delivery pipeline so that a bad routing config cannot fan out into a per-tenant buffer explosion, and how would you balance fail-open versus fail-closed behavior?", "score": 1.3637, "hn_points": 9, "hn_comments": 1}, {"url": "https://tech.instacart.com/lessons-learned-the-journey-to-real-time-machine-learning-at-instacart-942f3a656af3", "company": "Instacart", "industry": "marketplace", "title": "Lessons Learned: The Journey to Real-Time Machine Learning at Instacart", "date": "2022-09-06", "primary_problem": "ml_data", "problems": ["realtime", "scale_ingestion"], "post_type": "case_study", "level": "intermediate", "stack": ["Kafka", "Flink", "Feature Store", "gRPC"], "scale": "Terabytes of event data per day; features generated in seconds (previously hours); hundreds of models served in real time", "key_decisions": ["Centralize raw events in Kafka across siloed streaming tools: gains a consistent format and schema checks, at the cost of a few hundred ms extra latency and more resources", "Keep event storage separate from stream computation: gives a durable, replayable ground truth with configurable retention, but adds another component to operate", "Move from batch to real-time serving behind a unified interface (Griffin) and a widely used RPC framework: standardizes testing, canaries and monitoring, but ties ML teams to shared infrastructure and a new learning curve"], "summary": "Instacart describes moving its ML systems from batch-precomputed predictions to real-time serving and real-time features built on a feature store, an online inference platform, Kafka and Flink. The post covers the latency, availability and tooling challenges, plus the decision to centralize raw events in Kafka to reconcile multiple streaming stacks across teams.", "interview_angle": "How would you design a real-time feature pipeline that serves both streaming features and batch features at low latency, and how would you consolidate events from several siloed streaming teams into one consistent, replayable source?", "score": 1.3634, "hn_points": 0, "hn_comments": 0}, {"url": "https://engineering.grab.com/safer-flink-deployments", "company": "Grab", "industry": "mobility", "title": "Safer deployment of streaming applications", "date": "2023-05-02", "primary_problem": "platform", "problems": ["realtime", "quality"], "post_type": "case_study", "level": "advanced", "stack": ["Flink", "Kafka", "Kubernetes", "Spinnaker", "Helm", "Terraform", "Docker", "Scala", "Slack"], "scale": "", "key_decisions": ["Take a Flink savepoint before stopping the running job so the new version starts from identical state and Kafka offsets, trading extra deployment steps for state consistency", "Reject canary rollout for stream joins because partial traffic yields incomplete, inaccurate results", "Use blue-green with only one version consuming Kafka at a time and automatic rollback on health-check failure, storing previous replica counts as annotations because standalone clusters do not record them"], "summary": "Grab's real-time data platform team redesigned how Flink applications are deployed on Kubernetes via Spinnaker, adding savepoints before cutover so state and Kafka offsets stay consistent. The new flow runs automated health probes and rolls back to the prior configmap and resource layout when checks fail.", "interview_angle": "How would you safely deploy stateful stream processing jobs with rollback, given that canary traffic splitting breaks join semantics and state must match across versions?", "score": 1.3632, "hn_points": 0, "hn_comments": 0}, {"url": "https://tech.instacart.com/turning-data-into-velocity-capers-edge-and-cloud-data-flywheel-with-capsight-544a49ca3db7", "company": "Instacart", "industry": "marketplace", "title": "Turning Data into Velocity: Caper\u2019s Edge and Cloud Data Flywheel with Capsight", "date": "2026-02-17", "primary_problem": "ml_data", "problems": ["scale_ingestion", "quality"], "post_type": "case_study", "level": "intermediate", "stack": ["Ray"], "scale": "Millions of images daily across cart fleet; gigabytes of multimodal data per cart", "key_decisions": ["Trigger-based capture (activity signal plus barcode) limits collection to meaningful events, trading some missed signals for far less irrelevant data and network load", "Local buffering with storage thresholds and oldest-file cleanup on the cart, trading possible data loss on failed uploads for protection of disk and store network", "VLM pre-labeling with human correction instead of from-scratch annotation, trading model-error risk for a projected >70% annotation cost cut"], "summary": "Instacart describes Capsight, a platform that turns its Caper smart carts into a distributed data collection system: edge collector, cloud Depot for ingestion and curation, and a Ray-based Learner for training. The pipeline uses trigger-based capture and VLM pre-labeling to shorten the model iteration cycle from about a month to a week and to improve accuracy by over 5%.", "interview_angle": "How would you design an edge-to-cloud pipeline that collects selective multimodal sensor data from thousands of devices with limited store bandwidth, then turns it into labeled training sets?", "score": 1.363, "hn_points": 0, "hn_comments": 0}, {"url": "https://medium.com/expedia-group-tech/using-llms-to-analyze-spark-sql-plans-a-practical-approach-to-debugging-long-running-jobs-35eace7eeec4", "company": "Expedia", "industry": "travel", "title": "Using LLMs to Analyze Spark SQL Plans: A Practical Approach to Debugging Long-Running Jobs", "date": "2026-06-30", "primary_problem": "performance", "problems": ["cost", "platform"], "post_type": "case_study", "level": "advanced", "stack": ["Spark", "Iceberg", "LLM", "MCP server"], "scale": "Jobs running 1+ hours to 3+ hours; 23.5 TiB full scan; 279.7 GiB max skewed partition", "key_decisions": ["Use an LLM over Spark History Server plan and metric data rather than raw UI inspection; gains faster triage but risks hallucinated findings, which is mitigated by strict rule-based prompts and evidence requirements", "Constrain the model to a fixed set of anti-patterns (missed broadcasts, skew, missing partition filters, oversized broadcasts) with JSON output; improves consistency but limits detection to known rules", "Verify each LLM finding against the physical plan before changing code; costs manual validation time but keeps fixes grounded in real evidence"], "summary": "Expedia built an LLM-driven workflow that reads slow Spark SQL execution plans and task metrics pulled through an open-source Spark History Server MCP integration, then flags anti-patterns such as missed broadcast joins, skew, missing partition filters and oversized broadcasts. Engineers validated each finding in the physical plan, and the fixes reportedly cut runtimes by 40\u201395% on long-running jobs.", "interview_angle": "How would you diagnose a long-running Spark job with a 300-node plan\u2014what signals (broadcast size thresholds, partition size distribution, scan input size, spill metrics) would you check first, and how would you automate that triage?", "score": 1.3628, "hn_points": 0, "hn_comments": 0}, {"url": "https://engineering.zalando.com/posts/2026/10/structure-automating-data-ingestion-with-a-rag-flywheel.html", "company": "Zalando", "industry": "ecommerce", "title": "Automating Data Ingestion with a RAG Flywheel", "date": "2026-10-11", "primary_problem": "ml_data", "problems": ["quality", "platform"], "post_type": "case_study", "level": "advanced", "stack": ["AWS Bedrock", "Amazon Titan Text Embeddings V2", "Anthropic Claude", "PostgreSQL", "pgvector", "OpenAI Node SDK", "TypeScript"], "scale": "\"85% suggestion acceptance rate in production; no data volume stated\"", "key_decisions": ["Hardcode temperature to 0 and force tool-call output shape, trading creativity for repeatable mappings, while still validating every result in the API because tool use does not guarantee semantic correctness", "Use pgvector with HNSW and a 0.8 cosine similarity threshold ranked by approval count, favoring consensus over single-upload matches at the cost of cold-start coverage for novel columns", "Keep a human-in-the-loop review on every suggestion and make the historical embedding index deletable, trading automation speed for control over stale or wrong learning history"], "summary": "Zalando's Supply Operations team automates mapping of heterogeneous supplier spreadsheet headers to a 55+ column internal schema using an LLM on AWS Bedrock. Approved mappings are embedded into pgvector and retrieved as context for future uploads, forming a RAG feedback loop, with API-side validation and human review gating every suggestion.", "interview_angle": "How would you design a schema-mapping service that ingests messy supplier files, uses LLM suggestions with guardrails, and improves over time from human-approved history without letting bad mappings propagate?", "score": 1.3575, "hn_points": 0, "hn_comments": 0}, {"url": "https://shopify.engineering/catalog-clustering-part-ii", "company": "Shopify", "industry": "ecommerce", "title": "Cross-store product clustering across millions of stores", "date": "2026-10-20", "primary_problem": "lineage_catalog", "problems": ["scale_ingestion", "cost"], "post_type": "case_study", "level": "advanced", "stack": ["GBDT", "multilingual E5", "approximate nearest-neighbor search", "LLM judge"], "scale": "Billions of product listings across millions of stores; trillions of candidate pairs", "key_decisions": ["Pairwise matching with tiered scorers (L1 GBDT on CPU, L2 cross-encoder, L3 image-aware reranker) trades inference cost against match quality, with expensive LLM judgments reused as training data for cheaper models", "Bounded union-find with degree-based component budgets splits the graph into parallelizable units, at the cost of possibly splitting some true matches across components", "Precision-first GBDT merge rule in hierarchical agglomerative clustering guards against mixing product groups, accepting lower recall; cached scores and priority queues let daily builds reuse prior GPU work"], "summary": "Shopify describes a cross-store product clustering system that groups listings of the same real-world product under a global identifier across billions of listings. The pipeline retrieves candidate pairs with embedding search, scores them with three tiered models, and merges them into bounded components using a precision-tuned agglomerative clustering step with cached scores.", "interview_angle": "How would you design entity resolution across billions of records when pairwise comparisons are non-transitive, cost-constrained, and the catalog changes continuously?", "score": 1.3543, "hn_points": 0, "hn_comments": 0}, {"url": "https://netflixtechblog.com/data-reprocessing-pipeline-in-asset-management-platform-netflix-46fe225c35c9", "company": "Netflix", "industry": "media", "title": "Data Reprocessing Pipeline in Asset Management Platform @Netflix", "date": "2022-12-17", "primary_problem": "late_data", "problems": ["scale_ingestion", "migration"], "post_type": "case_study", "level": "advanced", "stack": ["Cassandra", "Kafka", "Elasticsearch", "Iceberg", "Atlas"], "scale": "", "key_decisions": ["Paginate Cassandra reads using sortable TimeUUID keys with asset-type and time-bucket sharding, avoiding reliance on driver paging limits but requiring careful table design upfront", "Use Kafka for async reprocessing with tunable consumer count and thread pools, enabling throttling and halt at the cost of added pipeline components and timeout tuning", "Acknowledge failed events and route them to a dead letter queue for later reprocessing, keeping the consumer unblocked at the cost of deferred error handling"], "summary": "Netflix describes a reusable pipeline for reprocessing existing asset metadata in its Asset Management Platform, covering backfills, reindexing, and schema changes without downtime. The design extracts assets from Cassandra via paginated reads, fans out per-asset events through Kafka, and processes them with pluggable processors isolated in separate clusters.", "interview_angle": "How would you backfill or reprocess billions of existing records in a live operational store without degrading production traffic, and how would you paginate and throttle that work safely?", "score": 1.3541, "hn_points": 0, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/adopting-opentelemetry-for-our-logging-pipeline", "company": "Cloudflare", "industry": "infra", "title": "Adopting OpenTelemetry for our logging pipeline", "date": "2024-06-03", "primary_problem": "migration", "problems": ["scale_ingestion", "platform"], "post_type": "case_study", "level": "advanced", "stack": ["OpenTelemetry Collector", "syslog-ng", "Kafka", "Salt", "Nomad", "systemd-journald", "Prometheus", "Go"], "scale": "Millions of log events per second globally", "key_decisions": ["Replace syslog-ng with a custom OpenTelemetry Collector distribution built via OCB, trading the cost of maintaining internal components and forks for Go maintainability and unified telemetry tooling", "Fork the upstream file exporter to add plain text and syslog formats and custom permissions, instead of upstreaming, accepting a fork to maintain", "Roll out edge gradually but onboard core roles manually with canaries, and swap daemons in one systemd oneshot to minimize named-pipe blocking gap"], "summary": "Cloudflare replaced syslog-ng on every server in its log pipeline with a custom OpenTelemetry Collector distribution, building internal exporters and processors to keep downstream systems unchanged. The rollout surfaced failover and cutover issues where named-pipe writers blocked, which they fixed with tighter timeouts and a single oneshot swap of daemons.", "interview_angle": "How would you replace a log-shipping agent across a fleet of thousands of servers without changing downstream consumers, and how would you avoid blocking producers during cutover?", "score": 1.3528, "hn_points": 4, "hn_comments": 0}, {"url": "https://shopify.engineering/real-time-buyer-signal-data-pipeline-shopify-inbox", "company": "Shopify", "industry": "ecommerce", "title": "Building a Real-time Buyer Signal Data Pipeline for Shopify Inbox", "date": "2021-12-13", "primary_problem": "realtime", "problems": ["late_data", "cdc_sync"], "post_type": "case_study", "level": "advanced", "stack": ["Kafka", "Beam", "Google Cloud Dataflow", "Debezium", "MySQL"], "scale": "4M+ conversations exchanged on Shopify Inbox in 2020; tens of thousands of cart/checkout events per second", "key_decisions": ["Used Apache Beam stateful processing with timers and a global window to keep per-buyer snapshots, trading state size and garbage-collection complexity for accurate real-time signals", "Filtered cart and checkout events early to cut workload, accepting the risk of dropping events that might be needed later", "Handled out-of-order events by comparing timestamps against state and inferring cart actions from quantity changes, which is robust but depends on inferred logic rather than explicit source actions"], "summary": "Shopify built a real-time Apache Beam pipeline on Dataflow that combines Kafka event streams and Debezium CDC to surface cart and order signals to merchants during Shopify Inbox conversations. The design centers on stateful per-buyer aggregation with timers, handling cross-source ordering, and an A/B test showing gains in response rate and conversion.", "interview_angle": "How would you design a low-latency pipeline that joins multiple out-of-order event sources per user, keeps bounded state with expiring windows, and emits only when a business condition holds?", "score": 1.3523, "hn_points": 0, "hn_comments": 0}, {"url": "https://engineering.grab.com/big-data-real-time-presto-talariadb", "company": "Grab", "industry": "mobility", "title": "Querying Big Data in Real-time with Presto & Grab's TalariaDB", "date": "2019-01-02", "primary_problem": "realtime", "problems": ["scale_ingestion", "performance"], "post_type": "deep_dive", "level": "advanced", "stack": ["Presto", "TalariaDB", "Kafka", "Spark", "S3", "ORC", "Badger", "Route53", "Kubernetes", "Golang"], "scale": "Ingests several TB/hour; targets at least 1 million events/sec per cluster; queries 2-3 TB/hour; ~1 minute end-to-end latency", "key_decisions": ["Build a custom time-series store (TalariaDB) on Badger LSM tree rather than adopt an off-the-shelf database, trading generality for simplicity and low latency over a one-hour hot window", "Store pre-batched columnar blocks keyed by metric name and time instead of single rows, improving ingestion throughput and scan efficiency at the cost of more complex key management", "Favor availability over consistency (AP) with no replication: partial data is served when nodes fail, and downscaling must wait for data to expire"], "summary": "Grab describes TalariaDB, a distributed low-latency time-series store that holds the last hour of real-time event data and serves it to Presto through the Thrift connector. Events are batched into columnar files, ingested via S3 notifications into a Badger LSM tree, and queried with SQL within about a minute of being tracked.", "interview_angle": "How would you design a system that makes events queryable with SQL within a minute while ingesting millions of events per second and keeping only a short hot retention window?", "score": 1.3508, "hn_points": 1, "hn_comments": 0}, {"url": "https://medium.com/pinterest-engineering/partition-finalization-in-pinterests-next-generation-db-ingestion-framework-4c7da6e4cc8f", "company": "Pinterest", "industry": "social", "title": "Partition Finalization in Pinterest\u2019s Next-Generation DB Ingestion Framework", "date": "2026-09-25", "primary_problem": "late_data", "problems": ["storage_formats", "cdc_sync"], "post_type": "deep_dive", "level": "advanced", "stack": ["Kafka", "Flink", "Spark", "Iceberg"], "scale": "", "key_decisions": ["Derive partition finalization from event-time statistics stored in Iceberg snapshot summaries, avoiding an external service but tying the signal to commit metadata", "Use a monotonic, non-regressing watermark computed as the minimum of recent per-commit minimum event times, rounded to the hour; this is conservative but can delay freshness, with an optional percentile policy for freshness-tolerant tables that accepts rare late records", "Build generic Accumulators and CommitProcessor extension points into the Flink-to-Iceberg sink so the mechanism is reusable, at the cost of custom sink operators when enabled"], "summary": "Pinterest's stream-based DB ingestion framework needed a way to tell downstream batch consumers when an hourly Iceberg partition is complete, since streaming CDC writes no longer make completeness implicit. They have Flink compute event-time statistics per checkpoint, store a mergeable t-digest sketch in the Iceberg snapshot summary, and advance a non-regressing finalization watermark stored as a table property that is propagated to the base table.", "interview_angle": "How would you signal to downstream batch jobs that a streaming-ingested time partition is complete enough to read, without rerunning or scanning the table, and how do you trade off completeness against freshness?", "score": 1.3508, "hn_points": 0, "hn_comments": 0}, {"url": "https://netflixtechblog.com/building-a-resilient-data-platform-with-write-ahead-log-at-netflix-127b6712359a", "company": "Netflix", "industry": "media", "title": "Building a Resilient Data Platform with Write-Ahead Log at Netflix", "date": "2025-09-26", "primary_problem": "platform", "problems": ["realtime", "cdc_sync"], "post_type": "deep_dive", "level": "advanced", "stack": ["Kafka", "SQS", "Cassandra", "EVCache", "Memcached", "Envoy"], "scale": "Hundreds of millions of users; scale figures not stated", "key_decisions": ["Single generic WAL API with namespace-level config so teams can switch between Kafka and SQS without code changes, at the cost of an extra abstraction layer to operate", "At-least-once delivery semantics chosen for simplicity and reliability, meaning consumers must tolerate duplicate processing", "Asynchronous MutateItems via WAL with completion markers and durable state instead of synchronous client-side retries, trading immediate consistency for eventual completion"], "summary": "Netflix describes a generic Write-Ahead Log service built on Kafka and SQS behind a single API, deployed via its Data Gateway with per-namespace configuration. It is used for delayed queues, cross-region replication of non-replicated stores like EVCache, retries, and two-phase multi-partition mutations in Key-Value.", "interview_angle": "How would you design a reliable write-ahead log service that decouples producers from consumers, supports retries with delay, and replicates data across regions without changing application code?", "score": 1.3499, "hn_points": 3, "hn_comments": 0}, {"url": "https://shopify.engineering/managing-pii-shopify-scale", "company": "Shopify", "industry": "ecommerce", "title": "Schematizing Deletion at Scale", "date": "2021-06-10", "primary_problem": "governance_privacy", "problems": ["scale_ingestion", "migration"], "post_type": "case_study", "level": "advanced", "stack": ["Kafka"], "scale": "About 20 billion events/day (~230K events/s, peaks over 1M/s); tokenization vault holds 500B+ mappings (~200 TB); several PB of historic data", "key_decisions": ["Enforce event schemas at generation time with privacy context, trading upfront friction for guaranteed structure and privacy review", "Use obfuscation and tokenization before the warehouse so deletion means removing vault mappings rather than rewriting petabytes, at the cost of losing raw values for some analyses", "Per-controller tokens so a deletion request for one merchant does not affect data held for others, at the cost of more token mappings"], "summary": "Shopify describes a schematization platform that attaches types, ownership and privacy metadata to each analytical event, then obfuscates or tokenizes PII in the Kafka pipeline before it reaches the warehouse. Deletion becomes a vault operation that breaks token-to-PII links, so the petabyte-scale warehouse rarely needs rewriting, and the post covers the three-year effort to migrate historic datasets.", "interview_angle": "How would you design PII deletion for a high-volume event warehouse without rewriting petabytes of data? Walk through tokenization with per-controller consistency, a vault as the single source of truth, and how you would migrate historic datasets.", "score": 1.3487, "hn_points": 2, "hn_comments": 0}, {"url": "https://monzo.com/blog/2022/02/04/how-we-validated-our-handling-time-data", "company": "Monzo", "industry": "fintech", "title": "How we validated our handling time data", "date": "2022-02-04", "primary_problem": "quality", "problems": ["lineage_catalog", "performance"], "post_type": "case_study", "level": "intermediate", "stack": ["dbt", "Google Sheets", "BizOps"], "scale": "250+ processes validated with 60+ minutes of video each; 4 hours of initial validation video", "key_decisions": ["Validate handling time against independent ground truth from screen recordings, trading annotation effort for a benchmark that catches logic errors", "Embed time and task metadata as QR codes on screen so annotation tooling can read it back, trading upfront engineering work for reliable, scalable labelling", "Encode physically impossible-value and outlier checks as dbt tests, trading some ongoing maintenance for early alerts on data drift"], "summary": "Monzo's Operations data team found their customer-service handling time data produced impossible values, with raw figures 10x to 300x larger than logged-in time. They fixed event gaps and logic, then built a ground-truth benchmark from opt-in screen recordings, using QR-coded metadata to scale annotation and feed dbt quality checks.", "interview_angle": "How would you validate a derived operational metric when no independent dataset exists, and how would you turn one-off validation into ongoing automated checks?", "score": 1.3451, "hn_points": 0, "hn_comments": 0}, {"url": "https://www.coinbase.com/blog/how-we-scaled-data-streaming-at-coinbase-using-aws-msk", "company": "Coinbase", "industry": "fintech", "title": "How we scaled data streaming at Coinbase using AWS MSK", "date": "2021-08-24", "primary_problem": "platform", "problems": ["realtime", "cdc_sync"], "post_type": "case_study", "level": "intermediate", "stack": ["Kafka", "AWS MSK", "Kafka Connect", "Kinesis", "Snowflake", "Delta Lake", "Confluent Schema Registry", "Kafdrop", "Cruise Control", "ZooKeeper", "MongoDB", "PostgreSQL", "Golang", "Terraform"], "scale": "Billions of events daily; 30 MSK broker nodes (~17TB storage/broker); sub-10ms p50 e2e latency", "key_decisions": ["Adopt AWS MSK instead of self-managed Kafka to offload broker patching, recovery and upgrades, trading some control over internals for lower operational load", "Switch low-latency service communication from Kinesis (~200ms) to Kafka (\u003c10ms), accepting more client-side stream plumbing in exchange for much lower latency", "Build a Kafka Security Service that syncs topic ACLs and issues TLS certs tied to service identity, adding custom tooling beyond MSK's native auth"], "summary": "Coinbase's Data Platform team describes running its streaming backbone on AWS MSK, covering clickstream ingestion, CDC via Kafka Connect, and a Snowflake ETL feed. They report large latency gains over Kinesis and operational savings, plus custom tooling for ACL-based access control and a unified streaming SDK.", "interview_angle": "How would you design a multi-tenant streaming platform that balances managed-service operational savings against latency, access control and per-service security requirements?", "score": 1.3449, "hn_points": 0, "hn_comments": 0}, {"url": "https://shopify.engineering/faster-trino-query-execution-verification-benchmarking-profiling", "company": "Shopify", "industry": "ecommerce", "title": "Shopify's Path to a Faster Trino Query Execution: Custom Verification, Benchmarking, and Profiling Tooling", "date": "2021-10-27", "primary_problem": "performance", "problems": ["quality", "platform"], "post_type": "case_study", "level": "advanced", "stack": ["Trino", "Python", "PyTest", "trino-python-client", "TPC-DS", "Kubernetes"], "scale": "500 Gbps data handled; hundreds of Trino nodes, tens of thousands of vCPUs; p95 query target of 5 seconds", "key_decisions": ["Built one shared Python library for verification, benchmarking and profiling, trading upfront engineering effort for consistent, repeatable testing across use cases", "Used PyTest as the developer interface for verification so Data Platform engineers could reuse a familiar unit-testing pattern, at the cost of forcing performance checks into pass/fail thresholds", "Scoped down to verification only and deferred full benchmarking and profiling interfaces, accepting less coverage now to ship a reliable upgrade gate sooner"], "summary": "Shopify's Data Reliability team built a lightweight Python framework on top of trino-python-client to verify, benchmark and profile changes to its forked Trino cluster before rollout. The tool, exposed through PyTest fixtures, helped validate a successful Trino upgrade while keeping p95 query times stable.", "interview_angle": "How would you design a safe change-validation pipeline for a shared query engine, covering correctness checks, performance regression against a control cluster, and replaying realistic traffic?", "score": 1.3448, "hn_points": 5, "hn_comments": 0}, {"url": "https://engineering.grab.com/zero-trust-with-kafka", "company": "Grab", "industry": "mobility", "title": "Zero trust with Kafka", "date": "2022-12-07", "primary_problem": "governance_privacy", "problems": ["platform"], "post_type": "case_study", "level": "advanced", "stack": ["Kafka", "Strimzi", "Kubernetes", "HashiCorp Vault", "Open Policy Agent", "Terraform", "GitLab CI", "S3", "Golang", "Zookeeper"], "scale": "99.99% availability target for Kafka clusters across Grab verticals", "key_decisions": ["Chose mTLS over OAuth or SCRAM for authentication because peers can verify identity offline without a central auth server, at the cost of certificate management complexity", "Used Vault PKI to issue short-lived client certificates with capped TTLs, avoiding CRL maintenance but making Vault a dependency mitigated by SDK retries and renewal at two-thirds of TTL", "Adopted OPA with policy-based access control and one OPA per Kafka cluster, reducing blast radius while keeping authorisation changes reviewable through Git approvals; trade-off is a static policy model and throughput loss from encryption"], "summary": "Grab's real-time data platform team describes how it moved its Kafka clusters to zero-trust security using mutual TLS with Vault-issued short-lived certificates, Strimzi-managed CAs, and OPA-based topic authorisation driven by Git-reviewed policies. The post also covers the throughput cost of encryption and the plan to move from static PBAC toward attribute-based access control.", "interview_angle": "How would you secure a multi-tenant Kafka platform with zero trust: which authentication mechanism, how to issue and rotate short-lived client credentials, and how to keep topic authorisation auditable and self-service without creating a single point of failure?", "score": 1.3441, "hn_points": 0, "hn_comments": 0}, {"url": "https://www.capitalone.com/tech/software-engineering/spark-tuning-executor-optimization", "company": "Capital One", "industry": "fintech", "title": "Spark Executor Tuning for Optimal Performance | Capital One Tech", "date": "2026-04-28", "primary_problem": "performance", "problems": ["platform"], "post_type": "deep_dive", "level": "intermediate", "stack": ["Spark"], "scale": "5 worker nodes, 12 cores and 48 GB RAM each (example cluster)", "key_decisions": ["Fat executors maximize parallelism and data locality but waste resources and reduce fault tolerance when a single executor fails", "Thin executors improve fault tolerance and recovery granularity but add network traffic between driver and executors and reduce locality", "Optimal sizing reserves cores and memory for the OS, cluster manager and memory overhead, then targets 3-5 cores per executor to balance throughput and resource use"], "summary": "The article explains how Spark executor sizing affects parallelism, data locality, fault tolerance and network traffic, comparing fat, thin and optimally sized executors. It walks through a worked example on a 5-node cluster, applying rules for reserving OS resources, overhead memory and a 3-5 core target per executor.", "interview_angle": "How would you size Spark executors for a given cluster, and what trade-offs do fat versus thin executors introduce for parallelism, locality and failure recovery?", "score": 1.3435, "hn_points": 0, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/bgp-hijack-detection", "company": "Cloudflare", "industry": "infra", "title": "Cloudflare Radar's new BGP origin hijack detection system", "date": "2023-07-28", "primary_problem": "realtime", "problems": ["scale_ingestion", "lineage_catalog"], "post_type": "case_study", "level": "advanced", "stack": ["Rust", "PostgreSQL", "BGPKIT", "Cloudflare Workers", "Cloudflare KV"], "scale": "About 170 full-feed BGP peers on a single 32 GB node, roughly 200 MB RAM per peer's prefix trie", "key_decisions": ["Used an in-memory Rust prefix trie to track origin state instead of a database, trading restart-time rebuilds and RAM use for fast, simple per-message lookups", "Scored each origin-change signal with weighted evidence checks (RPKI, IRR, bogons, AS relationships, AS path) rather than a binary verdict, trading explainability and tunability against lack of a definitive answer", "Aggregated per-message signals into hijack events by hijacker and victim with a six-hour quiet period, reducing alert volume at the cost of delayed event closure"], "summary": "Cloudflare describes a streaming pipeline that consumes live and historical BGP update messages, detects prefix origin changes with an in-memory prefix trie, and scores them against RPKI, IRR, bogon and AS relationship datasets to flag likely hijacks. The detected signals are aggregated into events, stored in PostgreSQL, and exposed through Radar's website and API.", "interview_angle": "How would you design a near-real-time pipeline that processes a firehose of stateless BGP update messages, maintains derived state to detect changes, and reduces alert noise by aggregating events?", "score": 1.3431, "hn_points": 13, "hn_comments": 1}, {"url": "https://engineering.grab.com/evolution-of-grab-machine-learning-feature-store", "company": "Grab", "industry": "mobility", "title": "The evolution of Grab's machine learning feature store", "date": "2025-07-24", "primary_problem": "ml_data", "problems": ["migration", "performance"], "post_type": "case_study", "level": "advanced", "stack": ["Amazon Aurora PostgreSQL", "S3", "Parquet", "Spark"], "scale": "", "key_decisions": ["Organise features as versioned feature tables loaded atomically from the data lake, trading simpler user-side version handling for a more involved ingestion pipeline with validation and warm-up", "Choose Aurora PostgreSQL with separate serverless writer and provisioned readers, gaining read/write isolation and cost savings on mostly-idle writes while accepting a managed-database dependency", "Move from a centralised feature-serving API to decentralised per-orchestrator deployments, improving isolation, rollout flexibility and cache hit rates at the cost of harder version tracking"], "summary": "Grab describes its second-generation ML feature store, which replaces the earlier Amphawa design with feature tables that are written from the data lake and atomically ingested into Aurora PostgreSQL. The post explains the motivation (contextual retrieval, atomic collection updates, read/write isolation), the ingestion workflow with validation and shadow-read warm-up, and the move to decentralised serving deployments.", "interview_angle": "How would you design a feature store serving layer that supports atomic version switches of feature sets, isolates reads from writes, and keeps read-heavy traffic cheap and fast?", "score": 1.341, "hn_points": 0, "hn_comments": 0}, {"url": "https://engineering.grab.com/using-grabs-trust-counter-service-to-detect-fraud-successfully", "company": "Grab", "industry": "mobility", "title": "Using Grab\u2019s Trust Counter Service to Detect Fraud Successfully", "date": "2019-10-21", "primary_problem": "realtime", "problems": ["scale_ingestion", "performance"], "post_type": "case_study", "level": "advanced", "stack": ["ScyllaDB", "Redis", "gRPC", "Datadog", "Slack", "Grab-Stats", "GrabPlugin"], "scale": "Billions of fraud detections per day across millions of daily transactions; ~5k stream QPS at peak; 100K target QPS; p99 read under 150ms", "key_decisions": ["Pre-aggregate signals into 15-minute, 1-hour and 1-day buckets and stitch query windows together, trading storage and write amplification for bounded read latency over long time ranges", "Use ScyllaDB behind a Grab-Stats layer instead of in-memory stores like ElastiCache, trading some raw latency for roughly 10x lower cost and good aggregation performance", "Make counters self-service via UI and rule editor with an asynchronous ingestion path and synchronous storage writes, trading engineering control for faster analyst iteration (weeks down to minutes)"], "summary": "Grab's Trust Platform built a Counter service that streams booking and payment signals, computes per-entity counters (such as driver-passenger pair events) and serves them to a fraud rule engine in real time. The design uses multi-granularity time buckets over ScyllaDB to keep long-window queries within latency SLAs, and exposes a self-serve UI and SDK so analysts can create counters without engineering deployments.", "interview_angle": "How would you design a real-time counting service that answers both 30-minute and 90-day window queries under a p99 latency SLA, and how would you let non-engineers define new counters safely?", "score": 1.339, "hn_points": 0, "hn_comments": 0}, {"url": "https://shopify.engineering/bfcm-live-map-2021-apache-flink-redesign", "company": "Shopify", "industry": "ecommerce", "title": "Scaling Shopify's BFCM Live Map: An Apache Flink Redesign", "date": "2021-12-10", "primary_problem": "realtime", "problems": ["scale_ingestion", "performance"], "post_type": "case_study", "level": "intermediate", "stack": ["Flink", "Kafka", "Redis", "Spark", "Go", "React"], "scale": "Around 50,000 checkout messages/sec at 2021 BFCM peak; load-tested at 1 million events/sec; 1.7M+ merchants", "key_decisions": ["Put Flink on the critical path to filter checkout events so the custom Go service Cricket only handles about 1% of volume, trading a new dependency for relief on the bottleneck.", "Run Flink jobs in cross-region sharded active-active deployment for high availability, accepting the operational complexity of multi-region state.", "Keep Cricket as the compute source for existing metrics while using it as a relay for new Flink-computed metrics, which limited migration risk but left the Redis fan-out bottleneck in place."], "summary": "Shopify rebuilt the data path behind its BFCM live map so Apache Flink filters and computes high-volume checkout events ahead of a legacy Go streaming service, Cricket. The Flink jobs ran at 100% uptime during BFCM, but the Redis-based delivery layer caused CPU and memory problems that needed a fix during the event.", "interview_angle": "How would you redesign a real-time metrics fan-out to many browser clients when the data is sampled and only the latest value matters, and where would you place backpressure and state?", "score": 1.3385, "hn_points": 8, "hn_comments": 5}, {"url": "https://blog.cloudflare.com/how-we-built-cloudflare-queues", "company": "Cloudflare", "industry": "infra", "title": "Durable Objects aren't just durable, they're fast: a 10x speedup for Cloudflare Queues", "date": "2024-10-24", "primary_problem": "scale_ingestion", "problems": ["realtime", "performance"], "post_type": "case_study", "level": "advanced", "stack": ["Cloudflare Queues", "Durable Objects", "Workers", "Workers KV", "Workers for Platforms"], "scale": "Max throughput per queue raised from 400 to 5000 messages/sec; consumer concurrency from 20 to 250; median send latency ~200ms to ~60ms", "key_decisions": ["Chose Durable Objects over Kafka or Pulsar to avoid operating messaging infrastructure across many tenants, accepting platform coupling and single-object limits", "Replaced one Durable Object per queue with sharded storage Durable Objects in every region, trading simpler ordering guarantees for lower latency and higher throughput", "Used Workers KV to publish a shard map for cheap global reads while a Coordinator object handles autoscaling from shard heartbeats, accepting eventual consistency of the map"], "summary": "Cloudflare rebuilt the Queues message broker from a single Durable Object per queue to a horizontally sharded design spanning regions. The new design, with a coordinator, shard map in Workers KV, and autoscaled consumer shards, raised per-queue throughput over 10x and consumer concurrency from 20 to 250.", "interview_angle": "How would you scale a single-partition message queue horizontally across regions while keeping per-tenant isolation, load balancing writes and autoscaling consumers based on backlog?", "score": 1.3371, "hn_points": 28, "hn_comments": 0}, {"url": "https://eng.lyft.com/big-savings-on-big-data-9c74b7a35326", "company": "Lyft", "industry": "mobility", "title": "Big Savings On Big Data", "date": "2023-04-11", "primary_problem": "cost", "problems": ["platform", "performance"], "post_type": "case_study", "level": "intermediate", "stack": ["Spark", "Ray", "Presto", "Hive", "Fugue", "FugueSQL", "Kubernetes", "AWS EMR", "Pandas"], "scale": "Dev cost per run cut from $25 to $10.7 (-57%); prod runs up 424% in 2022; total dev cost down 32%", "key_decisions": ["Ephemeral Spark/Ray clusters per run instead of long-lived or autoscaling clusters: lowers idle cost but adds per-run spin-up and requires explicit resource declarations", "Choosing Presto for small aggregations and Hive for large scalable jobs: faster for small work, but users must pick the right engine per task", "Fugue abstraction with FugueSQL cell-level caching instead of monolithic CTE SQL: faster iteration and local execution, at the cost of adopting a new syntax layer"], "summary": "Lyft's LyftLearn team reports how ephemeral compute clusters, engine-selection guidance, and a Fugue-based abstraction cut the per-run cost of big data ML workloads roughly in half while tripling dev iteration speed. The post frames cost and productivity as measured outcomes of platform design choices rather than a pure infrastructure tutorial.", "interview_angle": "How would you cut compute cost for a multi-tenant Spark platform without slowing down developer iteration? Discuss ephemeral clusters versus autoscaling, and caching intermediate results to avoid rerunning whole pipelines.", "score": 1.3367, "hn_points": 0, "hn_comments": 0}, {"url": "https://shopify.engineering/reducing-bigquery-costs", "company": "Shopify", "industry": "ecommerce", "title": "Reducing BigQuery Costs: How We Fixed A $1 Million Query", "date": "2022-11-03", "primary_problem": "cost", "problems": ["performance", "platform"], "post_type": "case_study", "level": "intermediate", "stack": ["BigQuery", "Flink", "Kafka", "RocksDB", "Google Cloud Storage", "Parquet"], "scale": "One billion rows ingested into Flink state; projected 60 RPM (~2.6M queries/month); 75 GB scanned per query before clustering vs ~108 MB after", "key_decisions": ["Offload serving queries to BigQuery instead of ingesting an ever-growing dataset into Flink state: simpler pipeline and higher throughput, but adds per-query cost exposure", "Cluster the BigQuery table on the columns used in WHERE filters: cut bytes scanned about 150x, at the cost of having to choose clustering keys around known query patterns", "Project cost from bytes billed times expected QPS before launch: catches a near-$1M/month problem early, but relies on rough extrapolation from a single sample query"], "summary": "Shopify's team building a marketing tool on Flink found that a single BigQuery query scanned about 75 GB, which projected to nearly $1M per month at general-availability query volume. Clustering the table on the query's WHERE-clause columns cut scanned bytes roughly 150x, bringing the projection to about $1,400 per month.", "interview_angle": "How would you estimate and control the cost of a serving layer built on a pay-per-bytes-scanned warehouse, and when would you choose clustering or partitioning to cut scan volume?", "score": 1.3366, "hn_points": 2, "hn_comments": 0}, {"url": "https://monzo.com/blog/2023/04/28/speeding-up-our-balance-read-time-the-planning-phase", "company": "Monzo", "industry": "fintech", "title": "Speeding up our balance read time: The planning phase", "date": "2023-04-28", "primary_problem": "performance", "problems": ["storage_formats", "scale_ingestion"], "post_type": "case_study", "level": "advanced", "stack": ["Cassandra"], "scale": "P99 balance read latency rising with ledger entries growth; no absolute volume stated", "key_decisions": ["Precompute running balances in blocks stored in a separate table keyed by balance name, trading write-side complexity and storage for far fewer entries read per balance", "Reindex ledger entries into a time-bucketed time series table so reads can skip irrelevant partitions, trading a costly migration for bounded partition sizes", "Choose bucket size and concurrent per-bucket reads via experiments on a mock ledger service, avoiding risk to the live payment path but with results that varied by user type"], "summary": "Monzo planned a project to cut ledger balance read latency, which was rising with the growing number of ledger entries and threatening card payment authorisation during stand-in processing. The team chose to reduce data read per balance via block-level precomputed sums and a time-bucketed Cassandra schema, validated through experiments on a mock service.", "interview_angle": "How would you speed up balance computation over an ever-growing append-only ledger without full scans, and how would you choose partition/bucket sizes for a wide-column store while keeping results correct?", "score": 1.3345, "hn_points": 0, "hn_comments": 0}, {"url": "https://engineering.grab.com/building-hyper-self-service-distributed-tracing-feedback-system", "company": "Grab", "industry": "mobility", "title": "Building a Hyper Self-Service, Distributed Tracing and Feedback System for Rule & Machine Learning (ML) Predictions", "date": "2021-05-24", "primary_problem": "platform", "problems": ["scale_ingestion", "governance_privacy"], "post_type": "case_study", "level": "intermediate", "stack": ["Kafka", "Elasticsearch", "S3", "Presto", "Go"], "scale": "80 million logs per day (~200GB/day) across 2 teams, 5 services, ~50 business scenarios", "key_decisions": ["Self-service user-defined entities and custom fields (capped at 5 entities and a fixed number of custom fields) over a flexible schema, trading some flexibility for fast onboarding and a stable index layout", "Kafka buffer between services and Elasticsearch, absorbing traffic surges at the cost of extra infrastructure and a pipeline to monitor", "Dual-writing events to Kafka and S3 so analysts can query with Presto, while Elasticsearch serves interactive, access-controlled lookups"], "summary": "Grab's TISS team built Archivist, a centralised tracing and feedback system that logs billions of rule and ML prediction decisions through Kafka into a shared Elasticsearch cluster, with an S3 copy for analysts. The design replaces ad hoc Kibana logs with a structured, self-service event schema and role-based access in a portal, cutting new scenario onboarding from days to minutes.", "interview_angle": "How would you design a multi-tenant event logging pipeline for ML/rule decisions that supports self-service schema onboarding, buffers surges, serves both interactive search and batch analytics, and enforces fine-grained access to sensitive data?", "score": 1.333, "hn_points": 0, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/how-we-built-instant-logs", "company": "Cloudflare", "industry": "infra", "title": "How we built Instant Logs", "date": "2021-09-14", "primary_problem": "realtime", "problems": ["scale_ingestion", "performance"], "post_type": "case_study", "level": "advanced", "stack": ["Cloudflare Workers", "Durable Objects", "WebSocket", "Kafka", "Logpush"], "scale": "From a few requests per day to hundreds of thousands of requests per second; sub-3-second average end-to-end latency target", "key_decisions": ["Run the dataplane at the edge with Workers and Durable Objects instead of Kafka in core data centers, trading Kafka's durability and buffering for lower latency and no extra hops.", "Shard ingestion across Durable Objects by a shard key so a single coordinator is not overwhelmed, at the cost of added routing complexity.", "Use reservoir sampling with per-line sample intervals instead of uncontrolled dropping, keeping traffic statistics accurate at the cost of slight buffering latency."], "summary": "Cloudflare describes Instant Logs, a real-time HTTP log streaming pipeline built on Workers and Durable Objects rather than their Kafka-based Logpush stack. The design uses filtering in Workers, a sharding layer of Durable Objects, and sub-second reservoir sampling so clients get sub-3-second latency at any traffic volume.", "interview_angle": "How would you design a real-time log tailing service across thousands of edge servers that handles volumes from a trickle to hundreds of thousands of events per second without dropping information silently?", "score": 1.3313, "hn_points": 7, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/azul-certificate-transparency-log", "company": "Cloudflare", "industry": "infra", "title": "A next-generation Certificate Transparency log built on Cloudflare Workers", "date": "2025-04-11", "primary_problem": "scale_ingestion", "problems": ["storage_formats", "realtime"], "post_type": "case_study", "level": "advanced", "stack": ["Cloudflare Workers", "Durable Objects", "Cloudflare R2", "Workers KV", "Rust", "Go", "Sunlight", "SQLite"], "scale": "~33M read requests/day and ~6M write requests/day on existing Nimbus2025 log; target 70 writes/s; 50+ GB dedup cache over 6 months", "key_decisions": ["Store CT log as static, cacheable tiles in object storage served via CDN instead of dynamic read APIs, trading protocol compatibility for lower operating cost and availability", "Return SCTs only after sequencing so the log index is known, adding seconds of latency but removing the merge-delay risk and simplifying auditing", "Split the deduplication cache into a short-term in-memory cache and a long-term Workers KV store, accepting eventual consistency to avoid slow remote reads in the sequencing loop"], "summary": "The post describes Cloudflare's static Certificate Transparency log implementation, Azul, rebuilt on Workers, R2 and Durable Objects in Rust. It explains why tiled static logs reduce operational burden and how batching across extra Durable Object layers fixed sequencing throughput bottlenecks.", "interview_angle": "How would you design a append-only, high-throughput log ingestion service that serves reads from cacheable object storage while sequencing writes through a single-threaded coordinator, and where would you add batching to remove the bottleneck?", "score": 1.3271, "hn_points": 5, "hn_comments": 0}, {"url": "https://netflixtechblog.com/scaling-global-storytelling-modernizing-localization-analytics-at-netflix-816f47290641", "company": "Netflix", "industry": "media", "title": "Scaling Global Storytelling: Modernizing Localization Analytics at Netflix", "date": "2026-03-06", "primary_problem": "modeling", "problems": ["platform", "lineage_catalog"], "post_type": "case_study", "level": "intermediate", "stack": [], "scale": "300 million+ members, 190+ countries, 50+ languages, 40+ dashboards audited", "key_decisions": ["Consolidate duplicated per-domain localization logic into shared backend pipelines and tables, trading a larger upfront refactor for a single source of truth", "Adopt a write-once, read-many model with a centralized Language Asset Producer table feeding Dub Quality and Translation Quality metrics, so logic changes propagate everywhere", "Merge audio and text language metrics into a unified consumption language view, trading the simplicity of separate metrics for clearer stakeholder insights"], "summary": "Netflix's Localization analytics team audited more than 40 dashboards and tools, then consolidated duplicated business logic into shared backend pipelines and central tables. The goal was consistent \"who made this dub\" reporting and less maintenance when upstream logic changes, with event-level subtitle analytics planned next.", "interview_angle": "How would you consolidate duplicated metric logic that is spread across many isolated dashboards and pipelines into one trusted model that downstream consumers share?", "score": 1.3232, "hn_points": 0, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/billions-and-billions-of-logs-scaling-ai-gateway-with-the-cloudflare", "company": "Cloudflare", "industry": "infra", "title": "Billions and billions (of logs): scaling AI Gateway with the Cloudflare Developer Platform", "date": "2024-10-24", "primary_problem": "scale_ingestion", "problems": ["storage_formats", "cost"], "post_type": "case_study", "level": "intermediate", "stack": ["Cloudflare Workers", "Cloudflare D1", "Cloudflare R2", "Durable Objects", "SQLite"], "scale": "2 billion proxied requests in one year; up to 100 million logs per account (10 million per gateway across 10 gateways)", "key_decisions": ["Moved large request/response bodies from D1 to R2 and kept D1 as a searchable log index, trading simplicity for much longer retention", "Sharded log storage by account ID plus gateway name across Durable Objects, raising the per-account ceiling tenfold and isolating noisy tenants, at the cost of more objects to manage", "Added an Account Manager Durable Object that tracks row counts and entitlements from periodic updates, so limits are enforced asynchronously rather than on every insert"], "summary": "Cloudflare describes how AI Gateway extended log retention from 30 minutes to effectively indefinite by splitting storage between D1 (index) and R2 (bodies), then moving persistent logs into SQLite-backed Durable Objects sharded per gateway. An Account Manager Durable Object enforces per-account quotas using periodic row-count updates.", "interview_angle": "How would you design a per-tenant log store that must keep billions of large records queryable for a long retention window while enforcing quotas and isolating heavy tenants?", "score": 1.3191, "hn_points": 1, "hn_comments": 0}, {"url": "https://netflixtechblog.com/how-and-why-netflix-built-a-real-time-distributed-graph-part-3-querying-the-graph-with-grpc-0f3468349607", "company": "Netflix", "industry": "media", "title": "How and Why Netflix Built a Real-Time Distributed Graph: Part 3 \u2014 Querying the graph with gRPC\u2026", "date": "2026-08-07", "primary_problem": "performance", "problems": ["realtime", "platform"], "post_type": "deep_dive", "level": "advanced", "stack": ["gRPC", "Flink", "EVCache", "KVDAL"], "scale": "8 billion nodes, 150 billion edges, tens of thousands of queries per second, P99 under 100ms for single-hop queries", "key_decisions": ["Breadth-first, level-by-level traversal batches lookups per hop instead of sequential round trips, at the cost of holding each frontier in memory", "Async-first composition on a small thread pool (16-24 threads) avoids thread-per-request overhead, trading away easier debugging of async stack traces", "Selective caching with TTLs matched to data volatility and retention windows gives 70-80% hit rates but skips nodes near expiry, trading raw hit volume for focus"], "summary": "Netflix describes the serving layer of its Real-Time Distributed Graph, which answers multi-hop graph queries over billions of nodes and edges via a gRPC API. The design combines breadth-first traversal, streamed adjacency lists with early filtering, async execution on small thread pools, opt-in fail-open enrichments, and selective caching with smart TTLs.", "interview_angle": "How would you serve sub-100ms multi-hop graph queries over a constantly updating billion-edge graph? Discuss traversal strategy (BFS vs DFS), filter pushdown into storage, bounded concurrency, and cache TTL policy tied to data retention.", "score": 1.3179, "hn_points": 2, "hn_comments": 0}, {"url": "https://engineering.grab.com/blog/19", "company": "Grab", "industry": "mobility", "title": "Grab Tech", "date": "2019-08-01", "primary_problem": "lineage_catalog", "problems": ["quality", "platform"], "post_type": "case_study", "level": "advanced", "stack": ["Iceberg", "Kafka", "Flink", "Spark", "StarRocks", "Kubernetes", "Airflow", "Presto", "Hugo"], "scale": "", "key_decisions": ["Adopt Apache Iceberg for the data lake to get table-format features, trading migration effort for reliability and evolution", "Build a unified one-click ingestion platform on Flink versus per-team pipelines, trading platform investment for consistency", "Certify datasets and automate data product increments (DPIs) to enforce reliability, trading upfront governance overhead for trust"], "summary": "This is a Grab Tech engineering blog index page listing roughly 150 posts from 2016 to 2026, not a single article. Its data-engineering-relevant entries cover Iceberg lake adoption, the Hugo Flink ingestion platform, data mesh certification, Kafka stream contracts, and Spark observability on StarRocks.", "interview_angle": "How would you design a self-serve, one-click ingestion platform on Flink that lets many teams land data into a lakehouse with certification and quality checks?", "score": 1.3155, "hn_points": 0, "hn_comments": 0}, {"url": "https://monzo.com/blog/2021/08/10/spinning-up-an-analytics-engineering-team", "company": "Monzo", "industry": "fintech", "title": "Spinning up an Analytics Engineering Team", "date": "2021-08-10", "primary_problem": "modeling", "problems": ["platform", "quality"], "post_type": "case_study", "level": "intermediate", "stack": ["dbt"], "scale": "4000+ dbt models; data function grew from 20 to 80+ people", "key_decisions": ["Hub-and-spoke org model: a small central analytics engineering pool owns shared models while members temporarily embed in collectives; trades domain depth in squads for consistent standards and prioritisation capacity.", "Keep self-serve but add specialised analytics engineers: preserves analyst autonomy while adding modelling rigour; trade-off is more coordination and an added team to staff.", "Centralise ownership of crucial shared data models: improves consistency and maintenance across the warehouse, but risks becoming a bottleneck if demand grows."], "summary": "Monzo describes forming an Analytics Engineering team as its warehouse grew to over 4,000 dbt models and ownership of shared models became siloed across squads. The team adopts a hub-and-spoke model to keep self-serve modelling healthy while adding standards and maintenance for shared data assets.", "interview_angle": "How would you organise data modelling ownership at a company with thousands of models and many embedded teams, balancing self-serve speed against consistency and maintenance?", "score": 1.3145, "hn_points": 0, "hn_comments": 0}, {"url": "https://engineering.grab.com/faster-using-the-go-plugin-to-replace-Lua-VM", "company": "Grab", "industry": "mobility", "title": "2.3x faster using the Go plugin to replace Lua virtual machine", "date": "2023-05-15", "primary_problem": "performance", "problems": ["scale_ingestion", "platform"], "post_type": "case_study", "level": "advanced", "stack": ["Talaria", "Go", "Lua", "Docker", "S3"], "scale": "Ingestion of millions of transactions and connections daily; Go plugin roughly 2.3x faster and 2.3x less memory than Lua VM", "key_decisions": ["Replace per-event Lua VM execution with Go plugins (.so shared libraries) for custom ingestion transforms, gaining about 2.3x speed and memory savings but requiring compiled code and matching Go versions", "Cache and reuse Lua VMs as a baseline optimization, showing caching narrows but does not close the gap with native code", "Expose plugin and Lua loaders behind a common Handler interface so users can pick either, trading flexibility of scripting for compile-time safety and speed"], "summary": "Grab describes how its open-source time-series database Talaria swapped Lua scripting for Go plugins to run user-defined ingestion transforms, after benchmarks showed Lua VM overhead dominated per-event processing. The Go plugin approach matches native Go call performance and cuts memory use, with the main constraint being that plugin and service must be built with the same Go version.", "interview_angle": "How would you make user-defined transformations run fast inside a high-volume ingestion path, and what trade-offs come with scripting languages versus compiled plugins?", "score": 1.3128, "hn_points": 0, "hn_comments": 0}, {"url": "https://eng.lyft.com/metric-semantic-layer-how-lyft-governs-and-scales-key-data-definitions-56bee3643c29", "company": "Lyft", "industry": "mobility", "title": "Metric Semantic Layer: How Lyft Governs and Scales Key Data Definitions", "date": "2026-06-10", "primary_problem": "lineage_catalog", "problems": ["modeling", "quality"], "post_type": "case_study", "level": "intermediate", "stack": ["Python", "YAML", "Jinja", "Amundsen", "Airflow", "MCP", "Hex"], "scale": "", "key_decisions": ["Defining metrics as YAML configs with Jinja SQL templates: readable and DRY, but adds templating complexity and a learning curve for contributors", "Admitting only 'Golden Metrics' with at least two use cases: keeps the layer lean and high-value, but leaves niche metrics outside the governed set", "Requiring paired business and operational owners (team-level) for every definition change: improves accountability and quality, but slows change approval"], "summary": "Lyft built an internal Metric Semantic Layer, a Python package where each metric's plain-English description and canonical SQL live in versioned YAML and Jinja templates. Governance relies on selection criteria for which metrics qualify and joint business and operational ownership, with access exposed via APIs, Amundsen, a self-serve UI, and an MCP for AI tools.", "interview_angle": "How would you design a single source of truth for metric definitions so that many downstream dashboards, pipelines and AI tools get consistent SQL, and how would you keep ownership and change management from breaking under team turnover?", "score": 1.3082, "hn_points": 0, "hn_comments": 0}, {"url": "https://engineering.grab.com/enchancing-flink-shadow-testing", "company": "Grab", "industry": "mobility", "title": "Enhancing Flink deployment with shadow testing", "date": "2026-05-07", "primary_problem": "platform", "problems": ["realtime", "cdc_sync"], "post_type": "case_study", "level": "advanced", "stack": ["Flink", "Kubernetes", "Kafka", "Debezium", "S3", "Datadog", "StatsD", "Kibana"], "scale": "", "key_decisions": ["Run a shadow copy of each Flink job in parallel with production before promotion, which avoids downtime on failed deploys but doubles temporary resource use during the test window", "Isolate shadow runs by using separate Kafka consumer groups, a shifted Debezium server ID range, and dedicated sinks, which keeps the main job unaffected but requires connector-specific support", "Limit shadow testing to a one-hour steady-state check with short retention on shadow sinks, trading full-fidelity validation for lower cost and faster deploys"], "summary": "Grab's data streaming team added a shadow testing stage to its Flink deployment pipeline, running the new version beside the live job on mirrored production inputs and writing to isolated sinks. This removes the roughly 10-minute downtime that occurred when a bad production deploy was rolled back.", "interview_angle": "How would you validate a stateful streaming job change in production without affecting live outputs or consumer offsets, and how would you isolate source and sink side effects?", "score": 1.3032, "hn_points": 0, "hn_comments": 0}, {"url": "https://medium.com/expedia-group-tech/how-i-taught-an-ai-to-read-my-logs-9c04f1cfa750", "company": "Expedia", "industry": "travel", "title": "How I Taught an AI to Read My Logs", "date": "2026-11-10", "primary_problem": "cost", "problems": ["performance", "quality"], "post_type": "case_study", "level": "advanced", "stack": ["Spark", "Iceberg", "Trino", "Python"], "scale": "Daily compute cost on a couple of pipelines dropped by more than 90% after Iceberg V3 migration; no overall volume stated", "key_decisions": ["Let an AI skill read Spark plans, stage metrics and executor memory instead of relying on configs, trading setup effort for consistent diagnosis on top-cost jobs", "Migrate Iceberg tables to V3 with deletion vectors instead of merge-on-read files, cutting compute cost sharply but requiring plan re-checks to confirm the change", "Query Iceberg snapshot metadata through Trino MCP to find stale tables, trading direct SQL flexibility for a standardized catalog check"], "summary": "Expedia describes building AI-driven skills that read Spark execution plans, stage and executor metrics, and Iceberg snapshot metadata to diagnose cost, OOM and stale-table issues. The post reports a 90%+ daily compute cut on pipelines migrated to Iceberg V3 and catches like a full-scan MERGE that deleted rows outside its window.", "interview_angle": "How would you find and fix the most expensive Spark and Iceberg jobs across a large pipeline portfolio, and what signals would you check beyond the configuration to separate spill from near-capacity memory or a full-scan MERGE from a healthy one?", "score": 1.3008, "hn_points": 0, "hn_comments": 0}, {"url": "https://netflixtechblog.com/reverse-searching-netflixs-federated-graph-222ac5d23576", "company": "Netflix", "industry": "media", "title": "Reverse Searching Netflix\u2019s Federated Graph", "date": "2024-04-04", "primary_problem": "realtime", "problems": ["cdc_sync", "platform"], "post_type": "deep_dive", "level": "advanced", "stack": ["Elasticsearch", "CockroachDB", "Kafka", "GraphQL"], "scale": "over 100 applications integrated, nearly 50 indices", "key_decisions": ["Use Elasticsearch percolator fields to match changed documents against stored saved searches, avoiding repeated federated queries but adding a dedicated percolate index to maintain", "Split indexing into separate document and percolate pipelines so each index can be tuned for its query type, at the cost of running and mapping two pipelines per index", "Share mappings via index templates and version indices with side-by-side reindexing from a log-compacted Kafka topic, trading extra storage and pipeline complexity for safe schema changes without asking sources to resend data"], "summary": "Netflix's Graph Search team built reverse search, which stores saved searches as Elasticsearch percolator queries so that a changed movie document can be matched against subscribers' queries. The pipeline ingests saved-search changes from CockroachDB via CDC, translates the Graph Search DSL, and uses index versioning with log-compacted Kafka replays to backfill and cut over safely.", "interview_angle": "How would you notify users whose saved filters match a changing record without re-running every query against a large federated store? Discuss percolator-style matching, CDC-fed indexing, and versioned reindexing with alias cutover.", "score": 1.2945, "hn_points": 1, "hn_comments": 0}, {"url": "https://netflixtechblog.com/data-engineers-of-netflix-interview-with-pallavi-phadnis-a1fcc5f64906", "company": "Netflix", "industry": "media", "title": "Data Engineers of Netflix \u2014 Interview with Pallavi Phadnis", "date": "2021-10-28", "primary_problem": "scale_ingestion", "problems": ["realtime", "storage_formats"], "post_type": "case_study", "level": "intermediate", "stack": ["Flink", "Iceberg", "Kafka"], "scale": "5 million+ events per sec at peak", "key_decisions": ["Rebuilt the legacy logging pipeline as a new V2 platform on Flink and Iceberg, trading a large migration effort for better availability and usability", "Processes and enriches events in real time rather than in batch, which lowers latency but adds stateful stream-processing complexity", "Invested in storage and compute efficiency to cut costs at petabyte scale, accepting tuning work on upstream frameworks such as Flink and Kafka"], "summary": "This interview profile covers a Netflix data engineer's work on Consolidated Logging V2, a real-time platform that processes and enriches user interaction events at over 5 million events per second using Flink and Iceberg. It is mostly career and culture content, with the technical substance limited to a brief description of the platform rebuild and its cost and availability gains.", "interview_angle": "How would you design a petabyte-scale logging pipeline that enriches millions of events per second in real time and lands them in an open table format while keeping costs down?", "score": 1.2934, "hn_points": 0, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/safe-change-at-any-scale", "company": "Cloudflare", "industry": "infra", "title": "Scaling with safety: Cloudflare's approach to global service health metrics and software releases", "date": "2025-05-05", "primary_problem": "performance", "problems": ["scale_ingestion", "cost"], "post_type": "case_study", "level": "advanced", "stack": ["Prometheus", "Thanos", "R2", "PromQL", "Parquet", "Cloudprober"], "scale": "8 PB of metrics across 4.5 billion time series and 17 million objects; batch runs cut from 30 hours to 2 hours", "key_decisions": ["Precompute the release-scope machine join as a Prometheus recording rule: cuts query-time load but adds write-time evaluation cost on every instance", "Push data-center-scoped aggregates to the edge via Thanos distributed query execution instead of recording rules for every SLI: avoids write-time cost but requires the query engine to coalesce partial results", "Use adaptive, TCP-style concurrency control with jitter for batch queries: protects on-call queries and Thanos stability at the cost of slower individual batch query latency"], "summary": "Cloudflare's Health Mediated Deployments system uses Prometheus metrics stored in Thanos and R2 to decide whether new code rolls out, pauses, or reverts. To make backtesting over historical incidents fast, they combined recording rules, distributed query execution pushed to data centers, and adaptive concurrency control, cutting batch runtimes from about 30 hours to 2 hours.", "interview_angle": "How would you make a global, multi-region metrics query layer fast for batch analysis without overloading it? Discuss pushing aggregations to the edge, recording rules versus runtime distributed execution, and throttling low-priority batch traffic.", "score": 1.2899, "hn_points": 7, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/workflows-v2", "company": "Cloudflare", "industry": "infra", "title": "Rearchitecting the Workflows control plane for the agentic era", "date": "2026-04-15", "primary_problem": "scale_ingestion", "problems": ["platform", "migration"], "post_type": "case_study", "level": "advanced", "stack": ["Cloudflare Workflows", "Durable Objects", "SQLite", "Workers"], "scale": "50,000 concurrent instances; 300 instances/second per account; 2 million queued instances per workflow; millions of instances in the first year", "key_decisions": ["Shard the per-account control plane singleton into per-workflow SousChef units, trading a simpler single-registry view for horizontal scalability", "Use a periodic (once per second) batched slot-leasing gatekeeper to cap load on the Account DO, trading some scheduling latency for bounded request rates and fairness", "Convert existing Account DOs in place into SousChefs rather than migrating instance metadata, trading migration complexity for zero downtime and no data movement"], "summary": "Cloudflare redesigned the control plane of its Workflows durable execution engine, moving from a single account-level Durable Object bottleneck to a horizontally sharded design with SousChef shards and a batched slot-leasing Gatekeeper. They upgraded limits to 50,000 concurrent instances and 300 creations per second, and migrated live accounts in place without downtime.", "interview_angle": "How would you scale a durable task orchestrator that has a single coordinator bottleneck, while enforcing global concurrency limits and migrating live customers without downtime?", "score": 1.2886, "hn_points": 3, "hn_comments": 0}, {"url": "https://netflixtechblog.com/how-netflix-content-engineering-makes-a-federated-graph-searchable-5c0c1c7d7eaf", "company": "Netflix", "industry": "media", "title": "How Netflix Content Engineering makes a federated graph searchable", "date": "2022-04-12", "primary_problem": "realtime", "problems": ["cdc_sync", "platform"], "post_type": "case_study", "level": "advanced", "stack": ["GraphQL", "Elasticsearch", "Flink", "Kafka", "Avro", "graphql-java", "Python"], "scale": "", "key_decisions": ["Index a templated GraphQL subgraph into Elasticsearch rather than having each service implement its own search endpoint, trading pipeline complexity for a reusable search surface", "Use CDC or application events that carry only entity ids and re-fetch full documents through the federated gateway, trading extra gateway load for simpler events and always-fresh data", "Use the index itself for reverse lookups from related-entity changes back to primary entities, trading a circular pipeline dependency for encapsulated join logic"], "summary": "Netflix built Studio Search, which turns a subgraph of its federated GraphQL graph into a searchable Elasticsearch index kept near-real-time via Flink-based Data Mesh pipelines triggered by CDC events. The post also covers automating pipeline provisioning by generating Avro schemas and index templates from GraphQL queries, plus challenges around backfills, reverse lookups and index consistency.", "interview_angle": "How would you keep a search index synchronized with entities owned by many services, when a change to a related entity must update the primary documents that reference it?", "score": 1.2883, "hn_points": 5, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/80-percent-lower-cloud-cost-how-baselime-moved-from-aws-to-cloudflare", "company": "Cloudflare", "industry": "infra", "title": "Moving Baselime from AWS to Cloudflare: simpler architecture, improved performance, over 80% lower cloud costs", "date": "2024-10-31", "primary_problem": "cost", "problems": ["scale_ingestion", "migration"], "post_type": "case_study", "level": "intermediate", "stack": ["AWS Lambda", "Kinesis Data Streams", "ClickHouse", "EC2", "CloudFront", "DynamoDB", "Cloudflare Workers", "Durable Objects", "Workers Analytics Engine", "Cloudflare Queues", "D1", "Workers KV"], "scale": "Tens of billions of events daily; over 1 billion events/day after joining Cloudflare; daily cloud bill cut from $1,940 to $325", "key_decisions": ["Moved telemetry ingestion from Lambda plus Kinesis to Cloudflare Workers, cutting I/O-bound compute cost but tying the pipeline to a single vendor's platform", "Replaced self-hosted ClickHouse on EC2 with managed Workers Analytics Engine, removing capacity planning at the cost of less control over storage and query internals", "Used a strangler fig migration with dual writes to ClickHouse and the new store for the 30-day retention window, trading temporary duplication for zero data loss and safe cutover"], "summary": "Baselime rebuilt its observability telemetry pipeline from a multi-service AWS stack (Lambda, Kinesis, self-hosted ClickHouse on EC2) onto Cloudflare Workers, Durable Objects and Workers Analytics Engine. The migration cut the cloud bill by over 80% while reducing latency, operational load and architectural complexity.", "interview_angle": "How would you design a high-volume telemetry ingestion pipeline to minimize I/O-bound compute cost, and when would you choose a managed analytics store over self-hosted ClickHouse?", "score": 1.2878, "hn_points": 3, "hn_comments": 1}, {"url": "https://blog.cloudflare.com/making-super-slurper-five-times-faster", "company": "Cloudflare", "industry": "infra", "title": "Making Super Slurper 5x faster with Workers, Durable Objects, and Queues", "date": "2025-04-10", "primary_problem": "migration", "problems": ["scale_ingestion", "cdc_sync"], "post_type": "case_study", "level": "advanced", "stack": ["Cloudflare Workers", "Durable Objects", "Cloudflare Queues", "Hyperdrive", "PostgreSQL", "Kubernetes", "SQLite", "S3", "Cloudflare R2"], "scale": "Petabytes of data moved overall; test run of 75,000 objects in 3m25s vs 15m30s before; billions of object keys supported", "key_decisions": ["Moved transfer workers from Kubernetes in a core data center to serverless Workers, trading control over infrastructure for auto-scaling and lower-latency placement near sources", "Sharded per-job state across SQLite-backed Durable Objects instead of one PostgreSQL instance, trading simpler queries for distributed state management and a 10 GB per-object storage limit workaround", "Handled at-least-once queue delivery with per-object locks, sequence IDs on listings, transactional counts and a destination existence check, trading extra database writes for exactly-once-like transfers"], "summary": "Cloudflare rebuilt Super Slurper, its bulk object storage migration tool, on Workers, Queues and Durable Objects to replace a Kubernetes and PostgreSQL pipeline that could not scale past tens of pods. The redesign delivered up to 5x faster transfers, with duplicate-message handling achieved through per-object locks and transactional counts.", "interview_angle": "How would you design a petabyte-scale object storage migration pipeline that auto-scales, tolerates at-least-once queue delivery, and avoids copying the same object twice?", "score": 1.2864, "hn_points": 0, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/moving-quicksilver-into-production", "company": "Cloudflare", "industry": "infra", "title": "Moving Quicksilver into production", "date": "2020-11-25", "primary_problem": "migration", "problems": ["cdc_sync", "storage_formats"], "post_type": "case_study", "level": "advanced", "stack": ["Quicksilver", "Kyoto Tycoon", "LMDB", "RocksDB", "Kubernetes", "Raft", "etcd", "ClickHouse", "Salt", "memcached"], "scale": "Billions of KV pairs replicated to 200+ data centers; Kyoto Tycoon removal took about four years", "key_decisions": ["Ran Quicksilver in parallel with Kyoto Tycoon behind a bridge and shifted reads gradually, trading a longer rollout for safe rollback at each step", "Moved the root writer to a Raft cluster to remove the single point of failure, at the cost of harder code and testing", "Replaced LMDB with RocksDB to cut storage size and write amplification, accepting higher CPU use and some read latency"], "summary": "Cloudflare describes how it migrated its distributed KV store Quicksilver into production by replacing Kyoto Tycoon edge-by-edge and then at the core, with bridges for dual running. The post also covers replication and disk-wear problems caused by LMDB write amplification, and the move toward sharding and RocksDB.", "interview_angle": "How would you migrate a globally replicated key-value store with hundreds of consumers without downtime, and how would you handle rollback and hidden consumers?", "score": 1.2863, "hn_points": 4, "hn_comments": 0}, {"url": "https://www.capitalone.com/tech/cloud/serverless-transactions-serve-customers", "company": "Capital One", "industry": "fintech", "title": "Serverless Transactions Serve Customers | Capital One", "date": "2017-11-21", "primary_problem": "migration", "problems": ["cdc_sync", "scale_ingestion"], "post_type": "case_study", "level": "intermediate", "stack": ["DynamoDB", "AWS Lambda", "Elastic Stack", "CloudWatch", "SNS", "Kibana"], "scale": "Billions of transactional records loaded; ~80% of legacy traffic is reads", "key_decisions": ["Offload read-only transaction traffic from the mainframe to a serverless cloud store, accepting eventual consistency between read and write models (CQRS)", "Use DynamoDB as the read datastore for scalability and spikes, trading away flexibility because keys cannot be changed after table creation", "Shuffle sorted source files before bulk load to avoid hot partitions, at the cost of extra preprocessing before ingestion"], "summary": "Capital One moved the read-heavy transaction workload off its mainframe into a serverless AWS architecture backed by DynamoDB, fed by batch and near real-time sync. The post highlights choosing what to migrate first, using CQRS to manage the split between write and read models, and fixing hot-partition throttling during bulk loads.", "interview_angle": "How would you migrate billions of mainframe transaction records to a cloud read store while keeping it in sync near real-time and avoiding hot partitions during bulk load?", "score": 1.2851, "hn_points": 0, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/detecting-workers-builds-errors-across-1-million-durable-durable-objects", "company": "Cloudflare", "industry": "infra", "title": "Let\u2019s DO this: detecting Workers Builds errors across 1 million Durable Objects", "date": "2025-05-29", "primary_problem": "quality", "problems": ["scale_ingestion", "platform"], "post_type": "case_study", "level": "advanced", "stack": ["Cloudflare Workers", "Durable Objects", "Workers Queues", "PostgreSQL", "Hyperdrive", "Cloudflare Containers", "Workers KV", "R2", "ts-pattern", "Sentry", "TypeScript"], "scale": "More than 1 million failed builds backfilled in a couple of hours; roughly 1000 builds fetched per alarm cycle, sent to Queues in batches of 100", "key_decisions": ["Parse build logs asynchronously via a Queue consumer after failure, trading immediate categorization for decoupled, retryable processing", "Use a single Durable Object with a 1-second alarm loop to backfill historical builds, trading throughput per invocation for a simple, API-triggered and resumable job", "Normalize wrangler error lines with regex matchers into groups and mask account-specific identifiers, trading some grouping precision for privacy and aggregatable top-issue views"], "summary": "Cloudflare built an automated error detection pipeline for Workers Builds that classifies failed build logs into grouped error categories via a Queue consumer. To backfill over a million historical builds stored across per-build Durable Objects, they used a single Durable Object driven by alarms that feeds failed build IDs into the queue.", "interview_angle": "How would you backfill categorization over a million historical records when the data is spread across many small stores and per-invocation execution limits apply? Discuss queue fan-out, resumable cursors, and idempotent reprocessing.", "score": 1.2795, "hn_points": 1, "hn_comments": 0}, {"url": "https://www.capitalone.com/tech/cloud/delta-lake-transaction-logs", "company": "Capital One", "industry": "fintech", "title": "Delta Lake Transaction Logs Explained | Capital One", "date": "2025-07-16", "primary_problem": "storage_formats", "problems": ["cdc_sync", "governance_privacy"], "post_type": "deep_dive", "level": "intermediate", "stack": ["Delta Lake", "Parquet", "Spark", "Amazon EMR", "AWS Glue", "Snowflake"], "scale": "", "key_decisions": ["Rely on an append-only JSON commit log with optimistic concurrency instead of locks, trading retry work under heavy concurrent writes for simpler coordination", "Rewrite whole Parquet files on update rather than in-place edits, gaining immutability and time travel at the cost of write amplification", "Use periodic checkpoints plus OPTIMIZE and VACUUM to bound log growth, trading maintenance jobs and reduced time-travel retention for faster reads"], "summary": "The article explains how Delta Lake's _delta_log works, covering JSON commits, Parquet checkpoints, add/remove/metadata actions, optimistic concurrency, and time travel. It closes with operational guidance on checkpoint intervals, small-file compaction, VACUUM retention, and multi-region replication pitfalls.", "interview_angle": "How would you design an append-only transaction log for a lakehouse table so that multiple writers can commit concurrently, readers see only completed versions, and metadata growth stays under control?", "score": 1.2783, "hn_points": 0, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/scaling-security-scans", "company": "Cloudflare", "industry": "infra", "title": "Scaling Security Insights: how we achieved a 10x increase in global scanning capacity", "date": "2026-06-12", "primary_problem": "scale_ingestion", "problems": ["realtime", "performance"], "post_type": "case_study", "level": "advanced", "stack": ["Kafka", "Go", "PostgreSQL"], "scale": "From 10 to 120+ scans per second per checker; millions of accounts; batches up to 500,000 insights", "key_decisions": ["Batching Kafka consumption with per-message goroutines instead of adding partitions: avoids broker load but risks re-work on crash and slightly more memory", "Splitting consumers into slow and fast lanes to avoid head-of-line blocking: isolates heavy accounts but adds operational complexity", "Switching the API to active-passive near the primary database: removes cross-region latency and pool exhaustion, but gives up active-active redundancy"], "summary": "Cloudflare's Security Insights pipeline scanned accounts too infrequently and missed many free accounts, so it needed about 10x more throughput. The fixes were batched and parallel Kafka consumption, split fast and slow lanes, bulk Postgres writes, an active-passive API near the primary database, and a rescheduler with adaptive rate limiting.", "interview_angle": "How would you scale a scheduled scan pipeline built on Kafka partitions to 10x throughput without simply adding partitions, and how would you avoid bursty scheduling and cross-region database latency?", "score": 1.2774, "hn_points": 2, "hn_comments": 0}, {"url": "https://medium.com/wise-engineering/data-inventory-4eff3f015553", "company": "Wise", "industry": "fintech", "title": "Data Inventory", "date": "2025-02-19", "primary_problem": "lineage_catalog", "problems": ["governance_privacy", "platform"], "post_type": "case_study", "level": "intermediate", "stack": ["MariaDB", "PostgreSQL", "S3", "Kafka", "Terraform"], "scale": "", "key_decisions": ["Use a structured asset_id format (data_asset://type/subtype/top/sub) for uniqueness and human readability, trading off granularity against sensitivity", "Assign ownership via metadata from product teams with a producer-then-consumer fallback, accepting some unresolved edge cases", "Start classification with a manual UI for all systems, trading developer experience for a single product that scales across stores"], "summary": "Wise's Data Governance team describes Data Inventory, a catalog of data assets that records where data lives, who owns it, its schema, and its sensitivity classification, built to satisfy ISO 27001 and internal security controls. The post explains how assets are auto-discovered from provisioning systems, registered with structured identifiers, and notified for classification, while noting that off-the-shelf catalogs were rejected for security reasons.", "interview_angle": "How would you design a data catalog for a company with strict security controls that must cover heterogeneous stores, assign ownership, and capture sensitivity classification without hurting developer experience?", "score": 1.2753, "hn_points": 0, "hn_comments": 0}, {"url": "https://eng.lyft.com/building-a-gateway-to-flyte-474b451b32c8", "company": "Lyft", "industry": "mobility", "title": "Building a Gateway to Flyte", "date": "2020-11-18", "primary_problem": "platform", "problems": ["lineage_catalog", "governance_privacy"], "post_type": "deep_dive", "level": "advanced", "stack": ["Flyte", "gRPC", "REST", "grpc-gateway", "gorm", "Kubernetes", "OpenID Connect", "PagerDuty", "Slack"], "scale": "9,000+ workflows, 20,000+ tasks, over 1M workflow executions per month, 400+ users", "key_decisions": ["Centralized stateless control plane (Flyte Admin) separated from the data plane, which eases scaling and multi-cluster placement but adds a critical dependency for coordination", "Hosting multi-tenant config, quotas and registrations in one service gives a single source of truth and governance, at the cost of a central bottleneck that must be isolated per user", "Using a relational store via gorm with lean access patterns (few joins, small transactions) keeps the service simple and portable, but limits query flexibility for analytics on execution metadata"], "summary": "Lyft describes Flyte Admin, the stateless gRPC/REST control plane for its Flyte orchestration platform, which stores workflow and task definitions and execution metadata and manages quotas and cluster placement. The design separates control from the execution data plane so that clusters can be added without downtime and noisy users are isolated from one another.", "interview_angle": "How would you design a multi-tenant orchestration control plane that tracks workflow metadata, enforces quotas, and scales execution across multiple clusters without downtime?", "score": 1.275, "hn_points": 4, "hn_comments": 0}, {"url": "https://shopify.engineering/how-shopify-improved-consumer-search-intent-with-real-time-ml", "company": "Shopify", "industry": "ecommerce", "title": "How Shopify improved consumer search intent with real-time ML", "date": "2024-10-18", "primary_problem": "ml_data", "problems": ["realtime", "cost"], "post_type": "case_study", "level": "advanced", "stack": ["Dataflow", "Beam", "BigQuery", "Python", "GPU (T4)"], "scale": "~2,500 embeddings per second (~216 million per day)", "key_decisions": ["Chose Dataflow streaming over batch embedding generation to keep merchant catalog updates instantly searchable, accepting higher pipeline complexity", "Lowered worker harness thread count from 12 to 4 to cut memory footprint ~2.6x, letting them drop from high-memory to standard workers and save ~14% cost, since the GPU was already the bottleneck", "Kept in-bundle batching instead of stateful batching because stateful batching forces a shuffle and adds latency; per-process model loading compensates for smaller batches"], "summary": "Shopify runs near-real-time image and text embedding pipelines on Dataflow with GPU inference, feeding both a warehouse and a downstream search index. The post focuses on tuning worker memory, model loading per process, and batching trade-offs to balance cost, throughput and latency.", "interview_angle": "How would you design a streaming ML inference pipeline that embeds millions of catalog items per day, and how would you tune memory, GPU utilization and batching under a latency target?", "score": 1.2737, "hn_points": 0, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/stream-firewall-events-directly-to-your-siem", "company": "Cloudflare", "industry": "infra", "title": "Stream Firewall Events directly to your SIEM", "date": "2020-04-24", "primary_problem": "scale_ingestion", "problems": ["cost", "cdc_sync"], "post_type": "case_study", "level": "intermediate", "stack": ["Cloudflare Logpush", "Sumo Logic", "Terraform", "S3", "Azure Blob Storage", "Google Cloud Storage"], "scale": "Billions of requests per day on the highest-traffic sites; about 5% trigger security rules; firewall events delivered within 60 seconds", "key_decisions": ["Filter at the source by shipping only Firewall Events via Logpush instead of the full HTTP request firehose, cutting per-log-line SIEM costs but limiting the dataset to security-relevant fields", "Require an ownership challenge token before a Logpush job can write to a destination, adding setup friction in exchange for preventing misconfigured or malicious log floods", "Use Terraform to provision the collector, HTTP source and Logpush job as code, trading a steeper initial setup for repeatable, version-controlled configuration"], "summary": "Cloudflare added a Logpush dataset that exports only Firewall Events to a SIEM or cloud storage rather than all HTTP requests, so customers pay for and search only security-relevant logs. The post is a hands-on tutorial that wires this up with Terraform and Sumo Logic, including a validation step and a test request.", "interview_angle": "How would you reduce SIEM ingestion costs when most upstream log records are benign? A good answer covers filtering at the source versus client-side, delivery latency, and validating destinations before pushing data.", "score": 1.2733, "hn_points": 4, "hn_comments": 0}, {"url": "https://shopify.engineering/catalog-clustering", "company": "Shopify", "industry": "ecommerce", "title": "Clustering billions of products for agentic commerce with Catalog API", "date": "2026-06-17", "primary_problem": "ml_data", "problems": ["scale_ingestion", "quality"], "post_type": "case_study", "level": "advanced", "stack": ["OpenAI Structured Outputs", "FAISS", "HNSW", "Liquid"], "scale": "Billions of products across millions of Shopify stores", "key_decisions": ["Precision-first: set a hard precision floor and maximize recall under it, accepting ungrouped variants over wrong merges", "Rules-first singleton detection and deterministic matching so LLMs only handle ambiguous shops, trading some coverage for cost and precision", "Two-stage LLM pipeline with ANN-based pre-chunking and dynamic per-chunk strict JSON schemas, trading extra LLM calls for guaranteed completeness and reliable output"], "summary": "Shopify describes how it clusters billions of product listings into Universal Product Identifiers so AI agents can find the same item across variant structures. The approach starts with intra-store LLM clustering, using ANN-based chunking, a propose-then-critique pipeline, and per-chunk structured output schemas, with cross-store clustering planned for a later post.", "interview_angle": "How would you design a product-matching pipeline over billions of heterogeneous records that bounds false merges, using cheap deterministic rules first and LLMs only where judgment is needed, with chunking so model context stays manageable?", "score": 1.2656, "hn_points": 0, "hn_comments": 0}, {"url": "https://netflixtechblog.com/2-diving-deeper-into-psyberg-stateless-vs-stateful-data-processing-1d273b3aaefb", "company": "Netflix", "industry": "media", "title": "Diving Deeper into Psyberg: Stateless vs Stateful Data Processing", "date": "2023-11-15", "primary_problem": "late_data", "problems": ["storage_formats", "quality"], "post_type": "deep_dive", "level": "advanced", "stack": ["Iceberg", "Spark", "Netflix Maestro", "Psyberg"], "scale": "", "key_decisions": ["Split incremental loads into stateless (append late records) and stateful (reprocess overlapping windows) patterns, trading simpler appends for correct derived state when event sequence matters.", "Drive range selection from Iceberg snapshot metadata and high watermark table rather than wall-clock scans, which keeps reprocessing bounded but depends on reliable snapshot bookkeeping.", "Use Write-Audit-Publish on uncommitted Iceberg snapshots with blocking count and completeness audits before publishing, adding latency to each run in exchange for protecting downstream tables."], "summary": "Netflix's Membership and Finance data engineering team describes two Psyberg modes for incremental fact-table loads: stateless, which appends late-arriving independent events, and stateful, which reprocesses overlapping windows so derived account state stays correct. The post walks through initialization from Iceberg snapshot metadata, the use of processing versus landing timestamps and VTTS to bound batches, write-audit-publish validation, and high watermark commits.", "interview_angle": "How would you design an incremental loader for late-arriving events that must produce correct derived state (e.g., account lifecycle) versus simple append-only facts, and how would you bound the reprocessing window using snapshot metadata and watermarks?", "score": 1.2651, "hn_points": 0, "hn_comments": 0}, {"url": "https://engineering.zalando.com/posts/2026/03/search-quality-assurance-with-llm-judge.html", "company": "Zalando", "industry": "ecommerce", "title": "Search Quality Assurance with AI as a Judge", "date": "2026-03-16", "primary_problem": "quality", "problems": ["ml_data", "platform"], "post_type": "case_study", "level": "advanced", "stack": ["Airflow", "Kubernetes", "GPT-4o", "ElastiCache", "Nakadi", "Kafka", "Data Lake"], "scale": "1,500 search segments per market x 25 results each, 3 markets; ~250 USD per full run", "key_decisions": ["Use LLM-as-a-judge for pre-launch search relevance testing instead of manual expert annotation, trading some judge accuracy for coverage and speed", "Cluster real queries by NER tag groups and translate them with an LLM to reuse search intents in new languages, trading translation fidelity for automatic coverage", "Cache product data and per-(query, product) judgments in a shared ElastiCache layer, trading infrastructure complexity for fewer API calls and lower LLM cost"], "summary": "Zalando built an Airflow-orchestrated pipeline that clusters historical search queries by NER tag groups, translates them into new market languages, and scores search results with GPT-4o as a relevance judge. The system lets teams find search, NER, and product-data issues before launching in new countries, at roughly 250 USD per run.", "interview_angle": "How would you design an automated pre-launch search quality test suite for a new market with no user traffic, covering query selection, multilingual coverage, and caching of expensive enrichment calls?", "score": 1.2635, "hn_points": 0, "hn_comments": 0}, {"url": "https://netflixtechblog.com/high-throughput-graph-abstraction-at-netflix-part-i-e88063e6f6d5", "company": "Netflix", "industry": "media", "title": "High-Throughput Graph Abstraction at Netflix: Part I", "date": "2026-02-09", "primary_problem": "performance", "problems": ["scale_ingestion", "storage_formats"], "post_type": "deep_dive", "level": "advanced", "stack": ["Kafka", "EVCache", "Cassandra", "gRPC", "Key-Value Abstraction", "TimeSeries Abstraction"], "scale": "10 million ops/sec, 650 TB of graph data", "key_decisions": ["Separate edge links from edge properties into different namespaces to avoid wide partitions and allow single-property upserts, at the cost of non-atomic cross-namespace writes", "Use schema-driven write validation and query planning on a metadata graph, trading upfront modeling rigidity for data quality and pruned traversals", "Combine write-aside caching of edge links with read-aside EVCache for properties, choosing invalidation-on-write or TTL per dataset based on write rate and staleness tolerance"], "summary": "Netflix describes the Graph Abstraction, a property-graph service serving around 10 million operations per second over 650 TB for OLTP-style graph use cases such as the real-time distributed graph and service topology. The post covers how it layers graph indexes on its KV and TimeSeries abstractions, enforces schemas, caches reads and writes, and keeps multi-region data eventually consistent.", "interview_angle": "How would you design a low-latency graph store on top of a partitioned key-value store, including how you split adjacency lists from edge properties and keep forward and reverse indexes consistent without cross-partition transactions?", "score": 1.2631, "hn_points": 0, "hn_comments": 0}, {"url": "https://eng.lyft.com/ml-feature-serving-infrastructure-at-lyft-d30bf2d3c32a", "company": "Lyft", "industry": "mobility", "title": "ML Feature Serving Infrastructure at Lyft", "date": "2021-03-16", "primary_problem": "ml_data", "problems": ["realtime", "migration"], "post_type": "deep_dive", "level": "advanced", "stack": ["SQL", "Flyte", "Flink", "Kafka", "DynamoDB", "Redis", "Hive", "Elasticsearch", "gRPC", "REST"], "scale": "Several thousand features, millions of requests per minute, single-digit ms latency, 99.99%+ availability", "key_decisions": ["Define features once in SQL with JSON metadata so training and serving share the same definitions and validations, at the cost of building and maintaining a custom DSL-like pipeline.", "Use DynamoDB as the latest-value store with Redis write-through cache and conditional-write optimistic locking, trading strong consistency for low-latency reads.", "Replicate serving data to Hive for training and Elasticsearch, accepting eventual consistency between offline and online feature values in exchange for simpler architecture."], "summary": "Lyft describes its Feature Service, which takes SQL-defined batch and streaming features and makes them available both as historical training data in Hive and as low-latency point lookups for online inference. The design centers on DynamoDB for latest values, Redis caching, and replication to Hive, with eventual consistency between training and serving accepted as tolerable.", "interview_angle": "How would you design a feature store that serves the same feature definitions for offline training and online low-latency inference, and what consistency guarantees would you offer between the two?", "score": 1.2599, "hn_points": 2, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/from-0-to-20-billion-how-we-built-crawler-hints", "company": "Cloudflare", "industry": "infra", "title": "From 0 to 20 billion - How We Built Crawler Hints", "date": "2021-12-16", "primary_problem": "scale_ingestion", "problems": ["realtime", "quality"], "post_type": "case_study", "level": "advanced", "stack": ["Kafka", "Redis", "Cap'n Proto", "Kubernetes", "Prometheus", "Grafana", "Kibana", "Go"], "scale": "25 billion crawl signals processed in about two months; 28M HTTP requests/s average; 81,000 opted-in customers", "key_decisions": ["Used Redis as a deduplicating distributed buffer with two alternating clusters, trading operational complexity for resilience and cross-instance dedup over an in-memory map", "Placed a Kafka topic between Redis batching and partner dispatch so partner API slowness does not lose batches, at the cost of an extra hop", "Sent 100% of cache misses instead of sampling, accepting higher volume to avoid losing signal, and used opt-in plus lag/capacity alerts to roll out safely"], "summary": "Cloudflare describes a pipeline that takes cache-miss events from its global edge through Kafka, deduplicates and batches URLs in alternating Redis clusters, and dispatches them via Kafka consumers to search engine partners through the IndexNow API. The post also covers the opt-in rollout, monitoring, and Kubernetes-based self-healing used to run it.", "interview_angle": "How would you design a globally fed, deduplicated batching pipeline that pushes batches to external partners with retries, without losing data when a partner API is slow?", "score": 1.2593, "hn_points": 3, "hn_comments": 1}, {"url": "https://eng.lyft.com/powering-security-reports-with-cartography-and-flyte-fd02a4a96b2f", "company": "Lyft", "industry": "mobility", "title": "Powering Security Reports with Cartography and Flyte", "date": "2021-10-13", "primary_problem": "platform", "problems": ["cdc_sync", "lineage_catalog"], "post_type": "case_study", "level": "intermediate", "stack": ["Neo4j", "Cypher", "Flyte", "Spark", "Presto", "S3", "Hive", "Mode", "Superset", "Jupyter", "Slack", "Cartography"], "scale": "", "key_decisions": ["Chose scheduled Flyte ETLs over cron jobs for recurring Cartography queries, gaining DAG dependencies and reuse at the cost of depending on internal data infrastructure", "Extracted graph data into S3 as Hive-partitioned tables instead of storing only aggregates, enabling long retention and historical analysis at the cost of storage growth", "Used pre-canned Cypher queries materialized into SQL-queryable tables rather than translating Cypher to SQL or using a JDBC bridge, avoiding abandoned tooling and unsupported driver limits in Mode"], "summary": "Lyft's Security team built an ETL pipeline on Flyte that extracts graph data from Cartography (backed by Neo4j), lands it in S3 as partitioned Hive tables, and refreshes Mode dashboards and reports. The post explains why this beat both cron jobs and Cypher-to-SQL translation for analytics consumption.", "interview_angle": "How would you expose a graph database to SQL-only BI tools? A good answer weighs pre-computed query extracts against query translation layers and discusses partitioning and retention of snapshot data.", "score": 1.2587, "hn_points": 0, "hn_comments": 0}, {"url": "https://netflixtechblog.com/scalable-annotation-service-marken-f5ba9266d428", "company": "Netflix", "industry": "media", "title": "Scalable Annotation Service \u2014 Marken", "date": "2023-01-26", "primary_problem": "storage_formats", "problems": ["scale_ingestion", "performance"], "post_type": "case_study", "level": "advanced", "stack": ["Cassandra", "Elasticsearch", "Iceberg", "Hive", "Zookeeper"], "scale": "1.9 billion annotations, 2.6 TB, Cassandra cluster scaled from 12 to 24 nodes", "key_decisions": ["Cassandra as source of truth for annotations, chosen for horizontal scaling and team expertise, at the cost of relying on a separate Elasticsearch index for search", "Elasticsearch for full-text, stem, temporal/spatial and semantic search, trading index sync complexity and higher semantic query latency for flexible retrieval", "Separate ingestion stack with Java threadpool throttling for bulk ML backfills, protecting interactive latency at the cost of operating another fleet"], "summary": "Netflix's Marken is a generic annotation service that lets any microservice attach schema-defined metadata, including temporal and spatial data, to its entities. Cassandra stores the source of truth, Elasticsearch serves low-latency search, and Iceberg holds the full dataset for bulk analytics.", "interview_angle": "How would you design a service that stores flexible, schema-driven annotations with time and space attributes, serves low-latency UI search, and also feeds bulk analytics without blocking online traffic?", "score": 1.2543, "hn_points": 3, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/dns-build-improvement", "company": "Cloudflare", "industry": "infra", "title": "How we improved DNS record build speed by more than 4,000x", "date": "2022-05-25", "primary_problem": "realtime", "problems": ["performance", "cdc_sync"], "post_type": "case_study", "level": "advanced", "stack": ["PostgreSQL", "Kafka", "Quicksilver"], "scale": "250 DNS record changes/s on average; zones with millions of records; 38.7 trillion DNS queries/month", "key_decisions": ["Switch from full zone rebuilds to per-record builds, cutting propagation work but requiring a new scheduler and locking between build types", "Emit separate create and delete events for record updates so stale names get cleaned up, trading event simplicity for correct cleanup", "Keep full builds for the roughly 13% of zone-settings changes that need whole-zone context, accepting two build paths to maintain"], "summary": "Cloudflare reduced DNS record propagation time by moving its Zone Builder from rebuilding entire zones on each change to building only the changed record, using a new Kafka event pipeline and scheduler. Per-record builds averaged about 150x faster than full builds, and roughly 4000x faster on a million-record test zone.", "interview_angle": "How would you redesign a change-propagation pipeline so that each update costs time proportional to the change rather than the size of the dataset, and how do you handle ordering, concurrency between two build paths, and cleanup of renamed keys?", "score": 1.2535, "hn_points": 4, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/sqlite-in-durable-objects", "company": "Cloudflare", "industry": "infra", "title": "Zero-latency SQLite storage in every Durable Object", "date": "2024-09-26", "primary_problem": "storage_formats", "problems": ["cdc_sync", "quality"], "post_type": "deep_dive", "level": "advanced", "stack": ["SQLite", "Durable Objects", "Cloudflare Workers", "R2", "Litestream", "D1"], "scale": "up to 1 GB SQL storage per object during beta, 10 GB at GA; 5 follower replicas per DO; WAL batches every 10 seconds or 16 MB", "key_decisions": ["Run SQLite embedded in the same thread as the app with synchronous queries: near-zero latency and simpler code, but a single object is capped by one thread and one machine", "Use Output Gates to hold responses until writes are durable: lets writes stay asynchronous under the hood without losing durability, at the cost of a forced restart on write failure", "Stream WAL changes to object storage in batches (10 s or 16 MB) with 5 follower replicas acknowledging commits: cheap durable storage with low write latency, but a small window where data depends on followers and periodic snapshots bound replay cost"], "summary": "Cloudflare describes SQLite-backed Durable Objects, where SQLite runs embedded in the same thread as application code so queries are near zero latency. Under the hood, the Storage Relay Service uses local disk as a cache over object storage, shipping WAL change batches and periodic snapshots to R2 and relaying commits through follower machines for durability and point-in-time recovery.", "interview_angle": "How would you design a durable, low-latency embedded database backed by object storage, ensuring confirmed writes survive a host failure without waiting for each upload to finish?", "score": 1.2501, "hn_points": 59, "hn_comments": 11}, {"url": "https://blog.cloudflare.com/bringing-connections-into-view-real-time-bgp-route-visibility-on-cloudflare", "company": "Cloudflare", "industry": "infra", "title": "Bringing connections into view: real-time BGP route visibility on Cloudflare Radar", "date": "2025-05-21", "primary_problem": "realtime", "problems": ["scale_ingestion", "performance"], "post_type": "case_study", "level": "advanced", "stack": ["RIS Live WebSocket", "OpenBMP Kafka", "Cloudflare Radar API", "jq"], "scale": "8 route collectors, 261 full routing tables, ~45 GB memory on a single node (~170 MB per table)", "key_decisions": ["Streaming real-time BGP updates from RIS Live and OpenBMP Kafka into in-memory snapshots instead of batch-processing archive files, trading delay (seconds vs. 10-30 minutes) for continuous update complexity", "Partitioning routing data into one snapshot per collector so collectors can be added or excluded independently, at the cost of fan-out queries across actors", "Using an actor model with a central controller so each collector runs on its own thread, keeping queries non-blocking while keeping hundreds of full tables in one node's memory"], "summary": "Cloudflare added a real-time BGP route lookup to Radar, fed by live streams from RIPE RIS and RouteViews rather than archive dumps that lag 10 to 30 minutes. The system keeps per-collector prefix-trie snapshots in memory, updated continuously and queried through an actor model, and exposes the results via the Radar UI and API.", "interview_angle": "How would you turn batch-archived BGP update files into a low-latency queryable view, and how would you partition and query many independent streams without blocking ingestion?", "score": 1.2452, "hn_points": 2, "hn_comments": 0}, {"url": "https://netflixtechblog.com/scaling-media-machine-learning-at-netflix-f19b400243", "company": "Netflix", "industry": "media", "title": "Scaling Media Machine Learning at Netflix", "date": "2023-02-13", "primary_problem": "ml_data", "problems": ["platform", "cost"], "post_type": "case_study", "level": "advanced", "stack": ["Metaflow", "Ray", "Iceberg", "Trino", "Cassandra", "Elasticsearch", "Spark", "S3", "Conductor", "Titus", "FSx", "Spring Boot"], "scale": "~2K shots per title (~2M pairs per title); 10-episode series ~200M comparisons; 3-5x training throughput gain", "key_decisions": ["Memoize shared features (shot segmentation, embeddings) in a feature store so pipelines reuse results, trading storage and coupling for lower compute cost and consistent outputs", "Standardize media encodes before feature computation, trading upfront catalog-wide preprocessing cost for matching quality across titles", "Build a dependency-aware triggering layer (Amber) instead of bespoke per-pipeline triggers, trading a shared platform dependency for fewer duplicate triggers and maintenance burden"], "summary": "Netflix describes its media ML infrastructure, covering media access, a feature store for memoized embeddings, dependency-aware compute triggering, GPU training, and serving via a search service. It uses the Match Cutting feature to show how moving from a single-title Metaflow pipeline to cross-title matching required standardized inputs, shared shot segmentation, and orchestration that avoids quadratic recomputation.", "interview_angle": "How would you design a feature store and triggering system for large video assets so that expensive shared computations are memoized, new arrivals automatically flow through dependent computations, and quadratic pairwise matching across arbitrary subsets stays tractable?", "score": 1.2439, "hn_points": 3, "hn_comments": 0}, {"url": "https://netflixtechblog.com/data-ingestion-pipeline-with-operation-management-3c5c638740a8", "company": "Netflix", "industry": "media", "title": "Data ingestion pipeline with Operation Management", "date": "2023-03-03", "primary_problem": "storage_formats", "problems": ["platform", "quality"], "post_type": "deep_dive", "level": "advanced", "stack": ["Cassandra", "Elasticsearch", "EVCache", "Memcache", "SQS"], "scale": "2K-5K annotations per algorithm run", "key_decisions": ["Model each algorithm run as an operation with STARTED/FINISHED/CANCELED states and an active flag, so readers see either the old full set or the new full set, never a partial mix", "Use Cassandra as source of truth and Elasticsearch as a derived index, failing the client call if Cassandra write fails but retrying Elasticsearch flag updates asynchronously via SQS", "Exclude in-flight operations at query time using a distributed cache of STARTED operation IDs, trading query-side filtering cost for fast non-blocking writes"], "summary": "Netflix describes how Marken implements atomic replacement of annotation sets produced by algorithm runs on top of Cassandra and Elasticsearch, emulating a distributed transaction without a dedicated transactional store. The design uses operation records, active flags in the search index, and a cache of in-progress operations so readers never see partial results, with SQS-driven retries for index update failures.", "interview_angle": "How would you atomically swap a large batch of derived records in a search index backed by a separate source-of-truth store, while keeping reads consistent and handling partial failures?", "score": 1.2438, "hn_points": 0, "hn_comments": 0}, {"url": "https://netflixtechblog.com/part-1-a-survey-of-analytics-engineering-work-at-netflix-d761cfd551ee", "company": "Netflix", "industry": "media", "title": "Part 1: A Survey of Analytics Engineering Work at Netflix", "date": "2024-12-17", "primary_problem": "modeling", "problems": ["lineage_catalog", "platform"], "post_type": "case_study", "level": "intermediate", "stack": ["DataJunction", "LLM"], "scale": "", "key_decisions": ["Centralize metric definitions in a semantic layer (DataJunction) so one metric can be reused across dashboards and experimentation, trading upfront registration effort for consistency", "Use dimension linking so the metric owner declares foreign keys and the system performs joins for consumers, reducing bespoke query logic but relying on correct key metadata", "Build a curated Foundational Platform Data layer feeding Cloud Efficiency Analytics, centralizing platform inventory and usage data for cost attribution at the cost of coordinating many upstream providers and SLAs"], "summary": "Netflix's Analytics Engineering survey introduces DataJunction, an open-source semantic layer for registering metrics once and querying them across dimensions, and summarizes LORE, an LLM-based analytics chatbot. It also describes a Foundational Platform Data and Cloud Efficiency Analytics layer that attributes cloud cost and ownership to engineering teams.", "interview_angle": "How would you design a metrics layer so that the same metric definition serves dashboards and experiments consistently, including automatic joins to dimension tables?", "score": 1.2434, "hn_points": 1, "hn_comments": 0}, {"url": "https://www.coinbase.com/blog/a-dedicated-architecture-for-solana-at-coinbase", "company": "Coinbase", "industry": "fintech", "title": "The Challenge: A Generalized Architecture Meets a Unique Blockchain", "date": "2026-01-30", "primary_problem": "realtime", "problems": ["scale_ingestion", "late_data"], "post_type": "case_study", "level": "advanced", "stack": ["Kafka", "Geyser", "gRPC", "Solana"], "scale": "12x Solana transaction throughput increase; 5x withdrawal capacity; 8x baseline traffic spikes absorbed", "key_decisions": ["Replaced polling of finalized slots with a hybrid model: Geyser push streams plus parallel RPC block fetches, gaining low latency while keeping backfill and failover reliability over pure push", "Built a dedicated Solana-specific indexing layer instead of extending the chain-agnostic pipeline, trading reuse for removal of sequential constraints that did not apply to Solana", "Processed blocks in parallel and used a high-water mark checkpoint to restore ordering for downstream components, trading added complexity for throughput"], "summary": "Coinbase replaced its generalized, chain-agnostic blockchain ingestion path for Solana with a dedicated streaming pipeline that streams finalized slots, parses and filters blocks in parallel, and publishes transactions through Kafka. The team validated it in a 30-day shadow mode before cutover, reporting 12x throughput, 5x withdrawal capacity, and 20% lower deposit latency.", "interview_angle": "How would you redesign an ingestion pipeline that was limited by the lowest common denominator across heterogeneous sources, while keeping strict ordering guarantees downstream when processing is parallelized?", "score": 1.2412, "hn_points": 0, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/d1-read-replication-beta", "company": "Cloudflare", "industry": "infra", "title": "Sequential consistency without borders: How D1 implements global read replication", "date": "2025-04-10", "primary_problem": "cdc_sync", "problems": ["performance", "storage_formats"], "post_type": "deep_dive", "level": "advanced", "stack": ["Cloudflare D1", "SQLite", "Cloudflare Durable Objects", "Cloudflare Workers", "Write-ahead log"], "scale": "Confirm lag measured between primary and replicas across regions; quorum of 3 of 5 durability followers", "key_decisions": ["Asynchronous replication streams WAL entries to replicas before quorum confirmation, trading replica staleness for lower write-path latency, with replicas hiding unconfirmed writes until committed", "Session bookmarks (Lamport-style monotonic timestamps) let clients resume sequential consistency across replicas, at the cost of replicas sometimes blocking until they catch up", "Static replica set in every region with nearest-region routing keeps implementation simple, but places no adaptive limits on replica count or placement"], "summary": "Cloudflare describes how D1 read replication streams SQLite WAL entries from a primary Durable Object to regional replicas, keeping unconfirmed writes hidden until a durability quorum confirms them. A Sessions API uses monotonic bookmarks so that a client's reads and writes stay sequentially consistent even when requests hop between replicas.", "interview_angle": "How would you replicate a single-writer database globally with low read latency while guaranteeing read-your-own-writes for a user whose requests may land on different replicas?", "score": 1.24, "hn_points": 5, "hn_comments": 0}, {"url": "https://engineering.zalando.com/posts/2021/07/knowledge-graph-master-data-mdm.html", "company": "Zalando", "industry": "ecommerce", "title": "Knowledge Graph Technologies Accelerate and Improve the Data Model Definition for Master Data", "date": "2021-07-28", "primary_problem": "modeling", "problems": ["lineage_catalog", "platform"], "post_type": "case_study", "level": "intermediate", "stack": ["Neo4j", "Python"], "scale": "tens of tables and hundreds of columns", "key_decisions": ["Model source systems and their columns as a knowledge graph of business concepts, so the golden-record logical model is generated from it rather than hand-drawn (trade-off: upfront effort to agree on unified naming of concepts and attributes)", "Generate each concept as a table and each relationship as its own table with foreign keys, including relationships as nodes (trade-off: more tables to manage, but relationships can carry mapping metadata)", "Use Neo4j visualisations generated from the graph for domain experts instead of SQL schema or spreadsheets (trade-off: better stakeholder readability, but the images are a reading aid rather than a source of truth)"], "summary": "Zalando describes an MDM project that uses a knowledge graph to map source system columns to shared business concepts, then auto-generates the golden record's logical data model and transformation mappings from that graph. The approach reduces manual modeling work and improves communication between domain experts and engineers, with lineage from each source to the golden record captured as a side effect.", "interview_angle": "How would you design a canonical data model for consolidating records from several source systems with different schemas, and how would you keep the mappings and lineage traceable and maintainable as sources grow?", "score": 1.24, "hn_points": 0, "hn_comments": 0}, {"url": "https://shopify.engineering/leveraging-multimodal-llms", "company": "Shopify", "industry": "ecommerce", "title": "Leveraging multimodal LLMs for Shopify\u2019s global catalogue: Recap of expo talk at ICLR 2025", "date": "2025-07-16", "primary_problem": "ml_data", "problems": ["scale_ingestion", "lineage_catalog"], "post_type": "case_study", "level": "advanced", "stack": ["Kafka", "Triton Inference Server", "Qwen2VL", "LLaVA", "LLaMA", "FP8 quantization"], "scale": "10M+ product updates/day; 40M LLM calls/day; ~16B tokens/day", "key_decisions": ["Multi-task fine-tuning of one vision LLM per catalogue entity: shares signal across tasks and improves quality, but couples tasks and complicates per-task iteration", "Selective field extraction during training: cuts median latency from 2s to 500ms and GPU token use by 40%, at the cost of needing instruction-following metrics to guard generalization", "Open-source fine-tuned VLMs instead of commercial APIs: far cheaper at high volume and gives control, but requires owning GPU serving and model upkeep"], "summary": "Shopify describes a Global Catalogue that streams over 10 million daily product updates through multimodal LLMs to classify, attribute, and deduplicate merchant listings into canonical product records. The post covers the data layers (CDC-backed product data, matching via graph connected components with edge pruning, reconciliation), LLM-driven annotation and active learning, and serving infrastructure handling about 40 million calls per day.", "interview_angle": "How would you design a pipeline that ingests millions of heterogeneous product updates per day, enriches them with LLM inference at low latency and controlled GPU cost, and deduplicates them into canonical entities without false merges?", "score": 1.239, "hn_points": 0, "hn_comments": 0}, {"url": "https://netflixtechblog.com/building-a-media-understanding-platform-for-ml-innovations-9bef9962dcb7", "company": "Netflix", "industry": "media", "title": "Building a Media Understanding Platform for ML Innovations", "date": "2023-03-14", "primary_problem": "ml_data", "problems": ["platform", "performance"], "post_type": "case_study", "level": "advanced", "stack": ["Cassandra", "Elasticsearch", "GraphQL", "gRPC", "Domain Graph Service Framework"], "scale": "A typical 1 hour video can contain over 80,000 frames", "key_decisions": ["Precompute ML algorithm outputs and serve them online instead of on-demand batch runs: faster user response but requires backfills and storage for every algorithm output", "Standardize on a shared annotation search service (Marken) with common schema types rather than per-algorithm datastores: easier maintenance and consistency at the cost of not using specialized vector stores", "Expose a generic query schema through gRPC/GraphQL and a pluggable search gateway: decouples apps from algorithms, but adds a translation layer and latency"], "summary": "Netflix describes a Media Search Platform that decouples ML-generated media annotations from the studio applications that consume them, evolving from on-demand batch runs and tightly coupled per-app integrations. The architecture routes queries through a gateway with embedding and translation steps into a shared searcher backed by Cassandra and Elasticsearch, with a custom sink ingesting algorithm outputs.", "interview_angle": "How would you design a serving layer that lets many ML algorithms with different output schemas and encodings be indexed and queried uniformly, including safe bulk backfills of precomputed embeddings?", "score": 1.2373, "hn_points": 1, "hn_comments": 0}, {"url": "https://monzo.com/blog/2023/09/12/the-skadnetwork-puzzle-using-data-to-solve-for-effective-performance", "company": "Monzo", "industry": "fintech", "title": "The SKAdNetwork Puzzle: Using Data to Solve for Effective Performance Marketing", "date": "2023-09-12", "primary_problem": "modeling", "problems": ["quality", "late_data"], "post_type": "case_study", "level": "intermediate", "stack": ["BigQuery", "dbt", "Airflow", "Looker", "Adjust"], "scale": "", "key_decisions": ["Scale SKAdNetwork-reported activations by an internal completion ratio, trading exact user-level accuracy for a simple, transparent correction that is consistent across channels", "Build denormalised campaign- and ad-level models by unioning sparse common-schema sources, trading some null-heavy storage for modularity and easier debugging", "Keep the adjustment in its own model and union block so it can be toggled on or off in dashboards, trading an extra layer of logic for transparency"], "summary": "Monzo's marketing data team describes how Apple's SKAdNetwork privacy constraints (limited conversion values, 24-hour windows, delayed postbacks) under-report iOS activations, and how they correct this using internal completion ratios. They built modular BigQuery and dbt models, orchestrated by Airflow and surfaced in Looker, to hold the adjustments separately from raw reported figures.", "interview_angle": "How would you model marketing attribution when a source system withholds or delays user-level conversion events, and how would you keep corrections transparent and toggleable for downstream reporting?", "score": 1.2348, "hn_points": 0, "hn_comments": 0}, {"url": "https://dropbox.tech/infrastructure/netflash-tracking-dropbox-network-traffic-in-real-time-with-elasticsearch", "company": "Dropbox", "industry": "saas", "title": "NetFlash: Tracking Dropbox network traffic in real-time with Elasticsearch", "date": "2016-10-06", "primary_problem": "realtime", "problems": ["scale_ingestion", "lineage_catalog"], "post_type": "case_study", "level": "advanced", "stack": ["Elasticsearch", "Kibana", "Kafka", "Hive", "HDFS", "Zookeeper", "Go", "Hadoop"], "scale": "260 billion NetFlow datagram records per day", "key_decisions": ["Run a parallel near-real-time pipeline (Kafka into Elasticsearch) alongside the existing Hive/HDFS batch path, trading duplicated infrastructure for query latency measured in seconds rather than hours.", "Enrich NetFlow records at the collectors with a local IP-to-infrastructure cache so every log carries searchable tokens, trading cache freshness and memory for avoiding per-record production DB lookups.", "Downsample logs 4x and keep only eight days indexed with one replica in Elasticsearch, trading historical search depth and redundancy for cluster stability and cost; long-term data stays in Hive."], "summary": "Dropbox built NetFlash, a parallel pipeline that enriches roughly 260 billion daily NetFlow records and indexes them in Elasticsearch via Kafka so network engineers can query traffic in near real time with Kibana dashboards. The post covers collector tuning, cluster stability fixes (spare data nodes to prevent shard reallocation cascades), and retention and downsampling trade-offs.", "interview_angle": "How would you give on-call engineers a near-real-time view of high-volume network logs when the batch warehouse takes hours to surface new data? Discuss enrichment at ingestion, index sizing, retention limits, and keeping a search cluster stable under failures.", "score": 1.234, "hn_points": 0, "hn_comments": 0}, {"url": "https://dropbox.tech/infrastructure/multimedia-search-dropbox-dash-evolution", "company": "Dropbox", "industry": "saas", "title": "How we brought multimedia search to Dropbox Dash", "date": "2025-05-29", "primary_problem": "cost", "problems": ["scale_ingestion", "performance"], "post_type": "case_study", "level": "intermediate", "stack": ["Riviera"], "scale": "Media files ~3x larger (images) and ~13x larger (video) than non-media; ingest rate ~1000x query rate; Riviera processes tens of petabytes daily", "key_decisions": ["Index lightweight metadata (path, title, EXIF) instead of full media content to keep compute low, trading away semantic/OCR relevance for now", "Generate previews just-in-time at query time with 30-day caching rather than precomputing all resolutions, saving storage but adding read-path latency", "Retain raw media blobs for future feature computation instead of deleting after preview generation, costing storage in exchange for re-ingestion avoidance"], "summary": "Dropbox describes how Dash added multimedia search by indexing cheap metadata from images, video and audio, and generating previews on demand. The post focuses on the storage and compute cost trade-offs of media ingestion and on reusing the Riviera framework and previews service.", "interview_angle": "How would you design search over large unlabeled media files when precomputing previews for every asset is too expensive, and where do you trade freshness and latency against cost?", "score": 1.2322, "hn_points": 0, "hn_comments": 0}, {"url": "https://building.nu.com/feature-stores-in-real-time-ml-part-3-examples-from-nubank", "company": "Nubank", "industry": "fintech", "title": "Feature stores in real-time ML, part 3:\u00a0 Examples from Nubank", "date": "2026-10-14", "primary_problem": "ml_data", "problems": ["realtime", "performance"], "post_type": "case_study", "level": "advanced", "stack": ["Flink", "Pinot", "DynamoDB", "Spark", "Parquet", "S3", "Kafka", "Feldera"], "scale": "", "key_decisions": ["Precompute features nightly into a denormalized KV store: very cheap and simple lookups, but serving data is stale and you must handle snapshot availability to avoid leakage", "Compute on-demand aggregations via Flink and Pinot with dual-write to offline and online paths: fresher features and less wasted compute, but aggregation logic diverges between Spark and SQL so skew must be monitored", "Two-stage Flink pipeline materializing per-customer rolling counts into DynamoDB: very low serving latency, but most precomputed rows are never read and the training code still differs"], "summary": "Nubank describes three feature-serving architectures for real-time ML: a nightly batch snapshot pushed to a key-value store, on-demand aggregations served by Flink and Pinot with dual-writes, and a two-stage Flink pipeline materializing rolling features into DynamoDB. The post stresses trade-offs between freshness, cost, latency and training-serving skew, and notes that these are partial feature store setups rather than a complete one.", "interview_angle": "How would you design a feature serving layer for real-time fraud or credit decisions that balances freshness, latency and cost, and how would you limit training-serving skew between batch and streaming feature logic?", "score": 1.229, "hn_points": 0, "hn_comments": 0}, {"url": "https://medium.com/pinterest-engineering/scaling-model-evaluation-at-pinterest-with-ray-part-4-4a96cd12cc11", "company": "Pinterest", "industry": "social", "title": "Scaling Model Evaluation at Pinterest with Ray (Part 4)", "date": "2026-11-04", "primary_problem": "performance", "problems": ["platform", "cost"], "post_type": "case_study", "level": "advanced", "stack": ["Ray", "Spark", "S3"], "scale": "Up to 3M rows per dataset (Large), up to 300 experiments; up to 32% lower end-to-end evaluation time", "key_decisions": ["Fuse metric computation with Ray inference instead of writing predictions to S3 and re-reading them, trading pipeline complexity for lower serde and cluster-startup overhead", "Use decomposable metric contracts (compute partials per batch, reduce globally) so metrics like MAE and approximate ROC-AUC can run batch-wise, accepting approximation for threshold-based AUC", "Pack complete segments into group-preserving buckets with Spark for group-wise metrics like Precision@K, trading extra colocation work for correct per-segment results"], "summary": "Pinterest describes a model evaluation platform that fuses metric computation into Ray batch inference, using a reducible-metric interface so partial results can be computed per batch and combined. Group-wise metrics are handled by Spark-based bucketing that keeps each request's rows together, and benchmarks show up to 32% lower end-to-end evaluation time with runtime growing roughly linearly in experiment count.", "interview_angle": "How would you compute global, non-decomposable metrics like ROC-AUC over a large distributed dataset without a full global sort, and when is an approximation acceptable?", "score": 1.2279, "hn_points": 0, "hn_comments": 0}, {"url": "https://shopify.engineering/server-sent-events-data-streaming", "company": "Shopify", "industry": "ecommerce", "title": "Using Server Sent Events to Simplify Real-time Streaming at Scale", "date": "2022-11-30", "primary_problem": "realtime", "problems": ["performance", "platform"], "post_type": "case_study", "level": "intermediate", "stack": ["Server-Sent Events", "Golang", "Nginx", "Flink", "Kafka", "Google Cloud Storage", "Parquet", "Redis", "MySQL", "WebSocket", "Java", "okhttp-eventsource"], "scale": "323 billion rows ingested during BFCM 2021; data visible on Live Map within 21 seconds end to end", "key_decisions": ["Chose Server-Sent Events over WebSocket for a read-only visualization, trading bidirectional capability for simpler, HTTP-native unidirectional push and automatic reconnection", "Removed the poll-based mailbox layer so data is pushed as soon as Flink produces it, trading the 10-second polling simplicity for lower latency and more connection state on the server", "Load-tested a horizontally scaled Golang SSE server behind Nginx with a distributed Java client simulating many connections, trading test infrastructure cost for knowing per-pod capacity before peak"], "summary": "Shopify replaced a multi-hop polling architecture for its BFCM Live Map with a Golang SSE server that pushes Flink-computed sales and trending data from Kafka directly to browsers. The redesign removed the Cricket service and mailbox polling layer, bringing end-to-end latency to about 21 seconds with 100 percent uptime during BFCM 2022.", "interview_angle": "How would you design a real-time dashboard that pushes streaming aggregates from Kafka to thousands of concurrent browser clients, and how would you size and load-balance the push tier?", "score": 1.2266, "hn_points": 2, "hn_comments": 2}, {"url": "https://www.capitalone.com/tech/cloud/eno-real-time-alerts-powered-by-serverless", "company": "Capital One", "industry": "fintech", "title": "Serverless Streaming & Eno's Proactive-Intelligent Insights | Capital One", "date": "2020-11-17", "primary_problem": "realtime", "problems": ["scale_ingestion", "platform"], "post_type": "case_study", "level": "intermediate", "stack": ["Amazon Kinesis", "AWS Lambda", "Spark"], "scale": "", "key_decisions": ["Replaced a Spark cluster setup with Lambda microservices chained over Kinesis, trading some control over processing for lower operations overhead and better utilization across availability zones and regions.", "Built an internal SDK that centralizes retries (blocking vs non-blocking), deduplication, envelopes, logging and secrets, trading upfront library investment for consistent behavior across functions.", "Structured the pipeline into Source, Processing and Sink layers with configuration-driven, business-free source and sink functions, favoring reuse across teams over per-insight monolithic jobs."], "summary": "Capital One describes how its Eno insights feature moved from a Spark-based streaming setup to a serverless event-driven pipeline built on AWS Lambda and Amazon Kinesis. The post covers the layered design, the internal SDK for retries and deduplication, and how the Generous Tip insight uses this architecture to flag anomalous card tips in near real time.", "interview_angle": "How would you design a real-time transaction-monitoring pipeline that stays resilient across zones and regions while keeping operational overhead low, and how would you handle retries and duplicate events?", "score": 1.2231, "hn_points": 0, "hn_comments": 0}, {"url": "https://monzo.com/blog/2022/02/18/how-we-calculate-balances", "company": "Monzo", "industry": "fintech", "title": "How we calculate balances", "date": "2022-02-18", "primary_problem": "modeling", "problems": ["quality", "lineage_catalog"], "post_type": "case_study", "level": "advanced", "stack": ["Go", "service.ledger"], "scale": "", "key_decisions": ["Centralise balance definitions in a single config (name plus time axis) generated statically with address config, trading flexibility for one source of truth shared by backend and warehouse", "Use committed or reporting timestamps as the only time axes instead of flake IDs, trading some implementation coupling for clearer semantics that match accounting and regulatory needs", "Expose a balance-by-name endpoint with parallel entry fetching, trading per-caller flexibility for consistency and a simpler interface that prevents misuse"], "summary": "Monzo explains how it reworked balance calculation in its double-entry ledger service so that every team gets the same balance for a given name. The redesign centres on balance definitions that map named balances to a fixed time axis and set of ledger addresses, which improves warehouse-to-backend reconciliation.", "interview_angle": "How would you keep balance definitions consistent between an operational ledger and a data warehouse so regulatory reconciliation reports agree?", "score": 1.2226, "hn_points": 1, "hn_comments": 0}, {"url": "https://dropbox.tech/application/why-we-chose-apache-superset-as-our-data-exploration-platform", "company": "Dropbox", "industry": "saas", "title": "Why we chose Apache Superset as our data exploration platform", "date": "2021-01-19", "primary_problem": "platform", "problems": ["lineage_catalog", "governance_privacy"], "post_type": "case_study", "level": "intermediate", "stack": ["Apache Superset", "Hive", "Presto", "S3", "Redash", "Metabase", "Mode", "Periscope"], "scale": "More than 10 internal data visualization tools consolidated into one", "key_decisions": ["Consolidate over 10 ad-hoc visualization tools into a single data exploration platform, trading away best-in-class features of individual competitors for fewer systems to maintain", "Prioritize security and user friendliness over flexibility and extensibility, accepting a tool with fewer alerting features than Redash in exchange for granular ACLs and easier adoption", "Prefer buy or open source over building in-house, and contribute missing features (like progress bars and ACL features) back upstream rather than building a custom tool"], "summary": "Dropbox describes consolidating more than ten internal data visualization tools into Apache Superset, evaluated against ranked criteria of security, user friendliness, maintainability and extensibility. The post frames the choice as pushing SQL-to-chart exploration onto the warehouse engine (Hive/Presto over S3) while keeping visualization separate from data processing.", "interview_angle": "How would you choose a self-serve BI/data exploration tool for a company with sensitive data and many legacy tools, and how would you weigh security, usability and maintenance against extensibility?", "score": 1.2204, "hn_points": 5, "hn_comments": 0}, {"url": "https://netflixtechblog.com/formulating-out-of-memory-kill-prediction-on-the-netflix-app-as-a-machine-learning-problem-989599029109", "company": "Netflix", "industry": "media", "title": "Formulating \u2018Out of Memory Kill\u2019 Prediction on the Netflix App as a Machine Learning Problem", "date": "2022-07-21", "primary_problem": "ml_data", "problems": ["quality", "scale_ingestion"], "post_type": "case_study", "level": "intermediate", "stack": ["Spark", "XGBoost"], "scale": "Millions of devices; OOM kills occur in about 0.9% of entries", "key_decisions": ["Joins device capability tables by composite key (device type, SDK version) and resolves conflicting values by majority vote, trading some nuance for consistent characteristics", "Filters rows before joins and restricts analysis to a single day and device to cut Spark compute and memory pressure, at the cost of narrower coverage", "Uses a graded sliding-window label on memory readings before each kill, turning OOM prediction into multi-class classification while keeping only inference-time features; this favors recall because false negatives are costlier"], "summary": "Netflix describes how it builds a labeled dataset from device capability tables and runtime memory logs to predict out-of-memory kills on TVs and set-top boxes. The post focuses on joining sources, cleaning conflicting device metadata, and a graded time-window labeling scheme that turns kill prediction into a classification problem.", "interview_angle": "How would you build a labeled training dataset from high-volume, heavily imbalanced device telemetry where labels come from events that occur after the features, and avoid leaking future information into the features?", "score": 1.2202, "hn_points": 2, "hn_comments": 0}, {"url": "https://dropbox.tech/infrastructure/how-our-universal-content-processing-platform-riviera-evolved-for-ai-and-beyond", "company": "Dropbox", "industry": "saas", "title": "How our universal content processing platform Riviera evolved for AI and beyond", "date": "2026-07-20", "primary_problem": "platform", "problems": ["scale_ingestion", "performance"], "post_type": "case_study", "level": "advanced", "stack": ["Model Context Protocol"], "scale": "Hundreds of thousands of transformations per second; more than 100 capabilities; 300+ file formats; about 8 years of video output per day", "key_decisions": ["Split each preview into reusable transformation steps (e.g., PowerPoint to PDF to page images) instead of building product-specific pipelines, trading upfront design effort for reuse across features", "Separate a central coordinator that validates, composes and caches requests from stateless backend workers per transformation type, which protects workers from duplicate work but adds a central component to operate", "Expose a plugin model so product teams can contribute transformations without changing core infrastructure, which speeds feature delivery but requires clear boundaries to keep the platform maintainable"], "summary": "Dropbox describes Riviera, its content processing platform that began as a preview generator and grew into a shared service for file transformations used by Replay, Sign, Search and Dash. The post explains how decomposing transformations into reusable steps, a central coordinator with caching, and a plugin architecture let the platform serve AI document preparation and now external API users.", "interview_angle": "How would you design a shared content transformation platform that serves many product teams, reuses intermediate outputs like thumbnails and PDFs, and keeps the core stable while new file types are added?", "score": 1.215, "hn_points": 0, "hn_comments": 0}, {"url": "https://netflixtechblog.com/data-pipeline-asset-management-with-dataflow-86525b3e21ca", "company": "Netflix", "industry": "media", "title": "Data pipeline asset management with Dataflow", "date": "2021-10-15", "primary_problem": "platform", "problems": ["migration", "governance_privacy"], "post_type": "deep_dive", "level": "advanced", "stack": ["Dataflow", "Spark", "Scala", "Python", "S3", "Jenkins", "Gradle", "YAML"], "scale": "", "key_decisions": ["Version each asset under a generated UUID and bundle assets with the workflow definition, trading some storage and registry complexity for atomic, reproducible rollbacks", "Keep assets in a Dataflow-managed S3 location instead of user-chosen paths, removing user-managed storage as a runtime dependency but centralizing the registry under the platform team", "Render workflow templates at deploy time to pin concrete asset pointers, which makes runs deterministic but means 'latest' references are resolved only at deployment rather than at execution"], "summary": "Netflix describes Dataflow, an internal CLI that versions data pipeline assets (JARs, Python eggs, SQL) and bundles them with scheduler workflow definitions so each deployment is reproducible and rollback-safe. The approach replaces ad hoc fixed S3 paths with UUID-referenced assets and branch-based deployments, and the team split a monorepo to adopt it.", "interview_angle": "How would you design a deployment system for scheduled data pipelines so that a rollback restores both workflow logic and its dependent code artifacts exactly as they ran before?", "score": 1.2137, "hn_points": 3, "hn_comments": 0}, {"url": "https://shopify.engineering/shopify-manages-petabyte-scale-mysql-backup-restore", "company": "Shopify", "industry": "ecommerce", "title": "How Shopify Manages Petabyte Scale MySQL Backup and Restore", "date": "2019-10-01", "primary_problem": "quality", "problems": ["cost", "platform"], "post_type": "case_study", "level": "advanced", "stack": ["MySQL", "Percona XtraBackup", "Google Cloud Storage", "Google Compute Engine", "Persistent Disk", "Kubernetes"], "scale": "Petabyte-scale MySQL fleet across 3 GCP regions; ~100 snapshots per day; over 1 PB verified daily", "key_decisions": ["Switched from Xtrabackup file backups to Persistent Disk snapshots: far faster backup and restore (RTO under 30 minutes) but higher storage cost and no built-in integrity checks", "Ran snapshot CronJobs on Kubernetes every 15 minutes across regions, snapshotting replicas in each region to avoid cross-region transfer costs", "Enforced a retention policy (latest two per shard plus dailies/weeklies) with automated deletion, and verified restored daily snapshots for startup, replication and InnoDB corruption, with offsite archives for catastrophe recovery"], "summary": "Shopify replaced Xtrabackup file-based MySQL backups with Persistent Disk snapshots orchestrated by Kubernetes CronJobs, cutting restore time from over six hours to under 30 minutes. The design adds automated retention, daily restore-based verification, and offsite copies because snapshots only live inside GCP.", "interview_angle": "How would you design backup and restore for a petabyte-scale relational database fleet to meet a tight RTO while controlling snapshot storage cost and verifying backup integrity?", "score": 1.2126, "hn_points": 0, "hn_comments": 0}, {"url": "https://engineering.zalando.com/posts/2016/05/scalable-fraud-detection-fashion-platform.html", "company": "Zalando", "industry": "ecommerce", "title": "Zalando Engineering Blog - Scalable Fraud Detection for Zalando's Fashion Platform", "date": "2016-05-31", "primary_problem": "migration", "problems": ["scale_ingestion", "ml_data"], "post_type": "case_study", "level": "intermediate", "stack": ["Python", "scikit-learn", "CherryPy", "Spark", "Scala", "Play framework", "S3", "AWS"], "scale": "Load test of 5,000 prediction requests; Spark learning on one driver and five workers", "key_decisions": ["Moved the fraud model pipeline from Python/scikit-learn to Spark/Scala, gaining distributed training and a typed codebase at the cost of a steep learning curve and some MLlib accuracy gaps", "Decoupled data acquisition from learning by landing source data on S3, removing the busy analytics database bottleneck but adding a separate ingestion layer to maintain", "Replaced JSON configs with code-as-configuration and a model-as-tree abstraction, improving type safety and reuse while making the framework harder to adopt for a team without JVM background"], "summary": "Zalando's Payana team rebuilt its real-time fraud-risk model service and training pipeline, moving from a Python/scikit-learn stack on an in-house cluster to Spark, Scala and Play on AWS. The new design separates data loading to S3 from learning, models compose as trees, and configuration is expressed as typed code, cutting learning time roughly in half and keeping prediction latency low under concurrency.", "interview_angle": "How would you redesign a fraud-scoring system that must both retrain models frequently on large history and serve low-latency predictions under unpredictable load, and how would you decouple training data acquisition from the source databases?", "score": 1.2098, "hn_points": 0, "hn_comments": 0}, {"url": "https://eng.lyft.com/building-a-large-scale-unsupervised-model-anomaly-detection-system-part-2-3690f4c37c5b", "company": "Lyft", "industry": "mobility", "title": "Building a large scale unsupervised model anomaly detection system \u2014 Part 2", "date": "2023-04-25", "primary_problem": "quality", "problems": ["platform", "ml_data"], "post_type": "case_study", "level": "advanced", "stack": ["whylogs", "Nixtla StatsForecast", "Fugue", "Spark", "Pandas", "Slack", "Mode Analytics"], "scale": "", "key_decisions": ["Profile raw data with whylogs in one pass so metrics stay cheap to compute, trading away ad hoc raw-data recomputation", "Adopt StatsForecast for fast confidence-interval forecasting, accepting less domain-specific tuning than hand-built rules or z-scores", "Route alerts to team Slack channels instead of PagerDuty to avoid alert fatigue, accepting that urgent issues may be noticed later"], "summary": "Lyft describes an automated anomaly detection system for ML model and business metrics that profiles data with whylogs, forecasts each profile time series with StatsForecast, and flags points outside confidence intervals. It also explains anomalies by regressing prediction changes on feature drift with SHAP values, and alerts owners via Slack.", "interview_angle": "How would you design an observability system that monitors thousands of ML features and business metrics automatically, scaling from pandas to Spark and explaining detected anomalies by feature drift?", "score": 1.2048, "hn_points": 0, "hn_comments": 0}, {"url": "https://engineering.zalando.com/posts/2016/03/apache-showdown-flink-vs.-spark.html", "company": "Zalando", "industry": "ecommerce", "title": "Zalando Engineering Blog - Apache Showdown: Flink vs. Spark", "date": "2016-03-31", "primary_problem": "realtime", "problems": ["scale_ingestion", "late_data"], "post_type": "case_study", "level": "intermediate", "stack": ["Flink", "Spark", "Kafka", "S3", "Oracle", "Storm", "Samza", "RocksDB"], "scale": "", "key_decisions": ["Chose Flink over Spark for native event-at-a-time processing and low, stable latency at high throughput, accepting that Flink 0.10/1.0 state was memory-bound until RocksDB out-of-core state arrived.", "Picked a key/value state model over Spark's dataset-scan state to keep update cost constant as state grows, trading off the risk of OutOfMemory failures.", "Prioritised built-in event-time and out-of-order handling plus a split operator for monitoring, reducing custom logic at the cost of a less mature ecosystem and smaller talent pool."], "summary": "Zalando evaluated Apache Spark and Apache Flink as the stream processing engine for its Saiki data integration platform, which pulls operational events from Kafka into an S3 data lake and feeds near real-time BI and continuous ETL. Proof-of-concept aggregation and monitoring jobs showed Flink delivering lower latency at high throughput, with better event-time handling and a split operator, so it was selected.", "interview_angle": "How would you choose a stream processing engine for stateful joins and time-based monitoring over Kafka, and what trade-offs in latency, state management and out-of-order handling would drive that choice?", "score": 1.2025, "hn_points": 0, "hn_comments": 0}, {"url": "https://shopify.engineering/running-apache-kafka-on-kubernetes-at-shopify", "company": "Shopify", "industry": "ecommerce", "title": "Running Apache Kafka on Kubernetes at Shopify", "date": "2018-11-07", "primary_problem": "platform", "problems": ["migration", "scale_ingestion"], "post_type": "case_study", "level": "advanced", "stack": ["Kafka", "Kubernetes", "Google Cloud Platform", "Chef", "Docker", "MirrorMaker"], "scale": "Billions of messages/events per day across multiple regional clusters", "key_decisions": ["Run Kafka brokers on Kubernetes StatefulSets instead of GCP VMs: gains orchestrated, ordered rollouts and custom controllers, but adds Kubernetes operational complexity for a stateful system", "Build and host its own Kafka container image rather than pulling third-party images: more control and availability, at the cost of maintaining an image pipeline", "Migrate with a mirror-then-cutover approach (regional clusters plus aggregate clusters mirrored in both environments) for zero downtime: safer but temporarily doubles infrastructure and mirroring traffic"], "summary": "Shopify describes moving its Kafka data bus from data centers to Google Cloud with zero downtime, using MirrorMaker to mirror regional and aggregate clusters before switching clients over. It explains choosing Kubernetes StatefulSets over raw VMs and lists practices like anti-affinity, persistent volumes, and rack-awareness to protect availability.", "interview_angle": "How would you move a stateful, high-throughput streaming system like Kafka to the cloud with zero downtime, and how would you keep brokers available during rolling restarts on Kubernetes?", "score": 1.2007, "hn_points": 0, "hn_comments": 0}, {"url": "https://engineering.grab.com/automated-experiment-analysis", "company": "Grab", "industry": "mobility", "title": "Automated Experiment Analysis - Making experimental analysis scalable", "date": "2022-05-30", "primary_problem": "platform", "problems": ["modeling", "quality"], "post_type": "case_study", "level": "intermediate", "stack": ["Azure Data Factory", "Spark", "Databricks", "Azure Data Lake", "CosmosDB", "Power BI", "Python"], "scale": "", "key_decisions": ["Decoupling the Decision Engine statistical library from data pipelines so statistical methods can evolve independently, at the cost of an extra interface to maintain", "Storing experiment configs and outputs as bronze/silver/gold layers in the lake, which gives reproducibility and review but adds pipeline stages to operate", "Embedding Power BI dashboards in the GrabX UI rather than building a custom front end, trading UI flexibility for faster delivery and a single workflow"], "summary": "Grab built an automated experiment analysis product that turns metric selections from experiment setup into Spark-based pipelines, runs standardised statistical tests, and publishes results to an embedded Power BI view. The design centres on a metrics glossary, medallion-style datasets, and a decoupled statistics package, aiming to replace ad-hoc manual analysis with reproducible, company-wide results.", "interview_angle": "How would you design a self-serve A/B test analysis pipeline that standardises metric definitions, keeps statistical logic decoupled from data sourcing, and guarantees reproducible results across many experiments?", "score": 1.1975, "hn_points": 0, "hn_comments": 0}, {"url": "https://shopify.engineering/optimizing-apache-flink-tips-part-two", "company": "Shopify", "industry": "ecommerce", "title": "3 (More) Tips for Optimizing Apache Flink Applications", "date": "2022-12-13", "primary_problem": "realtime", "problems": ["performance", "cdc_sync"], "post_type": "deep_dive", "level": "advanced", "stack": ["Flink", "Kafka", "Bigtable", "Cloud object storage"], "scale": "25 task managers x 4 slots for parallelism 100 (example only; no production volume stated)", "key_decisions": ["Start with environment-level parallelism and rely on slot sharing, trading per-operator tuning for better resource utilization", "Batch writes to sinks like Kafka and Bigtable, trading a little latency for throughput and lower sink CPU", "Use key bucketing (salting) to spread skewed keys, at the cost of needing a second aggregation step to recombine results"], "summary": "Shopify shares three practical Flink tuning tips: matching parallelism to task manager slot counts, avoiding sink and key-skew bottlenecks through batching and key bucketing, and using HybridSource to read Kafka archives in cloud storage followed by live Kafka as one logical stream. The post is a follow-up to an earlier tuning article and focuses on stateful streaming performance rather than specific production metrics.", "interview_angle": "How would you backfill a years-long Kafka topic from archived storage and then seamlessly switch to live data in a streaming job, while avoiding hot keys and sink backpressure?", "score": 1.1946, "hn_points": 0, "hn_comments": 0}, {"url": "https://medium.com/airbnb-engineering/de-identifying-text-at-scale-how-airbnb-protects-personal-data-in-ai-training-32f3ff8ff7d0", "company": "Airbnb", "industry": "marketplace", "title": "De-identifying text at scale: How Airbnb protects personal data in AI training", "date": "2026-11-17", "primary_problem": "governance_privacy", "problems": ["ml_data", "quality"], "post_type": "deep_dive", "level": "advanced", "stack": ["Presidio", "GLiNER", "spaCy", "Faker", "Python"], "scale": "", "key_decisions": ["Embedded Presidio as an in-process Python library rather than a central service, avoiding a single holder of raw personal data at the cost of requiring every pipeline to call the current compliant version", "Replaced spaCy with GLiNER for person and location detection so a street address can be requested specifically, trading some speed for better precision", "Used realistic seeded fake values instead of placeholder tokens, so the run-specific secret keeps outputs unlinkable across runs while staying consistent within a run, with no stored real-to-fake mapping"], "summary": "Airbnb describes a text de-identification pipeline that detects personal data in messages, reviews, and support chats before the text is used for ML training. It is built on the open-source Presidio library with custom recognizers, GLiNER-based NER, and per-entity benchmarking across recall, precision, and throughput.", "interview_angle": "How would you design a PII redaction step inside a training data pipeline so that downstream models stay useful, outputs can't be linked across runs, and every pipeline reliably applies the current privacy configuration?", "score": 1.1944, "hn_points": 0, "hn_comments": 0}, {"url": "https://www.coinbase.com/blog/how-coinbase-builds-sequence-features-for-machine-learning", "company": "Coinbase", "industry": "fintech", "title": "How Coinbase Builds Sequence Features for Machine Learning", "date": "2025-05-13", "primary_problem": "ml_data", "problems": ["realtime", "scale_ingestion"], "post_type": "case_study", "level": "advanced", "stack": ["Tecton", "Databricks", "Spark", "Kafka", "Delta Lake", "DynamoDB"], "scale": "~2k events/second on the most demanding streaming job; serves hundreds of millions of users", "key_decisions": ["Register each ML event explicitly in a registry and auto-generate Tecton data sources, trading upfront governance work for consistent schemas and easier discovery", "Use stateless Spark structured streaming in continuous mode (0-second micro-batch) writing raw events to DynamoDB, with sequences rolled up at read time, minimizing freshness lag but pushing work to online serving", "Run Databricks single-node clusters for stateless streaming jobs, cutting 20-40% CPU and cost while keeping freshness, which only works because the jobs are not memory-heavy"], "summary": "Coinbase built a framework where ML engineers declare a sequence feature's events and semantics, and it generates Tecton streaming feature views backed by Spark over Kafka and Delta sources. The design targets second-level freshness and sub-100ms online reads, and uses an event registry plus single-node Databricks clusters to keep the pipelines manageable and cheap.", "interview_angle": "How would you design a feature pipeline that serves per-user event sequences with second-level freshness and sub-100ms online reads, while letting many teams add new event types without bespoke pipelines?", "score": 1.1902, "hn_points": 0, "hn_comments": 0}, {"url": "https://www.capitalone.com/tech/cloud/cost-visibility-clickhouse", "company": "Capital One", "industry": "fintech", "title": "Cloud Cost Visibility with ClickHouse | Capital One", "date": "2025-10-22", "primary_problem": "cost", "problems": ["realtime", "performance"], "post_type": "case_study", "level": "intermediate", "stack": ["ClickHouse"], "scale": "", "key_decisions": ["Adopting ClickHouse over other stores for real-time cloud cost analytics, trading general-purpose flexibility for columnar analytical speed", "Using MergeTree with partitioning and primary key indexing for fast inserts and queries as volumes grow, at the cost of tuning table design", "Choosing open source ClickHouse so the team can extend and contribute back, accepting the operational burden of self-managing it"], "summary": "Capital One describes using open source ClickHouse as the backbone for near real-time cloud cost visibility, covering billing events, utilization data and telemetry. The post is mostly a high-level rationale for the tool and the FinOps outcomes it enables, with few concrete architecture or volume details.", "interview_angle": "How would you design a near real-time cost analytics store over billing and utilization events so FinOps teams can spot anomalies quickly and query history cheaply?", "score": 1.1883, "hn_points": 0, "hn_comments": 0}, {"url": "https://www.coinbase.com/blog/databricks-cost-management-at-coinbase", "company": "Coinbase", "industry": "fintech", "title": "Databricks cost management at Coinbase", "date": "2023-05-24", "primary_problem": "cost", "problems": ["platform", "quality"], "post_type": "case_study", "level": "intermediate", "stack": ["Databricks", "Spark", "Databricks Overwatch", "AWS"], "scale": "", "key_decisions": ["Enforce cluster tagging on all Databricks jobs to attribute spend to teams, trading some developer friction for clear chargeback visibility", "Use a predefined set of instance pools with zero minimum idle instances and a 2-minute idle timeout, trading cold-start latency for lower idle spend", "Centralize cluster policies (DBU/hour caps, allowed instance types, pool IDs) to enforce quotas, trading flexibility for predictable spend"], "summary": "Coinbase built a cost management layer for its Databricks workloads, combining cluster tagging for team attribution, a cost insights pipeline built on Overwatch-processed logs, and quota enforcement. Quotas are enforced through categorized instance pools and cluster policies whose settings were tuned from observed job submission patterns.", "interview_angle": "How would you design cost attribution and enforcement for a shared Spark platform: what signals you would collect from billing and cluster logs, and how you would cap spend without blocking teams?", "score": 1.187, "hn_points": 0, "hn_comments": 0}, {"url": "https://engineering.grab.com/automatic-rule-backtesting", "company": "Grab", "industry": "mobility", "title": "Automatic rule backtesting with large quantities of data", "date": "2022-09-08", "primary_problem": "platform", "problems": ["scale_ingestion", "migration"], "post_type": "case_study", "level": "intermediate", "stack": ["Spark", "Kafka", "S3", "Amazon EMR", "AWS Lambda", "Amazon SQS", "Parquet", "Avro", "Presto", "Kubernetes"], "scale": "", "key_decisions": ["Replay historical rule events with a cloud-agnostic Spark pipeline instead of shadow mode, trading upfront build effort for much faster rule onboarding", "Event-driven job orchestration via SQS and Lambda to launch EMR Spark jobs, which decouples the UI from compute but adds more moving parts to debug", "Store trust inference events in S3 as Snappy Parquet partitioned by time, which speeds replay but leaves no automatic retention so archiving is deferred"], "summary": "Grab built a backtesting system that replays historical rule-engine events through a Spark pipeline on EMR, triggered from the rule editor UI via SQS and Lambda. It replaces inconsistent offline analyses and multi-day shadow-mode runs with on-demand replay over stored events in S3.", "interview_angle": "How would you design a system that replays months of historical events through a new business rule on demand, with job orchestration, result storage, and a path to let non-engineers self-serve?", "score": 1.186, "hn_points": 0, "hn_comments": 0}, {"url": "https://tech.instacart.com/instacarts-item-availability-architecture-solving-for-scale-and-consistency-f5661acb20a6", "company": "Instacart", "industry": "marketplace", "title": "Instacart\u2019s Item Availability Architecture: Solving for scale and consistency.", "date": "2023-09-06", "primary_problem": "performance", "problems": ["scale_ingestion", "realtime"], "post_type": "case_study", "level": "advanced", "stack": ["Snowflake", "Kinesis", "SQL database", "gRPC"], "scale": "Hundreds of millions of items across 80,000+ retail locations", "key_decisions": ["Store ML availability scores in a DB table so retrieval can use SQL joins, trading storage and write load for low-latency bulk reads over per-request RPC calls", "Combine periodic full syncs from Snowflake with on-demand lazy refresh triggered by search results, cutting ingestion load by about two-thirds but leaving some items to update only on the full-sync cadence", "Use per-model DB columns plus config-driven mappings and a delta/threshold resolver so experiments scale without new joins, at the cost of wide tables and combinatorial threshold management"], "summary": "Instacart describes the serving infrastructure for real-time item availability scores, which pushes ML-generated scores from Snowflake and on-demand refreshes into a database for fast retrieval-stage filtering. It also covers a config-driven framework for running multiple models in parallel and a delta-based threshold system that is auto-tuned with a feedback loop.", "interview_angle": "How would you design a pipeline that syncs ML scores from a warehouse into an online store for low-latency, consistent bulk reads, while refreshing only stale items and supporting several model versions at once?", "score": 1.1833, "hn_points": 0, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/explaining-cloudflares-abr-analytics", "company": "Cloudflare", "industry": "infra", "title": "Explaining Cloudflare's ABR Analytics", "date": "2020-09-29", "primary_problem": "performance", "problems": ["scale_ingestion", "cost"], "post_type": "deep_dive", "level": "advanced", "stack": ["ClickHouse"], "scale": "Seven orders of magnitude of resolution per dataset; ~12% extra disk storage for multi-resolution tables", "key_decisions": ["Store the same events at multiple sample rates in separate ClickHouse tables so queries pick a resolution matching their needs: faster and cheaper queries, at the cost of about 12% extra storage and some estimate error.", "Use rollups versus raw sampled data: rollups save space but fix attributes up front and lose information; sampling keeps every attribute queryable but gives approximate results.", "Choose sampling by distinct value for count-distinct (sample IPs rather than requests): uniform random sampling cannot estimate cardinality, but this trades complexity for accuracy; topK estimates from samples can be biased at high cardinality."], "summary": "Cloudflare describes ABR (Adaptive Bit Rate) for its analytics: each query runs against a pre-sampled table whose resolution matches the question, so dashboards stay fast and reliable even when data volumes spike or servers fail. The approach stores the same events at multiple sample rates in ClickHouse, and it handles topK and count-distinct with sampling techniques suited to each.", "interview_angle": "How would you serve interactive analytics over a highly skewed event stream with unpredictable query sizes? Discuss multi-resolution sampled tables versus pre-computed rollups, and how to estimate count-distinct and topK from samples.", "score": 1.1821, "hn_points": 3, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/d1-control-plane", "company": "Cloudflare", "industry": "infra", "title": "Under the hood, off the hot path: how D1 scales to millions of databases", "date": "2026-10-13", "primary_problem": "scale_ingestion", "problems": ["cost", "platform"], "post_type": "deep_dive", "level": "advanced", "stack": ["D1", "SQLite", "Durable Objects", "Workers KV", "Hyperdrive", "PostgreSQL", "ClickHouse", "Quicksilver", "Cloudflare Queues"], "scale": "Millions of D1 databases created, hundreds of thousands active at any point; 15x database growth in one year, 65x in two years", "key_decisions": ["Use unique Durable Object IDs with Postgres as source of truth and periodic heartbeats to self-correct orphans, trading extra retry complexity for no lookup on the query path", "Batch per-database storage updates through a queue and precompute per-account totals with a delta table, accepting eventual consistency in exchange for avoiding row lock contention and expensive sums", "Serve query routing from Workers KV and limit enforcement from Quicksilver/ClickHouse rather than central Postgres, trading freshness of limits for keeping the hot path off central infrastructure"], "summary": "Cloudflare describes the control plane behind D1, its SQLite-on-Durable-Objects database service, which must handle millions of databases with hundreds of thousands active. The post covers database creation with retries and heartbeats, keeping query routing off central Postgres via Workers KV, and enforcing storage and row-based usage limits using queues, incremental aggregation tables, Hyperdrive caching, and ClickHouse.", "interview_angle": "How would you design a control plane for millions of small databases so that per-query routing avoids a central bottleneck, while still enforcing per-account storage quotas with eventually consistent usage aggregation?", "score": 1.1804, "hn_points": 4, "hn_comments": 0}, {"url": "https://eng.lyft.com/elasticsearch-optimizations-at-lyft-b555dc020932", "company": "Lyft", "industry": "mobility", "title": "Elasticsearch Optimizations at Lyft", "date": "2021-02-23", "primary_problem": "performance", "problems": ["cost"], "post_type": "case_study", "level": "intermediate", "stack": ["Elasticsearch", "Apache JMeter", "AWS"], "scale": "~300 million documents per index, ~4000 fields, 20 primary shards; scroll latency cut to ~307ms", "key_decisions": ["Drop _source and sort by _doc in scroll requests: much lower latency, but results come back unordered and without field values", "Route count queries by _routing to a single shard using the known user ID: far less cluster load, but relies on the long-lived index design where document IDs are known up front", "Use terminate_after to stop count queries early: faster and cheaper per query, but only correct when you need a capped count rather than an exact total"], "summary": "Lyft tuned an Elasticsearch cluster that backs cohort targeting and user feature lookups, which had grown slower and more expensive as new use cases arrived. By omitting _source and sorting by _doc for scroll requests, and routing count queries to one shard with _routing and terminate_after, they cut scroll latency to a few hundred milliseconds and lowered CPU load and cluster resources.", "interview_angle": "How would you serve cohort membership checks and bulk audience exports from a large search index with tight latency and cost targets? Discuss document layout, shard routing, and trade-offs in what fields to fetch.", "score": 1.1784, "hn_points": 2, "hn_comments": 0}, {"url": "https://dropbox.tech/application/scaling-mongodb-at-mailbox", "company": "Dropbox", "industry": "saas", "title": "Scaling MongoDB at Mailbox", "date": "2013-09-12", "primary_problem": "migration", "problems": ["cdc_sync", "scale_ingestion"], "post_type": "case_study", "level": "advanced", "stack": ["MongoDB", "Python", "gevent", "pymongo", "mongodump"], "scale": "Hundreds of millions of emails and over 100 million oplog operations migrated in about 9 hours", "key_decisions": ["Used a custom gevent-based Python copier in a single process per shard instead of threads or multiprocess pools, trading C++ speed for development ease and far higher throughput from I/O concurrency", "Replayed oplog changes to the new cluster and re-copied the full document on update instead of applying the update op, trading exact update semantics for simplicity and guaranteed recency", "Verified consistency with retry comparisons under eventual consistency plus a final check of recently modified ops during a short downtime window, accepting some residual risk for live-traffic cutover"], "summary": "Dropbox moved a hot MongoDB collection for Mailbox to a dedicated cluster to relieve database-level write lock contention, building a custom tool (Hydra) that snapshots the collection and streams oplog changes live. The team relied on gevent-based concurrency, per-_id ordering of replayed ops, and iterative comparison of source and destination to reach a near-zero-downtime cutover.", "interview_angle": "How would you migrate a live, high-write collection between database clusters with minimal downtime while keeping data consistent, given the source is not transactional and cannot be cloned via native tools?", "score": 1.1748, "hn_points": 0, "hn_comments": 0}, {"url": "https://engineering.grab.com/exposing-kafka-cluster", "company": "Grab", "industry": "mobility", "title": "Exposing a Kafka Cluster via a VPC Endpoint Service", "date": "2022-02-18", "primary_problem": "platform", "problems": ["scale_ingestion", "cost"], "post_type": "deep_dive", "level": "advanced", "stack": ["Kafka", "AWS VPC", "AWS PrivateLink", "Network Load Balancer", "Route 53", "Terraform", "Jenkins", "Ansible"], "scale": "3 Kafka brokers across 3 AZs; 4 NLB listeners", "key_decisions": ["Expose Kafka via VPC Endpoint Service instead of VPC peering to shrink network attack surface, at the cost of more complex setup", "One NLB listener and target group per broker so clients can reach each broker deterministically, at the cost of manual port and SG changes when scaling", "Add per-AZ DNS names so clients connect to same-AZ endpoints, avoiding cross-AZ data transfer charges and latency"], "summary": "Grab exposes a multi-AZ Kafka cluster in its main VPC to producers and consumers in a separate GrabKios VPC using an AWS VPC Endpoint Service fronted by a Network Load Balancer. Per-broker listeners and zonal DNS names let clients reach each broker deterministically while keeping traffic within an availability zone.", "interview_angle": "How would you let a service in another network reach a multi-broker Kafka cluster securely without VPC peering, while keeping each client connected to a broker in its own AZ?", "score": 1.1743, "hn_points": 0, "hn_comments": 0}, {"url": "https://medium.com/paypal-tech/declarative-feature-engineering-at-paypal-eddcae81c06d", "company": "PayPal", "industry": "fintech", "title": "Declarative Feature Engineering at PayPal", "date": "2023-12-11", "primary_problem": "ml_data", "problems": ["platform", "cost"], "post_type": "case_study", "level": "advanced", "stack": ["Feature Store"], "scale": "Several thousand payment transactions per minute; 400 million active consumers and merchants", "key_decisions": ["Express features as declarative configs so scientists specify what to compute and the system chooses batch, near-real-time or real-time execution; trade-off is less low-level control for complex logic", "Split features into simple, code-based and analytical-platform tiers with different strategies; trade-off is that the most complex tier stays costly to maintain", "Enforce point-in-time correct computation and register features in a shared store; trade-off is extra system machinery in exchange for self-service backfills and feature reuse"], "summary": "PayPal describes a config-based approach to feature engineering that lets data scientists declare simple features and have the platform generate pipelines for batch or real-time execution. The post frames predictable time to market and total cost of ownership around feature reuse, with point-in-time backfills and a shared feature store as core parts of the design.", "interview_angle": "How would you design a self-serve feature platform that lets data scientists declare features once and run them in both batch and real-time with point-in-time correct backfills?", "score": 1.1729, "hn_points": 1, "hn_comments": 0}, {"url": "https://engineering.grab.com/democratising-fare-storage-at-scale-using-event-sourcing", "company": "Grab", "industry": "mobility", "title": "Democratising Fare Storage at Scale Using Event Sourcing", "date": "2020-11-23", "primary_problem": "modeling", "problems": ["quality", "platform"], "post_type": "case_study", "level": "advanced", "stack": ["DynamoDB", "Protocol Buffers", "Go"], "scale": "millions of bookings created per day", "key_decisions": ["Event sourcing with CQRS over a single mutable booking table: full audit trail and decoupled fare data, but more complex reads that must replay events (cached for eventually consistent reads)", "Optimistic locking with a fare version instead of pessimistic locks: low overhead since conflicts are rare, but clients must retry on version mismatch", "Client-generated transaction IDs for idempotency plus schema-less metadata serialised by the SDK: safe retries and fast feature iteration, at the cost of pushing complexity into clients"], "summary": "Grab replaced a bloated legacy booking table with an event-sourced Fare Storage service backed by DynamoDB, storing every fare change as an ordered event. The design uses optimistic locking via version numbers, client-side transaction IDs for idempotent writes, and SDK-managed schema-less metadata so teams can ship fare features without touching the store.", "interview_angle": "How would you design an append-only audit store for concurrent updates to a monetary value, guaranteeing ordering and idempotent retries without coupling storage to business logic?", "score": 1.1727, "hn_points": 0, "hn_comments": 0}, {"url": "https://shopify.engineering/kafka-producer-pipeline-for-ruby-on-rails", "company": "Shopify", "industry": "ecommerce", "title": "Kafka Producer Pipeline for Ruby on Rails", "date": "2014-07-22", "primary_problem": "scale_ingestion", "problems": ["realtime", "platform"], "post_type": "case_study", "level": "advanced", "stack": ["Kafka", "Ruby on Rails", "Go", "Sarama", "SysV message queues", "Docker", "StatsD"], "scale": "Local queue sized to hold about two hours of events during Kafka downtime; queue usually only a few KB", "key_decisions": ["Used a Go producer on the host rather than a Kafka client in Ruby, trading an extra hop for simpler integration with the Rails stack", "Buffered events in a kernel-owned SysV message queue so either end can restart without losing data, at the cost of a host-local, non-portable IPC mechanic", "When containerizing, ran one host-level proxy reached over TCP instead of a producer in every container, avoiding thousands of extra Kafka connections but adding a network dependency"], "summary": "Shopify built a Kafka event producer that Rails code could feed without a direct Ruby-to-Kafka client, using a Go producer built on Sarama and a local SysV message queue as a durable buffer. When they moved to Docker, containers could no longer share the IPC queue, so they added a TCP-to-SysV proxy on the host.", "interview_angle": "How would you get events from a language with no good Kafka client into Kafka while tolerating broker downtime and containerized workloads without losing data?", "score": 1.1709, "hn_points": 0, "hn_comments": 0}, {"url": "https://shopify.engineering/apache-beam-for-search-getting-started-by-hacking-time", "company": "Shopify", "industry": "ecommerce", "title": "Apache Beam for Search: Getting Started by Hacking Time", "date": "2021-01-08", "primary_problem": "late_data", "problems": ["realtime", "scale_ingestion"], "post_type": "deep_dive", "level": "intermediate", "stack": ["Beam", "Kafka", "Java", "Spark", "Apache Storm"], "scale": "", "key_decisions": ["Use Kafka create time or a custom event-time field instead of processing time, so windows reflect when users actually searched or clicked, at the cost of having to wait for watermarks.", "Set an allowed out-of-orderness bound (e.g. 5 minutes) on the source watermark, trading completeness of late events against result latency and dropped events.", "Use one Beam model for both historical replay and live streams rather than separate Spark batch and Storm streaming systems, accepting the complexity of learning Beam's time semantics."], "summary": "The post is an introduction to Apache Beam for processing search clickstream data at Shopify's Discovery team, focused on handling event time versus processing time. It walks through configuring a Kafka source with create-time and a custom timestamp policy, with an analogy about replaying movies at high speed to explain watermarks and allowed delay.", "interview_angle": "How would you design a streaming pipeline that computes click popularity per search query when events arrive out of order, and how do you choose the watermark delay and event-time source?", "score": 1.168, "hn_points": 87, "hn_comments": 8}, {"url": "https://monzo.com/blog/how-we-built-year-in-monzo-unlocking-the-data-magic", "company": "Monzo", "industry": "fintech", "title": "How we built Year in Monzo: unlocking the data magic \u2728", "date": "2023-12-20", "primary_problem": "quality", "problems": ["modeling", "governance_privacy"], "post_type": "case_study", "level": "intermediate", "stack": [], "scale": "Over 8.5 million merchants shopped at in 2023; 6,000+ merchant names curated", "key_decisions": ["Set eligibility thresholds (15 eligible transactions, merchants with 1,000+ transactions) to balance inclusivity against story depth and data-cleaning effort", "Rank merchants by transaction frequency rather than amount, with popularity as tie-breaker, trading off spend-value signal for simplicity", "Use human-in-the-loop merchant name curation with crowd-sourcing for the top merchants, accepting manual effort to fix messy merchant data"], "summary": "Monzo's analytics team describes how they chose which data points could power the personalised Year in Monzo 2023 eras, with rules for audience size, data availability and exclusion of harmful merchants. The post also covers the QA process (data model review, staff testing, merchant name cleanup) used to ship the feature.", "interview_angle": "How would you design a pipeline that produces per-user personalised summaries from transaction data while handling messy merchant names and enforcing exclusion rules for sensitive categories?", "score": 1.1648, "hn_points": 0, "hn_comments": 0}, {"url": "https://engineering.zalando.com/posts/2023/11/patching-pgjdbc.html", "company": "Zalando", "industry": "ecommerce", "title": "Patching the PostgreSQL JDBC Driver", "date": "2023-11-08", "primary_problem": "cdc_sync", "problems": ["cost", "realtime"], "post_type": "deep_dive", "level": "advanced", "stack": ["PostgreSQL", "Debezium", "PgJDBC", "AWS Lambda", "Docker"], "scale": "Hundreds of Postgres-sourced event streams", "key_decisions": ["Confirm LSNs on KeepAlive messages in the JDBC driver rather than writing dummy rows to idle tables, which fixes the root cause for all clients but requires an upstream driver change and patching.", "Build a patched PgJDBC 42.6.1 image and run it in test while production stays on the stock image, trading rollout speed for safe verification.", "Use a conservative LSN-advance rule (advance only when no relevant change is pending) so no relevant events can be skipped, at the cost of a more complex client state machine."], "summary": "Zalando traced runaway Postgres WAL growth in logical replication to idle replication slots that never advance when a table they don't watch receives no writes. They fixed it upstream in the PgJDBC driver by confirming LSNs from KeepAlive messages, then rolled out a patched Debezium image to hundreds of event streams.", "interview_angle": "How would you prevent WAL bloat from idle logical replication slots on a shared Postgres server, and what are the trade-offs versus writing heartbeat rows to force slot advancement?", "score": 1.1638, "hn_points": 0, "hn_comments": 0}, {"url": "https://engineering.zalando.com/posts/2018/02/solving-many-small-files-avro.html", "company": "Zalando", "industry": "ecommerce", "title": "Zalando Engineering Blog - Crushing AVRO Small Files with Spark", "date": "2018-02-06", "primary_problem": "storage_formats", "problems": ["cost", "performance"], "post_type": "case_study", "level": "intermediate", "stack": ["Spark", "AVRO", "Hadoop", "AWS EMR", "S3", "s3-dist-cp", "Filecrush", "Avro-Tools"], "scale": "", "key_decisions": ["Wrote a custom Spark job that repartitions daily AVRO output to target block-sized files, trading a bespoke codebase for correctness on AVRO files that naive concatenation would corrupt.", "Sized output partitions from input size, an assumed AVRO compression ratio and the HDFS block size, which is simple but depends on estimate accuracy.", "Switched from spark-avro to the low-level newAPIHadoopFile/saveAsNewAPIHadoopFile GenericRecord APIs after spark-avro mangled the schema, accepting more verbose code to keep the schema intact."], "summary": "Zalando's Fashion Content Platform had many small AVRO files from a real-time writer, which slowed Hadoop jobs on EMR/S3. They built a Spark compaction job that regroups daily data into larger files, after existing tools like s3-dist-cp, Filecrush and Avro-Tools failed for AVRO or S3 reasons.", "interview_angle": "How would you compact millions of small files written by a streaming system into large splittable files on S3 without breaking the file format or schema?", "score": 1.161, "hn_points": 0, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/route-leak-detection-with-cloudflare-radar", "company": "Cloudflare", "industry": "infra", "title": "How we detect route leaks and our new Cloudflare Radar route leak service", "date": "2022-11-23", "primary_problem": "scale_ingestion", "problems": ["realtime", "quality"], "post_type": "case_study", "level": "advanced", "stack": ["Kafka", "BGPKIT Broker", "BGPKIT Parser", "Rust", "RouteViews", "RIPE RIS", "CAIDA AS relationship data"], "scale": "Over 2 billion BGP messages per day (about 30,000 per second) from 63 collectors and 2,400+ collector peers", "key_decisions": ["Use semi-real-time public BGP archives (10-30 min delay) instead of true real-time feeds, trading freshness for completeness across all public collectors", "Base detection on the valley-free model with inferred AS relationships, blending CAIDA data with in-house datasets and per-prefix granularity to cut false positives, at the cost of depending on inference accuracy", "Store per-message leak entries long-term and aggregate them into leak events by leaker ASN within short windows, so downstream UIs and API consume consolidated events"], "summary": "Cloudflare describes a pipeline that ingests public BGP archive files from RouteViews and RIPE RIS, converts them into a high-volume message stream, and runs valley-free detection to flag route leaks. The detected events are stored, aggregated into incidents, and exposed through Cloudflare Radar pages and a public API.", "interview_angle": "How would you design a pipeline that ingests tens of thousands of messages per second from many archive sources with delayed availability, and keeps false positives low using inferred reference data?", "score": 1.1553, "hn_points": 4, "hn_comments": 0}, {"url": "https://www.coinbase.com/blog/incident-post-mortem-november-19-2021", "company": "Coinbase", "industry": "fintech", "title": "Incident Post Mortem: November 19, 2021", "date": "2021-11-19", "primary_problem": "quality", "problems": ["platform", "cost"], "post_type": "postmortem", "level": "intermediate", "stack": [], "scale": "approximately 0.0072% of Coinbase's verified users affected", "key_decisions": ["Disabled trading in GYEN and POWR immediately on detection, trading user-facing availability for limiting further over-crediting", "Chose most favorable exchange rates for customers when debiting or crediting, trading off financial cost to the company for customer trust and fairness", "Restricted affected accounts temporarily while investigating, trading customer access for accurate reconciliation"], "summary": "Coinbase describes an incident where a data rollout tied to asset precision propagated at different speeds through internal systems, crediting some customers 100x or 1/100th of their actual GYEN and POWR purchases. The post covers detection through position risk monitoring, trading halts, account restrictions, and the reconciliation approach for over- and under-credited balances.", "interview_angle": "How would you design validation for a config or reference-data change that propagates asynchronously across multiple downstream systems, so that a bad value is caught before it produces wrong balances?", "score": 1.1497, "hn_points": 0, "hn_comments": 0}, {"url": "https://monzo.com/blog/vertically-scaling-ordered-consumption-using-kafka", "company": "Monzo", "industry": "fintech", "title": "Vertically scaling ordered consumption using Kafka", "date": "2024-10-29", "primary_problem": "realtime", "problems": ["scale_ingestion", "platform"], "post_type": "deep_dive", "level": "advanced", "stack": ["Kafka", "Go", "Kubernetes"], "scale": "", "key_decisions": ["Per-key ordering built on unordered concurrent consumption: messages with the same partition key are serialized via a local mutex while different keys proceed in parallel, trading head-of-line blocking for throughput.", "Use a long-lived distributed lock per partition to guarantee single consumer per partition, accepting extra lock cost to avoid zombie consumers breaking ordering.", "Prefer adding a generated opt-in option instead of extra Kafka partitions, avoiding partition-count planning, offset-reset pitfalls and one-way partition additions, at the cost of head-of-line stalls on a locked key."], "summary": "Monzo extended its in-house Kafka consumer library so that unordered concurrent subscriptions can enforce strict ordering per partition key, using local mutexes instead of distributed locks or extra partitions. The post explains the sharp edges of scaling ordered consumption by adding partitions and the trade-offs of the naive per-key serialization design.", "interview_angle": "How would you let a batch consumer process messages concurrently while guaranteeing per-key ordering and mutual exclusion, without scaling by partition count alone?", "score": 1.1475, "hn_points": 0, "hn_comments": 0}, {"url": "https://engineering.grab.com/building-grab-s-experimentation-platform", "company": "Grab", "industry": "mobility", "title": "Building Grab\u2019s Experimentation Platform", "date": "2018-07-13", "primary_problem": "platform", "problems": ["realtime", "modeling"], "post_type": "case_study", "level": "intermediate", "stack": ["S3", "Android SDK", "iOS SDK", "Golang"], "scale": "~25 concurrent experiments; ~2500 metrics computed per day; ~50,000 experiment/metric combinations", "key_decisions": ["Build a unified in-house experimentation platform rather than per-team custom pipelines, trading upfront engineering cost for consistency and reuse", "Use JSON experiment definitions consumed by SDKs without network calls, trading flexibility for low latency and machine-executable configs", "Use geo-temporal segmentation and an expert validation layer to limit interference between concurrent experiments, trading some experiment capacity for validity"], "summary": "Grab describes its in-house experimentation platform (ExP), which lets teams define variables, metrics, groups and time-bound experiment definitions that SDKs apply without network calls. Experimental events are streamed in real time and stored in S3, and the platform handles assignment strategies, interference prevention and staged rollouts at a scale of about 25 concurrent experiments and 2,500 daily metrics.", "interview_angle": "How would you design an experimentation platform that streams exposure and metric events in real time, computes many metrics per day, and prevents concurrent experiments from interfering with each other across users who interact (e.g., drivers and passengers)?", "score": 1.1468, "hn_points": 0, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/how-we-built-dmarc-management", "company": "Cloudflare", "industry": "infra", "title": "How we built DMARC Management using Cloudflare Workers", "date": "2023-03-17", "primary_problem": "scale_ingestion", "problems": ["storage_formats", "platform"], "post_type": "case_study", "level": "intermediate", "stack": ["Cloudflare Workers", "Email Routing", "Workers KV", "R2", "Workers Analytics Engine", "D1", "workerd", "Cap'n Proto", "postal-mime", "fast-xml-parser", "pako", "unzipit"], "scale": "Unbounded number of DMARC report emails across many domains; no volume stated", "key_decisions": ["Process inbound report emails in an Email Worker instead of running mail servers, trading control over the runtime for serverless scalability", "Store raw compressed reports in R2 for reprocessing while pushing parsed fields to Workers Analytics Engine for dashboard queries, separating archival from query workloads", "Key per-domain configuration in Workers KV by RUA address, which gives fast lookups but is eventually consistent and suited to read-heavy metadata"], "summary": "Cloudflare built a DMARC report ingestion service on Cloudflare Workers: an Email Worker receives report emails, extracts and decompresses XML attachments, archives the raw files in R2, and writes parsed fields to Workers Analytics Engine for dashboard queries. The post is largely a product walkthrough of platform primitives with little on volumes or operational tradeoffs.", "interview_angle": "How would you ingest an unbounded stream of small inbound emails with attachments, route each to a per-tenant config, archive raw payloads for reprocessing, and expose aggregated analytics with serverless components?", "score": 1.1385, "hn_points": 15, "hn_comments": 2}, {"url": "https://netflixtechblog.com/democratizing-machine-learning-at-netflix-building-the-model-lifecycle-graph-5cc6d5828bb1", "company": "Netflix", "industry": "media", "title": "Democratizing Machine Learning at Netflix: Building the Model Lifecycle Graph", "date": "2026-05-04", "primary_problem": "lineage_catalog", "problems": ["platform", "ml_data"], "post_type": "deep_dive", "level": "advanced", "stack": ["Kafka", "AWS SNS", "AWS SQS", "Datomic", "Elasticsearch"], "scale": "", "key_decisions": ["Thin event notifications followed by hydration from source-of-truth APIs: simpler producers and resilience to reordering, at the cost of extra read load on source systems", "Datomic as graph store and cache for reified relationships, with asynchronous enrichment jobs inferring cross-system edges: flexible graph traversal, but relationships appear with a delay of minutes", "Elasticsearch for free-text discovery on a unified entity index alongside graph navigation: fast search entry point, with a near-real-time index that can lag the graph"], "summary": "Netflix's AI Platform team built a Metadata Service that ingests events from ML tooling (pipelines, model registry, experimentation, feature store, datasets, identity) and hydrates them from source APIs into a normalized entity model. The service stores entities and inferred relationships in a Datomic graph and indexes them in Elasticsearch so practitioners can search, trace lineage and assess impact of models and features across domains.", "interview_angle": "How would you design a metadata graph that unifies lineage and impact analysis across many heterogeneous source systems, and how do you handle eventual consistency and out-of-order events?", "score": 1.1383, "hn_points": 0, "hn_comments": 0}, {"url": "https://shopify.engineering/building-commerce-data-models-with-shopifyql", "company": "Shopify", "industry": "ecommerce", "title": "ShopifyQL Notebooks: Simplifying Querying with Commerce Data Models", "date": "2023-02-14", "primary_problem": "modeling", "problems": ["performance", "platform"], "post_type": "case_study", "level": "intermediate", "stack": ["ShopifyQL", "BigQuery", "Trino", "Google Sheets"], "scale": "", "key_decisions": ["Organize the commerce data model around business questions and a single row grain, trading some flexibility for an opinionated, easy-to-explore model", "Use fully additive metrics where possible so users can aggregate across any dimension, while accepting that semi-additive and non-additive metrics need care", "Switch the products model from full-drop rebuilds to incremental builds and pre-roll older daily data into summary tables, trading higher pipeline maintenance for faster builds and queries"], "summary": "Shopify describes how it designs commerce data models that power ShopifyQL Notebooks, a self-serve analytics tool for merchants. The post walks through a six-step process covering business questions, mock data, upstream discovery, quality, freshness, and build and query performance, illustrated with the products model.", "interview_angle": "How would you design a self-serve analytics data model for non-technical users so it stays at a consistent grain, supports additive metrics, and still returns quickly for very large merchants?", "score": 1.1325, "hn_points": 3, "hn_comments": 0}, {"url": "https://engineering.grab.com/graph-networks", "company": "Grab", "industry": "mobility", "title": "Graph Networks - Striking fraud syndicates in the dark", "date": "2022-04-28", "primary_problem": "ml_data", "problems": ["platform", "realtime"], "post_type": "case_study", "level": "intermediate", "stack": ["AWS Neptune"], "scale": "Graph database with over 1 billion nodes", "key_decisions": ["Build a graph database platform with over a billion nodes to surface connections between accounts that flat rule-based checks miss, trading extra infrastructure for better syndicate detection", "Expose network-based features through a configurable system so engineers can tune ML features without redeploying, at the cost of added configuration complexity", "Use graph neural networks for fraud and money laundering detection rather than hand-built rules, accepting heavier model training and explainability work"], "summary": "Grab's Integrity team describes a graph-based prediction platform for detecting fraud syndicates, including a graph database with over a billion nodes, graph visualisation tools for risk analysts, a network-based feature system, and GNN models. The post is an overview introducing a series, so it covers architecture at a high level without deep implementation detail.", "interview_angle": "How would you design a graph-backed feature system that serves real-time fraud scoring over a billion-node entity graph while letting analysts explore connections interactively?", "score": 1.1319, "hn_points": 0, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/how-we-made-our-dns-stack-3x-faster", "company": "Cloudflare", "industry": "infra", "title": "How we made our DNS stack 3x faster", "date": "2017-04-11", "primary_problem": "migration", "problems": ["storage_formats", "performance"], "post_type": "case_study", "level": "advanced", "stack": ["Go", "MessagePack", "Protocol Buffers", "miekg/dns", "tinylib/msgp", "PowerDNS"], "scale": "~1 million DNS queries/sec; 100M+ resource records; changes to 5+ zones/sec; 6M+ zones; >100 PoPs", "key_decisions": ["Regrouped DNS records from one key per resource record into RRSet and single-address keys, cutting KV round trips per query at the cost of a more complex write path", "Switched the edge serialization from mixed JSON/Protobuf to MessagePack with generated code, avoiding a duplicated schema but losing a language-agnostic schema contract", "Migrated zones gradually with parallel old and new systems and whole-zone answer comparison, trading a slower rollout for easy rollback and no customer-visible cutover"], "summary": "Cloudflare replaced its DNS record data model and the pipeline that pushes zone changes from a central database to edge KV stores in over 100 PoPs. The redesign grouped records by RRSet, moved to MessagePack, and cut edge storage about 9x while averaging 3x faster query handling, with zones migrated gradually in parallel with the old system.", "interview_angle": "How would you redesign a config-distribution pipeline so edge nodes need fewer KV lookups per request, and how would you migrate millions of entities with rollback safety and no downtime?", "score": 1.1269, "hn_points": 15, "hn_comments": 0}, {"url": "https://dropbox.tech/infrastructure/meet-chrono-our-scalable-consistent-metadata-caching-solution", "company": "Dropbox", "industry": "saas", "title": "Meet Chrono, our scalable, consistent, metadata caching solution", "date": "2024-07-25", "primary_problem": "performance", "problems": ["quality", "scale_ingestion"], "post_type": "deep_dive", "level": "advanced", "stack": ["Panda", "Chrono", "Memcache", "TLA+", "Edgestore"], "scale": "High-volume metadata read QPS; exact figures not stated", "key_decisions": ["Build a separate timestamp-tracking service (Chrono) instead of weaker cache invalidation, keeping read-after-write guarantees without changing client code; trade-off is an extra service on the write and read path.", "Use Attempt-before-write with a max permitted commit timestamp so cached entries can be validated against a persisted upper bound; trade-off is a few seconds of cache staleness window and added latency on writes.", "Decouple the cache (Memcache) from the attempt-tracking service so each scales independently; trade-off is hashed slots that alias unrelated keys in exchange for bounded memory."], "summary": "Dropbox built Chrono, a consistency-aware caching layer on top of its Panda MVCC key-value store, to absorb high read QPS on metadata while preserving read-after-write semantics. Chrono tracks the latest write-attempt timestamp per key, and clients use it to decide whether a Memcache entry is still safe to serve.", "interview_angle": "How would you add a lossy read cache in front of a strongly consistent store without serving stale data after writes, and what happens when the writer crashes between storage and cache updates?", "score": 1.1229, "hn_points": 3, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/building-vectorize-a-distributed-vector-database-on-cloudflare-developer-platform", "company": "Cloudflare", "industry": "infra", "title": "Building Vectorize, a distributed vector database, on Cloudflare\u2019s Developer Platform", "date": "2024-10-22", "primary_problem": "storage_formats", "problems": ["performance", "ml_data"], "post_type": "deep_dive", "level": "advanced", "stack": ["Cloudflare Workers", "R2", "Durable Objects", "SQLite", "Cloudflare Queues", "Cloudflare Cache", "Rust"], "scale": "Up to 5 million vectors per index, up to 1536 dimensions, batches of up to 200,000 vectors", "key_decisions": ["Store IVF index files and versioned manifests on R2 with a single root manifest pointer, so commits are atomic and readers get immutable snapshots, at the cost of eventual consistency for writes", "Use a Durable Object SQLite WAL as coordinator and delegate heavy index updates to pooled executors, which keeps the coordinator small but adds queue-based orchestration and fencing of stalled executors", "Batch pending writes adaptively (up to 200,000 vectors or 1,000 blocks) rather than pausing to collect them, trading per-write latency for much higher ingestion throughput"], "summary": "Cloudflare describes how Vectorize, a globally distributed vector database, uses IVF indexing and product quantization stored as versioned snapshots on R2. Writes flow through a Durable Object SQLite write-ahead log that coordinates pooled executors, batches updates adaptively, and commits by atomically swapping a root manifest.", "interview_angle": "Design an append-and-commit write path for a file-based index on object storage: how do you get atomic visibility, snapshot reads, safe retries from stalled workers, and throughput via batching?", "score": 1.1195, "hn_points": 1, "hn_comments": 1}, {"url": "https://www.capitalone.com/tech/software-engineering/batch-to-real-time-with-change-data-capture", "company": "Capital One", "industry": "fintech", "title": "Change Data Capture: From Batch to Real-Time | Capital One", "date": "2021-03-16", "primary_problem": "cdc_sync", "problems": ["realtime", "platform"], "post_type": "deep_dive", "level": "intermediate", "stack": ["Kafka", "Debezium", "AWS DMS", "Kinesis", "Kafka Connect", "MySQL", "PostgreSQL", "MongoDB", "SQL Server", "Oracle"], "scale": "", "key_decisions": ["Use CDC on existing batch-oriented applications rather than designing new services around database-published events; CDC adds latency and carries source-schema coupling, but lets consumers migrate incrementally.", "Choose Debezium over AWS DMS (or vice versa) based on database support, stream target preference, and need for initial full load; Debezium's Kafka Connect route decouples producer and consumer while its embedded engine is simpler but couples them.", "Use Kafka as a retained event log for replay and event sourcing, accepting the need for snapshot events and consumers that rebuild current state from history."], "summary": "The article explains how change data capture reads database transaction logs and streams row-level changes to consumers, positioning it as a way to move batch-oriented financial applications toward real-time microservices. It compares Debezium and AWS DMS on operating model, database support, and stream integration, and gives guidance on when CDC fits versus building events directly in services.", "interview_angle": "How would you replace a nightly batch extract from a monolithic core database with near-real-time change events for downstream consumers, and what trade-offs would you weigh between a managed CDC service and an open-source connector?", "score": 1.1174, "hn_points": 0, "hn_comments": 0}, {"url": "https://dropbox.tech/machine-learning/architecture-of-nautilus-the-new-dropbox-search-engine", "company": "Dropbox", "industry": "saas", "title": "Architecture of Nautilus, the new Dropbox search engine", "date": "2018-09-27", "primary_problem": "scale_ingestion", "problems": ["realtime", "platform"], "post_type": "deep_dive", "level": "advanced", "stack": ["Apache Tika", "Kafka", "Octopus"], "scale": "Hundreds of billions of pieces of content; 500M+ registered users; tens of thousands of processes on more than a thousand hosts", "key_decisions": ["Hybrid indexing: periodic offline full index builds (about every 3 days) plus near-real-time mutations (seconds) via Kafka, trading freshness complexity for completeness and simpler reprocessing", "Store extracted content in a document store with one column per extractor, enabling parallel independent updates but adding a layer of access control and encryption to manage", "Separate retrieval (tuned for recall) from ML ranking (tuned for precision), letting each be optimized independently at the cost of an extra serving hop and latency budget (500ms p95)"], "summary": "Dropbox describes Nautilus, its new full-text search engine, which combines periodic offline index rebuilds with near-real-time index mutations applied through Kafka. The architecture separates document extraction, offline indexing, a sharded retrieval engine, and an ML ranking orchestrator that also handles ACL checks and shadow traffic.", "interview_angle": "How would you design a search index over hundreds of billions of access-controlled documents that stays fresh within seconds while supporting safe rebuilds and experimentation?", "score": 1.1141, "hn_points": 0, "hn_comments": 0}, {"url": "https://shopify.engineering/build-experiment-pipeline-from-scratch", "company": "Shopify", "industry": "ecommerce", "title": "How to Build an Experiment Pipeline from Scratch", "date": "2020-10-15", "primary_problem": "modeling", "problems": ["platform", "quality"], "post_type": "case_study", "level": "intermediate", "stack": ["Spark", "Verdict"], "scale": "", "key_decisions": ["Built a three-stage pipeline (experiment definition files, many-to-one union, filtering) so multiple data scientists can ship experiments in parallel, at the cost of enforcing a shared output contract across definitions.", "Randomized at the shop grain but exposed results via the primary email, and excluded shops sharing an email, trading some sample size for avoiding cross-contamination.", "Enforced a 30-day cross-experiment exclusion window with a manual override for high-risk tests, trading experiment throughput for cleaner controlled variables."], "summary": "Shopify built an email experimentation pipeline in PySpark because its existing Verdict framework could not randomize email recipients. The pipeline handles eligibility criteria, ongoing randomization, exclusion of overlapping experiments and linked shops, and backfills of past experiments.", "interview_angle": "How would you design a randomization pipeline that prevents cross-contamination between concurrent experiments when units map many-to-many to contacts?", "score": 1.1119, "hn_points": 0, "hn_comments": 0}, {"url": "https://engineering.fb.com/2026/11/03/ml-applications/f3-lightning-how-meta-accelerates-ads-ml-features-to-production", "company": "Meta", "industry": "social", "title": "F3 Lightning: How Meta Accelerates Ads ML Features to Production at Scale", "date": "2026-11-03", "primary_problem": "ml_data", "problems": ["platform", "performance"], "post_type": "deep_dive", "level": "advanced", "stack": ["F3", "Meta Ads ML feature platform"], "scale": "More than 20,000 features per ads ranking request; comparable features reach production ~3.6x faster", "key_decisions": ["Compile each feature into its own independently releasable configuration rather than one merged graph, trading away cross-feature release batching for isolated, faster releases", "Recover shared-computation efficiency at service startup via stable content-derived identifiers, one deduplicated execution plan, and a flattened ordered list, adding startup complexity to keep per-request cost flat", "Use one shared per-request memory buffer with reference-based sharing and dense integer slots, trading a small amount of copy simplicity for fewer cache misses and lookups"], "summary": "Meta describes F3 Lightning, a layer on its ads ML feature framework that decouples feature releases so each feature compiles, validates, ships and rolls back independently. It preserves the efficiency of the earlier merged DAG by deduplicating work at startup, using stable identifiers, a single execution plan, a shared memory buffer and dense index mapping.", "interview_angle": "How would you let thousands of independently owned feature definitions ship separately from a shared computation graph without losing deduplication and per-request efficiency?", "score": 1.1094, "hn_points": 1, "hn_comments": 0}, {"url": "https://www.capitalone.com/tech/software-engineering/dynamodb-streams-lambda-pattern-best-practices", "company": "Capital One", "industry": "fintech", "title": "DynamoDB Lambda Pattern: Best Practices | Capital One Tech", "date": "2025-11-06", "primary_problem": "cdc_sync", "problems": ["realtime", "scale_ingestion"], "post_type": "deep_dive", "level": "intermediate", "stack": ["DynamoDB", "DynamoDB Streams", "AWS Lambda", "Kinesis Data Streams", "EventBridge", "Flink", "Amazon Data Firehose", "Kafka", "AWS DMS", "CloudWatch", "SQS"], "scale": "", "key_decisions": ["Use Lambda directly on DynamoDB Streams for simple CDC versus Kinesis or Flink for higher throughput and multiple consumers; trade simplicity for fan-out and latency.", "Accept per-shard ordering and hot-shard bottlenecks inherent to DynamoDB Streams versus fanning out work inside Lambda, which can break ordering guarantees.", "Offload failed records to SQS or a DLQ after limited Lambda retries to avoid backlog on hot shards, trading operational complexity for data safety."], "summary": "The author examines the DynamoDB Streams plus Lambda pattern for CDC and lists production pitfalls: Lambda concurrency limits tied to shards, hot shards that DynamoDB does not split, ordering constraints, retry and DLQ handling, and cost. The post closes with a use-case table comparing DynamoDB Streams with Lambda, Kinesis, EventBridge, MSK and Flink for different latency and fan-out needs.", "interview_angle": "How would you design CDC from a high-write DynamoDB table to multiple downstream consumers while handling hot shards, ordering, and failed records?", "score": 1.1069, "hn_points": 0, "hn_comments": 0}, {"url": "https://www.coinbase.com/blog/developing-databricks-ci-cd-at-coinbase", "company": "Coinbase", "industry": "fintech", "title": "Developing Databricks CI/CD at Coinbase", "date": "2023-06-05", "primary_problem": "platform", "problems": ["realtime", "quality"], "post_type": "case_study", "level": "advanced", "stack": ["Databricks", "Temporal", "Pants", "Kafka", "Spark", "GitHub", "Slack", "PagerDuty"], "scale": "", "key_decisions": ["Blue-green job submission for streaming jobs: runs old and new versions side by side so there is no processing gap, at the cost of duplicate compute during the health window", "Distributed lock plus streaming checkpoint table so only one job version persists output; this avoids duplicate writes but adds a coordination service to operate", "Declarative YAML and Pants BUILD targets hide Databricks specifics from users, trading flexibility for consistency and easier auto-deployment"], "summary": "Coinbase describes an internal CI/CD platform for deploying Databricks compute tasks, with CI building artifacts such as wheels and JARs and a CD layer that submits jobs through Temporal workflows. The standout piece is a blue-green submission strategy for streaming jobs that uses a distributed lock and a checkpoint table so the new job version takes over only after it catches up.", "interview_angle": "How would you deploy a streaming job update with zero data gap and no duplicate writes? Walk through running old and new versions in parallel, checkpoint-based catch-up, and lock-based handoff.", "score": 1.1019, "hn_points": 0, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/quicksilver-v2-evolution-of-a-globally-distributed-key-value-store-part-1", "company": "Cloudflare", "industry": "infra", "title": "Quicksilver v2: evolution of a globally distributed key-value store (Part 1)", "date": "2025-07-10", "primary_problem": "storage_formats", "problems": ["cost", "cdc_sync"], "post_type": "deep_dive", "level": "advanced", "stack": ["RocksDB", "ClickHouse", "Consul"], "scale": "Dozens of root servers with terabytes of storage; about 5 billion keys in one instance; proxy working sets about 20% of keyspace in large data centers and about 1% in small ones", "key_decisions": ["Split replicas and persistent proxy caches instead of full copies on every node, cutting disk use up to about 50% at the cost of cache-miss latency to replicas", "Use MVCC column family with a two-hour history window in RocksDB to give proxies consistent reads during asynchronous replication, trading extra disk (~500 MB) for correctness", "Keep all keys on proxies but drop values for uncached entries, preserving Bloom filter speed for negative lookups while avoiding the larger memory cost of Cuckoo filters"], "summary": "Cloudflare redesigned its Quicksilver key-value store so that small data centers hold a few full replicas and many proxies that keep only a persistent on-disk cache of hot keys. The post covers the consistency problems this creates (MVCC for lagging proxies, a sliding window for leading ones), negative-lookup handling with key/value separation, and replica discovery via the Network Oracle.", "interview_angle": "How would you reduce disk usage of a globally replicated store without hurting latency or sequential consistency, and how do you handle a cache that lags or leads asynchronous replicas?", "score": 1.1008, "hn_points": 0, "hn_comments": 0}, {"url": "https://shopify.engineering/mysql-database-shard-balancing-terabyte-scale", "company": "Shopify", "industry": "ecommerce", "title": "Shard Balancing: Moving Shops Confidently with Zero-Downtime at Terabyte-scale", "date": "2021-09-24", "primary_problem": "migration", "problems": ["cdc_sync", "scale_ingestion"], "post_type": "deep_dive", "level": "advanced", "stack": ["MySQL", "Ghostferry", "Redis", "Memcached"], "scale": "Millions of merchants across a fleet of MySQL shards; no specific volume stated", "key_decisions": ["Copy data with batched transactions plus binlog tailing so the shop stays online, trading extra write-lock complexity for near-zero downtime", "Use a Redis-backed multi-reader-single-writer lock to freeze writes only during cutover, accepting a short write pause and possible move failure if the lock is not acquired in time", "Update the unsharded routing table as the commit point, then verify and prune the source copy, trading temporary duplicate storage for a safe rollback window"], "summary": "Shopify describes how it rebalances MySQL shards by moving individual shops between pods without visible downtime, using its open-source Ghostferry tool to batch-copy rows and tail the binlog. The cutover is guarded by an application-level reader-writer lock and a routing table update, followed by verification and pruning of stale source data.", "interview_angle": "How would you move a tenant's rows between sharded databases while the tenant keeps serving traffic, guaranteeing no lost writes during the brief cutover?", "score": 1.0962, "hn_points": 0, "hn_comments": 0}, {"url": "https://www.capitalone.com/tech/software-engineering/introduction-to-testing-with-data-build-tool", "company": "Capital One", "industry": "fintech", "title": "An Introduction to Testing with Data Build Tool | Capital One", "date": "2022-04-27", "primary_problem": "quality", "problems": ["modeling", "platform"], "post_type": "deep_dive", "level": "intermediate", "stack": ["dbt", "SQL", "Jinja"], "scale": "", "key_decisions": ["Co-locate data tests with model code in dbt so tests change in the same commit as logic, trading away the freedom to choose independent test frameworks", "Use schema tests for single-record checks and SQL data tests for multi-record or cross-model checks, which is flexible but puts test cost on query runs", "Build reusable Jinja macros and versioned packages for shared transformations, centralizing logic at the cost of coupling projects to a common package version"], "summary": "The post argues that separating transformation code from its data quality tests causes drift and false failures, and proposes dbt as a way to keep tests in the same repo and commit as models. It explains dbt's core pieces (models, macros, schema and data tests, packages) and how ephemeral CTE models enable finer-grained testing.", "interview_angle": "How would you design a data quality testing workflow so that test logic and transformation logic cannot drift apart across commits, and what trade-offs come with embedding tests in the transformation tool?", "score": 1.0959, "hn_points": 0, "hn_comments": 0}, {"url": "https://dropbox.tech/machine-learning/bringing-ai-powered-answers-and-summaries-to-file-previews-on-the-web", "company": "Dropbox", "industry": "saas", "title": "Bringing AI-powered answers and summaries to file previews on the web", "date": "2024-07-11", "primary_problem": "ml_data", "problems": ["cost", "performance"], "post_type": "case_study", "level": "advanced", "stack": ["Riviera", "LLM", "k-means clustering"], "scale": "2.5 billion file conversion requests per day (~1 exabyte/day), ~300 file types", "key_decisions": ["Compute embeddings and AI responses in real time rather than precomputing, so only user-selected files are sent to the LLM; trades latency per request for privacy and no wasted compute on unused requests", "Treat embeddings, summaries and Q&A as cacheable conversions inside the Riviera pipeline so summary and Q&A share transcripts and embeddings; trades cache storage for fewer LLM calls", "Use k-means clustering to pick diverse chunks for summaries instead of map-reduce summary-of-summaries; improves topic coverage and reduces hallucination risk but adds clustering work per file"], "summary": "Dropbox describes how it extends its Riviera file-conversion pipeline to produce text, chunked embeddings, and then LLM-driven summaries and Q&A for file previews, including multi-file support. The post highlights chunk selection via k-means clustering and a power-law-based cutoff to choose how much context to send, plus caching that cut cost per summary by 93% and p75 latency from 115s to 4s.", "interview_angle": "How would you design a pipeline that converts arbitrary file types to text and embeddings at massive scale, with caching of intermediate stages so multiple LLM features can reuse work while keeping per-request latency low?", "score": 1.0926, "hn_points": 0, "hn_comments": 0}, {"url": "https://eng.lyft.com/a-federated-approach-to-providing-user-privacy-rights-3d9ab73441d9", "company": "Lyft", "industry": "mobility", "title": "A Federated Approach To Providing User Privacy Rights", "date": "2022-09-07", "primary_problem": "governance_privacy", "problems": ["lineage_catalog", "cost"], "post_type": "deep_dive", "level": "advanced", "stack": ["DynamoDB", "Hive", "protobuf"], "scale": "", "key_decisions": ["Federated erasure/export design with a central orchestrator instead of a centralized deletion system: teams own their data lifecycle, but cross-service consistency depends on each team's integration", "Asynchronous state machine with sanction endpoints and a wait period before deletion: allows holds and transaction reconciliation, at the cost of longer end-to-end deletion latency", "Cron-based self-healing sweep plus idempotent retries: improves reliability for stuck requests, but adds an extra scanning component to operate"], "summary": "Lyft describes a federated architecture for fulfilling privacy rights such as CCPA data export and deletion, with a central orchestrator driving an asynchronous state machine that calls into each owning service. The post also covers a central datastore catalog, retention annotations that generate TTL code, and a client library that lets teams plug into erasure flows.", "interview_angle": "How would you design a system that deletes or exports a user's data across many microservices and datastores reliably, including holds for legal reasons and retries after partial failures?", "score": 1.0904, "hn_points": 0, "hn_comments": 0}, {"url": "https://www.capitalone.com/tech/software-engineering/active-active-shared-nothing-database-architecture", "company": "Capital One", "industry": "fintech", "title": "Active-Active Shared-Nothing Database Architecture | Capital One", "date": "2020-10-14", "primary_problem": "storage_formats", "problems": ["platform", "quality"], "post_type": "deep_dive", "level": "advanced", "stack": ["Oracle Real Application Clusters"], "scale": "", "key_decisions": ["Active-active shared-nothing database replication removes brown-out downtime but introduces write conflicts that the application must resolve, trading availability for data accuracy.", "Asynchronous replication is preferred over synchronous because synchronous commits are expensive across regions and slow applications, accepting brief brown-outs instead.", "Choosing AASN per datastore type: suitable for caches, static content and session state, but unsuitable for systems of record, with conflict resolution strategies (last writer, timestamp, locality or application weight) each carrying accuracy costs."], "summary": "This Capital One article, written as a narrative, explains when active-active shared-nothing database architectures across regions are viable versus when they risk conflicts and silent data corruption. It contrasts this with active-passive setups, covers CAP trade-offs and conflict resolution methods, and maps five application patterns to datastore types.", "interview_angle": "How would you design a multi-region database tier for high availability, and which datastore types could safely accept writes in both regions without conflict resolution?", "score": 1.0903, "hn_points": 0, "hn_comments": 0}, {"url": "https://discord.com/blog/how-discord-automates-scylladb-clusters-at-scale", "company": "Discord", "industry": "social", "title": "How Discord Automates ScyllaDB Clusters at Scale", "date": "2026-05-08", "primary_problem": "platform", "problems": ["quality", "performance"], "post_type": "deep_dive", "level": "advanced", "stack": ["ScyllaDB", "Rust", "YAML", "SQLite", "Prometheus", "Discord webhooks"], "scale": "30-node cluster rolling restarts (two-hour operations)", "key_decisions": ["Declarative YAML workflows instead of Rust code, so retries, concurrency and timeouts can be tuned without redeploying the binary, at the cost of a custom DSL to learn and maintain", "Per-job SQLite state for resumability, skipping completed tasks after interruption; chosen over distributed state for operational simplicity, accepting limited scalability", "Zone-based concurrency grouping with per-batch node limits to avoid quorum loss, trading slower rolling operations for safety"], "summary": "Discord describes the Scylla Control Plane (SCP), which automates multi-node ScyllaDB cluster operations using tasks, YAML-defined workflows and jobs. The design emphasizes idempotent tasks, explicit condition checks between steps, resumable jobs backed by SQLite, and classification of recoverable versus unrecoverable errors.", "interview_angle": "How would you design an orchestrator for rolling maintenance on a distributed database so that it is resumable after failures, respects zone-level fault domains, and halts safely on unsafe state?", "score": 1.0816, "hn_points": 3, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/cloudflare-r2-mosaicml-train-llms-anywhere-faster-cheaper", "company": "Cloudflare", "industry": "infra", "title": "Cloudflare R2 and MosaicML enable training LLMs on any compute, anywhere in the world, with zero switching costs", "date": "2023-05-16", "primary_problem": "ml_data", "problems": ["cost", "storage_formats"], "post_type": "case_study", "level": "advanced", "stack": ["Cloudflare R2", "MosaicML", "StreamingDataset", "Composer", "PyTorch", "AWS S3 API", "MCLI"], "scale": "Training datasets in terabytes to petabytes; LLM checkpoints hundreds of GB each", "key_decisions": ["Store training data and checkpoints in zero-egress object storage (R2) so jobs can move across clouds, trading some dependence on a single storage vendor for flexibility", "Stream data from object storage with StreamingDataset (shuffled, deterministic shards) instead of a shared file system, avoiding EFS/NFS cost but relying on network throughput", "Use asynchronous checkpoint uploads and resumable data loading so training can pause and resume on different GPUs without losing determinism"], "summary": "The post shows how MosaicML's StreamingDataset and Composer libraries can read training data and write checkpoints directly to Cloudflare R2 object storage. Because R2 charges no egress fees, a training run can be paused and resumed across different cloud GPU providers without data transfer costs.", "interview_angle": "How would you design a training data pipeline that streams petabytes from object storage to thousands of GPUs while staying deterministic and resumable, and how does egress pricing shape where you store data?", "score": 1.0806, "hn_points": 4, "hn_comments": 0}, {"url": "https://engineering.zalando.com/posts/2022/06/accelerate-apache-airflow-testing-through-dag-versioning.html", "company": "Zalando", "industry": "ecommerce", "title": "Accelerate testing in Apache Airflow through DAG versioning", "date": "2022-06-09", "primary_problem": "platform", "problems": ["migration", "quality"], "post_type": "deep_dive", "level": "advanced", "stack": ["Airflow", "Databricks", "Spark", "Hive", "S3", "Amazon MWAA", "zFlow", "GitHub"], "scale": "Environment creation under 1 minute on a shared Airflow server, versus up to 30 minutes for a new MWAA server", "key_decisions": ["Reuse one Airflow server with per-branch environments instead of spinning up a new server per pull request: much faster and cheaper, but requires patching Airflow's DAG class and handling id collisions.", "Use Airflow's packaged DAG zip feature per branch for dependency isolation: clean separation, but Jinja template paths break inside zips and need an extra unpacked copy.", "Create data environments as views pointing at test tables instead of copying data: saves time and storage, but only read-through access and copies are needed only for outputs needing seed data."], "summary": "Zalando's Performance Marketing team describes how they run multiple isolated versions of their marketing ROI Airflow pipeline on one shared server, with each branch getting its own DAG namespace and a matching Spark/Hive data environment built from DDLs. Environments are created in under a minute and cleaned up automatically when pull requests close, letting teams test end-to-end without blocking each other.", "interview_angle": "How would you let several teams test changes to a shared batch pipeline end-to-end in parallel, covering both orchestrator isolation and data-level isolation without copying full datasets?", "score": 1.0806, "hn_points": 0, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/understand-the-impact-of-your-waiting-rooms-settings-with-waiting-room-analytics", "company": "Cloudflare", "industry": "infra", "title": "Understand the impact of Waiting Room settings with Waiting Room Analytics", "date": "2023-06-07", "primary_problem": "realtime", "problems": ["scale_ingestion", "performance"], "post_type": "deep_dive", "level": "advanced", "stack": ["Cloudflare Workers", "Durable Objects", "Workers KV", "ClickHouse", "Workers Analytics Engine", "HdrHistogram", "GraphQL"], "scale": "Per-minute aggregated analytics per waiting room, retained 30 days, 5,000 histogram points per minute limit", "key_decisions": ["Aggregate per-user metrics into minute buckets at each data center rather than writing raw per-request events, trading raw granularity for less noise and alignment with routing decisions", "Store time-in-queue and time-on-origin as HdrHistograms that can be merged across nodes, since summing percentiles across workers is mathematically wrong; this adds complexity in the aggregation path", "Use Adaptive Bit Rate sampling (100%, 10%, 1% resolutions) at query time so long ranges stay responsive, trading exact values over long windows for consistent latency"], "summary": "Cloudflare describes how it built Waiting Room Analytics on its distributed edge, reusing the existing routing aggregation pipeline to emit per-minute metrics into ClickHouse. The design uses mergeable HdrHistograms for wait-time percentiles and adaptive resolution sampling so 30-day queries stay fast.", "interview_angle": "How would you collect and aggregate metrics from many distributed edge nodes into a central store while keeping percentiles correct and queries fast over long time ranges?", "score": 1.08, "hn_points": 0, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/r2-rayid-retrieval", "company": "Cloudflare", "industry": "infra", "title": "Indexing millions of HTTP requests using Durable Objects", "date": "2022-11-15", "primary_problem": "storage_formats", "problems": ["performance", "cost"], "post_type": "deep_dive", "level": "advanced", "stack": ["Cloudflare Workers", "Durable Objects", "R2", "Logpush", "Streams API"], "scale": "Millions of logs per customer in batches on R2; roughly one batch per second per zone (~86,400 batches/day)", "key_decisions": ["Use a forward index (batch name to list of RayIDs) in Durable Object storage instead of a full database, trading query flexibility for zero infrastructure to run", "Stream gzip-compressed batches from R2 through TransformationStreams in chunks to avoid Worker out-of-memory errors, at the cost of more complex code", "Encode time into batch naming and RayID prefix so lookups only check a few candidate batches, relying on an observed assumption that 95% of RayIDs land within five minutes, which may break if RayID format changes"], "summary": "Cloudflare describes an R2 Log Retrieval API that builds a forward index of RayIDs per stored log batch using Durable Objects as transactional key-value storage. Batches are stream-decompressed and parsed in chunks to avoid memory limits, and time-encoded names narrow lookups to a few candidate batches.", "interview_angle": "How would you design a lookup index over millions of compressed log files in object storage without running a database, and how would you bound the search space using time encoded in identifiers?", "score": 1.0714, "hn_points": 0, "hn_comments": 0}, {"url": "https://shopify.engineering/sidekick-curation", "company": "Shopify", "industry": "ecommerce", "title": "Teaching Sidekick to say no: automated data curation with LLM judge consensus", "date": "2026-06-15", "primary_problem": "quality", "problems": ["ml_data"], "post_type": "case_study", "level": "advanced", "stack": ["Sidekick", "Toloka", "Frontier LLMs"], "scale": "Tens of thousands of production queries; ~600 seed standard queries plus 602 refusal annotations", "key_decisions": ["Use a four-model LLM judge ensemble with unanimous agreement on label and reasoning; trade coverage for precision by sending disagreements to humans", "Calibrate judges with few-shot examples from a small human-annotated seed set rather than merging conflicting labels directly; trade seed-quality dependence for scalable labeling", "Define mutually exclusive refusal taxonomy (solvable with context, missing capability, wrong skill, ambiguous) to avoid judge disagreement and downstream label inconsistency"], "summary": "Shopify addressed a training-data blind spot in Sidekick's customer segmentation skill: production logs contain only successful queries, so the model never learned to refuse impossible requests. They used a small human-labeled seed set to calibrate a panel of frontier LLM judges that resolve label conflicts under a strict unanimity gate, and fed new production traffic back into each fine-tuning cycle as a data flywheel.", "interview_angle": "How would you curate training data when production logs only contain successes? Discuss using an LLM-judge ensemble with consensus gating, seed-based calibration, and a feedback loop, and the precision-vs-coverage trade-off.", "score": 1.0706, "hn_points": 0, "hn_comments": 0}, {"url": "https://engineering.grab.com/graph-service-platform", "company": "Grab", "industry": "mobility", "title": "Graph service platform", "date": "2023-01-05", "primary_problem": "platform", "problems": ["scale_ingestion", "realtime"], "post_type": "case_study", "level": "intermediate", "stack": ["S3", "Amazon Neptune", "DynamoDB", "Kafka", "Confluent", "Gremlin"], "scale": "", "key_decisions": ["Wrap graph databases behind a PaaS-style graph service with RESTful APIs, trading flexibility for simpler use by fraud teams", "Route all access through the graph service so Neptune is never hit directly, adding a hop but controlling load and schema validation", "Ingest via batch CSV loads from S3 and Kafka streams, using Kafka to absorb write pressure on Neptune at the cost of added pipeline complexity"], "summary": "Grab describes a graph service platform that wraps Amazon Neptune and DynamoDB behind RESTful APIs so GrabDefence teams can load and query linked fraud data without managing graph infrastructure. Data arrives through S3 CSV batch loads with schema checks, or through Kafka streams that relieve write pressure on the graph database.", "interview_angle": "How would you design a managed graph service for fraud detection that supports both batch loads and streaming writes while protecting the graph database from write overload?", "score": 1.0696, "hn_points": 0, "hn_comments": 0}, {"url": "https://engineering.zalando.com/posts/2017/11/running-kafka-streams-applications-aws.html", "company": "Zalando", "industry": "ecommerce", "title": "Zalando Engineering Blog - Running Kafka Streams applications in AWS", "date": "2017-11-30", "primary_problem": "realtime", "problems": ["performance", "platform"], "post_type": "deep_dive", "level": "advanced", "stack": ["Kafka Streams", "Kafka", "RocksDB", "AWS EBS", "AWS EC2", "Amazon CloudWatch", "Prometheus", "Dropwizard Metrics", "Remora", "Zookeeper", "S3"], "scale": "Kafka Streams instances on M4.large with 4GB JVM heap; about 200MB state per partition in RocksDB", "key_decisions": ["Provisioned much larger EBS volumes on GP2 to gain baseline IOPS and faster burst-balance replenishment, trading extra storage cost for stable RocksDB I/O", "Added a per-record processing timeout and lowered max.poll.records so that slow records do not exceed the consumer poll interval and trigger endless rebalances, at the cost of possibly skipping or failing edge-case records", "Kept GP2 over provisioned IOPS (IO1) for cost reasons, and kept JVM heap modest so RocksDB off-heap memory fits in instance RAM"], "summary": "Zalando describes operating Kafka Streams applications on AWS, focusing on how EBS burst-credit exhaustion caused RocksDB state store slowdowns and how rebalancing from long-running records was mitigated. They also outline monitoring choices, including a custom consumer lag tool, JVM heap, and host-level metrics.", "interview_angle": "How would you run stateful stream processing with local RocksDB state on cloud VMs, and what signals would you monitor to detect I/O throttling, rebalance storms, and consumer lag?", "score": 1.0663, "hn_points": 0, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/intelligent-automatic-restarts-for-unhealthy-kafka-consumers", "company": "Cloudflare", "industry": "infra", "title": "Intelligent, automatic restarts for unhealthy Kafka consumers", "date": "2023-01-24", "primary_problem": "realtime", "problems": ["platform", "quality"], "post_type": "deep_dive", "level": "advanced", "stack": ["Kafka", "Kubernetes", "Sarama", "PagerDuty"], "scale": "Topics with up to hundreds of partitions; scale not quantified", "key_decisions": ["Use offset progress (committed vs latest offset changing) as the liveness signal instead of a simple broker connectivity check, trading more logic in probes for detection of idle-but-connected consumers", "Keep per-partition offset state in memory and clear entries on rebalance, avoiding false unhealthy reports but requiring hooks into the consumer session lifecycle", "Use Kubernetes restarts for automatic recovery, which reduces manual intervention but risks cascading restarts that trigger more rebalances"], "summary": "Cloudflare describes how consumers that stayed connected to Kafka but stopped making progress were caught by a smarter Kubernetes liveness probe based on committed versus latest offsets. An initial version caused cascading restarts because in-memory offset state went stale after rebalances, and the fix was to clear partition state through the consumer session lifecycle.", "interview_angle": "How would you detect and auto-recover a Kafka consumer group that is connected but not making progress, and what failure modes could your health check itself introduce during rebalances?", "score": 1.0658, "hn_points": 2, "hn_comments": 0}, {"url": "https://engineering.zalando.com/posts/2025/06/inventory-optimisation-system.html", "company": "Zalando", "industry": "ecommerce", "title": "Building a dynamic inventory optimisation system: A deep dive", "date": "2025-06-29", "primary_problem": "ml_data", "problems": ["scale_ingestion", "performance"], "post_type": "deep_dive", "level": "advanced", "stack": ["Databricks", "Spark", "Delta Lake", "AWS SageMaker", "SageMaker Feature Store", "Nixtla MLForecast", "LightGBM", "Numba", "AWS Step Functions", "AWS SQS", "AWS Lambda", "S3", "zFlow"], "scale": "5 million SKUs, 3 years of history per weekly run, under 2 hours forecasting runtime, 12-week forecast horizon", "key_decisions": ["Chose LightGBM with Nixtla MLForecast over deep models like TFT for forecasting, trading peak model capacity for fast iteration, lightweight training and simpler infrastructure", "Split feature engineering into distributed PySpark pre-processing and single-node vectorised transformation, trading horizontal scale for library efficiency in the second stage", "Ran batch and real-time optimisation off a shared feature store with online and offline stores, keeping outputs consistent at the cost of syncing two delivery paths"], "summary": "Zalando describes a replenishment optimisation system that produces weekly probabilistic demand forecasts for millions of article-merchant pairs and feeds them into a Monte Carlo based inventory optimiser. The pipelines run on Databricks and SageMaker, with a SageMaker Feature Store serving both daily batch and interactive partner-triggered recommendations.", "interview_angle": "How would you design a weekly forecasting pipeline for millions of SKUs that must finish in hours, and keep batch and interactive inventory recommendations consistent from the same features?", "score": 1.0641, "hn_points": 0, "hn_comments": 0}, {"url": "https://www.capitalone.com/tech/software-engineering/create-postgresql-table", "company": "Capital One", "industry": "fintech", "title": "How To Create and Partition PostgreSQL Tables | Capital One", "date": "2023-12-20", "primary_problem": "performance", "problems": ["modeling", "cost"], "post_type": "deep_dive", "level": "intermediate", "stack": ["PostgreSQL"], "scale": "", "key_decisions": ["Choose range, list or hash partitioning based on the query and data pattern; range suits time-series but needs a partition per interval", "Partition only when table size exceeds server memory or when history must be separated from new data; partitioning adds maintenance overhead", "Partition by a column that queries filter on, since queries not referencing the partition key lose the pruning benefit"], "summary": "This Capital One tutorial explains how to partition large PostgreSQL tables by range, list, or hash to improve query speed and data management. It walks through creating parent and child tables with examples on insurance policy data, plus how to drop or detach partitions and the main limitations of the approach.", "interview_angle": "How would you partition a multi-year event or transaction table in PostgreSQL to speed up time-bounded queries and make retention easier, and what trade-offs would you weigh between range, list and hash keys?", "score": 1.063, "hn_points": 0, "hn_comments": 0}, {"url": "https://engineering.grab.com/securing-gitops-pipeline", "company": "Grab", "industry": "mobility", "title": "Securing GitOps pipelines", "date": "2023-03-01", "primary_problem": "platform", "problems": ["governance_privacy", "quality"], "post_type": "case_study", "level": "advanced", "stack": ["Terraform", "Kafka", "Flink", "Kafka Connect", "GitLab CI", "Atlantis", "Python", "Kubernetes"], "scale": "", "key_decisions": ["Built an in-house GitOps tool (Khone) instead of adopting Kubernetes-native GitOps products, gaining full control over the flow at the cost of maintaining custom code", "Encoded namespace, environment and cluster in file paths so properties are validated once and boilerplate is removed, trading rigid directory conventions for simpler user input", "Loaded pipeline config and scripts from a separate admin repository (with branch-based testing) to block tampering by MR authors, adding a clone step to every job but keeping it cheap via shallow clones"], "summary": "Grab's Coban team replaced Atlantis-driven Terraform workflows for streaming infrastructure (Kafka topics, Flink pipelines, Kafka Connect connectors) with an in-house GitOps pipeline called Khone. The design adds HCL code inspection, path-based validation and protected pipeline config so that users cannot escalate privileges or tamper with CI scripts.", "interview_angle": "How would you design a self-service GitOps workflow for provisioning data infrastructure (topics, jobs, connectors) that enforces least privilege and prevents CI pipeline tampering?", "score": 1.06, "hn_points": 0, "hn_comments": 0}, {"url": "https://eng.lyft.com/orchestrating-data-pipelines-at-lyft-comparing-flyte-and-airflow-72c40d143aad", "company": "Lyft", "industry": "mobility", "title": "Orchestrating Data Pipelines at Lyft: comparing Flyte and Airflow", "date": "2022-03-24", "primary_problem": "platform", "problems": ["performance", "cost"], "post_type": "opinion", "level": "advanced", "stack": ["Airflow", "Flyte", "Kubernetes", "Spark", "Hive", "Trino", "Celery", "S3", "Docker", "XGBoost", "PyTorch", "Apache Sedona", "LyftLearn"], "scale": "About 750K data pipelines, 400K Spark jobs, 9 trillion analytical events per month, more than 10K unique workflows and about 1M executions per month", "key_decisions": ["Keep Airflow for SQL-heavy ETL orchestrating Hive/Trino, accepting shared dependencies and limited isolation in exchange for simplicity and fewer images to maintain", "Adopt Flyte for resource-intensive Python/Spark/ML workloads, gaining per-task dependency isolation, Kubernetes resource quotas and workflow versioning at the cost of maintaining Docker images and ephemeral pod startup overhead", "Use domains (dev/staging/prod) and cached task results in Flyte to speed iteration and cut cost, while avoiding Flyte for small frequent batches and table sensing where Airflow fits better"], "summary": "Lyft compares its two orchestration engines, Airflow and Flyte, explaining architecture, strengths and drawbacks of each and why Flyte was built to fill gaps around dependency isolation, resource isolation and versioning. The post offers a decision guide by use-case class (SQL ETL versus custom-environment compute) and walks through production examples such as pricing, ETA, supply/demand forecasting and computer vision mapping.", "interview_angle": "How would you choose between a centralized DAG scheduler and a Kubernetes-native per-task-isolated orchestrator for a mixed workload of SQL ETL, Spark, and GPU ML training, and what trade-offs would you call out around isolation, versioning, and ephemeral infrastructure overhead?", "score": 1.0558, "hn_points": 15, "hn_comments": 2}, {"url": "https://monzo.com/blog/building-year-in-monzo-as-told-by-engineering", "company": "Monzo", "industry": "fintech", "title": "How we built Year in Monzo: As told by the engineering team", "date": "2023-12-22", "primary_problem": "scale_ingestion", "problems": ["platform", "cost"], "post_type": "case_study", "level": "intermediate", "stack": ["Kafka", "AWS Keyspaces", "S3", "Headless Chrome", "Kubernetes", "Go", "Jetpack Compose", "Lottie"], "scale": "Over 5 million personalised images generated; pipeline run for all users in about 5 hours; Chrome scaled from ~120 to 600 instances", "key_decisions": ["Used a Kafka-based per-user pipeline with built-in retries and a dead letter queue for enrichment, trading simplicity for resilience over a bespoke work queue", "Pre-generated and stored all enriched data and images in Keyspaces and S3 so API reads only need authorisation and reshaping, trading storage and batch compute for low-latency serving", "Scaled headless Chrome from ~120 to 600 instances to fix OOM cascades instead of re-architecting to a work queue, prioritising deadline over compute cost and operational complexity"], "summary": "Monzo describes the pre-processing pipeline behind Year in Monzo, which enriches per-user data via Kafka consumers, stores results in Keyspaces, and renders over 5 million shareable images with headless Chrome. The main data engineering episode is an out-of-memory cascade during bulk generation, fixed by scaling Chrome replicas rather than redesigning around a work queue.", "interview_angle": "How would you design a batch pipeline that fans out millions of per-user enrichment and rendering jobs with retries, dead-letter handling and bounded resource use, and when is scaling out the right fix versus adding a work queue?", "score": 1.0535, "hn_points": 0, "hn_comments": 0}, {"url": "https://www.capitalone.com/tech/open-source/data-profiler-evaluating-data-quality-at-scale", "company": "Capital One", "industry": "fintech", "title": "Evaluating Data Quality for Machine Learning Models at Scale | Capital One", "date": "2021-12-08", "primary_problem": "quality", "problems": ["ml_data", "lineage_catalog"], "post_type": "deep_dive", "level": "intermediate", "stack": ["DataProfiler", "pandas", "Python", "Parquet", "Avro"], "scale": "", "key_decisions": ["Auto-detect file format and delimiter so any file loads without user specification, trading robustness for upfront complexity", "Compute all profile statistics in a single O(n) pass with subsampling and mergeable profiles, enabling parallel processing at the cost of approximate statistics", "Persist profiles alongside trained models and diff training, test and live data to flag drift before it harms model performance"], "summary": "Capital One presents its open-source DataProfiler library, which auto-loads heterogeneous files, builds mergeable single-pass statistical profiles, and diffs profiles to detect data drift between training, test and live data for ML models. The post is a library walkthrough focused on data validation for ML pipelines rather than a production architecture account.", "interview_angle": "How would you detect distribution drift between training and live data for many datasets at enterprise scale without re-scanning everything, and why make profiles mergeable?", "score": 1.0508, "hn_points": 1, "hn_comments": 0}, {"url": "https://shopify.engineering/rails-business-systems-intergration-platform", "company": "Shopify", "industry": "ecommerce", "title": "Building a Business System Integration and Automation Platform at Shopify", "date": "2022-04-22", "primary_problem": "platform", "problems": ["migration"], "post_type": "case_study", "level": "intermediate", "stack": ["Ruby", "Rails", "MuleSoft", "Kafka", "WebMock", "Mocha", "Sorbet", "GitHub"], "scale": "18 integrations running; migrated all MuleSoft apps; team grew from one to two developers", "key_decisions": ["Chose Ruby on Rails over MuleSoft to stay within Shopify's tech stack and reuse internal infrastructure, trading away vendor-managed runtime.", "Structured the platform as a modular monolith of Rails Engines, gaining per-integration code isolation at the cost of more setup than namespaces.", "Kept the platform stateless with no data storage, so it is never a source of truth; accepted duplicated logic in Actions to keep integrations decoupled."], "summary": "Shopify describes building an internal business system integration platform in Ruby on Rails after finding MuleSoft limiting for its stack and hosting needs. The design favors minimal validation, transparency, reusability and security, using Rails Engines, plain hashes, and a no-storage approach.", "interview_angle": "How would you design an internal integration platform that moves data between SaaS business systems with heterogeneous APIs, balancing buy-versus-build, transparency and security?", "score": 1.0504, "hn_points": 0, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/building-network-analytics-v2", "company": "Cloudflare", "industry": "infra", "title": "How we built Network Analytics v2", "date": "2023-05-02", "primary_problem": "scale_ingestion", "problems": ["realtime", "performance"], "post_type": "deep_dive", "level": "advanced", "stack": ["ClickHouse", "XDP", "iptables", "Netflow", "sFlow", "GraphQL"], "scale": "", "key_decisions": ["Emit packet samples from each mitigation component with its own metadata instead of one sampler at network entry, trading more sample streams for extensible, stateful-compatible reporting", "Split the XDP sampler around the mitigation decision so metadata is copied only for packets actually sampled, avoiding per-packet copy cost at the price of more complex program layout", "Use a ClickHouse AggregatingMergeTree table storing running min/max per attack ID, making attack-wide queries fast at the cost of only supporting aggregates that can be merged incrementally and needing a few rows per attack to combine"], "summary": "Cloudflare rebuilt Network Analytics so that each mitigation component (XDP, iptables, flowtrackd, Magic Firewall) emits its own metadata-rich packet samples through a new samplerd pipeline into ClickHouse. They avoid double-sampling by staging rules with packet marks and speed up attack-level queries with a precomputed AggregatingMergeTree min/max table.", "interview_angle": "How would you design a sampling pipeline that captures the final fate of each event across multiple stages without oversampling or copying metadata for every packet, and how would you precompute per-attack summaries so dashboards stay fast?", "score": 1.0501, "hn_points": 2, "hn_comments": 0}, {"url": "https://engineering.zalando.com/posts/2025/12/contributing-to-debezium.html", "company": "Zalando", "industry": "ecommerce", "title": "Contributing to Debezium: Fixing Logical Replication at Scale", "date": "2025-12-18", "primary_problem": "cdc_sync", "problems": ["cost", "quality"], "post_type": "open_source", "level": "advanced", "stack": ["PostgreSQL", "Debezium", "Kafka Connect", "Kubernetes", "pgjdbc", "Patroni"], "scale": "Hundreds of thousands of events per second at peak across 100+ Kubernetes clusters", "key_decisions": ["Make the pgjdbc keepalive LSN flush opt-in via a three-mode lsn.flush.mode enum (manual, connector, connector_and_driver), trading a simpler default for the ability to prevent WAL growth on low-activity databases", "Use an ephemeral memory offset store and trust the replication slot as source of truth, avoiding offset/slot mismatch failures but relying on slot management that survives failovers", "Add offset.mismatch.strategy with four modes (no_validation, trust_offset, trust_slot, trust_greater_lsn) and keep deprecated booleans mapped for backward compatibility, accepting more configuration complexity for operator flexibility"], "summary": "Zalando describes contributing two features to Debezium's PostgreSQL connector to fix runaway WAL growth on low-activity databases and to handle mismatches between stored offsets and replication slot positions. The changes add configurable LSN flush modes and offset mismatch strategies, with backward-compatible mappings for deprecated settings, and shipped in Debezium 3.4.0.", "interview_angle": "How would you keep a Postgres logical replication consumer from letting WAL pile up on a quiet database while still guaranteeing it can restart safely without data loss?", "score": 1.0478, "hn_points": 3, "hn_comments": 0}, {"url": "https://netflixtechblog.com/how-netflix-content-engineering-makes-a-federated-graph-searchable-part-2-49348511c06c", "company": "Netflix", "industry": "media", "title": "How Netflix Content Engineering makes a federated graph searchable (Part 2)", "date": "2022-06-15", "primary_problem": "platform", "problems": ["governance_privacy", "lineage_catalog"], "post_type": "case_study", "level": "advanced", "stack": ["Elasticsearch", "GraphQL", "ANTLR", "DGS framework", "Spinnaker"], "scale": "", "key_decisions": ["Expose a SQL-like custom DSL instead of raw Elasticsearch queries, trading flexibility for ease of use and a possible future engine swap", "Use query-time (late binding) authorization that appends policy constraints as filters, letting source teams change policies independently at the cost of a policy call per query", "Index only lean search fields and hydrate the rest via GraphQL federation, keeping indices small while giving users access to the full graph"], "summary": "Netflix describes the query side of Studio Search, a config-driven search platform over its federated content graph in Elasticsearch. It covers a SQL-like query DSL built with ANTLR, query-time access control enforced by appending policy filters, and federation-based hydration of search results.", "interview_angle": "How would you give many internal teams searchable access to a shared dataset while enforcing per-source access policies and keeping indices lean?", "score": 1.0465, "hn_points": 0, "hn_comments": 0}, {"url": "https://engineering.grab.com/processing-etl-tasks-with-ratchet", "company": "Grab", "industry": "mobility", "title": "Processing ETL tasks with Ratchet", "date": "2021-07-19", "primary_problem": "platform", "problems": ["quality"], "post_type": "deep_dive", "level": "intermediate", "stack": ["Go", "Ratchet", "S3", "JSON", "CSV"], "scale": "", "key_decisions": ["Use a Go-native pipeline library (Ratchet) with goroutine-per-stage processors, gaining concurrency and type consistency but tying the team to an internal framework", "Split each ETL task into extract, transform and load stages behind a Job Processor, making stages reusable and failures easier to localise, at the cost of more boilerplate for simple jobs", "Validate manually uploaded CSV rows in the transform stage so human errors are caught before reaching downstream microservices, trading per-row processing cost for cleaner propagation"], "summary": "Grab's Lending team describes how it uses Ratchet, an internal Go library, to build modular ETL pipelines for tasks such as whitelisting merchants from operations-uploaded CSV files. The post walks through extract, transform and load stages wired together by Job Processors, with validation to stop manual upload errors from propagating.", "interview_angle": "How would you design a self-serve, stage-based ETL framework for many small batch jobs that ingest manually uploaded files, and where would you place validation so bad rows fail early?", "score": 1.0387, "hn_points": 0, "hn_comments": 0}, {"url": "https://dropbox.tech/infrastructure/monitoring-server-applications-with-vortex", "company": "Dropbox", "industry": "saas", "title": "Monitoring server applications with Vortex", "date": "2019-11-14", "primary_problem": "scale_ingestion", "problems": ["performance", "platform"], "post_type": "deep_dive", "level": "advanced", "stack": ["Kafka", "HBase", "RocksDB", "Cassandra", "Graphite"], "scale": "600M+ metrics per minute, 1,000 machines, 60,000 alerts evaluated continuously", "key_decisions": ["Poll-based two-tier collection (NodeCollector and MetricCollector) keeps the node-side aggregator stateless, at the cost of some buffering delay before data reaches storage", "Buffering metrics for four minutes in MetricCollector lets data be regrouped by metric name for efficient reads and reduces Cassandra write load, but adds latency for unflushed data", "Enforcing per-node and per-process metric limits with preferential dropping protects ingestion from high-cardinality bursts, but means some metrics are intentionally lost under pressure"], "summary": "Dropbox describes Vortex, its rebuilt server monitoring system, which replaces a fragile Kafka/HBase/RocksDB pipeline with horizontally scalable, poll-based ingestion and a multitenant query cache with live streaming. The design emphasizes automatic recovery, ingestion limits against high-cardinality metrics, and topology tags that reduce cardinality, plus downsampling to keep query cost bounded.", "interview_angle": "How would you design a multi-tenant metrics ingestion and query system that scales horizontally, tolerates machine loss without manual repair, and protects itself from a single team emitting high-cardinality data?", "score": 1.0352, "hn_points": 0, "hn_comments": 0}, {"url": "https://www.capitalone.com/tech/machine-learning/how-to-build-offline-evaluation-frameworks", "company": "Capital One", "industry": "fintech", "title": "Offline Evaluation Framework for ML Models | Capital One", "date": "2021-01-21", "primary_problem": "ml_data", "problems": ["late_data", "lineage_catalog"], "post_type": "deep_dive", "level": "advanced", "stack": ["Spark", "Python", "R", "JVM"], "scale": "", "key_decisions": ["Passively snapshot upstream microservice stores and logs instead of requiring every service to persist state; trades completeness and exact consistency for no added load and no code changes upstream", "Stitch snapshots with approximate time-window temporal joins rather than exact event alignment; gives usable point-in-time views across systems but introduces approximation error", "Expose time-travel reads as Spark APIs for offline simulation of new models; enables scalable replay and reduces reliance on live A/B tests, at the cost of maintaining a custom JVM library and snapshot tracking"], "summary": "Capital One describes a \"wormhole\" framework that passively snapshots data from personalization microservices, stitches those snapshots with approximate temporal joins, and exposes time-travel reads so data scientists can replay new models against historical state. The design centers on persisting state transitions, snapshot generation with data quality checks, and a Spark-based stitching library used for offline evaluation.", "interview_angle": "How would you reconstruct the point-in-time state of many microservices from logs and snapshots so that offline model evaluation matches what production saw, and what approximations would you accept?", "score": 1.0347, "hn_points": 0, "hn_comments": 0}, {"url": "https://www.capitalone.com/tech/software-engineering/pyspark-performance-optimization-local-file", "company": "Capital One", "industry": "fintech", "title": "PySpark: Boost Read & Write Performance | Capital One", "date": "2023-04-17", "primary_problem": "performance", "problems": ["platform"], "post_type": "deep_dive", "level": "intermediate", "stack": ["Spark", "Parquet", "Python", "Jupyter", "PyCharm", "S3"], "scale": "", "key_decisions": ["Materialize an intermediate DataFrame to Parquet and re-read it to truncate a long lazy lineage, trading extra I/O for stable memory use", "Cache and run an action after reloading versus skipping cache so data is not held in memory, since caching large Parquet sets can hurt Spark's native optimization", "Use a temporary self-deleting directory for convenience versus a managed path, which avoids path management but makes the intermediate data non-reusable and harder to debug"], "summary": "The author describes a helper that writes a PySpark DataFrame to Parquet and reads it back to cut off a long, deeply nested computation graph that causes heap and garbage collection failures. The post explains why lazy evaluation causes this, when the trick applies, and when it does not, such as with UDFs or very large datasets.", "interview_angle": "How would you diagnose and fix Spark out-of-memory failures in a long chain of joins, and when would you checkpoint an intermediate result versus relying on caching or query-plan optimization?", "score": 1.0338, "hn_points": 0, "hn_comments": 0}, {"url": "https://engineering.zalando.com/posts/2017/10/reattaching-kafka-ebs-in-aws.html", "company": "Zalando", "industry": "ecommerce", "title": "Zalando Engineering Blog - Reattaching Kafka EBS in AWS", "date": "2017-10-26", "primary_problem": "platform", "problems": ["scale_ingestion", "cost"], "post_type": "deep_dive", "level": "advanced", "stack": ["Kafka", "Nakadi", "AWS EBS", "AWS EC2", "ZooKeeper", "Boto 3", "Python", "Senza", "Taupage", "CloudWatch"], "scale": "15 Kafka brokers, ingest 5TB/day, egress 30TB/day", "key_decisions": ["Detach EBS volumes before terminating a broker and reattach them to a replacement instance, avoiding a multi-hour re-replication at the cost of extra automation scripts and careful graceful shutdown.", "Use EC2 auto recovery via a StatusCheckFailed_System alarm so failed instances reboot with their EBS volumes intact, trading some recovery reliability for no data copy.", "Choose network-attached EBS (gp2, then st1) over local instance storage, gaining durability and flexibility while accepting network-bound throughput and dependence on EBS behavior."], "summary": "Zalando's Kafka team describes keeping broker data across instance termination, type changes, image upgrades and version upgrades by detaching and reattaching EBS volumes instead of rebuilding replicas. They report that upgrading a 15-broker cluster went from hours of re-replication to about 2 hours total, roughly 42x faster.", "interview_angle": "How would you keep a stateful Kafka cluster operable on cloud VMs without re-replicating terabytes every time a broker is replaced or upgraded?", "score": 1.0328, "hn_points": 0, "hn_comments": 0}, {"url": "https://engineering.grab.com/building-hyperlocal-grabmaps", "company": "Grab", "industry": "mobility", "title": "Building hyperlocal GrabMaps", "date": "2023-08-30", "primary_problem": "platform", "problems": ["modeling", "scale_ingestion"], "post_type": "case_study", "level": "intermediate", "stack": ["Spark", "Parquet", "OpenStreetMap", "geohash"], "scale": "", "key_decisions": ["Convert the OSM .pbf extract to Parquet so the road network can be processed with big data tools instead of binary parsing, trading an extra conversion step for scalable joins.", "Partition processing by geohash and build a bi-directional graph per cell, keeping each unit small and parallelisable but risking missed links that cross cell boundaries.", "Combine automated rules from OSM attributes and geometry with local map-team rules, favouring automation and coverage while depending on the quality of hand-authored specifications."], "summary": "Grab describes a pipeline that turns OpenStreetMap road data for Southeast Asia into Parquet and runs Spark-based geohash-partitioned graph computations to tag hyperlocal attributes such as intersection links. These tags are published to downstream routing services like GrabNav to improve route suggestions.", "interview_angle": "How would you design a geospatial batch pipeline that derives topology features (such as intersections) from a large road network, partitioning work spatially and handling edges that cross partition boundaries?", "score": 1.0312, "hn_points": 0, "hn_comments": 0}, {"url": "https://shopify.engineering/how-to-introduce-composite-primary-keys-in-rails", "company": "Shopify", "industry": "ecommerce", "title": "How to Introduce Composite Primary Keys in Rails", "date": "2020-10-29", "primary_problem": "performance", "problems": ["storage_formats", "migration"], "post_type": "case_study", "level": "advanced", "stack": ["Ruby on Rails", "Active Record", "MySQL", "InnoDB", "Ghostferry", "Large Hadron Migrator"], "scale": "Core operational MySQL database serving over a million merchants; ~1 hour/day less elapsed query time per shard; median buffer pool reads per query 1.8 to 1.2", "key_decisions": ["Use composite primary key (shop_id, id) so rows for one tenant are clustered on disk, cutting page reads per query, at the cost of roughly 10x slower inserts", "Keep id as a non-unique secondary key and force Active Record to treat it as primary, avoiding gem monkey-patching but accepting the risk of duplicate ids", "Skip a unique constraint on id to avoid deadlocks during trigger-based live migrations (LHM), trading away a database-enforced guarantee"], "summary": "Shopify changed its main MySQL orders table from a single auto-increment key to a composite (shop_id, id) primary key so each merchant's rows sit together on disk, reducing buffer pool page reads and speeding queries by 5-6x for key paths. The post covers the Rails compatibility workarounds, the live-migration deadlock risk, and the tooling changes needed in Ghostferry and the warehouse extractor.", "interview_angle": "How would you design the primary key/clustering for a multi-tenant table so that per-tenant scans stay cheap, and what do you give up on inserts and migrations to get there?", "score": 1.0311, "hn_points": 0, "hn_comments": 0}, {"url": "https://engineering.zalando.com/posts/2021/10/space-efficient-machine-learning-feature-stores-using-probabilistic-data-structures.html", "company": "Zalando", "industry": "ecommerce", "title": "Space efficient machine learning feature stores using probabilistic data structures - a benchmark", "date": "2021-10-04", "primary_problem": "ml_data", "problems": ["performance", "cost"], "post_type": "deep_dive", "level": "advanced", "stack": ["Bloom filter", "Redis", "Python", "JVM"], "scale": "About 5.7 mil training examples, 1.762 bil data points; feature store reduced from 15GB to 470MB", "key_decisions": ["Replace a networked key-value feature store with an in-process Bloom filter state, cutting memory from about 15GB to 470MB at a small AUC cost", "Accept false positives in exchange for sublinear space, tuning the compression level to trade AUC against state size", "Avoid per-lookup network calls and their latency variance, but accept that every node must receive all writes and deletes require full regeneration"], "summary": "The post proposes serving ML features from an in-process Bloom filter instead of an external key-value store, reducing feature state to a few percent of the original size with near-identical model AUC on a click prediction benchmark. It also lays out the limits: every node must absorb all writes, deletes require rebuilding the state from source, and complex queries are hard.", "interview_angle": "How would you design a low-latency feature store for a recommender that avoids a network call per lookup, and what freshness and deletion trade-offs would you accept with a compact in-memory representation?", "score": 1.0288, "hn_points": 0, "hn_comments": 0}, {"url": "https://www.capitalone.com/tech/software-engineering/event-driven-architecture-performance-testing", "company": "Capital One", "industry": "fintech", "title": "Event-Driven Architecture Performance Testing | Capital One", "date": "2025-08-28", "primary_problem": "realtime", "problems": ["quality", "scale_ingestion"], "post_type": "deep_dive", "level": "intermediate", "stack": ["Kafka", "Amazon MSK", "Amazon EventBridge", "RabbitMQ", "k6", "Locust", "Gatling", "JMeter", "Kafka Streams", "ECS Fargate", "Kubernetes", "AWS Lambda", "DynamoDB", "S3", "Elasticsearch", "Prometheus", "Grafana", "OpenTelemetry", "AWS X-Ray", "CloudWatch", "Jaeger", "Chaos Mesh", "Gremlin", "Fluent Bit"], "scale": "Thousands of events/second in example load tests; no production figures stated", "key_decisions": ["Measure end-to-end latency with trace IDs and timestamps embedded in events, trading instrumentation effort for cross-service visibility", "Use burst, ramp and soak load profiles rather than a single steady rate, which reveals backpressure and autoscaling behaviour but needs more test orchestration", "Inject broker and consumer failures with chaos tools to validate durability, accepting that tests run against production-like rather than production infrastructure"], "summary": "The article is a general guide to performance testing event-driven architectures, covering throughput, end-to-end latency, consumer lag, and resiliency. It suggests a reference setup of load generators, Kafka or MSK, consumers and observability tooling, plus SLO-driven testing practices. It is more about testing methodology for streaming systems than a specific Capital One data platform implementation.", "interview_angle": "How would you design a test harness to verify a Kafka-based streaming pipeline meets its end-to-end latency SLO and survives broker or consumer failures?", "score": 1.0279, "hn_points": 0, "hn_comments": 0}, {"url": "https://www.capitalone.com/tech/cloud/automating-partitioning", "company": "Capital One", "industry": "fintech", "title": "Automating Partitioning to Improve Performance | Capital One", "date": "2023-05-11", "primary_problem": "performance", "problems": ["cost", "platform"], "post_type": "deep_dive", "level": "intermediate", "stack": ["PostgreSQL", "Aurora PostgreSQL", "pg_partman"], "scale": "", "key_decisions": ["Use pg_partman to automate partition creation and maintenance instead of hand-written trigger and inheritance logic; trades some extension dependency for much less custom code", "Use native range partitioning on a timestamp with interval-based subpartitions on a secondary id, which constrains primary key design to include the partition columns", "Set retention through pg_partman config so old partitions are dropped or detached on a schedule, trading automatic deletion for a need to choose detach vs. drop carefully"], "summary": "Capital One's fraud-decisioning team moved a latency-sensitive workload to Aurora PostgreSQL and used the pg_partman extension to automate time-based and sub-partitioning. The post walks through setup, default-partition handling, and scheduled retention via maintenance jobs.", "interview_angle": "How would you partition a large, time-series PostgreSQL table to keep queries within SLA while automating retention and partition creation without custom triggers?", "score": 1.0265, "hn_points": 0, "hn_comments": 0}, {"url": "https://shopify.engineering/track-state-type-2-dimensional-models", "company": "Shopify", "industry": "ecommerce", "title": "How to Track State with Type 2 Dimensional Models", "date": "2020-08-27", "primary_problem": "modeling", "problems": ["cdc_sync", "late_data"], "post_type": "deep_dive", "level": "intermediate", "stack": ["Kafka", "Ruby on Rails", "Spark", "dbt", "MySQL", "Jupyter"], "scale": "", "key_decisions": ["Log record changes via Rails after_commit callbacks to Kafka rather than modifying core app tables to track history: quick to ship and fine-grained, but exposed to code paths that bypass the callback and to event loss.", "Build Type 2 dimensions from event logs with PySpark or dbt SQL instead of periodic snapshots: captures every change between runs, at the cost of relying on an event pipeline that can drop events.", "Plan to move to MySQL binlog extraction for change history: more reliable and automatic across all tables, but requires a separate data pipeline project and handling of deletes."], "summary": "The post explains how Shopify's international data science team turned a Type 1 users table into a Type 2 slowly changing dimension to track each user's language over time. It compares four approaches (app-model redesign, snapshot stitching, Kafka event logging via after_commit, and binlogs) and shows PySpark and dbt recipes that derive valid_from/valid_to ranges from an event log.", "interview_angle": "How would you design a history-tracking (SCD Type 2) pipeline for an operational table that was never built to track changes, and how would you handle missed updates, deletes and duplicate events?", "score": 1.0264, "hn_points": 0, "hn_comments": 0}, {"url": "https://engineering.zalando.com/posts/2017/11/real-time-ranking-kafka.html", "company": "Zalando", "industry": "ecommerce", "title": "Zalando Engineering Blog - Real-time Ranking with Apache Kafka\u2019s Streams API", "date": "2017-11-23", "primary_problem": "realtime", "problems": ["platform", "performance"], "post_type": "case_study", "level": "intermediate", "stack": ["Kafka", "Kafka Streams", "Scala", "AWS", "S3", "Spark", "Hadoop"], "scale": "", "key_decisions": ["Chose Kafka Streams over Hadoop and Spark for a small team, trading batch-tool maturity for lower infrastructure overhead and always-current results", "Used a modified HITS algorithm at domain level with a fixed iteration count instead of eigenvector convergence, since sparse matrices gave unexpected results and iteration is simpler", "Used flatMap for extraction so per-document errors simply emit zero records, favoring simplicity over rigorous error handling"], "summary": "Zalando's Dublin Fashion Insight Centre built a near-real-time domain ranking system that extracts outbound links from crawled web documents and computes hub and authority scores with a modified HITS algorithm. The pipeline runs as Scala components on Kafka Streams deployed in containers on AWS, using a compacted topic and a local cache feeding a REST API.", "interview_angle": "How would you design a streaming pipeline that computes graph-based rankings incrementally over partial, continuously arriving link data, and when would you pick Kafka Streams over Spark or MapReduce?", "score": 1.0263, "hn_points": 0, "hn_comments": 0}, {"url": "https://netflixtechblog.com/maestro-netflixs-workflow-orchestrator-ee13a06f9c78", "company": "Netflix", "industry": "media", "title": "Maestro: Netflix\u2019s Workflow Orchestrator", "date": "2024-07-22", "primary_problem": "platform", "problems": ["scale_ingestion", "late_data"], "post_type": "announcement", "level": "advanced", "stack": ["Maestro", "Java", "Docker", "Kafka", "SNS"], "scale": "Thousands of workflow instances and about 500K jobs per day on average, peaking near 2M jobs on busy days", "key_decisions": ["Build a custom expression language (SEL) for runtime parameters instead of raw code injection: gains safety and sandboxing but adds maintenance of a homegrown language", "Support cyclic and acyclic workflows with native foreach, subworkflow and conditional patterns: more expressive but makes rollup and status computation recursive and eventually consistent", "Run one centralized orchestrator for all workflows against the shared warehouse: simpler coordination and better UX, but a single system carries all scaling and failure risk"], "summary": "Netflix open-sourced Maestro, a horizontally scalable orchestrator for data and ML workflows that handles retries, queuing and task dispatch for thousands of workflows and roughly half a million jobs per day. The post describes its run strategies, parameter merging, foreach and subworkflow patterns, signal-based dependencies, and aggregated rollup views.", "interview_angle": "How would you design a multi-tenant workflow orchestrator that supports backfills via fan-out with concurrency limits, safe user-defined parameters, and restart semantics that preserve state across runs?", "score": 1.0253, "hn_points": 307, "hn_comments": 159}, {"url": "https://engineering.zalando.com/posts/2021/01/experimentation-platform-part1.html", "company": "Zalando", "industry": "ecommerce", "title": "Zalando Engineering Blog - Experimentation Platform at Zalando: Part 1 - Evolution", "date": "2021-01-12", "primary_problem": "platform", "problems": ["quality", "migration"], "post_type": "case_study", "level": "intermediate", "stack": ["Spark"], "scale": "At least 20% of A/B tests affected by sample ratio mismatch; median A/B test runtime about three weeks", "key_decisions": ["Build an in-house experimentation platform (Octopus) instead of off-the-shelf A/B tools, trading upfront engineering cost for control over data infrastructure and analysis", "Rebuild the analysis system on Spark after the original architecture could not handle concurrent tests, trading two years of effort for scalability and lower maintenance cost", "Automate sample ratio mismatch alerts to owning teams, trading added alert noise for catching data quality issues before results reach users"], "summary": "Zalando's experimentation platform evolved from manual per-team A/B tests into a centralized service called Octopus, then through a two-year rebuild of its analysis system on Spark. The post frames the growth in three phases and highlights recurring data quality problems such as inconsistent tracking schemas and sample ratio mismatch.", "interview_angle": "How would you design an experimentation platform's data pipeline so that tracking data quality issues like sample ratio mismatch are detected automatically and the analysis layer scales with concurrent tests?", "score": 1.0244, "hn_points": 0, "hn_comments": 0}, {"url": "https://engineering.grab.com/telematics-at-grab", "company": "Grab", "industry": "mobility", "title": "How telematics helps Grab to improve safety", "date": "2022-03-24", "primary_problem": "scale_ingestion", "problems": ["cost", "quality"], "post_type": "case_study", "level": "intermediate", "stack": ["Android"], "scale": "", "key_decisions": ["Resample accelerometer, gyroscope and GPS onto a uniform time grid via interpolation then decimation, trading compute on-device for clean aligned signals", "Process crash detection on-device for low latency while generating traffic-event safety reports on the backend after each ride, trading latency for upload simplicity", "Compress sensor data with Fourier transform and batch-upload one text file per ride, trading delayed availability for lower network consumption"], "summary": "Grab describes an in-house telematics engine that turns phone accelerometer, gyroscope and GPS readings into driving-safety events and reports. The core data engineering work is time-synchronising irregularly sampled sensor streams, compressing them, and uploading per-ride files from heterogeneous Android devices.", "interview_angle": "How would you design ingestion of noisy, irregularly sampled device sensor streams from millions of heterogeneous phones, including alignment, compression and handling of delayed uploads?", "score": 1.0222, "hn_points": 0, "hn_comments": 0}, {"url": "https://shopify.engineering/leveraging-go-worker-pools", "company": "Shopify", "industry": "ecommerce", "title": "Leveraging Go Worker Pools to Scale Server-side Data Sharing", "date": "2022-09-09", "primary_problem": "scale_ingestion", "problems": ["realtime", "performance"], "post_type": "case_study", "level": "advanced", "stack": ["Go", "Kafka"], "scale": "Over 1 billion events/day; 7.75k to 21k events/sec per pod; peak 46k events/sec at BFCM 2021", "key_decisions": ["Bounded worker pools with fixed goroutine counts instead of unlimited goroutine spawning: caps resource use but requires tuning worker counts per stage", "Reusable generic Worker interface with pluggable work functions across processing, validation, parsing and augmentation: consistent pattern but a shared abstraction to maintain", "Channel-based job queue with WaitGroups and context cancellation for graceful shutdown: drains in-flight work safely but adds shutdown coordination complexity"], "summary": "Shopify's Server Pixels service, which processes over a billion customer events daily in Go, replaced unbounded goroutine spawning with Go worker pools to stop consumption lag. The change raised per-pod throughput from about 7.75k to 21k events per second ahead of BFCM.", "interview_angle": "How would you make a high-throughput Kafka consumer that processes batches resilient to traffic spikes without exhausting memory or CPU, and how would you shut it down gracefully?", "score": 1.0202, "hn_points": 0, "hn_comments": 0}, {"url": "https://stripe.com/blog/introducing-veneur-high-performance-and-global-aggregation-for-datadog", "company": "Stripe", "industry": "fintech", "title": "Introducing Veneur: high performance and global aggregation for Datadog", "date": "2016-10-18", "primary_problem": "scale_ingestion", "problems": ["realtime", "performance"], "post_type": "open_source", "level": "advanced", "stack": ["Datadog", "StatsD", "DogStatsD", "Veneur", "Go", "t-digest", "HyperLogLog"], "scale": "hundreds of hosts sending StatsD metrics; no exact volume stated", "key_decisions": ["Forward raw histogram state to a global Veneur instance instead of per-host percentiles, gaining correct global percentiles at the cost of one flush period of added latency and a new single point of failure", "Use t-digest approximate mergeable histograms with constant memory rather than storing all samples, trading percentile accuracy for bounded memory", "Abandon smart clients for client-side routing to keep StatsD's simplicity, accepting a server-side aggregation design instead"], "summary": "Stripe describes Veneur, an open-source DogStatsD-compatible metrics server it built after moving to Datadog, because per-host aggregation made global percentiles impossible. Veneur forwards histograms to a global instance that merges them using a constant-memory t-digest, and it degrades gracefully by reporting min, max and counts immediately.", "interview_angle": "How would you design a metrics pipeline that yields correct global p99 latency across hundreds of hosts without storing every sample, and what fails when the aggregation tier goes down?", "score": 1.0173, "hn_points": 16, "hn_comments": 1}, {"url": "https://engineering.zalando.com/posts/2022/02/transactional-outbox-with-aws-lambda-and-dynamodb.html", "company": "Zalando", "industry": "ecommerce", "title": "Utilizing Amazon DynamoDB and AWS Lambda for Asynchronous Event Publication", "date": "2022-02-02", "primary_problem": "cdc_sync", "problems": ["realtime", "quality"], "post_type": "case_study", "level": "intermediate", "stack": ["Amazon DynamoDB", "DynamoDB Streams", "AWS Lambda", "Nakadi", "Amazon SQS", "Kubernetes", "Python", "PostgreSQL"], "scale": "", "key_decisions": ["Use DynamoDB Streams as change data capture so the write path no longer waits on the message bus, trading synchronous publication guarantees for higher service availability", "Publish events from a Lambda consuming the stream with old and new images, accepting that event ordering is not guaranteed", "Use an SQS dead letter queue plus a Kubernetes CronJob retry loop as fallback, trading extra moving parts for no event loss during outages"], "summary": "Zalando Payments moved event publication for its Order Store off the synchronous REST path by implementing a transactional outbox with DynamoDB Streams and AWS Lambda. Failed publications fall back to an SQS queue that a Kubernetes CronJob drains, which raises the service's availability by removing one dependency from the request path.", "interview_angle": "How would you decouple a database write from downstream event publication so that a service's availability does not depend on the message broker, and how do you handle retries and ordering?", "score": 1.0169, "hn_points": 0, "hn_comments": 0}, {"url": "https://shopify.engineering/mitigating-deadlocks-in-high-concurrency-environments", "company": "Shopify", "industry": "ecommerce", "title": "Mitigating Deadlocks in high concurrency environments", "date": "2024-08-14", "primary_problem": "performance", "problems": ["scale_ingestion", "storage_formats"], "post_type": "case_study", "level": "advanced", "stack": ["MySQL", "InnoDB"], "scale": "", "key_decisions": ["Switched the primary key to a composite of account and id so InnoDB physically clusters rows per account, shrinking overlapping gap locks; trade-off is a schema change on a core table.", "Kept a unique index on id alone so existing joins and lookups keep working without application changes; trade-off is an extra index to maintain on writes.", "Removed artificial delays that had been added to avoid deadlocks, improving import throughput; trade-off is relying on DB-layer fix rather than application-level coordination."], "summary": "Shopify's ETL imports into a MySQL transactions table were deadlocking because gap locks taken during upserts overlapped across parallel processes, even when they touched different records. Adding a composite primary key that includes the account partition key keeps each process's locks within its own region of the index, which removed the deadlocks and the artificial delays used to mask them.", "interview_angle": "How would you reduce deadlocks from concurrent batch upserts into a MySQL/InnoDB table without changing application logic, and what does clustering by primary key imply for lock contention?", "score": 1.0152, "hn_points": 0, "hn_comments": 0}, {"url": "https://engineering.zalando.com/posts/2017/10/event-first-development---moving-towards-kafka-pipeline-applications.html", "company": "Zalando", "industry": "ecommerce", "title": "Zalando Engineering Blog - Event First Development - Moving Towards Kafka Pipeline Applications", "date": "2017-10-10", "primary_problem": "realtime", "problems": ["cdc_sync", "scale_ingestion"], "post_type": "case_study", "level": "advanced", "stack": ["Kafka", "PostgreSQL", "Solr", "Elasticsearch", "S3", "DynamoDB"], "scale": "", "key_decisions": ["Replace synchronous CRUD services with event sourcing on Kafka, trading immediate consistency for ordered, replayable event streams", "Use Kafka both as inbound event source and outbound event stream, so one application's output becomes another's input, at the cost of depending heavily on one platform", "Keep operational databases limited to the processed entity data (no distributed transactions or messaging tables), simplifying retries and DB tuning but requiring careful partition key choice for cross-entity validation"], "summary": "Zalando describes how its Fashion Platform Article services were redesigned from synchronous HTTP plus PostgreSQL CRUD into an event-first, asynchronous architecture built on Kafka. The post explains the benefits of ordered, partitioned, at-least-once event logs for both ingestion and outbound event delivery, plus log compaction for snapshots.", "interview_angle": "How would you design a service whose outbound event stream must be correct and ordered for many downstream consumers, and how do you partition data to keep per-entity ordering while scaling horizontally?", "score": 1.0144, "hn_points": 0, "hn_comments": 0}, {"url": "https://tech.instacart.com/catalog-localization-more-than-just-a-translation-7251675dc12b", "company": "Instacart", "industry": "marketplace", "title": "Catalog Localization: more than just a translation!", "date": "2021-11-01", "primary_problem": "modeling", "problems": ["scale_ingestion", "platform"], "post_type": "case_study", "level": "intermediate", "stack": [], "scale": "Millions of products, 65,000+ locations, billions of rows updated daily", "key_decisions": ["Separate locale-specific from locale-agnostic attributes so price and store-level data are not duplicated per language, trading some modeling complexity for lower data volume.", "Split non-grocery variation handling into a configuration layer and a localized-values layer, avoiding multiplying variation data by locale.", "Flatten nested partner JSON feeds into flat structures before normalization, trading extra onboarding work for a standard ingestion path."], "summary": "Instacart's Catalog team describes how it added localization to its product catalog for the Quebec launch, covering a tree of parent, retailer and store-level product data. The post focuses on modeling locale-specific attributes, handling non-grocery product variations, and flattening nested partner JSON feeds during ingestion.", "interview_angle": "How would you model a multi-tenant product catalog with hierarchical overrides (parent, retailer, store) so that localized attributes are stored once and only the locale-specific fields vary?", "score": 0.9966, "hn_points": 0, "hn_comments": 0}, {"url": "https://shopify.engineering/double-entry-transition-tables-shopify", "company": "Shopify", "industry": "ecommerce", "title": "Double Entry Transition Tables: How We Track State Changes At Shopify", "date": "2022-05-18", "primary_problem": "modeling", "problems": ["late_data", "quality"], "post_type": "deep_dive", "level": "intermediate", "stack": ["Spark"], "scale": "", "key_decisions": ["Model state history as double-entry rows (+1 new state, -1 previous state) so counts become a simple additive sum, at the cost of doubling row count and more upfront build effort", "Merge per-attribute tables on account_id and a sort key (transition_at plus a row-number index tiebreak) and forward-fill missing values, which makes simultaneous-timestamp ordering deterministic but requires a tiebreak column", "Build one shared transition table for Shopify and Balance statuses so new attributes can be added without rewriting downstream queries, trading a wider schema and merge pipeline for long-term maintenance savings"], "summary": "Shopify's Data team describes double entry transition tables, a fact-table pattern that records each state change as a -1 row for the old state and a +1 row for the new state. They use it to count merchants who hold both an active Shopify Balance account and an active Shopify account, historically and as attributes are added.", "interview_angle": "How would you model historical account status across multiple independent status attributes so that active counts over time are easy to compute and new attributes can be added without rewriting queries?", "score": 0.9865, "hn_points": 0, "hn_comments": 0}, {"url": "https://shopify.engineering/how-an-intern-released-3-terabytes-worth-of-storage-before-bfcm", "company": "Shopify", "industry": "ecommerce", "title": "How an Intern Released 3 Terabytes Worth of Storage Before BFCM", "date": "2018-12-14", "primary_problem": "cost", "problems": ["performance", "quality"], "post_type": "case_study", "level": "intermediate", "stack": ["MySQL", "Ruby on Rails", "job-iteration", "InnoDB"], "scale": "Roughly 5 billion records deleted (about 6 million per minute at peak), freeing 3 TB of storage", "key_decisions": ["Ran a throttled, paused-between-batches background deletion job rather than a single bulk DELETE, trading longer runtime for lower replication lag and database load", "Used cursor-based batch enumeration on indexed columns so each batch avoids re-scanning earlier rows, at the cost of tighter index design requirements", "Relied on an automatic throttling enumerator that pauses when the database shows overload, trading operational simplicity for dependence on internal tooling"], "summary": "An intern describes a Shopify background job that deleted about 5 billion historical reporting records from a MySQL database ahead of Black Friday Cyber Monday. The job used batched, cursor-paginated deletes with automatic throttling to free 3 TB and cut pages scanned per lookup roughly threefold without overloading the database.", "interview_angle": "How would you safely purge billions of old rows from a live OLTP database without causing replication lag or downtime? Discuss batching, cursor pagination, indexing for the delete predicate, and throttling based on database health.", "score": 0.9854, "hn_points": 0, "hn_comments": 0}, {"url": "https://engineering.fb.com/2020/08/12/security/delf", "company": "Meta", "industry": "social", "title": "DELF: Safeguarding deletion correctness in online social networks", "date": "2020-08-12", "primary_problem": "governance_privacy", "problems": ["quality", "platform"], "post_type": "deep_dive", "level": "advanced", "stack": ["Facebook internal data stores"], "scale": "Billions of deletions per day", "key_decisions": ["Declarative deletion annotations in data type specs instead of hand-written deletion code: removes repetitive logic but makes correctness depend on annotation accuracy", "Hide-first then asynchronous point deletes with retries: users see immediate effect while background graph traversal may lag and leave transient residue", "Restoration log for a limited undo window: guards against accidental deletion but keeps deleted data recoverable for a time, which conflicts with strict erasure"], "summary": "Meta describes DELF, a framework where developers declare deletion behavior through annotations in data type specifications, and the system executes cascading deletions asynchronously with retries and monitoring. Static and dynamic validation checks, plus privilege escalation checks, guard against annotation mistakes that could retain or wrongly remove data.", "interview_angle": "How would you design a system that propagates user deletion requests across many data stores and dependent objects while guaranteeing completeness and preventing accidental deletes?", "score": 0.9675, "hn_points": 0, "hn_comments": 0}, {"url": "https://shopify.engineering/shopify-in-context-analytics", "company": "Shopify", "industry": "ecommerce", "title": "How Shopify Built An In-Context Analytics Experience", "date": "2021-05-25", "primary_problem": "modeling", "problems": ["realtime", "lineage_catalog"], "post_type": "case_study", "level": "intermediate", "stack": ["Kafka", "Spark"], "scale": "", "key_decisions": ["Model the data at atomic grain (one row per fulfillment, in-transit or delivery event) so future products and dimensions can reuse it, trading extra modeling effort up front for flexibility.", "Build the dataset as a batch model first and backfill history from it, with a streaming pipeline covering only the most recent data; this lowers risk and limits load on streaming infrastructure but adds lambda-style complexity.", "Use a data specification sheet as a single source of truth for each metric's query so web, Android and iOS clients share identical logic, at the cost of manual upkeep."], "summary": "Shopify describes how it designed the data behind an in-context analytics feature on the Orders page, starting with metric selection and segment-level data exploration. The data model was built in batch first, then combined with a streaming layer for near-real-time recent data.", "interview_angle": "How would you design a metrics model that serves both historical backfill and near-real-time updates, and what grain would you pick so it can support future dimensions?", "score": 0.9426, "hn_points": 0, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/kyoto_tycoon_with_postgresql", "company": "Cloudflare", "industry": "infra", "title": "Integrating Kyoto Tycoon With PostgreSQL", "date": "2013-07-08", "primary_problem": "cdc_sync", "problems": ["realtime", "platform"], "post_type": "deep_dive", "level": "intermediate", "stack": ["PostgreSQL", "Kyoto Tycoon", "kt_fdw"], "scale": "Thousands of rule creations per second at peak; propagation up to ~3 seconds across 23 PoPs", "key_decisions": ["Replace periodic reconciliation scripts with a writable PostgreSQL foreign data wrapper so database triggers push changes to Kyoto Tycoon, trading custom FDW maintenance for lower latency and simpler logic", "Map PostgreSQL transactions onto Kyoto Tycoon transactions to get ACID-style semantics across the replicated store, accepting dependence on the FDW's transaction handling", "Rely on timestamp-based replication from a single primary to all PoPs, giving ordering and eventual consistency with about 3 seconds of propagation delay rather than strong global consistency"], "summary": "Cloudflare describes moving rule configuration from PostgreSQL to a globally replicated Kyoto Tycoon key-value store by writing a PostgreSQL foreign data wrapper, replacing polling-based reconciliation scripts. The approach uses triggers to push writes to KT, reducing lag and code complexity, and the FDW is open sourced.", "interview_angle": "How would you propagate configuration changes from a central relational database to edge locations worldwide while preserving creation-time ordering and minimizing lag, compared with periodic batch reconciliation?", "score": 0.9414, "hn_points": 0, "hn_comments": 0}, {"url": "https://engineering.grab.com/the-creation-of-our-powerful-campaign-builder", "company": "Grab", "industry": "mobility", "title": "Unveiling the process: The creation of our powerful campaign builder", "date": "2024-09-10", "primary_problem": "realtime", "problems": ["platform", "modeling"], "post_type": "deep_dive", "level": "intermediate", "stack": ["Kafka", "Amazon SQS"], "scale": "", "key_decisions": ["Model counters and delays as chained treatments that re-emit events to Kafka, keeping the rule engine uniform at the cost of extra hops and event types", "Use SQS delayed messages with re-publishing in 15-minute steps to exceed SQS's maximum delay, trading simplicity for repeated message handling", "Store both the visual node tree JSON and compiled treatments plus a node-treatment mapping, so campaigns display cleanly and updates can diff and modify treatments precisely"], "summary": "Grab describes how its Trident marketing platform executes IFTTT-style campaigns over real-time Kafka events, using treatments with features such as counters, delays and limits. It also explains converting a visual flow-chart node tree into executable treatments and diffing them when campaigns are updated.", "interview_angle": "How would you design a real-time rule engine that evaluates conditions on streaming events and supports stateful counters, delayed actions and per-user rate limits?", "score": 0.9397, "hn_points": 0, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/cloudflare-openai-discovery-agentic-web", "company": "Cloudflare", "industry": "infra", "title": "Cloudflare and OpenAI: making AI discovery better for everyone", "date": "2026-10-15", "primary_problem": "scale_ingestion", "problems": ["cost", "quality"], "post_type": "case_study", "level": "advanced", "stack": [], "scale": "Pilot covers ~1% of Cloudflare's network; OpenAI discovered hundreds of millions of new web pages", "key_decisions": ["Filter out nonexistent, soft-404 and duplicate URLs before fetching to cut wasted crawl work, trading some recall for crawler efficiency", "Use change signals to decide when to revisit a page, reducing load on site owners but risking staleness for pages that change unpredictably", "Flag harmful pages at the single-URL level rather than blocking whole domains, avoiding penalizing legitimate sites at the cost of more granular classification"], "summary": "Cloudflare and OpenAI ran a pilot using signals from a ~1% slice of Cloudflare's network to help OpenAI's search crawler find and index new pages more efficiently. The work centers on filtering out dead, redirecting, and duplicate URLs and using change signals to schedule recrawls, which reduces wasted fetches.", "interview_angle": "How would you design a crawl scheduler that prioritizes URL discovery while filtering dead and duplicate pages and deciding when to revisit content without overloading origin sites?", "score": 0.9388, "hn_points": 4, "hn_comments": 0}, {"url": "https://monzo.com/blog/2022/02/08/processing-payments-safely-at-scale", "company": "Monzo", "industry": "fintech", "title": "Processing payments safely at scale", "date": "2022-02-08", "primary_problem": "quality", "problems": ["cdc_sync", "governance_privacy"], "post_type": "deep_dive", "level": "intermediate", "stack": [], "scale": "", "key_decisions": ["Run coherence checks as SQL models over warehouse payment state and also as event-driven services; warehouse checks are easy to write but detect issues only after data lands, while services react faster but cost more to build.", "Reconcile internal ledger against settlement bank statements daily; this catches anything the other controls miss but is slow when settlement is daily.", "Require engineers to acknowledge and document reconciliation breaks with evidence; this adds process overhead but yields an audit trail for compliance."], "summary": "Monzo describes how it guards payment correctness while shipping many times a day, focusing on coherence checks that flag payments in invalid lifecycle states and reconciliation of the internal ledger against settlement accounts. The post frames these as detective controls that complement testing, feature flags and monitoring, and suggests they generalise beyond finance.", "interview_angle": "How would you detect silent data correctness bugs in a pipeline that moves money, given that alerts on errors can miss them? Discuss coherence checks versus reconciliation against an external source.", "score": 0.9332, "hn_points": 2, "hn_comments": 0}, {"url": "https://www.capitalone.com/tech/software-engineering/spline-spark-data-lineage", "company": "Capital One", "industry": "fintech", "title": "Capturing & Displaying Data Transformations with Spline | Capital One", "date": "2021-11-01", "primary_problem": "lineage_catalog", "problems": ["governance_privacy", "platform"], "post_type": "open_source", "level": "intermediate", "stack": ["Spline", "Spark", "ArangoDB", "Docker"], "scale": "", "key_decisions": ["Capture lineage automatically at run-time via a Spark query listener instead of maintaining design-time documentation manually; trade-off is coupling to Spark and only capturing on write actions", "Use Spline's agent, REST gateway, and UI stack deployed via Docker Compose for a quick sandbox; trade-off is a local, non-production setup that still needs hardening for real use", "Record run-time metadata such as record counts and partition info alongside lineage; trade-off is extra capture overhead and reliance on the agent's plan analysis"], "summary": "The post walks through using the open source Spline tool to automatically capture and visualize lineage from PySpark jobs, using a Docker-based Spline server and a Spark agent attached via spark-submit. It argues that run-time lineage capture catches drift from documented design and gives regulated organizations documentation they can show.", "interview_angle": "How would you automatically capture column-level lineage for batch Spark jobs without requiring engineers to hand-maintain documentation, and what are the limits of plan-based capture?", "score": 0.932, "hn_points": 0, "hn_comments": 0}, {"url": "https://engineering.grab.com/grabmart-data-for-faster-disease-outbreak-detection", "company": "Grab", "industry": "mobility", "title": "GrabMart data for faster disease outbreak detection", "date": "2026-10-13", "primary_problem": "governance_privacy", "problems": ["realtime", "quality"], "post_type": "deep_dive", "level": "advanced", "stack": [], "scale": "", "key_decisions": ["Restrict input to eligible, reviewed product categories and aggregate by coarse geography and time to limit disclosure, at the cost of weaker statistical signal", "Apply minimum-count thresholds and differential privacy at release, trading utility for privacy guarantees that need a documented budget", "Compare aggregated demand against seasonal baselines and keep public health experts in control of interpretation, accepting slower and more manual alerting"], "summary": "Grab outlines an early-stage concept for aggregating GrabMart over-the-counter purchase data into symptom-class demand series and scoring deviations from seasonal baselines as a supplementary outbreak signal. The post is explicit that this is not deployed and centers the design on minimisation, aggregation, differential privacy and prohibition of individual health inference.", "interview_angle": "How would you design a privacy-preserving aggregation pipeline over sensitive transactional data that feeds an anomaly detector, including eligibility filtering, geographic and temporal aggregation, minimum-count thresholds and differential privacy at release?", "score": 0.9255, "hn_points": 0, "hn_comments": 0}, {"url": "https://engineering.grab.com/blog/24", "company": "Grab", "industry": "mobility", "title": "Grab Tech", "date": "2017-05-01", "primary_problem": "platform", "problems": ["lineage_catalog", "quality"], "post_type": "case_study", "level": "intermediate", "stack": ["Flink", "Kafka", "Iceberg", "Spark", "StarRocks", "Airflow", "Presto"], "scale": "", "key_decisions": ["Build a centralized, one-click ingestion platform on Flink versus per-team pipelines: faster onboarding but a shared platform to operate", "Adopt Apache Iceberg for the data lake: schema evolution and table management versus migration effort from legacy formats", "Automate data reliability checks (DPIs) and certification: earlier detection of bad data at the cost of maintaining rule frameworks"], "summary": "This is an index page of Grab Tech engineering posts spanning iOS CI, Rails-to-Go migration, data mesh, Iceberg lakehouse adoption, Flink ingestion, and many AI projects. It mixes mobile, backend and data topics, so it is not itself a single data engineering case study.", "interview_angle": "How would you design a self-serve data ingestion platform and a data lake table format that serve many teams while keeping data reliable?", "score": 0.9239, "hn_points": 0, "hn_comments": 0}, {"url": "https://engineering.grab.com/blog/23", "company": "Grab", "industry": "mobility", "title": "Grab Tech", "date": "2017-10-04", "primary_problem": "platform", "problems": ["scale_ingestion", "storage_formats"], "post_type": "case_study", "level": "advanced", "stack": ["Grab Data Lake", "Iceberg", "Flink", "FlinkSQL", "Kafka", "Spark", "StarRocks", "Kubernetes", "Airflow"], "scale": "", "key_decisions": ["Build a self-serve, one-click ingestion platform on Flink rather than bespoke pipelines per team, trading upfront platform effort for consistency", "Adopt Apache Iceberg as the lakehouse table format to get reliable table evolution, at the cost of migration work on existing data lake tables", "Automate data reliability checks (DPIs) and certification across data mesh domains, trading strict central control for domain-owned quality signals"], "summary": "This is a blog index page for Grab Tech listing many posts across engineering, AI and data topics. It covers several data-related series such as data mesh, the Hugo ingestion platform, and the move of the data lake to Apache Iceberg, but the page itself contains no single technical analysis.", "interview_angle": "How would you design a self-serve data ingestion platform on Flink and a lakehouse table format like Iceberg for a large company with many domain teams?", "score": 0.9234, "hn_points": 0, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/logs-from-the-edge", "company": "Cloudflare", "industry": "infra", "title": "Logs from the Edge", "date": "2018-11-29", "primary_problem": "scale_ingestion", "problems": ["realtime", "governance_privacy"], "post_type": "case_study", "level": "intermediate", "stack": ["Cloudflare Workers", "Elasticsearch", "Kibana", "Cloudflare Access", "Argo Tunnel", "S3", "Google Cloud Storage"], "scale": "", "key_decisions": ["Use Worker sub-requests inside waitUntil so logging to ELK runs after the response is served, trading guaranteed delivery for zero added request latency", "Ship logs as one HTTP PUT per request to ELK, which is simple to build but adds per-request overhead versus batching", "Expose Kibana through Argo Tunnel and Access rather than a public origin, trading setup complexity for reduced attack surface"], "summary": "The post shows how a Cloudflare Worker can proxy each request, then asynchronously send a structured log record with Cloudflare-specific fields such as the ray ID, colo and TLS details to an Elasticsearch/Kibana stack. It also contrasts this DIY approach with Enterprise Log Share, which provides managed, guaranteed log delivery and retention.", "interview_angle": "How would you design per-request log shipping from an edge network to a central search store without adding latency, and what delivery guarantees would you give up by doing it that way?", "score": 0.9232, "hn_points": 4, "hn_comments": 0}, {"url": "https://www.capitalone.com/tech/cloud/event-streaming", "company": "Capital One", "industry": "fintech", "title": "Event Streaming: Tips for Event-Driven Apps | Capital One", "date": "2023-12-13", "primary_problem": "realtime", "problems": ["cdc_sync", "scale_ingestion"], "post_type": "deep_dive", "level": "intermediate", "stack": ["Kafka", "AWS Lambda", "Amazon Kinesis", "AWS Database Migration Service", "DynamoDB Streams"], "scale": "", "key_decisions": ["Use a Kafka-style message broker as a replayable event store, trading storage cost for the ability to rebuild state after failures", "Add CDC to existing applications to capture changes without disrupting production, at the cost of extra pipeline components to operate", "Use serverless Lambda consumers for event processing, gaining auto-scaling and pay-per-use while accepting limits on execution time and less control over infrastructure"], "summary": "This Capital One primer explains event streaming and event-driven architecture at a conceptual level, covering concepts like message brokers, CDC, and serverless consumers. It offers three high-level tips: use brokers to retain and replay past events, add CDC to existing apps, and use Lambda to scale event processing. It is introductory and contains no concrete architecture, metrics or incident details.", "interview_angle": "How would you design an event-driven pipeline that captures database changes and replays events to recover from a consumer failure, and what trade-offs would you make between managed serverless consumers and a self-run streaming cluster?", "score": 0.9155, "hn_points": 0, "hn_comments": 0}, {"url": "https://engineering.grab.com/performance-bottlenecks-go-apps", "company": "Grab", "industry": "mobility", "title": "Performance bottlenecks of Go application on Kubernetes with non-integer (floating) CPU allocation", "date": "2023-05-23", "primary_problem": "performance", "problems": ["platform", "cost"], "post_type": "deep_dive", "level": "advanced", "stack": ["Go", "Kubernetes", "Kafka", "S3", "Vertical Pod Autoscaler"], "scale": "", "key_decisions": ["Set a minimum VPA CPU floor of 2 cores for heavy Kafka-to-S3 pipelines, trading some cost for eliminating lag and throttling.", "Align GOMAXPROCS with Kubernetes CPU limits so the Go runtime sizes its threads to the pod's real allowance, accepting that non-integer CPUs round down.", "Upgrade VPA to a version that recommends integer CPU values, but enable this only for heavy pipelines since it over-provisions light ones."], "summary": "Grab's Coban team found that a Go stream-processing sink to S3 on Kubernetes lagged because VPA shrank CPU below 2 cores while AUTO-GOMAXPROCS rounded down to integers, causing throttling and a feedback loop. Setting a 2-core VPA floor and moving to integer-aware VPA recommendations restored throughput and cleared the backlog.", "interview_angle": "How would you size and autoscale a high-throughput Kafka consumer on Kubernetes so that CPU throttling does not create consumer lag, and what runtime settings must match the container CPU limit?", "score": 0.9138, "hn_points": 0, "hn_comments": 0}, {"url": "https://stripe.com/blog/reproducible-research", "company": "Stripe", "industry": "fintech", "title": "Reproducible research: Stripe\u2019s approach to data science", "date": "2016-11-22", "primary_problem": "governance_privacy", "problems": ["quality", "platform"], "post_type": "deep_dive", "level": "intermediate", "stack": ["Jupyter Notebook", "Redshift", "Hadoop", "Scalding", "Impala", "Git"], "scale": "", "key_decisions": ["Check in only notebook source code and strip outputs in a pre-commit hook, so every report is regenerated from scratch on publish (trade-off: more up-front work, but results are trustworthy)", "Publish notebooks by executing them on shared servers and serving static HTML (trade-off: notebooks must run back to front without manual steps)", "Build a common entry point for query-engine access used on both laptops and servers (trade-off: upfront tooling effort in exchange for removing environment-specific setup)"], "summary": "Stripe describes a workflow for making data science reports reproducible by standardizing on Jupyter Notebooks, stripping outputs before commit, and executing notebooks on shared servers to publish static HTML. The core idea is that anyone should be able to rerun and extend an analysis, and a shared access layer to query engines makes the same code work on laptops and production.", "interview_angle": "How would you make analytical reports reproducible and reviewable across a team, including handling credentials and query-engine access consistently between local and production environments?", "score": 0.9125, "hn_points": 3, "hn_comments": 0}, {"url": "https://www.capitalone.com/tech/open-source/datacompy-fugue-advanced-dataframes", "company": "Capital One", "industry": "fintech", "title": "DataComPy & Fugue: Advanced DataFrames | Capital One", "date": "2024-01-09", "primary_problem": "platform", "problems": ["quality", "performance"], "post_type": "open_source", "level": "intermediate", "stack": ["DataComPy", "Fugue", "Pandas", "Spark", "Dask", "Ray", "Polars", "DuckDB", "Arrow"], "scale": "12 million PyPI downloads", "key_decisions": ["Adopt Fugue as an abstraction layer so DataComPy runs across Pandas, Spark, Dask, Ray and others, trading some native Spark control for broad backend reach", "Use a coarse cogroup-style partition-and-compare approach instead of a join, gaining parallel performance while keeping results consistent with the Pandas comparison", "Allow cross-backend comparisons (e.g. Pandas vs Spark) by delegating conversion to Fugue, rather than building that natively, with a plan to possibly deprecate the native Spark implementation"], "summary": "Capital One describes how its open-source DataComPy library adopted the Fugue abstraction layer to parallelize DataFrame comparisons and compare datasets across different backends such as Pandas, Spark and DuckDB. The post frames the adoption as validated by over 12 million PyPI downloads and outlines next steps toward feature parity and possibly retiring the native Spark path.", "interview_angle": "How would you design a library that reconciles two large datasets for equality across heterogeneous engines (in-memory vs distributed) while keeping results consistent and avoiding a rewrite per backend?", "score": 0.9075, "hn_points": 0, "hn_comments": 0}, {"url": "https://www.capitalone.com/tech/open-source/data-profiler-synthetic-data-integration", "company": "Capital One", "industry": "fintech", "title": "Data Profiler Synthetic Integration Guide | Capital One", "date": "2023-11-20", "primary_problem": "quality", "problems": ["governance_privacy", "ml_data"], "post_type": "deep_dive", "level": "intermediate", "stack": ["Data Profiler", "synthetic-data", "Python"], "scale": "", "key_decisions": ["Profile-driven synthetic generation: derive synthetic data from statistical profiles rather than copying raw rows, trading fidelity for reduced access exposure", "Thin integration layer: wire two open-source libraries together with a few lines of code, keeping a consistent developer experience at the cost of coupling to both APIs", "Built-in validation via profile diff: compare original and synthetic profiles to check similarity, which catches drift but only checks summary statistics, not deeper correlations"], "summary": "Capital One describes an integration between its open-source Data Profiler and synthetic-data libraries that profiles a dataset, generates statistically similar synthetic rows, and validates them with a profile diff. The goal is to reduce access friction in development and testing for regulated financial data.", "interview_angle": "How would you give developers realistic test data without exposing production PII? A good answer covers profiling, synthetic generation, and validating that synthetic data preserves schema and distributions.", "score": 0.9059, "hn_points": 0, "hn_comments": 0}, {"url": "https://www.coinbase.com/blog/data-semantics-the-missing-layer-of-your-data-warehouse", "company": "Coinbase", "industry": "fintech", "title": "Data semantics: the missing layer of your data warehouse", "date": "2020-08-19", "primary_problem": "modeling", "problems": ["lineage_catalog", "platform"], "post_type": "deep_dive", "level": "intermediate", "stack": ["SQL", "YAML"], "scale": "", "key_decisions": ["Define measures and dimensions once in a semantic layer rather than rewriting SQL per question; trade-off is upfront modeling effort and governance of definitions", "Centralize semantic metadata in one orchestrating API as the single source of truth; trade-off is a critical shared dependency and bottleneck", "Decouple storage and compute from the question definition so engines can change; trade-off is reliance on the metadata being accurate about what the data means"], "summary": "Coinbase's data science team describes a semantic layer in which measures and dimensions are declared in YAML on top of warehouse tables, and a central API compiles user questions into SQL. The approach aims to remove repeated query logic, keep metric definitions consistent, and separate storage and compute choices from the business question.", "interview_angle": "How would you design a semantic metrics layer over a warehouse so that analysts ask questions in terms of measures and dimensions, and the system picks the storage location, compiles the SQL, and keeps metric definitions consistent across teams?", "score": 0.9029, "hn_points": 0, "hn_comments": 0}, {"url": "https://engineering.zalando.com/posts/2018/05/many-to-many-using-kafka.html", "company": "Zalando", "industry": "ecommerce", "title": "Zalando Engineering Blog - Many-to-Many Relationships Using Kafka", "date": "2018-05-08", "primary_problem": "realtime", "problems": ["modeling", "cdc_sync"], "post_type": "deep_dive", "level": "advanced", "stack": ["Kafka", "Scala"], "scale": "", "key_decisions": ["Broadcast each Attribute event to every partition of the topic so any partition's consumer can join locally, trading extra writes for no service calls", "Keep a separate Attribute local view per partition so a slow partition cannot overwrite newer data from a fast one, at the cost of storage duplication", "Couple database keys to Kafka partition IDs, which makes adding partitions harder; the team accepts this and overprovisions partitions up front"], "summary": "The post explains how Zalando joins many-to-many entities (Products and Attributes) in an event-driven Kafka pipeline when no single partition key co-locates them. It describes broadcasting reference events to all partitions and keeping per-partition local views, which amounts to a real-time broadcast join, and it notes the storage and partition-growth trade-offs.", "interview_angle": "How would you join two event streams where one side is shared by many entities and has no common key, without calling an external service per event?", "score": 0.8978, "hn_points": 0, "hn_comments": 0}, {"url": "https://www.capitalone.com/tech/open-source/lessons-from-adopting-python-as-a-team", "company": "Capital One", "industry": "fintech", "title": "Lessons for Adopting Python as a Web Team | Capital One", "date": "2023-10-23", "primary_problem": "migration", "problems": ["platform", "quality"], "post_type": "case_study", "level": "intermediate", "stack": ["Python", "Spark", "Pandas", "HDFS", "Parquet", "ELK stack", "Elasticsearch", "Logstash", "Kibana", "pytest", "Java", "NodeJS"], "scale": "", "key_decisions": ["Moved legacy licensed-ETL jobs to Python instead of Java for lighter bootstrap code and Pandas/Spark support; trade-off is retraining a team of web engineers on a new language.", "Used Pandas for small filtered datasets (under about 5MB) and Spark for large HDFS workloads; trade-off is Spark's create-new-dataframe behavior adds overhead on small data.", "Standardized structured logging to ELK and enforced PEP8 plus pytest-based TDD via automation; trade-off is upfront setup time in exchange for consistency in a dynamically typed codebase."], "summary": "A six-person web engineering team at Capital One moved from Java and NodeJS to Python while rewriting legacy licensed ETL jobs that read Parquet files and call enterprise APIs. The post covers the language choice, Pandas versus Spark trade-offs, structured logging to ELK, and tooling for PEP8 and pytest.", "interview_angle": "How would you migrate legacy licensed ETL jobs to an open-source stack, choosing between Pandas and Spark by data size and keeping the codebase observable and testable?", "score": 0.8974, "hn_points": 0, "hn_comments": 0}, {"url": "https://engineering.zalando.com/posts/2017/12/backing-up-kafka-zookeeper.html", "company": "Zalando", "industry": "ecommerce", "title": "Zalando Engineering Blog - Surviving Data Loss", "date": "2017-12-19", "primary_problem": "quality", "problems": ["platform", "cdc_sync"], "post_type": "deep_dive", "level": "intermediate", "stack": ["Kafka", "Kafka Connect", "ZooKeeper", "Exhibitor", "Burry", "S3", "Docker Compose"], "scale": "", "key_decisions": ["Use Kafka Connect with an S3 sink connector to back up topic contents, trading a custom backup pipeline for an off-the-shelf connector with less control over format", "Snapshot ZooKeeper daily with Burry instead of continuous backups, accepting a window of possible loss since daily change is infrequent", "Restore ZooKeeper only after new Kafka brokers have registered their ephemeral znodes, avoiding broker ID conflicts at the cost of a more involved restore sequence"], "summary": "Zalando's small team describes backing up Kafka topic data to S3 using a Kafka Connect S3 sink connector, with a matching restore path via a source connector. They also cover daily ZooKeeper snapshots using Burry and explain how to order restores so ephemeral broker znodes do not conflict with restored state.", "interview_angle": "How would you design a backup and disaster recovery strategy for a Kafka cluster, including topic data and coordination metadata, and what ordering constraints apply during restore?", "score": 0.8968, "hn_points": 0, "hn_comments": 0}, {"url": "https://netflixtechblog.com/datajunction-as-netflixs-answer-to-the-missing-piece-of-the-modern-data-stack-92af926b40a5", "company": "Netflix", "industry": "media", "title": "DataJunction as Netflix\u2019s answer to the missing piece of the modern data stack", "date": "2026-10-14", "primary_problem": "modeling", "problems": ["lineage_catalog", "platform"], "post_type": "open_source", "level": "advanced", "stack": ["DataJunction", "Druid", "Superset"], "scale": "", "key_decisions": ["Chose to build a semantic layer engine centered on SQL parsing and generation over a broader feature set, trading UI and extras for a solid core given limited resources", "Adopted cubes as the first-class serving interface for metrics and dimensions, favoring user familiarity and fast data access over a bespoke query API", "Adopted DataJunction over Mando and Minerva because its graph-based metadata store and SQL generation were stronger, accepting reliance on an open-source project with unofficial support"], "summary": "Netflix describes DataJunction, an open-source metrics semantic layer, and how its experimentation platform adopted it to replace a slow, complex metric onboarding process. The post covers the project's Facebook origins, the API-first and graph-first architecture, and the use of cubes to serve metrics to tools like Druid-backed explorers and Superset.", "interview_angle": "How would you design a metrics layer so that metric definitions are defined once, shared across dashboards and experiments, and still generate consistent SQL for multiple query engines?", "score": 0.8932, "hn_points": 0, "hn_comments": 0}, {"url": "https://engineering.zalando.com/posts/2018/03/data-analysis-spark.html", "company": "Zalando", "industry": "ecommerce", "title": "Zalando Engineering Blog - Data Analysis with Spark", "date": "2018-03-01", "primary_problem": "performance", "problems": ["realtime", "platform"], "post_type": "deep_dive", "level": "intermediate", "stack": ["Spark", "Spark ML", "Hadoop", "Scala"], "scale": "", "key_decisions": ["Use Spark's in-memory processing over Hadoop's disk-based iteration to cut latency for iterative ML training, at the cost of needing enough cluster memory", "Prefer reduceByKey over groupByKey to combine values locally before the network shuffle, trading some code simplicity for less data movement", "Adopt Spark SQL for structured data so pipelines can mix SQL and Scala, accepting a dependency on Spark's query engine"], "summary": "The post explains why Zalando's Digital Experience team chose Apache Spark over Hadoop for analysing large customer datasets, focusing on in-memory computation, lazy transformations versus eager actions, and fault tolerance via lineage replay. It walks through practical tuning ideas such as reduceByKey over groupByKey, partitioners, and Spark SQL for structured data. It is an introductory, conceptual overview rather than a detailed production account.", "interview_angle": "How would you speed up a team's iterative model training and aggregation jobs on large datasets, and which Spark mechanisms (lazy evaluation, shuffle reduction, partitioning) would you use to cut latency?", "score": 0.8898, "hn_points": 0, "hn_comments": 0}, {"url": "https://engineering.zalando.com/posts/2019/03/running-apache-flink-on-kubernetes.html", "company": "Zalando", "industry": "ecommerce", "title": "Zalando Engineering Blog - Running Apache Flink on Kubernetes", "date": "2019-03-22", "primary_problem": "platform", "problems": ["realtime", "governance_privacy"], "post_type": "deep_dive", "level": "advanced", "stack": ["Flink", "Kubernetes", "ZooKeeper", "etcd", "zetcd", "Docker"], "scale": "", "key_decisions": ["Run Flink as a per-job Job Cluster with the job JAR baked into the Docker image, so deployments follow the same git-traceable, two-person review workflow as other JVM apps, at the cost of deviating from the official Kubernetes guidance.", "Run the Job Manager as a Kubernetes Deployment with one replica rather than a Job, so a pod is always running for a never-ending stream, relying on pod restarts instead of hot-standby Job Managers.", "Keep Flink HA mode enabled only to persist checkpoint metadata, backing ZooKeeper with zetcd on the existing etcd cluster instead of adding a new coordination system."], "summary": "Zalando describes how it runs Apache Flink stream processing jobs on Kubernetes, choosing a per-job Job Cluster model so the job artifact ships in a Docker image that satisfies internal compliance rules. The setup uses a Job Manager Deployment, Task Managers scaled per job, and ZooKeeper-compatible checkpoint storage provided by zetcd on etcd.", "interview_angle": "How would you deploy a stateful streaming job on Kubernetes so it recovers from failures and meets audit requirements that every deployed artifact traces to a commit?", "score": 0.8893, "hn_points": 0, "hn_comments": 0}, {"url": "https://www.coinbase.com/blog/how-to-move-fast-with-confidence", "company": "Coinbase", "industry": "fintech", "title": "How to Move Fast with Confidence", "date": "2025-05-28", "primary_problem": "quality", "problems": ["realtime", "late_data"], "post_type": "deep_dive", "level": "advanced", "stack": ["O2 (in-house anomaly detection platform)"], "scale": "1B+ events/day", "key_decisions": ["Model business expectations as causal invariants (cause event to effect event within a deadline) and alert on violations, trading upfront modeling effort for fast detection of unknown failure modes", "Use an event-sourced Extract-Transform-Check pipeline with decoupled stages, enabling independent iteration at the cost of more moving parts", "Apply logic-on-write and logical clocks with watermarks so output is deterministic and state fits in memory, trading raw data retention and replay flexibility for speed"], "summary": "Coinbase describes O2, a real-time event-sourced pipeline that checks business invariants (for example, BTC sends completing within two hours or sell proceeds matching price times amount minus fees) and alerts on deviations. It processes over a billion events daily across more than 50 use cases, using event-time watermarks and in-memory state.", "interview_angle": "How would you design a system that continuously verifies business invariants over a high-volume event stream, handling late events with watermarks and alerting on violations within minutes?", "score": 0.8889, "hn_points": 0, "hn_comments": 0}, {"url": "https://monzo.com/blog/2016/11/30/laying-the-foundation-for-a-data-team", "company": "Monzo", "industry": "fintech", "title": "Laying the foundation for a data team", "date": "2016-11-30", "primary_problem": "platform", "problems": ["cost", "performance"], "post_type": "opinion", "level": "intermediate", "stack": ["BigQuery", "Cassandra", "Kubernetes", "Looker", "Dataflow", "Datastore", "Pub/Sub", "TensorFlow", "Stripe", "Intercom", "Exasol", "AWS"], "scale": "150+ microservices; single gigantic BigQuery event table", "key_decisions": ["Chose fully managed BigQuery over Redshift to avoid staging data in object storage and gain streaming inserts, trading away custom partitioning keys and some query latency", "Recorded all service events into one JSON-payload table instead of snapshotting Cassandra, making analytics independent of production databases at the cost of parsing and sanitising in a separate service", "Gave data scientists end-to-end ownership of pipelines and models on managed infrastructure instead of splitting ETL and modelling roles, trading specialisation for autonomy and faster iteration"], "summary": "Monzo describes how its small data team is built around autonomy, managed analytics infrastructure and automation, centred on a BigQuery event warehouse fed by sanitised microservice events. The post candidly lists BigQuery pain points such as slow small queries and no custom partitioning, along with the Google services used for fraud features and model training.", "interview_angle": "How would you design an analytics platform for a microservices company whose transactional databases (Cassandra) cannot be snapshotted, and what trade-offs come with a single event table in a managed warehouse?", "score": 0.8881, "hn_points": 23, "hn_comments": 2}, {"url": "https://www.capitalone.com/tech/software-engineering/basics-of-using-dynamodb-part-2", "company": "Capital One", "industry": "fintech", "title": "AWS DynamoDB Factors: Performance & Cost | Capital One", "date": "2023-07-24", "primary_problem": "cost", "problems": ["cdc_sync", "storage_formats"], "post_type": "deep_dive", "level": "intermediate", "stack": ["DynamoDB", "Kinesis Data Streams", "AWS Glue", "S3", "DAX"], "scale": "", "key_decisions": ["Reserved capacity versus on-demand or auto-scaled capacity: commit upfront for predictable savings but accept less flexibility", "Global tables replicate writes to every region, multiplying write costs in exchange for regional availability and locality", "Streaming changes via Kinesis or DynamoDB Streams adds per-write CDC charges, trading cost for real-time downstream integration"], "summary": "This is a second-part overview of DynamoDB pricing levers, covering reserved capacity, global tables, backups, change data capture to Kinesis, streams reads, exports to S3, and data transfer. It is a reference-style explainer on how each feature affects the bill rather than a account of a specific internal system. It reads as general AWS cost guidance and is only loosely data engineering.", "interview_angle": "How would you reduce the cost of a DynamoDB-backed pipeline that streams changes to a data lake, and which features add hidden per-write or replication charges?", "score": 0.8866, "hn_points": 0, "hn_comments": 0}, {"url": "https://engineering.zalando.com/posts/2018/04/improving-efficiency-offline-campaigns.html", "company": "Zalando", "industry": "ecommerce", "title": "Zalando Engineering Blog - Improving Efficiency in Offline Campaigns", "date": "2018-04-24", "primary_problem": "scale_ingestion", "problems": ["realtime", "governance_privacy"], "post_type": "case_study", "level": "intermediate", "stack": [], "scale": "", "key_decisions": ["Mandate a standardized partner API with idempotency keys over monthly CSV reports, trading partner effort for real-time, reliable data backhaul", "Require partners to conform to a common sales data schema, accepting onboarding friction in exchange for comparable offline and online campaign metrics", "Stage migration with parallel operation of old and new processes, trading longer timelines for lower risk to customers and revenue"], "summary": "Zalando built a partner-facing REST API to pull offline gift card sales data from retailers and resellers in near real time, replacing monthly CSV reports. The post covers idempotent operations, standardizing proprietary partner data, attribution to specific stores, and using the resulting data for ROI steering and fraud detection.", "interview_angle": "How would you design a partner data backhaul that ingests heterogeneous sales data from many external resellers in near real time while guaranteeing exactly-once effects for financial operations?", "score": 0.8839, "hn_points": 0, "hn_comments": 0}, {"url": "https://shopify.engineering/tangle", "company": "Shopify", "industry": "ecommerce", "title": "Tangle: An open-source ML experimentation platform built at Shopify scale", "date": "2025-12-05", "primary_problem": "ml_data", "problems": ["platform", "cost"], "post_type": "open_source", "level": "intermediate", "stack": ["Tangle", "Docker", "Podman", "HuggingFace Spaces", "HuggingFace Jobs", "HuggingFace Datasets", "SQLite", "XGBoost", "TensorFlow", "GCS", "S3", "YAML"], "scale": "Millions of search queries and billions of products processed; over a year of compute time saved", "key_decisions": ["Content-based caching of task outputs instead of lineage-based caching: fewer re-executions when upstream code changes but outputs match, at the cost of hashing and storing every artifact", "Containerized CLI components with file-based I/O instead of in-memory objects: language-neutral and hermetic, but adds upload/download overhead and no runtime type validation", "Optional, non-enforced typing of artifacts: keeps the system open and fast without central validation, but puts validation burden on each consuming component"], "summary": "Shopify open-sourced Tangle, a visual, platform-agnostic ML experimentation and pipeline platform born from Search & Discovery's need for reproducible, fast-iterating ML data preparation and training. Its core ideas are content-addressed caching shared globally across users, immutable artifacts with full run lineage, and language-neutral containerized components.", "interview_angle": "How would you design a pipeline caching layer that reuses results across teams and even still-running tasks, and what correctness guarantees would you need for deterministic components?", "score": 0.8785, "hn_points": 2, "hn_comments": 1}, {"url": "https://www.capitalone.com/tech/software-engineering/a-modern-dilemma-when-to-consume-from-a-stream-or-a-lake", "company": "Capital One", "industry": "fintech", "title": "A Dilemma: Consume Data from a Stream or a Lake | Capital One Tech", "date": "2026-11-18", "primary_problem": "realtime", "problems": ["late_data", "storage_formats"], "post_type": "opinion", "level": "intermediate", "stack": ["Kafka", "Flink", "Spark", "Delta Lake", "S3", "Parquet"], "scale": "2 million events per second at extreme volume", "key_decisions": ["Pick event streams for sub-second row-level work, accepting higher operational complexity than batch", "Use Delta CDF on S3 with Spark for cheaper high-volume record-level consumption, accepting latency that is rarely sub-second and replay delays", "Choose batch ETL for whole-day or multi-day historical context and large joins, accepting higher latency"], "summary": "The post is a decision framework for choosing between APIs, event streams, Delta CDF and batch ETL to consume data, based on latency, consistency, ordering and duplicate handling. It backs the guidance with use-case characteristics and examples such as deduplication, checksum verification, Flink window joins with late data, and micro-batching.", "interview_angle": "How would you choose between streaming consumption and lake-based (CDF or batch) consumption for a new data product, given latency, ordering, duplicates and cost requirements?", "score": 0.8718, "hn_points": 0, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/kyoto-tycoon-secure-replication", "company": "Cloudflare", "industry": "infra", "title": "Kyoto Tycoon Secure Replication", "date": "2014-12-22", "primary_problem": "governance_privacy", "problems": ["cdc_sync", "platform"], "post_type": "deep_dive", "level": "intermediate", "stack": ["Kyoto Tycoon", "Kyoto Cabinet", "PostgreSQL", "OpenSSL", "TLS"], "scale": "Replication from Postgres to 30 data centers, about 3 seconds full propagation", "key_decisions": ["Encrypt cross-datacenter replication with mutual TLS rather than relying on the network being trusted, at the cost of certificate management and handshake overhead", "Use an internal CA to issue and validate certificates for both replication peers, trading operational burden for controlled trust", "Patch the open-source Kyoto Tycoon directly and publish the changes, adding a fork to maintain instead of a wrapper or tunnel"], "summary": "Cloudflare describes adding mutually authenticated TLS to Kyoto Tycoon, the key-value store it uses to replicate sensitive data such as session ticket keys and DNS data from Postgres to its edge data centers. The change encrypts replication traffic in transit and verifies both peers via client certificates signed by an internal CA, and the code was released open source.", "interview_angle": "How would you secure cross-region replication of sensitive config or key data over untrusted networks while keeping propagation latency low?", "score": 0.8713, "hn_points": 3, "hn_comments": 0}, {"url": "https://dropbox.tech/developers/how-the-dropbox-datastore-api-handles-conflicts-part-two-resolving-collisions", "company": "Dropbox", "industry": "saas", "title": "How the Dropbox Datastore API Handles Conflicts \u2013 Part Two: Resolving Collisions", "date": "2013-08-30", "primary_problem": "quality", "problems": ["cdc_sync", "platform"], "post_type": "deep_dive", "level": "advanced", "stack": ["Dropbox Datastore API"], "scale": "", "key_decisions": ["Resolve conflicts per field with a configurable rule set (remote, local, max, min, sum) rather than one global policy, trading simplicity for predictable merge outcomes", "Model delta merging as a grid of pairwise squares so any traversal order gives the same final state, at the cost of O(N^2) worst-case work", "Treat record deletions as higher-level than field updates so deletes always win, while noting field deletions may switch to null-style semantics"], "summary": "The post explains how the Dropbox Datastore SDK resolves conflicting changes between offline or concurrent clients, working through a single-change algorithm and then merging whole delta lists via a grid of rebased changes. It covers per-field resolution rules, insert-versus-update collisions on manually chosen record IDs, and how field deletions are treated.", "interview_angle": "How would you design conflict resolution for offline-first replicated records so that merging change sets converges regardless of order, and what are the costs of pairwise merging for large deltas?", "score": 0.8647, "hn_points": 0, "hn_comments": 0}, {"url": "https://www.capitalone.com/tech/cloud/serverless-streaming", "company": "Capital One", "industry": "fintech", "title": "Scaling billions of requests with serverless | Capital One", "date": "2019-12-03", "primary_problem": "realtime", "problems": ["scale_ingestion", "cost"], "post_type": "opinion", "level": "intermediate", "stack": ["AWS Lambda", "Amazon Kinesis", "Spark", "Kafka"], "scale": "Thousands of events per second for alerting use cases; tens of events per second for low-volume events; most use cases under 1000 TPS", "key_decisions": ["Serverless Lambda-plus-Kinesis pipelines instead of Spark clusters: far less ops overhead and automatic scaling, but less suited to very high throughput (hundreds of thousands of TPS)", "Build an internal SDK wrapping message bus I/O, retries, secrets, envelopes and dedup: consistent behavior across services, at the cost of maintaining a shared library", "Split pipelines into source, processing and sink layers with configuration-driven components: reusable and easy to fan out, but adds more hops and moving parts"], "summary": "Capital One describes a serverless streaming pattern built on AWS Lambda and Kinesis, organized into source, processing and sink layers, for detecting unusual customer transactions in near real time. The post argues that Spark is overkill for typical low-volume streaming and lays out requirements for scaling, throttling, fault tolerance, reuse and monitoring, plus an internal SDK that handles retries, deduplication and envelopes.", "interview_angle": "How would you design a streaming pipeline for a few thousand events per second that must auto-scale, survive downstream API outages without losing events, and deduplicate at-least-once deliveries, and when would you choose serverless over a Spark cluster?", "score": 0.8332, "hn_points": 0, "hn_comments": 0}, {"url": "https://engineering.zalando.com/posts/2018/01/rock-solid-kafka.html", "company": "Zalando", "industry": "ecommerce", "title": "Zalando Engineering Blog - Rock Solid Kafka and ZooKeeper Ops on AWS", "date": "2018-01-04", "primary_problem": "platform", "problems": ["quality", "cost"], "post_type": "deep_dive", "level": "advanced", "stack": ["Kafka", "ZooKeeper", "Exhibitor", "AWS", "S3", "EC2 Auto Scaling", "Elastic Network Interfaces"], "scale": "", "key_decisions": ["Use static Elastic Network Interfaces instead of changing IPs so Kafka never needs its zookeeper.connect reconfigured or restarted; trade-off is extra AWS setup and AZ-bound ENI pools", "Keep Exhibitor-managed ZooKeeper ensemble with S3-shared config rather than building custom discovery; trade-off is Exhibitor may remove terminated nodes and trigger rolling restarts", "Rely on Auto Scaling Groups for instance replacement while accepting that new instances need the ENI re-attached at boot; trade-off is less automation than EC2 Auto Recovery, which lacks support for some instance types"], "summary": "Zalando describes how a Kafka and ZooKeeper cluster on AWS reacts to instance termination and replacement, showing that new IP addresses force slow rolling restarts across the stack. They propose attaching static Elastic Network Interfaces to replacement instances so that clients keep the same address and no reconfiguration or restarts are needed.", "interview_angle": "How would you keep a stateful messaging cluster highly available on cloud VMs that get replaced automatically, without forcing config changes and rolling restarts across dependent services?", "score": 0.8326, "hn_points": 0, "hn_comments": 0}, {"url": "https://medium.com/airbnb-engineering/project-lighthouse-part-3-introducing-project-lighthouse-anonymize-74f8b26653fb", "company": "Airbnb", "industry": "marketplace", "title": "Project Lighthouse\u200a\u2014\u200aPart 3: Introducing project-lighthouse-anonymize", "date": "2026-08-25", "primary_problem": "governance_privacy", "problems": ["quality", "scale_ingestion"], "post_type": "open_source", "level": "advanced", "stack": ["Python"], "scale": "", "key_decisions": ["Use k-anonymity (Mondrian partitioning) as the privacy model so sensitive attributes cannot be linked to individuals, at the cost of some data distortion", "Parallelize Mondrian with a hybrid recursive-queue model: recursion for small partitions, queues for large ones, trading implementation complexity for throughput on large datasets", "Measure anonymized data usefulness with Pearson correlation, RILM and NMIv1 plus classification-based thresholds, so analysts can judge fitness without deep anonymization expertise"], "summary": "Airbnb open-sourced the Python library behind Project Lighthouse's anonymization pipeline and published two papers on its scalable Mondrian-based k-anonymity algorithm and a data quality framework for anonymized data. The post explains how the privacy model, parallel execution, and quality metrics fit together and how to run the library on a dataset.", "interview_angle": "How would you design a pipeline that anonymizes a large user dataset for analysts while guaranteeing k-anonymity and checking that the output remains statistically useful?", "score": 0.8091, "hn_points": 0, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/cloudflare-k2-streams", "company": "Cloudflare", "industry": "infra", "title": "Announcing Cloudflare K2: serverless event streams", "date": "2026-10-01", "primary_problem": "realtime", "problems": ["scale_ingestion", "storage_formats"], "post_type": "announcement", "level": "advanced", "stack": ["Cloudflare R2", "Cloudflare Workers", "Cloudflare Pipelines", "Cloudflare Queues", "Kafka"], "scale": "Up to 30 MB/s produce per stream in public beta; 10GB storage cap; ~1 s p99 produce latency; 335+ cities", "key_decisions": ["Built the durable log on R2 object storage instead of running Kafka on edge nodes, trading higher produce latency (about 1 s p99) for offloaded replication and consensus and independent compute/storage scaling", "Accumulate writes in memory on an edge service and flush batched segment files, since object stores lack appends; this trades per-event latency for write efficiency", "Use R2 atomic operations for ordering and offsets instead of a separate coordination service, keeping the system simpler but tied to R2 semantics"], "summary": "Cloudflare announces K2, a serverless durable event streaming primitive built as a partitioned log on R2 object storage, motivated by a durable buffer for its Pipelines ingestion product on the edge. The post explains the trade-off of higher produce latency in exchange for simpler, cheaper, independently scaled storage, and how K2 differs from Queues and Pipelines.", "interview_angle": "How would you design a durable, replayable event log on top of object storage with no appends, and what latency and ordering trade-offs would you accept versus running Kafka?", "score": 0.8048, "hn_points": 297, "hn_comments": 112}, {"url": "https://blog.cloudflare.com/cloudflare-data-platform", "company": "Cloudflare", "industry": "infra", "title": "Announcing the Cloudflare Data Platform: ingest, store, and query your data directly on Cloudflare", "date": "2025-09-25", "primary_problem": "platform", "problems": ["scale_ingestion", "storage_formats"], "post_type": "announcement", "level": "intermediate", "stack": ["Cloudflare Pipelines", "Cloudflare R2", "R2 Data Catalog", "R2 SQL", "Iceberg", "Arroyo", "Parquet", "JSON", "Cloudflare Workers", "DuckDB", "Spark", "PyIceberg", "Databricks", "Snowflake"], "scale": "Petabyte-scale queries supported; no specific throughput figures stated", "key_decisions": ["Build ingestion as SQL-transformed streams to sinks (Pipelines on Arroyo) rather than custom consumers: simpler for users, but stateless transforms only for now", "Run automatic small-file compaction inside the managed Iceberg catalog: lower query latency for frequent writes, at the cost of extra maintenance compute and billing", "Use a custom serverless SQL engine (R2 SQL) on edge compute that exploits catalog statistics: no clusters to manage, but currently limited to filter queries"], "summary": "Cloudflare announced a bundled data platform made of Pipelines (streaming ingestion with SQL transforms into Iceberg or Parquet on R2), R2 Data Catalog (managed Iceberg catalog with automatic compaction), and R2 SQL (a serverless distributed query engine). The design focuses on zero-egress storage, usage-based pricing, and removing the need to run clusters for ingestion, maintenance, and querying.", "interview_angle": "How would you design a serverless event ingestion-to-lakehouse pipeline with exactly-once delivery, small-file compaction, and a query layer that avoids managing clusters?", "score": 0.8024, "hn_points": 83, "hn_comments": 17}, {"url": "https://www.capitalone.com/tech/open-source/basics-of-data-profiler", "company": "Capital One", "industry": "fintech", "title": "Data Profiler - An Open Source Solution to Explain Your Data | Capital One", "date": "2021-05-03", "primary_problem": "governance_privacy", "problems": ["quality", "lineage_catalog"], "post_type": "open_source", "level": "intermediate", "stack": ["Python", "Pandas", "Parquet", "Avro", "Data Profiler"], "scale": "", "key_decisions": ["Use a pluggable preprocessor-model-postprocessor pipeline so labelers can be swapped, trading some setup complexity for flexibility across data types", "Ship a default character-level CNN labeler for sensitive entity detection, accepting a fixed label set that needs retraining for new domains", "Profile every column to produce statistics plus sensitive-data classification, favoring broad coverage over a single-purpose PII scanner"], "summary": "Capital One presents Data Profiler, an open source Python library that profiles datasets across formats like CSV, Parquet, Avro and JSON to compute per-column statistics and detect sensitive entities such as SSNs or card numbers. The post emphasizes its swappable labeler pipeline, which lets teams replace the preprocessor, model or postprocessor for custom labels.", "interview_angle": "How would you detect PII leaking into large, heterogeneous data streams without monitoring every record manually, and what trade-offs come with a column-level ML classifier versus regex rules?", "score": 0.799, "hn_points": 1, "hn_comments": 0}, {"url": "https://www.capitalone.com/tech/cloud/lakehouse-format-convergence-delta-lake-iceberg", "company": "Capital One", "industry": "fintech", "title": "Lakehouse Convergence: Delta Lake & Iceberg | Capital One Tech", "date": "2025-11-10", "primary_problem": "storage_formats", "problems": ["lineage_catalog", "migration"], "post_type": "opinion", "level": "intermediate", "stack": ["Delta Lake", "Iceberg", "Delta Lake UniForm", "Databricks", "Snowflake", "Unity Catalog", "Polaris Catalog", "Trino", "Spark", "S3", "Athena", "BigQuery"], "scale": "", "key_decisions": ["Expose a Delta table with Iceberg-compatible metadata (UniForm) instead of maintaining duplicate copies per format; trade-off is asynchronous metadata sync lag and dependence on format feature support", "Center governance on a shared REST-based catalog rather than engine-coupled metastores; trade-off is adding a catalog dependency that becomes the control plane", "Treat format as a delivery detail for data products; trade-off is that write interoperability between formats is still immature, so read-side sharing is the practical path"], "summary": "The article argues that Delta Lake and Apache Iceberg are converging through features like UniForm and shared catalogs, letting one physical dataset serve many engines. It frames the catalog, not the file format, as the new architectural boundary for governance and platform design.", "interview_angle": "How would you design a multi-engine lakehouse so that one dataset is readable from Spark, Trino and a warehouse without duplication, and where would governance live?", "score": 0.7948, "hn_points": 0, "hn_comments": 0}, {"url": "https://engineering.fb.com/2020/07/10/open-source/private-matching", "company": "Meta", "industry": "social", "title": "Private matching for compute: New solutions to the problem of enabling compute on private set intersections", "date": "2020-07-10", "primary_problem": "governance_privacy", "problems": ["ml_data", "scale_ingestion"], "post_type": "open_source", "level": "advanced", "stack": ["Rust", "Paillier encryption", "elliptic curve cryptography (Curve25519)", "rust-paillier crate"], "scale": "Private-ID: 100 million records in 60 minutes; PS3I: 5 million records in 60 minutes", "key_decisions": ["Use double-encryption PSI-style matching so parties never see which records overlap, trading protocol complexity for stronger privacy than revealing matched rows", "Shuffle encrypted sets before exchange to break linkage between ciphertexts, at the cost of extra encryption rounds and communication", "Output only the intersection size (Private-ID) or additive secret shares (PS3I) so downstream MPC can run without repeating matching, trading away direct inner-join output for privacy"], "summary": "Meta open-sourced Private-ID and PS3I, two cryptographic protocols that let two parties align records on a shared identifier without exposing which records matched, so the aligned data can feed MPC or other privacy-preserving computation. The implementation in Rust is parallelizable and reports matching for around 100 million records within an hour.", "interview_angle": "How would you join two parties' datasets for analytics or ML training when neither side can see the other's raw records or match results? Discuss keyed double encryption, shuffling, and what leaks versus what is computed.", "score": 0.7817, "hn_points": 0, "hn_comments": 0}, {"url": "https://www.capitalone.com/tech/open-source/datacompy-open-source-dataframe-comparisons", "company": "Capital One", "industry": "fintech", "title": "DataComPy Open Source Comparison Project | Capital One", "date": "2021-10-20", "primary_problem": "quality", "problems": ["lineage_catalog", "migration"], "post_type": "open_source", "level": "intermediate", "stack": ["DataComPy", "Pandas", "Spark", "Python", "SAS"], "scale": "", "key_decisions": ["Open-sourcing an internal comparison tool after a year of use, trading internal control for community feedback and contributions", "Supporting both Pandas and Spark backends with separate code paths, which duplicates logic but matches the scale of each engine", "Offering configurable tolerances and known-difference transformations, which reduces noise in reports but requires users to define expected mismatches correctly"], "summary": "The post introduces DataComPy, an open-source Python library from Capital One for comparing Pandas and Spark dataframes to validate data across transformations, as a replacement for SAS PROC COMPARE. It explains the row- and column-level reporting, tolerance settings, column mapping, and known-difference transformations used in model-building and ETL validation.", "interview_angle": "How would you design a data reconciliation tool that verifies two systems produce matching results after a migration or transformation, handling tolerances, key mismatches and duplicate keys?", "score": 0.7726, "hn_points": 0, "hn_comments": 0}, {"url": "https://monzo.com/blog/2019/11/04/how-we-scaled-our-data-team-from-1-to-30-people-part-1", "company": "Monzo", "industry": "fintech", "title": "How we scaled our data team from 1 to 30 people (part 1)", "date": "2019-11-04", "primary_problem": "platform", "problems": ["modeling", "quality"], "post_type": "opinion", "level": "intermediate", "stack": ["BigQuery", "dbt", "Looker"], "scale": "30+ people in the data team", "key_decisions": ["Make every backend engineer responsible for emitting analytics events, removing the need for a central data engineering team, at the cost of relying on engineering discipline", "Keep transformations SQL-only in BigQuery with dbt and avoid moving data between servers, trading flexibility for a lower barrier to entry and simpler maintenance", "Tag datasets as crucial or non-crucial to apply stricter change management only where accuracy matters, trading uniform rigor for faster iteration elsewhere"], "summary": "Monzo describes how it scaled its data organisation from a handful of people to over 30 by distributing data collection to backend engineers and having data scientists own SQL-based transformations in BigQuery with dbt. The post frames the operating principles behind this, such as shared data models, Looker for self-serve analytics, and tiered accuracy requirements, and it promises a follow-up on the scaling challenges.", "interview_angle": "How would you design a data platform so that non-central teams can own ingestion and transformation safely, without a bottleneck team and without a tragedy of the commons on shared models?", "score": 0.7716, "hn_points": 0, "hn_comments": 0}, {"url": "https://www.capitalone.com/tech/open-source/sensitive-data-detection-with-data-profiler", "company": "Capital One", "industry": "fintech", "title": "Detecting Sensitive Information in Data with Data Profiler | Capital One", "date": "2021-05-25", "primary_problem": "governance_privacy", "problems": ["quality", "lineage_catalog"], "post_type": "open_source", "level": "intermediate", "stack": ["Data Profiler", "Python", "Pandas", "spaCy"], "scale": "", "key_decisions": ["Use a pretrained data labeler for both structured columns and unstructured text instead of hand-written regex rules, trading setup effort for broader entity coverage", "Disable the other profiler features (stats, type detection) and run only the labeler to keep the scan focused, trading away extra metadata", "Output predictions at character level or as word-level NER spans, trading granularity for interpretability and easier downstream tokenization"], "summary": "The post walks through Capital One's open source Data Profiler library, which uses a neural data labeler to flag PII in both tabular CSV columns and unstructured email text. It shows how to tune the labeler's output format so results map cleanly onto NER-style spans that downstream masking or tokenization can use.", "interview_angle": "How would you design a pipeline that scans a data lake for PII across structured and unstructured files, and where would you place the detection step relative to ingestion and access controls?", "score": 0.7642, "hn_points": 0, "hn_comments": 0}, {"url": "https://www.capitalone.com/tech/cloud/evolution-of-data-lakes", "company": "Capital One", "industry": "fintech", "title": "Understanding the Evolution of Data Lakes | Capital One", "date": "2025-11-06", "primary_problem": "storage_formats", "problems": ["platform", "migration"], "post_type": "opinion", "level": "intermediate", "stack": ["Hadoop", "Hive", "Pig", "MapReduce", "Snowflake", "BigQuery", "Redshift", "Spark", "Databricks", "Delta Lake", "Iceberg", "Hudi", "Unity Catalog", "MLflow"], "scale": "", "key_decisions": ["Choose a classic data lake for cheap, raw, schema-on-read storage, accepting weak governance and slow SQL access", "Choose a cloud warehouse for managed SQL analytics, accepting proprietary storage and limited streaming or unstructured support", "Choose a lakehouse on open table formats for unified batch, streaming and ML, accepting tuning complexity and multi-format governance overhead"], "summary": "The article traces data architecture from Hadoop-era data lakes through cloud warehouses and Spark/Databricks to the lakehouse model built on open table formats. It compares the three approaches across storage, governance, streaming, ML and operational complexity, and argues that vendors and enterprises are converging on blended strategies.", "interview_angle": "How would you choose between a data lake, a cloud warehouse and a lakehouse for a company that needs both BI reporting and near-real-time ML features, and what governance and cost trade-offs would you call out?", "score": 0.7483, "hn_points": 0, "hn_comments": 0}, {"url": "https://www.capitalone.com/tech/cloud/data-lake-zones", "company": "Capital One", "industry": "fintech", "title": "Data Lake Architecture: What is a Zone? | Capital One", "date": "2023-03-31", "primary_problem": "governance_privacy", "problems": ["lineage_catalog", "platform"], "post_type": "opinion", "level": "intermediate", "stack": ["S3"], "scale": "", "key_decisions": ["Organize the lake into purpose-based zones (raw, standardized, consumption, exploratory) rather than one monolithic store; trade-off is more upfront design and governance overhead per zone.", "Keep zones free of overlap and avoid copying data between them; trade-off is that some use cases must read across zones instead of getting convenient duplicates.", "Start with only the zones actually needed and let zone criteria guide expansion; trade-off is a simpler setup at the cost of possibly reworking boundaries later."], "summary": "Capital One argues that a data lake should be organized by consumption rather than just storage, splitting it into zones with distinct access, quality, lifecycle and usage properties. It describes raw, standardized, consumption and exploratory zones and contrasts them with a single-zone \"no-zone\" lake that erodes trust and access control.", "interview_angle": "How would you structure a multi-zone data lake so that raw, curated, product and ML-experimentation data each get appropriate access controls, quality guarantees and lifecycle policies?", "score": 0.7373, "hn_points": 0, "hn_comments": 0}, {"url": "https://www.capitalone.com/tech/cloud/data-lake-vs-data-warehouse", "company": "Capital One", "industry": "fintech", "title": "Data lake vs data warehouse: Comparison | Capital One", "date": "2024-01-19", "primary_problem": "storage_formats", "problems": ["modeling", "cost"], "post_type": "opinion", "level": "intermediate", "stack": [], "scale": "", "key_decisions": ["Schema-on-read lakes trade upfront modeling for flexibility, but push quality and retrieval-latency problems downstream", "Schema-on-write warehouses give consistent, fast BI queries at the cost of rigidity and silos", "ELT on lakes versus ETL on warehouses: transform late for flexibility or early for consistency"], "summary": "This is a conceptual Capital One explainer comparing data lakes and data warehouses across schema, users, processing, scale, cost and design approach. It also briefly covers data marts and lakehouses as alternatives and ends with a generic pitch about the company's use of storage solutions.", "interview_angle": "When would you pick a data lake over a warehouse for a given workload, and how would you mitigate the quality and governance risks of schema-on-read?", "score": 0.732, "hn_points": 0, "hn_comments": 0}, {"url": "https://tech.instacart.com/the-next-era-of-data-at-instacart-e081d8dfa162", "company": "Instacart", "industry": "marketplace", "title": "The Next Era of Data at Instacart", "date": "2023-08-16", "primary_problem": "platform", "problems": ["cdc_sync", "governance_privacy"], "post_type": "announcement", "level": "intermediate", "stack": ["Snowflake", "Debezium", "Kafka", "dbt", "Airflow", "Immuta", "Mode", "Amundsen", "Snowplow", "Segment"], "scale": "Billions of events, hundreds of TB per day across thousands of event types; thousands of CDC tables ingested to Snowflake", "key_decisions": ["Consolidated a dozen-plus Airflow instances and many event frameworks onto one dbt + Airflow deployment and one events system (Snowgoose), trading team autonomy for consistency and lower operational burden", "Moved to attribute-based access control via Immuta rather than static role-based controls, easing scale of policy management but adding dependence on a third-party platform", "Shifted from a large centralized data engineering team to a decentralized model where product engineering teams do their own DE work, trading central bottleneck removal for the need to train and support many engineers"], "summary": "Instacart describes Ground Truth, a half-year initiative that rebuilt its data stack around CDC ingestion into Snowflake, a consolidated events system, a single dbt + Airflow deployment, attribute-based access control, data quality checks and cataloging. The post also argues for moving from large central data engineering teams to a decentralized model where product teams self-serve data work, with LLMs as a future interface to the metadata.", "interview_angle": "How would you consolidate a fragmented data stack (many orchestrators, event frameworks and BI tools) into a self-serve platform while keeping governance, data quality and cost under control?", "score": 0.7087, "hn_points": 0, "hn_comments": 0}, {"url": "https://www.capitalone.com/tech/cloud/data-mesh-for-data-governance", "company": "Capital One", "industry": "fintech", "title": "Data Mesh 2.0: Revolutionizing Data Governance | Capital One", "date": "2024-01-25", "primary_problem": "governance_privacy", "problems": ["platform", "lineage_catalog"], "post_type": "opinion", "level": "intermediate", "stack": [], "scale": "", "key_decisions": ["Centralize ingestion, DQ, metadata and serving on horizontal platforms while keeping domain ownership of data products; trade-off is a heavier central platform team and dependency on it.", "Enforce a basic set of governance controls by default in the platform (schema validation, sensitive data detection, tokenization) with domains layering extra checks; trade-off is less domain flexibility in exchange for consistent compliance.", "Use a shared enterprise data model for cross-domain composite products while letting domains add attributes without changing keys; trade-off is coordination overhead versus interoperability."], "summary": "The post argues that pure data mesh pushes too much end-to-end work and governance burden onto domain teams, leading to cost and inconsistent enforcement. It proposes \"data mesh 2.0\", which keeps domain ownership of data products but moves wrangling, serving and governance into centralized, self-serve horizontal platforms with governance enforced by default.", "interview_angle": "How would you balance domain autonomy with enterprise-wide governance and data quality enforcement in a decentralized data architecture, and which parts would you centralize in a shared platform?", "score": 0.7029, "hn_points": 0, "hn_comments": 0}, {"url": "https://eng.lyft.com/flyte-joins-lf-ai-data-48c9b4b60eec", "company": "Lyft", "industry": "mobility", "title": "Flyte Joins LF AI & Data", "date": "2021-03-18", "primary_problem": "platform", "problems": ["ml_data", "migration"], "post_type": "announcement", "level": "intermediate", "stack": ["Flyte", "flytekit", "AWS Step Functions", "Python", "Java", "Scala", "Flink", "Ray", "Pandera", "Great Expectations", "Vaex"], "scale": "Flyte powers more than 1 million pipelines at Lyft (as of mid 2020)", "key_decisions": ["Moved from AWS Step Functions to a container-native scheduling engine for more flexibility and features, trading away the managed simplicity of a cloud scheduler", "Designed Flyte to be cloud-portable from the start (AWS and GCP) so outside partners could adopt it, at the cost of abstracting away cloud-specific services", "Donated the project to the Linux Foundation AI & Data to build neutral multi-company governance, giving up sole control of the roadmap"], "summary": "Lyft describes how Flyte, its internal orchestrator for ML and data processing jobs, grew from an ETA model-training need into a multi-tenant platform running over a million pipelines, and was open sourced in 2020. The post explains the move from AWS Step Functions to a container-native engine and the rewrite of the flytekit Python SDK, then announces the project's donation to LF AI & Data.", "interview_angle": "How would you design a multi-tenant orchestration platform for both ML training and data pipelines that scales to many teams, separates platform failures from user failures, and stays portable across clouds?", "score": 0.6962, "hn_points": 15, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/d1-turning-it-up-to-11", "company": "Cloudflare", "industry": "infra", "title": "D1: We turned it up to 11", "date": "2023-05-19", "primary_problem": "platform", "problems": ["storage_formats", "performance"], "post_type": "announcement", "level": "intermediate", "stack": ["D1", "SQLite", "Cloudflare Workers", "Wrangler", "Drizzle", "Kysely", "PostgreSQL"], "scale": "Thousands of databases and billions of queries seen during alpha; 500,000-row benchmark table; 1GB database size planned", "key_decisions": ["Rebuilt the storage subsystem on a new backend rather than tuning the alpha, trading migration effort for large read and write speedups", "Bill by read units (per 4KB) and write units (per 1KB) with no extra charge for replicas, making costs predictable but tying spend to scan size and index use", "Implement Time Travel by retaining a write-ahead log of changes to allow point-in-time restore within 30 days, trading storage overhead for recovery capability"], "summary": "Cloudflare announces a new storage backend for D1, its serverless SQLite-based database, claiming large gains in read and write performance. The post also covers pricing based on read and write units, a WAL-backed Time Travel point-in-time restore feature, and a roadmap for bigger databases and automatic replication.", "interview_angle": "How would you design a multi-tenant serverless database service with point-in-time recovery using a write-ahead log, and how would you price reads and writes so cost tracks scan size?", "score": 0.6678, "hn_points": 147, "hn_comments": 79}, {"url": "https://blog.cloudflare.com/cloudflare-acquires-arroyo-pipelines-streaming-ingestion-beta", "company": "Cloudflare", "industry": "infra", "title": "Just landed: streaming ingestion on Cloudflare with Arroyo and Pipelines", "date": "2025-04-10", "primary_problem": "scale_ingestion", "problems": ["realtime", "storage_formats"], "post_type": "announcement", "level": "intermediate", "stack": ["Cloudflare Pipelines", "Cloudflare R2", "Arroyo", "Cloudflare Workers", "Durable Objects", "Iceberg", "Flink", "Kafka", "Rust"], "scale": "Each pipeline scales to ~100,000 records per second; tens of thousands of RPS at launch", "key_decisions": ["Shard ingestion across Durable Objects with embedded SQLite so writes are persisted immediately, trading architectural complexity for horizontal scale and fast acknowledgement", "Batch records into larger NDJSON files with Hive-style date/time partitioning in R2 rather than many tiny files, trading write latency for query efficiency and lower operation costs", "Acquire Arroyo and use SQL as the stream processing API over Flink, trading Flink's maturity and ecosystem for easier use and no JVM operations"], "summary": "Cloudflare launched an open beta of Pipelines, a managed streaming ingestion service that accepts high-volume records over HTTP or Workers and writes batched files to R2 object storage. The post also announces the acquisition of Arroyo, a Rust-based SQL stream processing engine, to add in-flight transformations and Iceberg output later.", "interview_angle": "How would you design a managed, multi-tenant event ingestion service that buffers, batches and writes to object storage with backpressure, durability and zero-downtime pipeline updates?", "score": 0.6645, "hn_points": 5, "hn_comments": 0}, {"url": "https://netflixtechblog.com/data-mesh-a-data-movement-and-processing-platform-netflix-1288bcab2873", "company": "Netflix", "industry": "media", "title": "Data Mesh \u2014 A Data Movement and Processing Platform @ Netflix", "date": "2022-08-01", "primary_problem": "platform", "problems": ["cdc_sync", "realtime"], "post_type": "announcement", "level": "advanced", "stack": ["Kafka", "Flink", "Avro", "Iceberg", "Elasticsearch", "CockroachDB", "Cassandra", "MySQL", "PostgreSQL", "DBLog"], "scale": "", "key_decisions": ["Expose Data Mesh as a general data movement and processing platform rather than a CDC-only product, trading a broader scope for more complexity in the control plane", "Use Kafka topics as the shared transport between Flink processors, enabling reuse and sharing of intermediate streams at the cost of extra topics and hops", "Enforce Avro schemas on all pipelines as a first-class concept, improving data quality and lineage granularity while requiring compatibility checks and automated schema-evolution upgrades"], "summary": "Netflix introduces Data Mesh, its next-generation managed platform for moving and processing data between internal systems, evolving from a CDC-focused product into a general pipeline system. The post outlines the control plane/data plane split, connectors, Flink-based processors, Kafka transports and schema enforcement, and previews the roadmap toward feature parity with Keystone and Delta.", "interview_angle": "How would you design a self-serve streaming platform that supports CDC sources, reusable processing steps, and shared intermediate topics while enforcing schemas and tracking lineage?", "score": 0.6601, "hn_points": 5, "hn_comments": 1}, {"url": "https://blog.cloudflare.com/cloudflare-basin", "company": "Cloudflare", "industry": "infra", "title": "Introducing Cloudflare Basin: an open, serverless data platform, now generally available", "date": "2026-10-01", "primary_problem": "platform", "problems": ["storage_formats", "scale_ingestion"], "post_type": "announcement", "level": "intermediate", "stack": ["Iceberg", "Cloudflare R2", "Cloudflare Workers", "DuckDB", "Snowflake", "Spark", "PyIceberg", "Terraform", "SQL"], "scale": "Pipelines ingest up to 3 GB/s per stream", "key_decisions": ["Built on open Apache Iceberg and R2 so data stays portable across engines, trading tight integration for interoperability", "Serverless usage-based pricing with zero egress fees instead of provisioned clusters, which favors bursty and small workloads but shifts cost unpredictability to users", "Automatic compaction, snapshot expiration and manifest optimization handled by the catalog itself rather than external Spark maintenance jobs, trading control for operational simplicity"], "summary": "Cloudflare made its Data Platform generally available as Basin, a serverless stack of ingestion (Pipelines), an Iceberg REST catalog with automatic table maintenance, and a distributed SQL engine that queries Iceberg tables on R2. The post describes the product's growth since beta, including up to 3 GB/s per stream ingestion and new catalog maintenance features, along with the roadmap.", "interview_angle": "How would you design a serverless analytics platform on object storage with an open table format, covering ingestion throughput, automatic compaction and snapshot cleanup, and query planning with statistics?", "score": 0.6577, "hn_points": 2, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/data-anywhere-events-pipelines-durable-execution-workflows", "company": "Cloudflare", "industry": "infra", "title": "Data Anywhere with Pipelines, Event Notifications, and Workflows", "date": "2024-04-03", "primary_problem": "scale_ingestion", "problems": ["realtime", "platform"], "post_type": "announcement", "level": "intermediate", "stack": ["Cloudflare R2", "Cloudflare Workers", "Cloudflare Queues", "Cloudflare Workflows", "Cloudflare Pipelines", "Workers KV", "D1", "Vectorize", "Workers AI", "Kafka", "ClickHouse", "Databricks"], "scale": "tens of thousands of events per second (ingestion target)", "key_decisions": ["Expose ingestion over HTTP, WebSocket and Kafka-compatible endpoints so producers need no infrastructure changes, at the cost of building and operating protocol adapters", "Batch and partition incoming events by key before writing to R2 in query-ready formats, trading some latency for fewer, larger objects that are cheaper to query", "Drive downstream processing from R2 event notifications via Queues and durable Workflows steps, favoring retries and observability over a simpler polling design"], "summary": "Cloudflare announces Pipelines, a streaming ingestion service that batches, partitions and writes events to R2 in query-ready form, alongside R2 Event Notifications and a Workflows durable-execution engine. The post frames these as building blocks for a full data platform covering ingestion, storage and querying, with zero egress fees.", "interview_angle": "How would you design a managed ingestion endpoint that accepts tens of thousands of events per second over multiple protocols, batches them into large partitioned files in object storage, and triggers downstream processing when new data lands?", "score": 0.648, "hn_points": 19, "hn_comments": 1}, {"url": "https://netflixtechblog.com/a-recap-of-the-data-engineering-open-forum-at-netflix-6b4d4410b88f", "company": "Netflix", "industry": "media", "title": "A Recap of the Data Engineering Open Forum at Netflix", "date": "2024-06-20", "primary_problem": "platform", "problems": ["realtime", "quality"], "post_type": "announcement", "level": "intermediate", "stack": ["Kafka", "Spark", "SQLMesh", "Snowflake"], "scale": "Approximately 18 billion impressions daily; hundreds of thousands of workflows and millions of jobs daily", "key_decisions": ["Adding ML-driven auto remediation on top of a rule-based error classifier trades added model complexity for less manual on-call toil on big data job failures", "Delivering impressions in near real time instead of batch trades infrastructure cost and complexity for more responsive recommendations and adaptive pages", "Unbundled storage with open table formats versus a bundled warehouse trades some performance and governance convenience for flexibility and engine choice"], "summary": "Netflix recaps its inaugural Data Engineering Open Forum, a set of talks spanning ML-assisted job failure remediation, near-real-time impression delivery, post-GDPR platform design, warehouse unbundling, data quality scoring, and SQLMesh-based pipeline development. The post is an event roundup rather than a single deep technical write-up, so its value lies in pointers to the individual talks.", "interview_angle": "How would you design an auto-remediation layer for a large batch platform where thousands of job failures occur daily, combining rule-based classification with ML and keeping humans in the loop?", "score": 0.6322, "hn_points": 0, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/d1-open-beta-is-here", "company": "Cloudflare", "industry": "infra", "title": "D1: open beta is here", "date": "2023-09-28", "primary_problem": "platform", "problems": ["storage_formats", "cost"], "post_type": "announcement", "level": "intermediate", "stack": ["D1", "Workers", "Hyperdrive", "SQLite", "Drizzle ORM", "Kysely", "Wrangler", "GraphQL"], "scale": "Up to 2GB per database, 50,000 databases per account, 100,000+ databases for Workers for Platforms users", "key_decisions": ["Chose SQL-based interface over a custom query language so existing ORMs and tools work with minimal effort, trading away a bespoke API optimized for the platform", "Built Time Travel as always-on point-in-time recovery using append-only bookmarks at no extra cost, trading storage overhead and restore complexity for safer operations", "Switched billing from bytes to rows read/written so costs are easier to predict, while making indexes directly reduce cost"], "summary": "Cloudflare announces open beta for D1, its serverless SQL database, raising per-database storage to 2GB and account database counts to 50,000. The post explains Time Travel point-in-time recovery built on bookmarks, a row-based pricing model, and plans for read replication and GA in Q1 2024.", "interview_angle": "How would you design a per-tenant database platform with point-in-time recovery and usage-based pricing for tens of thousands of small databases, and what cold-start and restore trade-offs would you address?", "score": 0.6309, "hn_points": 14, "hn_comments": 0}, {"url": "https://medium.com/walmartglobaltech/kafka-inconsistencies-and-the-silent-failures-behind-real-time-decision-platforms-f6db55156286", "company": "Walmart", "industry": "retail", "title": "Kafka Inconsistencies and the Silent Failures Behind Real-Time Decision Platforms", "date": "2026-09-30", "primary_problem": "realtime", "problems": ["late_data", "quality"], "post_type": "opinion", "level": "advanced", "stack": ["Kafka", "Flink", "Kafka Streams"], "scale": "", "key_decisions": ["Partition by a stable entity key for per-entity ordering, accepting uneven load and making key changes a correctness change", "Consumer-side idempotency keyed on durable event IDs over relying on producer idempotence alone, at the cost of extra state", "Ship behavior changes behind feature flags or versioned consumer groups rather than letting a rolling deploy mix two code versions in one group, trading operational complexity for determinism"], "summary": "The post is a conceptual field guide to silent Kafka failures (duplicates, out-of-order events, stale consumers, silent loss, and mixed-version rolling deploys) that let real-time risk decisions go wrong while dashboards stay green. It illustrates these with a composite incident and offers mitigations such as event-time windowing, reconciliation, DLQ monitoring, and decoupling deploys from behavior changes.", "interview_angle": "How would you design a Kafka-based real-time risk decision pipeline so that duplicates, late events, and rolling deploys cannot silently change decisions, and how would you detect when they do?", "score": 0.6122, "hn_points": 0, "hn_comments": 0}, {"url": "https://shopify.engineering/shopifys-data-science-engineering-foundations", "company": "Shopify", "industry": "ecommerce", "title": "Shopify's Data Science & Engineering Foundations", "date": "2020-06-18", "primary_problem": "modeling", "problems": ["quality", "lineage_catalog"], "post_type": "opinion", "level": "intermediate", "stack": ["Spark", "Presto", "GitHub"], "scale": "", "key_decisions": ["Adopt Kimball dimensional modelling as one company-wide standard so tables join predictably, trading some flexibility for cross-team compatibility", "Keep a single modelling platform in one shared repo on Spark with a company-wide Presto cluster, trading access control overhead for openness (PII excluded)", "Require unit tests and peer review (at least two reviewers) on all pipeline and analysis code, trading development speed for accuracy and trust"], "summary": "Shopify's data team describes the foundational practices behind its warehouse: a shared dimensional modelling standard, one Spark-based modelling repo, a company-wide Presto cluster, and mandatory unit tests and peer review. The post frames these as the reasons analysts can reuse work and reproduce key metrics quickly.", "interview_angle": "How would you design a company-wide warehouse so that many teams can build and reuse models while keeping metrics reproducible and PII restricted?", "score": 0.6006, "hn_points": 205, "hn_comments": 25}, {"url": "https://www.capitalone.com/tech/cloud/data-management-at-scale", "company": "Capital One", "industry": "fintech", "title": "Managing Data at Scale | Capital One", "date": "2025-05-08", "primary_problem": "governance_privacy", "problems": ["platform", "lineage_catalog"], "post_type": "opinion", "level": "intermediate", "stack": [], "scale": "", "key_decisions": ["Domain-level data ownership with distributed approval instead of centralized gatekeeping: faster team autonomy, but governance depends on consistent standards across domains", "API contracts as the governance mechanism for service and data access: enforceable and explicit permissions, but requires upfront contract design and discipline", "Central catalog plus automated scanning, lineage and access controls: reduces duplication and human error, but needs investment in tooling before it pays off"], "summary": "Capital One describes its \"You Build, Your Data\" model, which pairs distributed domain ownership with automated governance such as a central dataset catalog, API contracts and self-service pipelines. The post is high-level and focuses on balancing team velocity against consistent governance rather than on specific technical implementations or metrics.", "interview_angle": "How would you design a self-service data platform where domain teams own their datasets but governance (access control, PII scanning, deduplication) is still enforced consistently across the organization?", "score": 0.5973, "hn_points": 0, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/spend-management", "company": "Cloudflare", "industry": "infra", "title": "Introducing Spend Management: Spending limits and alerts for Cloudflare", "date": "2026-11-13", "primary_problem": "cost", "problems": ["scale_ingestion", "realtime"], "post_type": "announcement", "level": "advanced", "stack": ["Quicksilver", "Cloudflare Email Service"], "scale": "More than 10 million developers on the platform; usage aggregated in one-minute and five-minute windows", "key_decisions": ["Two-stage metering pipeline (1-minute then 5-minute aggregates) cuts raw event volume before rating, at the cost of added latency before spend is visible", "Account-partitioned Usage Engine with local state and WAL keeps pricing state together, trading cross-partition coordination for partition-level recovery work", "Asynchronous cap enforcement via global key-value replication keeps rating out of the request path, accepting near-real-time (under 10 minutes) rather than instant blocking"], "summary": "Cloudflare describes Spend Management, a billing-driven metering and rating system that aggregates usage from its global network, prices accumulated spend per account, and propagates spending caps to edge nodes asynchronously. The design centers on two-stage aggregation, account-partitioned processing with durable state, and handling out-of-order usage and subscription streams.", "interview_angle": "How would you design a usage metering and billing pipeline that aggregates billions of events, tolerates out-of-order usage and subscription updates, and enforces spend limits globally without putting pricing computation in the request path?", "score": 0.5888, "hn_points": 6, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/ai-search-agent-primitive", "company": "Cloudflare", "industry": "infra", "title": "AI Search: the search primitive for your agents", "date": "2026-04-16", "primary_problem": "platform", "problems": ["storage_formats", "ml_data"], "post_type": "announcement", "level": "intermediate", "stack": ["Cloudflare Workers", "AI Search", "R2", "Vectorize", "Workers AI", "Agents SDK", "Wrangler", "Durable Objects", "BM25"], "scale": "Limits: up to 1M files per instance (paid), 5,000 instances per account (paid)", "key_decisions": ["Bundle built-in storage and vector index per instance instead of requiring users to wire R2 and sync jobs, trading flexibility for simpler onboarding and faster indexing", "Run BM25 keyword and vector search in parallel and fuse with reciprocal rank fusion, trading extra query work for exact-term recall that embeddings miss", "Expose runtime namespace APIs to create one instance per agent, customer or tenant, trading per-instance overhead for isolation without redeployment"], "summary": "Cloudflare announces AI Search, a managed retrieval service for agents that adds hybrid vector and BM25 search, built-in per-instance storage and indexing, metadata boosting, and cross-instance querying. The post walks through a customer-support agent example and lists beta limits and pricing intentions.", "interview_angle": "How would you design a per-tenant search indexing pipeline that ingests documents, chunks and indexes them, keeps the index fresh, and combines keyword and vector retrieval with fusion and reranking?", "score": 0.5845, "hn_points": 3, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/building-d1-a-global-database", "company": "Cloudflare", "industry": "infra", "title": "Building D1: a Global Database", "date": "2024-04-01", "primary_problem": "cdc_sync", "problems": ["platform", "performance"], "post_type": "announcement", "level": "intermediate", "stack": ["D1", "SQLite", "Durable Objects", "Cloudflare Workers", "Drizzle ORM", "Prisma", "Wrangler"], "scale": "Databases up to 10 GB, 50K databases per Workers Paid plan", "key_decisions": ["Read replication with sequential consistency via commit tokens and Lamport timestamps instead of strict routing to one replica: enables low latency reads anywhere but requires clients to round-trip tokens", "Keep writes on a single primary and route reads to any replica that has caught up to the session token: total write ordering preserved at the cost of replica lag on reads", "Use Durable Objects to guarantee a single active copy for default snapshot isolation: simple correctness but limits geographic read distribution unless opt-in Sessions API is used"], "summary": "Cloudflare describes D1, its serverless SQLite-based relational database, reaching general availability, and previews a global read replication design built on the Sessions API. The core idea is to deliver sequential consistency across asynchronous replicas by attaching commit tokens to queries so replicas delay reads until they have caught up.", "interview_angle": "How would you offer low-latency reads from geographically distributed replicas while preserving read-your-own-writes for a user session, and what trade-offs does a commit-token or Lamport-timestamp approach introduce compared with routing everything to one primary?", "score": 0.5789, "hn_points": 5, "hn_comments": 0}, {"url": "https://netflixtechblog.com/from-facts-metrics-to-media-machine-learning-evolving-the-data-engineering-function-at-netflix-6dcc91058d8d", "company": "Netflix", "industry": "media", "title": "From Facts & Metrics to Media Machine Learning: Evolving the Data Engineering Function at Netflix", "date": "2025-08-21", "primary_problem": "ml_data", "problems": ["storage_formats", "lineage_catalog"], "post_type": "announcement", "level": "intermediate", "stack": ["LanceDB", "AMP"], "scale": "", "key_decisions": ["Build a dedicated Media Data Lake with a central media table rather than keep media metadata scattered across domain systems, trading upfront modeling effort for consistent access", "Pilot a new vector-oriented storage engine (LanceDB) on a small 'data pond' scoped to video/audio before committing broadly, trading breadth for lower adoption risk", "Split access into online lightweight exploration and offline batch processing with GPU inference, trading architectural complexity for fit to both interactive and ML training workloads"], "summary": "Netflix describes formalizing a Media Data Engineering specialization around a Media Data Lake that stores media assets (video, audio, subtitles, scripts) and their ML-derived metadata. The team piloted LanceDB on a small video/audio dataset sourced from its asset management system to support model training, evaluation, and media search.", "interview_angle": "How would you design a data lake for unstructured media assets that must serve both interactive exploration and large batch ML training, including storing embeddings alongside metadata and keeping lineage across modalities?", "score": 0.5774, "hn_points": 3, "hn_comments": 0}, {"url": "https://dropbox.tech/developers/converting-the-dropbox-activity-log-into-common-event-framework-", "company": "Dropbox", "industry": "saas", "title": "Converting the Dropbox Activity Log into Common Event Format Events", "date": "2020-04-10", "primary_problem": "migration", "problems": ["governance_privacy", "scale_ingestion"], "post_type": "open_source", "level": "intermediate", "stack": ["Dropbox API", "Python", "Syslog", "CSV"], "scale": "", "key_decisions": ["Map Dropbox activity log fields onto CEF header and extension keys, keeping nested JSON in custom string fields, which preserves detail but makes downstream parsing harder", "Assign each event category a fixed severity rank that users can override, trading nuance for simple, consistent alerting", "Poll with the team_log cursor and handle expiry with reset exceptions, which supports incremental pulls but requires storing cursor state and recovering when it lapses"], "summary": "The post walks through pulling events from Dropbox Business's team activity log API and converting each event into the ArcSight Common Event Format for SIEM tools. It includes a Python script that filters, transforms, and ships events to a syslog server or CSV, with a configurable severity mapping by category.", "interview_angle": "How would you export audit log events from a SaaS API into a SIEM, handling pagination, cursor expiry, schema mapping, and severity normalization?", "score": 0.5731, "hn_points": 0, "hn_comments": 0}, {"url": "https://engineering.zalando.com/posts/2017/12/recipe-for-kafka-lag-monitoring.html", "company": "Zalando", "industry": "ecommerce", "title": "Zalando Engineering Blog - A Recipe for Kafka Lag Monitoring", "date": "2017-12-05", "primary_problem": "realtime", "problems": ["platform", "quality"], "post_type": "open_source", "level": "intermediate", "stack": ["Kafka", "Akka HTTP", "Scala", "Docker"], "scale": "", "key_decisions": ["Built a small custom lag monitor (Remora) instead of adopting Burrow, Kafka Manager or Kafka Lag Monitor, trading reuse of existing tools for a simpler app the team controls", "Wrapped Kafka's Java command-line tools in an Akka HTTP service, favoring the team's existing Scala skills over a lower-level implementation", "Exposed lag metrics to the existing metrics system via scraping, keeping monitoring independent of the streaming infrastructure it observes"], "summary": "Zalando describes Remora, a small open-sourced application that tracks Kafka consumer lag and pushes metrics into its metrics system. The post explains why lag monitoring matters for streaming architectures and why existing tools like Burrow and Kafka Manager were rejected in favor of a lightweight Scala/Akka HTTP wrapper around Kafka's CLI tools.", "interview_angle": "How would you design consumer lag monitoring for a large Kafka deployment across many teams, and what signals and alerts would you expose?", "score": 0.5703, "hn_points": 0, "hn_comments": 0}, {"url": "https://www.capitalone.com/tech/machine-learning/improved-data-quality", "company": "Capital One", "industry": "fintech", "title": "5 Reasons to Use ML for Better Data Quality | Capital One", "date": "2023-01-11", "primary_problem": "quality", "problems": ["ml_data", "lineage_catalog"], "post_type": "opinion", "level": "intermediate", "stack": ["Data Profiler"], "scale": "200,000 data feeds monitored (example figure)", "key_decisions": ["Use ML-driven automation for data quality triage instead of manual rule writing, trading upfront model build effort for lower ongoing staffing load", "Suppress low-severity alerts with ML so humans only see serious issues, risking missed edge cases that rules would catch", "Apply ML anomaly and changepoint detection to spot unexpected shifts, accepting false positives and the need for tuning"], "summary": "Capital One argues that machine learning can ease enterprise data quality work through automation, rule dissemination at scale, smarter alerting, anomaly detection and root cause analysis. The post is mostly a vendor-style opinion piece with little architectural detail, pointing to its open-sourced Data Profiler as one example.", "interview_angle": "How would you design an ML-assisted data quality monitoring system across thousands of feeds that minimizes alert fatigue while still catching anomalies and tracing root causes?", "score": 0.5644, "hn_points": 0, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/r2-local-uploads", "company": "Cloudflare", "industry": "infra", "title": "Improve global upload performance with R2 Local Uploads", "date": "2026-02-03", "primary_problem": "storage_formats", "problems": ["scale_ingestion", "migration"], "post_type": "announcement", "level": "advanced", "stack": ["Cloudflare R2", "Cloudflare Workers", "Durable Objects", "Cloudflare Queues", "Wrangler"], "scale": "Synthetic test: about 20 PutObject requests per second for 30 minutes, 5 MB objects; up to 75% lower TTLB", "key_decisions": ["Write object data to the client's region first and replicate asynchronously to the bucket region, trading temporary cross-region replica lag for much faster uploads while keeping reads strongly consistent.", "Publish metadata atomically with a pending-replica record and timestamped replication markers, giving at-least-once scheduling but requiring a background scanner and idempotent retries.", "Use a centralized pull-based poller over sharded regional queues to pace cross-region copies, reducing network pressure and cost at the expense of extra coordination components."], "summary": "Cloudflare describes R2 Local Uploads, which writes object data to a storage location near the client and then asynchronously copies it to the bucket's region while keeping the object immediately readable. The design uses atomically published metadata, replication markers, sharded regional Queues and a pull-based poller that dispatches copy jobs to the Gateway Worker.", "interview_angle": "How would you design a cross-region write path that acknowledges uploads locally but replicates to a home region asynchronously, while guaranteeing consistency, retries and controlled cross-region bandwidth?", "score": 0.5547, "hn_points": 5, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/workers-analytics-engine", "company": "Cloudflare", "industry": "infra", "title": "Introducing Workers Analytics Engine", "date": "2022-05-12", "primary_problem": "platform", "problems": ["realtime", "performance"], "post_type": "announcement", "level": "intermediate", "stack": ["Cloudflare Workers", "Wrangler", "Grafana", "Prometheus", "GraphQL"], "scale": "10s of millions of events per second", "key_decisions": ["Expose a schemaless-ish blob/double data point model instead of Prometheus-style labels, trading strict schema for unlimited cardinality of blob values", "Accept a few seconds of reporting latency in exchange for push-based writes rather than scrape intervals of a minute or more", "Ship a beta limited to one binding per worker and positional field ordering, deferring named fields and richer dashboards to later iterations"], "summary": "Cloudflare introduces Workers Analytics Engine, a managed time-series and event analytics service that Workers can write structured data points to and query with SQL. The post argues that a relational event model avoids the cardinality and long-range query problems of Prometheus-style metrics systems.", "interview_angle": "How would you design a per-tenant telemetry store that supports high-cardinality labels, seconds-level freshness, and fast queries across days of data, versus a scrape-based metrics stack?", "score": 0.5502, "hn_points": 15, "hn_comments": 3}, {"url": "https://blog.cloudflare.com/making-full-stack-easier-d1-ga-hyperdrive-queues", "company": "Cloudflare", "industry": "infra", "title": "Making state easy with D1 GA, Hyperdrive, Queues and Workers Analytics Engine updates", "date": "2024-04-01", "primary_problem": "platform", "problems": ["cdc_sync", "scale_ingestion"], "post_type": "announcement", "level": "intermediate", "stack": ["D1", "Hyperdrive", "Queues", "Workers Analytics Engine", "ClickHouse", "PostgreSQL", "MySQL", "Drizzle", "Kubernetes"], "scale": "over 2 million developers; at least one data point written on nearly every request to Cloudflare's network; D1 databases up to 10GB, 50,000 per account", "key_decisions": ["Making Hyperdrive free on Workers Paid (drops revenue but removes latency barrier to adoption) while keeping query caching and connection pooling at the edge", "Pull-based Queues consumers over HTTP let workers run anywhere, at the cost of managing leases, visibility timeouts and acks on the client side", "Usage-based pricing for Workers Analytics Engine on data points written and read queries, trading simple napkin math for no cardinality penalty on the provider side"], "summary": "Cloudflare announces general availability of D1 (serverless SQL), Hyperdrive (edge connection pooling and query caching for existing databases), and Workers Analytics Engine (ClickHouse-backed time-series analytics), plus pull-based consumers and delayed delivery for Queues. The post is a product announcement that describes features, roadmap items like D1 read replication with session consistency, and pricing changes.", "interview_angle": "How would you design a serverless analytics ingestion path for high-cardinality event data, and what trade-offs come with pull-based queue consumers versus push delivery?", "score": 0.5489, "hn_points": 4, "hn_comments": 0}, {"url": "https://www.capitalone.com/tech/cloud/4-tips-for-spark-and-nosql", "company": "Capital One", "industry": "fintech", "title": "Can Spark Applications Coexist with NoSQL Databases? | Capital One", "date": "2021-11-29", "primary_problem": "performance", "problems": ["platform"], "post_type": "opinion", "level": "intermediate", "stack": ["Spark", "Cassandra", "MongoDB"], "scale": "", "key_decisions": ["Design Cassandra schemas around query patterns rather than entities, accepting data duplication across tables to keep reads on partition keys", "Manage MongoDB client connections at JVM or partition level to avoid opening excessive connections from Spark executors, trading some setup complexity for cluster stability", "Add MongoDB indexes for update-heavy lookups instead of full collection scans, accepting extra write overhead"], "summary": "The post uses a theme-park analogy to share four practical tips for running Spark jobs against Cassandra and MongoDB backends, drawn from building a cloud-native card transaction platform. The tips cover partition key ordering, use-case-driven schema design, connection management, and indexing to avoid scans and overload.", "interview_angle": "How would you design reads and writes between Spark batch jobs and an operational NoSQL store so that queries hit partition keys and the database cluster is not overloaded by connection churn or full scans?", "score": 0.536, "hn_points": 0, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/logexplorer-ga", "company": "Cloudflare", "industry": "infra", "title": "Cloudflare Log Explorer is now GA, providing native observability and forensics", "date": "2025-06-18", "primary_problem": "storage_formats", "problems": ["scale_ingestion", "performance"], "post_type": "announcement", "level": "advanced", "stack": ["Cloudflare R2", "Parquet", "Delta Lake", "Apache DataFusion", "delta-rs", "Rust", "Buftee"], "scale": "Logs from 330+ cities in 125+ countries; scale figures not stated", "key_decisions": ["Write batches as Parquet to R2 and use a Delta Lake transaction log with min/max stats so queries only fetch relevant files, trading extra metadata management for pruning.", "Stage and squash commits from many ingested batches before committing to the Delta log, avoiding a flood of small files at the cost of some commit latency.", "Replace stock Delta compaction (size-based bin packing) with a custom algorithm that merges batches by minimum timestamp, improving time-range locality at the cost of bespoke maintenance."], "summary": "Cloudflare describes Log Explorer, a SQL-queryable log store built on R2 with Parquet files managed through a Delta Lake transaction log, queried with DataFusion and delta-rs. The post focuses on avoiding small-file fragmentation through batching, commit squashing and a timestamp-aware compaction that cut file overlap and sped up time-range queries.", "interview_angle": "How would you design a per-tenant log store on object storage that keeps time-range queries fast despite continuous small-batch ingestion?", "score": 0.5351, "hn_points": 0, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/r2-data-catalog-public-beta", "company": "Cloudflare", "industry": "infra", "title": "R2 Data Catalog: Managed Apache Iceberg tables with zero egress fees", "date": "2025-04-10", "primary_problem": "storage_formats", "problems": ["lineage_catalog", "platform"], "post_type": "announcement", "level": "intermediate", "stack": ["Iceberg", "Cloudflare R2", "PyIceberg", "PyArrow", "Snowflake", "Spark", "Trino", "DuckDB", "ClickHouse"], "scale": "", "key_decisions": ["Build the catalog directly into the R2 bucket and expose a standard Iceberg REST catalog, avoiding extra infrastructure but tying users to R2's catalog service", "Charge zero egress fees so multi-cloud engines can read data cheaply, while deferring catalog operation and compaction pricing until later", "Defer automatic compaction of small files to a later release, leaving early users to handle file layout themselves in exchange for a faster beta launch"], "summary": "Cloudflare launched an open beta of R2 Data Catalog, a managed Apache Iceberg REST catalog built into R2 buckets so teams can skip running their own catalog. The post explains Iceberg metadata (schemas, snapshots, partition specs) and why a catalog is needed to coordinate multi-engine access, with zero egress fees as a selling point.", "interview_angle": "How would you design a managed Iceberg catalog on object storage so that multiple engines (Spark, Trino, Snowflake) can safely read and write the same tables without an external service?", "score": 0.533, "hn_points": 47, "hn_comments": 8}, {"url": "https://blog.cloudflare.com/ai-search-ga", "company": "Cloudflare", "industry": "infra", "title": "AI Search is now generally available", "date": "2026-10-01", "primary_problem": "ml_data", "problems": ["storage_formats", "cost"], "post_type": "announcement", "level": "intermediate", "stack": ["Cloudflare AI Search", "Workers AI", "Vectorize", "R2", "Browser Run", "Qwen3-VL-Embedding"], "scale": "10 MiB max file size (up from 4 MiB); 5M free ingestion tokens per month", "key_decisions": ["Embed image pixels natively with a multimodal model while keeping captions, trading higher embedding cost and complexity for better visual recall; text-only models fall back to captioning queries.", "Use Matryoshka Representation Learning so smaller embedding vectors keep useful information, lowering storage footprint and search latency at some loss of fidelity.", "Bill by ingested tokens, stored GB, and query type rather than instance hours, simplifying cost estimation but making costs depend on content volume and query mix."], "summary": "Cloudflare moves its managed AI Search retrieval pipeline to general availability, adding native image embeddings, OCR for scanned PDFs, and larger file limits. The post also introduces usage-based billing starting November 2026, with ingestion, storage and query pricing and a free tier.", "interview_angle": "How would you design a managed ingestion-embedding-index pipeline that supports multimodal content, OCR, and usage-based pricing without requiring users to size capacity up front?", "score": 0.532, "hn_points": 3, "hn_comments": 0}, {"url": "https://netflixtechblog.com/our-first-netflix-data-engineering-summit-f326b0589102", "company": "Netflix", "industry": "media", "title": "Our First Netflix Data Engineering Summit", "date": "2023-12-14", "primary_problem": "platform", "problems": ["late_data", "realtime"], "post_type": "announcement", "level": "intermediate", "stack": ["Flink", "Spark", "Iceberg"], "scale": "", "key_decisions": ["Offer managed Streaming SQL on Flink to let non-experts build stream processing, trading some flexibility for ease of use", "Build Psyberg on Iceberg metadata to handle late-arriving data incrementally, trading tight coupling to one table format for simpler on-call", "Teach pipeline reliability through testing, validation and auditing in Spark, favoring generic practices over tool-specific fixes"], "summary": "Netflix published a set of talks from its first internal Data Engineering Forum, covering its batch and streaming stack, a managed Flink SQL layer, reliable pipeline practices, and an Iceberg-based incremental ETL framework. The post is mainly a roundup and index of videos rather than a detailed technical write-up, so its value lies in pointing to the underlying topics.", "interview_angle": "How would you design a batch pipeline that handles late-arriving data incrementally without full reprocessing, and what metadata would you rely on to detect what changed?", "score": 0.5245, "hn_points": 1, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/messages-at-your-speed-with-concurrency-and-explicit-acknowledgement", "company": "Cloudflare", "industry": "infra", "title": "Cloudflare Queues: messages at your speed with consumer concurrency and explicit acknowledgement", "date": "2023-05-19", "primary_problem": "realtime", "problems": ["scale_ingestion", "cost"], "post_type": "announcement", "level": "intermediate", "stack": ["Cloudflare Queues", "Cloudflare Workers", "Wrangler", "Workers KV", "R2"], "scale": "Throughput per queue raised from 100 to over 400 messages per second", "key_decisions": ["Autoscale consumer concurrency by default based on backlog and error rate, trading predictable load for faster drain of backlogs; a max_concurrency cap lets users limit rate-limited or costly downstream calls", "Per-message explicit ack/retry instead of whole-batch redelivery, which avoids reprocessing successful messages at the cost of more consumer code and per-message handling", "Pursuing R2 as a first-party consumer and HTTP pull to widen integrations beyond Workers, trading a simpler managed path against maintaining more delivery modes"], "summary": "Cloudflare announces consumer concurrency, which autoscales Worker consumers to match queue backlog, and explicit per-message acknowledgment, which stops a single bad message from forcing whole-batch retries. The post also reports queue throughput rising from 100 to over 400 messages per second and previews R2 and HTTP pull consumers.", "interview_angle": "How would you design a message queue consumer that autoscales to clear backlogs without overwhelming a rate-limited downstream API, and how do you handle partial batch failures without reprocessing successful messages?", "score": 0.5203, "hn_points": 3, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/investigating-multi-vector-attacks-in-log-explorer", "company": "Cloudflare", "industry": "infra", "title": "Investigating multi-vector attacks in Log Explorer", "date": "2026-03-10", "primary_problem": "scale_ingestion", "problems": ["realtime", "lineage_catalog"], "post_type": "announcement", "level": "intermediate", "stack": ["Cloudflare Log Explorer", "JSON Schema", "SQL", "Grafana"], "scale": "P99 ingestion latency reduced ~55%, P50 reduced ~25%; 14 new datasets; no absolute volume stated", "key_decisions": ["Schema-driven ingestion via JSON Schema lets new log datasets be added without hard-coding, at the cost of needing schema maintenance per dataset", "Increasing concurrency in one ingestion stage isolates tenants so one client's surge does not slow others, trading extra resource use for noisy-neighbor resilience", "Exposing many security datasets through one SQL interface makes cross-dataset correlation easy, but requires users to pivot manually across tables and time-partitioned queries"], "summary": "Cloudflare expanded Log Explorer to 14 more security and Zero Trust log datasets so analysts can correlate edge, network and access telemetry through SQL. The post also reports an ingestion upgrade that added concurrency to remove noisy-neighbor bottlenecks and cut P99 ingestion latency by about 55%.", "interview_angle": "How would you design a multi-tenant log ingestion path so one customer's traffic spike does not delay another's data availability, and how would you add new log schemas without code changes?", "score": 0.5195, "hn_points": 0, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/cloudflare-threat-intelligence-platform", "company": "Cloudflare", "industry": "infra", "title": "Evolving Cloudflare\u2019s Threat Intelligence Platform: actionable, scalable, and ETL-less", "date": "2026-03-03", "primary_problem": "storage_formats", "problems": ["platform", "realtime"], "post_type": "announcement", "level": "intermediate", "stack": ["Cloudflare Workers", "Durable Objects", "SQLite", "Cloudflare Queues", "R2", "Hyperdrive", "GraphQL", "STIX2"], "scale": "billions of events across thousands of logical shards", "key_decisions": ["Sharding threat events across thousands of SQLite-backed Durable Objects avoids a single write hotspot, but makes cross-shard queries require fan-out and aggregation.", "Skipping a classic ETL pipeline by querying data where it is stored reduces data latency to near zero, but couples storage and query logic to the edge runtime.", "Queues absorb attack-spike ingestion asynchronously and R2 holds long-term data while a hot SQLite index serves fast lookups, trading consistency simplicity for throughput and cost."], "summary": "Cloudflare describes its Threat Intelligence Platform, which stores and queries threat events in a sharded fleet of SQLite-backed Durable Objects with R2 for long-term retention and a GraphQL endpoint running in Workers. The design aims to remove ETL pipelines so that security teams can query, visualize, and push rules from live telemetry at the edge.", "interview_angle": "How would you design a low-latency, multi-tenant event store for billions of security events that avoids a central database hotspot while supporting ad hoc search across shards?", "score": 0.5144, "hn_points": 0, "hn_comments": 0}, {"url": "https://stripe.com/blog/real-time-stripe-data-postgres", "company": "Stripe", "industry": "fintech", "title": "Sync real-time Stripe data to Postgres with Stripe Data Pipeline", "date": "2026-10-15", "primary_problem": "cdc_sync", "problems": ["realtime", "quality"], "post_type": "announcement", "level": "intermediate", "stack": ["Stripe Data Pipeline", "PostgreSQL", "Supabase", "Neon", "AWS", "Databricks Lakebase"], "scale": "", "key_decisions": ["Offer a managed sync to Postgres instead of asking developers to maintain polling or webhook pipelines, trading flexibility for lower operational burden", "Backfill selected tables and then apply incremental updates, so the destination starts complete and stays current in seconds", "Run periodic audits comparing synced records against the Stripe source and correct discrepancies, trading extra compute for stronger correctness than webhooks alone"], "summary": "Stripe announces real-time sync of selected Stripe tables into customer-managed Postgres databases through Data Pipeline, handling backfill and incremental updates end to end. The product removes the need for customers to build and monitor their own API polling or webhook copy logic, and it audits synced records against the source to fix drift.", "interview_angle": "How would you design a managed CDC-style sync from a SaaS API with webhooks into an operational database, covering backfill, out-of-order events, and drift detection?", "score": 0.5024, "hn_points": 0, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/logs-r2", "company": "Cloudflare", "industry": "infra", "title": "Logs on R2: slash your logging costs", "date": "2022-05-11", "primary_problem": "cost", "problems": ["storage_formats", "lineage_catalog"], "post_type": "announcement", "level": "intermediate", "stack": ["Cloudflare R2", "Logpush", "Logpull", "S3", "Amazon Athena"], "scale": "100,000 requests/sec generates ~9.2 TB/day raw, ~850 GB/day gzipped, ~26 TB/month compressed", "key_decisions": ["Store Logpush output on R2 instead of S3 to avoid egress fees and lower per-GB storage price, trading away S3's broader ecosystem and integrations", "Keep logs gzip-compressed at rest to cut storage volume, accepting extra decompression cost when reading", "Build a separate log retrieval API (lookups by time and rayId, then filters) rather than rely on scanning raw files, trading engineering effort for usability over Athena-style full scans"], "summary": "Cloudflare announces that enterprise customers can push raw logs via Logpush into R2 object storage, arguing that R2's zero egress and lower per-GB price cut long-term log retention costs substantially versus S3. The post also previews a log retrieval API and upcoming dataset and filtering features to make historical logs easier to query.", "interview_angle": "How would you design a cheap, long-retention log archive for high-volume HTTP logs that still supports incident lookups by time and request ID without expensive full scans?", "score": 0.4998, "hn_points": 8, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/sippy-incremental-migration-s3-r2", "company": "Cloudflare", "industry": "infra", "title": "Sippy helps you avoid egress fees while incrementally migrating data from S3 to R2", "date": "2023-09-26", "primary_problem": "migration", "problems": ["cost", "cdc_sync"], "post_type": "announcement", "level": "intermediate", "stack": ["Cloudflare R2", "S3", "Cloudflare Workers", "Super Slurper"], "scale": "", "key_decisions": ["Copy objects on demand inside the read path rather than running a bulk transfer, which avoids a large upfront egress bill but means cold data is only moved when touched", "Serve the request from S3 and copy to R2 in parallel, so the client sees no extra latency but very large objects may need several requests to finish copying", "Pair the incremental service with a separate bulk tool (Super Slurper) to finish off untouched data, trading two migration paths for full cutover flexibility"], "summary": "Cloudflare announced the open beta of Sippy, a service built into R2 buckets that copies objects from S3 to R2 lazily as they are requested. This lets teams migrate incrementally and avoid most cross-cloud egress charges while keeping their applications running.", "interview_angle": "How would you migrate a multi-petabyte object store from one cloud to another while minimizing egress cost and keeping reads available during the move?", "score": 0.4952, "hn_points": 230, "hn_comments": 164}, {"url": "https://blog.cloudflare.com/conversational-search-with-nlweb-and-autorag", "company": "Cloudflare", "industry": "infra", "title": "Make Your Website Conversational for People and Agents with NLWeb and AutoRAG", "date": "2025-08-28", "primary_problem": "scale_ingestion", "problems": ["platform", "storage_formats"], "post_type": "announcement", "level": "intermediate", "stack": ["Cloudflare Workers", "AutoRAG", "R2", "Vectorize", "Durable Objects", "Workers AI", "AI Gateway", "Browser Rendering", "NLWeb", "MCP"], "scale": "Crawls up to 100k pages per site; 20 files processed in parallel across FileManagers (about 2.5GB effective memory per batch)", "key_decisions": ["Split file processing across many FileManager Durable Objects (one file each) instead of one object, trading coordination overhead for roughly 20x memory capacity under the 128MB limit", "Reuse the existing R2-based queue and file pipeline for website crawling, so HTML-to-Markdown improvements apply to both files and sites at the cost of treating URLs as object keys", "Add a Job module and JobManager with one active sync per RAG (cancelling running jobs on new triggers) to gain sync history, logs and consistency, at the cost of cancelling in-flight work"], "summary": "Cloudflare describes how AutoRAG added website crawling as a data source, so a site can be crawled from its sitemap, stored in R2, embedded into Vectorize and kept fresh via re-crawls. To support large dynamic sources they added job tracking and split per-file work across Durable Objects to avoid Worker memory limits.", "interview_angle": "How would you design a continuously refreshed crawl-and-embed pipeline for a website that must respect robots.txt, handle large page counts, and stay within per-worker memory limits?", "score": 0.4795, "hn_points": 0, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/introducing-automatic-audit-logs", "company": "Cloudflare", "industry": "infra", "title": "Automatic Audit Logs: new updates deliver increased transparency and accountability", "date": "2025-02-13", "primary_problem": "governance_privacy", "problems": ["scale_ingestion", "lineage_catalog"], "post_type": "announcement", "level": "intermediate", "stack": ["Cloudflare Workers", "OpenAPI", "Logfwdr", "Logreceiver", "Buftee"], "scale": "Tens of thousands of requests per second at API Gateway; 111 products covered (95% coverage)", "key_decisions": ["Generate audit logs automatically at the API Gateway instead of per-product manual events, trading some per-product context for consistent coverage across all products", "Redact sensitive fields using auditable markings in the OpenAPI schema, so only explicitly marked fields are kept, at the cost of requiring every product team to maintain schema annotations", "Retain 30 days in beta and extend to 18 months at GA, trading storage cost against the compliance value of longer history"], "summary": "Cloudflare describes a beta system that automatically captures audit logs for user API and dashboard actions by streaming requests through a redactor Worker, which strips sensitive data using the OpenAPI schema before buffering, ingesting and enriching records into a queryable store. The post is mainly a product announcement with architecture details covering pipeline stages, coverage expansion and retention plans.", "interview_angle": "How would you design a company-wide audit logging pipeline that captures every user action across many services without relying on each team to emit events, while redacting sensitive fields before storage?", "score": 0.4732, "hn_points": 0, "hn_comments": 0}, {"url": "https://dropbox.tech/infrastructure/introducing-cape", "company": "Dropbox", "industry": "saas", "title": "Introducing Cape", "date": "2017-05-17", "primary_problem": "realtime", "problems": ["scale_ingestion", "cdc_sync"], "post_type": "announcement", "level": "advanced", "stack": ["Kafka", "Redis", "Python", "Go"], "scale": "Several billion events per day, tens of thousands of events per second; p95 under 100 ms (Frontend to lambda start) and under 400 ms for SFJ and Edgestore", "key_decisions": ["Asynchronous, out-of-band event pings from SFJ and Edgestore keep the critical path unaffected, at the cost of possibly missing events that a separate sweeper must recover", "Cape Refresh periodically scans source metadata databases to guarantee at-least-once processing, trading extra read load for completeness", "Generic Domain/Subject/Sequence ID event model lets many sources share one framework, but requires per-source mapping and ordering logic in the Dispatcher"], "summary": "Dropbox introduces Cape, a generic framework for real-time asynchronous processing of billions of file and metadata events per day, replacing its predecessor Livefill. The design uses Kafka-backed dispatching, Redis-fed lambda workers, and a Refresh sweeper that recovers events whose asynchronous pings were lost, yielding at-least-once processing with sub-second latency.", "interview_angle": "How would you design an at-least-once event processing framework over a source whose change notifications are best-effort, and how would you recover missed events without slowing the source system?", "score": 0.4539, "hn_points": 0, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/instant-logs", "company": "Cloudflare", "industry": "infra", "title": "Data at Cloudflare just got a lot faster: Announcing Live-updating Analytics and Instant Logs", "date": "2021-09-14", "primary_problem": "realtime", "problems": ["performance", "scale_ingestion"], "post_type": "announcement", "level": "intermediate", "stack": [], "scale": "Petabytes of log data daily; average Instant Logs delay of about 2 seconds", "key_decisions": ["Chose sub-second-style glass-to-glass latency as the target for logs, accepting that real-time delivery is harder than batch Logpush", "Exposed live-updating analytics on the last-30-minutes view rather than rebuilding all dashboards, trading historical depth for freshness", "Offered Instant Logs as a simpler setup path than Logpush, trading the flexibility of storage destinations for immediacy in the dashboard"], "summary": "Cloudflare announces live-updating analytics dashboards and Instant Logs, which stream HTTP request logs to the dashboard with an average delay of about two seconds. The post frames real-time delivery as a product feature and compares its latency against other vendors' logging services.", "interview_angle": "How would you design a low-latency path from edge logs to a customer-facing dashboard, balancing delivery latency against ingestion throughput and historical query support?", "score": 0.4497, "hn_points": 0, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/how-fast-is-the-web", "company": "Cloudflare", "industry": "infra", "title": "How fast is the web? Explore billions of real-user measurements with BEACON", "date": "2026-09-28", "primary_problem": "governance_privacy", "problems": ["lineage_catalog", "modeling"], "post_type": "announcement", "level": "intermediate", "stack": ["BigQuery", "Cloudflare Radar", "RUM Archive"], "scale": "Billions of real-user measurements per day across 10,000 websites", "key_decisions": ["Publishing full histograms instead of single averages lets users derive any percentile, at the cost of larger, more complex data to handle", "Scoping to the 10,000 largest sites avoids top-site skew while keeping billions of records after normalizing, trading away coverage of smaller sites", "Stripping domain and URL identifiers and dropping groups with fewer than five data points protects privacy, at the cost of losing some granularity"], "summary": "Cloudflare published BEACON, an anonymized public BigQuery dataset of real-user web performance measurements (Core Web Vitals and their sub-parts) from about 10,000 large websites, updated daily. The post shows how the dataset's design choices (sampling, normalization, aggregation and anonymization) make it usable for research on browser, country and architecture differences.", "interview_angle": "How would you design a publicly shareable, privacy-preserving analytics dataset from high-volume user telemetry, balancing sampling bias, anonymization and granularity?", "score": 0.4475, "hn_points": 0, "hn_comments": 0}, {"url": "https://www.capitalone.com/tech/machine-learning/synthetic-data-research", "company": "Capital One", "industry": "fintech", "title": "Synthetic Data for ML Innovation| Capital One", "date": "2022-09-27", "primary_problem": "governance_privacy", "problems": ["ml_data"], "post_type": "opinion", "level": "intermediate", "stack": [], "scale": "", "key_decisions": ["Use synthetic data as a stand-in for regulated real data so researchers can iterate without direct access, trading off fidelity for privacy", "Send researcher applications into a secure environment holding real data and return only validation metrics, limiting data movement but adding a round-trip for testing", "Keep approval and data-minimization steps in front of every access request, accepting slower access in exchange for compliance"], "summary": "Capital One describes why synthetic data helps machine learning teams in regulated industries work on sensitive financial data without exposing real records. The post argues the main challenge is producing synthetic data that is still useful for research, and proposes running candidate applications inside a secure enclave that reports back only metrics.", "interview_angle": "How would you let external researchers validate models against sensitive production data without giving them access to the raw records?", "score": 0.4463, "hn_points": 0, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/announcing-logs-engine", "company": "Cloudflare", "industry": "infra", "title": "Store and process your Cloudflare Logs... with Cloudflare", "date": "2022-11-15", "primary_problem": "cost", "problems": ["scale_ingestion", "storage_formats"], "post_type": "announcement", "level": "intermediate", "stack": ["Cloudflare R2", "Logpush", "Logpull"], "scale": "Customers generate petabytes of logs, retained for months or years", "key_decisions": ["Separate storage from compute: keep logs cheaply in R2 and pay only for queries run, instead of indexing every line at ingest (trade-off: slower ad hoc queries over raw data)", "Narrow searches using ABR analytics before querying raw logs (trade-off: depends on analytics granularity and an extra step for users)", "Launch time-range and RayID lookup first, deferring arbitrary filtering and cross-dataset queries (trade-off: limited query expressiveness at launch)"], "summary": "Cloudflare announces Logs Engine, a product that stores Cloudflare log datasets in R2 and lets customers retrieve them by time range and request identifier. The design separates cheap storage from pay-per-query compute and uses analytics to narrow searches before scanning raw logs.", "interview_angle": "How would you design a low-cost log retention and search system that avoids indexing every log line at ingest, and how would you keep query scans bounded?", "score": 0.443, "hn_points": 0, "hn_comments": 0}, {"url": "https://www.capitalone.com/tech/software-engineering/giving-a-fast-changing-data-ecosystem-room-to-grow", "company": "Capital One", "industry": "fintech", "title": "Giving a Fast-Changing Data Ecosystem Room to Grow | Capital One", "date": "2019-01-03", "primary_problem": "platform", "problems": ["cdc_sync", "governance_privacy"], "post_type": "opinion", "level": "intermediate", "stack": [], "scale": "", "key_decisions": ["Pool data into a central lake fed by microservice event streams: gains broad data availability but creates a shared dependency that needs strong governance", "Build security and data protection in from the outset using cloud-native controls: safer by default but adds upfront design effort", "Tier storage by likelihood of reuse and catalogue data for automated discovery: lowers cost for cold data but requires metadata discipline"], "summary": "This Forbes-syndicated opinion piece from Capital One argues that data ecosystems should be designed for flexibility and change, covering data lakes fed by microservices, security, storage tiering, cataloguing and synchronization. It is high-level and light on concrete architecture, metrics or implementation details.", "interview_angle": "How would you design an enterprise data ecosystem that stays flexible as new tools appear, while keeping customer data synchronized, secure and discoverable?", "score": 0.436, "hn_points": 0, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/cloudflare-logpush-the-easy-way-to-get-your-logs-to-your-cloud-storage", "company": "Cloudflare", "industry": "infra", "title": "Logpush: the Easy Way to Get Your Logs to Your Cloud Storage", "date": "2019-02-25", "primary_problem": "scale_ingestion", "problems": ["platform"], "post_type": "announcement", "level": "intermediate", "stack": ["S3", "Google Cloud Storage"], "scale": "Domains on network grew 10x since the original logging post (no absolute volume stated)", "key_decisions": ["Push logs to customer cloud buckets instead of making customers poll the Logpull API: removes customer-side scripting but Cloudflare now owns delivery reliability and per-destination integrations", "Keep Logpull option parity (field selection, timestamp format, sampling) so existing pipelines migrate by copying options: eases adoption but constrains the new product to the old API's shape", "Launch with only S3 and GCS in Early Access for Enterprise: narrows support burden at the cost of slower coverage of other destinations"], "summary": "Cloudflare announces Logpush, a managed service that pushes per-request logs from its network directly into customer cloud storage such as S3 or Google Cloud Storage, replacing customer-written pull scripts. The post explains the motivation (growing log volume, repeated download-then-upload scripts) and how the push API reuses existing Logpull options.", "interview_angle": "How would you design a managed log-delivery service that pushes high-volume request logs from many producers into customer-owned object storage, with per-tenant field selection, sampling and retries?", "score": 0.4332, "hn_points": 2, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/announcing-network-analytics", "company": "Cloudflare", "industry": "infra", "title": "Announcing Network Analytics", "date": "2020-03-16", "primary_problem": "performance", "problems": ["scale_ingestion", "governance_privacy"], "post_type": "announcement", "level": "intermediate", "stack": ["GraphQL"], "scale": "Sampled edge traffic rolled up into 1-minute IP flow groups; retention of 30 days raw, 6 months hourly, 1 year daily; data centers in over 200 cities", "key_decisions": ["Store attacks as summary records instead of raw packet logs, trading per-packet fidelity for cheaper reads and up to one year of attack history", "Discard source IPs after 30 days as PII and roll data up to hourly then daily, trading forensic detail for privacy compliance and storage savings", "Plot traffic by the data center that ingested it rather than by source IP, trading attacker geolocation for accuracy under spoofing"], "summary": "Cloudflare describes the analytics backend behind its Network Analytics dashboard for Magic Transit and BYOIP customers, which works at the packet and bit level rather than HTTP. The pipeline samples edge traffic, builds one-minute IP flow aggregates, and applies tiered retention with PII removal and summarized attack logs.", "interview_angle": "How would you design tiered retention and rollups for sampled network flow logs that must keep one year of history while discarding PII source IPs after 30 days?", "score": 0.4316, "hn_points": 2, "hn_comments": 0}, {"url": "https://engineering.zalando.com/posts/2016/06/feature-extraction-science-or-engineering.html", "company": "Zalando", "industry": "ecommerce", "title": "Zalando Engineering Blog - Feature Extraction: Science or Engineering?", "date": "2016-06-23", "primary_problem": "ml_data", "problems": ["scale_ingestion", "performance"], "post_type": "opinion", "level": "intermediate", "stack": [], "scale": "massive server logs distributed over several machines; no specific figures stated", "key_decisions": ["Pre-aggregate per-user action logs so downstream feature jobs can selectively read history instead of rescanning raw logs; trades storage and an extra job for cheaper later reads", "Compute dynamic article features and user attributes as separate jobs that can optionally reuse article features, trading tight job interdependencies for reuse", "Keep architecture design and ML modeling knowledge in the same team, accepting tighter coupling in exchange for features that fit downstream model needs"], "summary": "Zalando describes the feature extraction pipeline behind its personalised recommender, where user action logs are pre-aggregated per user and then turned into dynamic article features and user attributes that feed a learned ranking model. The post is mostly an argument that feature engineering deserves scientific attention, with the engineering challenges of volume, job interdependencies and modeling coupling as the supporting case.", "interview_angle": "How would you design a feature extraction pipeline over massive, unbounded user event logs so that per-user features can be computed cheaply and reused by multiple downstream ranking models?", "score": 0.4242, "hn_points": 0, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/ai-search-easier", "company": "Cloudflare", "industry": "infra", "title": "Cloudflare AI Search: give your agents a search engine for your data", "date": "2026-08-06", "primary_problem": "platform", "problems": ["ml_data", "governance_privacy"], "post_type": "announcement", "level": "intermediate", "stack": ["Cloudflare AI Search", "Workers AI", "AI Gateway", "Vectorize", "R2", "Browser Run", "Wrangler", "Cloudflare Workers", "Cloudflare Access", "EmDash", "MCP"], "scale": "20M tokens ingestion example (20,000 documents plus 1,000 images), 30,000 queries/month example", "key_decisions": ["Managed end-to-end pipeline (crawl, chunk, embed, index, retrieve) instead of stitching primitives together, trading flexibility for ease of setup", "Free embedding and reranking on default Workers AI models, making costs predictable but tying users to select models", "Public endpoints with custom domains and optional Access for private search, trading fine-grained control for shareability and quick deployment"], "summary": "Cloudflare announces developer improvements to AI Search, a managed search service that crawls, chunks, embeds and indexes websites and files so agents can query them. The post walks through how they built a cross-surface Dev Stack MCP search, the bot identity and robots.txt handling, and a preview of per-token ingestion and query pricing.", "interview_angle": "How would you design a managed ingestion-to-retrieval pipeline for heterogeneous sources (web crawl, files, images) with multi-index querying, and how would you structure usage-based pricing around ingestion tokens and queries?", "score": 0.4213, "hn_points": 3, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/r2-sql-aggregations", "company": "Cloudflare", "industry": "infra", "title": "Announcing support for GROUP BY, SUM, and other aggregation queries in R2 SQL", "date": "2025-12-18", "primary_problem": "performance", "problems": ["storage_formats", "platform"], "post_type": "announcement", "level": "advanced", "stack": ["R2 SQL", "R2 Data Catalog", "Parquet", "gRPC"], "scale": "", "key_decisions": ["Scatter-gather aggregation keeps coordinator memory tiny by merging per-worker pre-aggregates, but cannot handle ORDER BY or HAVING on global aggregate values", "Shuffle stage hash-partitions groups so each worker owns complete totals, enabling local HAVING/ORDER BY, at the cost of an all-to-all exchange and a synchronization barrier", "Streaming k-way merge at the coordinator lets LIMIT queries stop early, trading a sorted-stream requirement on each worker for bounded coordinator work"], "summary": "Cloudflare added GROUP BY and aggregate functions to R2 SQL, a distributed query engine over Parquet data in R2 Data Catalog. The post explains two execution strategies: scatter-gather pre-aggregation for simple cases, and a hash-shuffle with barrier and streaming merge for queries needing global ORDER BY or HAVING.", "interview_angle": "How would you execute a distributed GROUP BY with ORDER BY on an aggregate and LIMIT over data spread randomly across many files, without funneling every group to one coordinator?", "score": 0.4185, "hn_points": 0, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/logpush-filters-alerts", "company": "Cloudflare", "industry": "infra", "title": "Logpush: now lower cost and with more visibility", "date": "2022-09-22", "primary_problem": "cost", "problems": ["scale_ingestion", "quality"], "post_type": "announcement", "level": "intermediate", "stack": ["Cloudflare R2", "Splunk", "S3", "GraphQL"], "scale": "About 21 billion records (2.1 TB compressed, 24.9 TB uncompressed) per day for one example customer", "key_decisions": ["Filter logs at push time on field values, so customers pay to store and move less data, at the cost of discarding records they might later want", "Alert on jobs failing for 24 hours rather than on every retry, trading faster detection for fewer noisy notifications", "Expose job health as queryable GraphQL aggregates instead of building a separate dashboard, keeping the API the single access path but limiting ad hoc analysis to the schema's dimensions"], "summary": "Cloudflare's Logpush service ships customer logs to destinations such as S3, R2 and Splunk. This announcement adds field-based filtering before push, failure alerts for stuck jobs, and a GraphQL API for delivery health metrics.", "interview_angle": "How would you reduce downstream log storage cost for a high-volume push pipeline without losing visibility into delivery failures?", "score": 0.4176, "hn_points": 0, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/export-logs-from-cloudflare-gateway-with-logpush", "company": "Cloudflare", "industry": "infra", "title": "Export logs from Cloudflare Gateway with Logpush", "date": "2020-05-29", "primary_problem": "scale_ingestion", "problems": ["governance_privacy", "platform"], "post_type": "announcement", "level": "intermediate", "stack": ["Cloudflare Gateway", "Cloudflare Logpush", "S3", "Google Cloud Storage", "Sumo Logic", "Microsoft Azure"], "scale": "About 114,000 DNS queries per week for one user; organizations can have tens or hundreds of millions of queries per week", "key_decisions": ["Push-based managed log export (Logpush) instead of customers polling APIs or downloading CSVs: less customer effort, but dependent on a contract plan", "Deltas exported every five minutes rather than real-time streaming: simpler and cheaper delivery at the cost of up to five minutes of latency", "Support for a fixed set of storage destinations (S3, GCS, Sumo Logic, Azure) plus user-selected fields: easy onboarding but limits flexibility to other sinks"], "summary": "Cloudflare announces a feature that exports Gateway DNS and filtering logs to customer-owned storage or SIEM tools via its Logpush service. Logs are delivered as five-minute deltas with customer-selected fields, so security teams can audit at scale without pulling data through the UI or API.", "interview_angle": "How would you design a managed log export pipeline for tens of millions of records per week that delivers incremental files to customer-owned object storage with configurable schemas and delivery monitoring?", "score": 0.4068, "hn_points": 0, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/d1-open-alpha", "company": "Cloudflare", "industry": "infra", "title": "UPDATE Supercloud SET status = 'open alpha' WHERE product = 'D1';", "date": "2022-11-16", "primary_problem": "platform", "problems": ["modeling", "migration"], "post_type": "announcement", "level": "intermediate", "stack": ["Cloudflare D1", "Cloudflare Workers", "Cloudflare Pages", "Wrangler", "SQLite", "Kysely", "d1-orm", "workers-qb"], "scale": "", "key_decisions": ["Ship an open alpha with a developer-facing surface (dashboard, Wrangler, Worker bindings) before replication and JS transactions are ready, trading completeness for early feedback", "Keep each D1 database on a single instance placed near its creator, accepting higher latency for distant Workers in exchange for simpler consistency", "Disable replication and transaction support in the alpha and roll them out gradually, so throughput numbers are not yet representative of the final product"], "summary": "Cloudflare announces an open alpha of D1, its serverless relational database built on Workers, aimed at letting developers try it through a dashboard, Wrangler CLI, migrations and Worker/Pages bindings. The post also lists community tooling and the current limitations (single instance, queued queries under load, backup-related blocking) that the team is still working on.", "interview_angle": "How would you design a globally distributed serverless SQL database, and what trade-offs arise between single-primary placement, replication for read scaling, and backup availability?", "score": 0.4042, "hn_points": 45, "hn_comments": 1}, {"url": "https://blog.cloudflare.com/one-observability-platform", "company": "Cloudflare", "industry": "infra", "title": "8 major updates to Cloudflare Observability", "date": "2026-10-02", "primary_problem": "platform", "problems": ["lineage_catalog", "cost"], "post_type": "announcement", "level": "intermediate", "stack": ["Cloudflare Workers", "Cloudflare Logpush", "Cloudflare Analytics Engine", "OpenTelemetry", "SQL"], "scale": "", "key_decisions": ["Unify logs, traces, analytics and alerts under one SQL API and dataset model, trading off per-product specialized tooling for cross-product correlation", "Move to volume-based (GB ingested and stored) observability pricing instead of event counts, since log and trace sizes vary widely", "Offer Logpush on all self-serve plans with a free allowance and an in-pipeline SQL Transformers step, instead of a separate ETL system"], "summary": "Cloudflare announces eight updates that consolidate logs, traces, analytics, alerts, dashboards and log export into one observability platform. The main data-engineering-relevant pieces are a unified SQL API across telemetry datasets, volume-based pricing for ingested and stored logs and traces, and Logpush with SQL transformations.", "interview_angle": "How would you design a unified telemetry platform that lets humans and agents query heterogeneous log, trace and analytics datasets through one SQL interface, and how would you price it by volume?", "score": 0.4035, "hn_points": 2, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/introducing-partner-analytics", "company": "Cloudflare", "industry": "infra", "title": "Introducing Partner Analytics", "date": "2015-07-23", "primary_problem": "scale_ingestion", "problems": ["performance", "platform"], "post_type": "announcement", "level": "intermediate", "stack": [], "scale": "Hundreds of TB of logs per day; 400 billion monthly page views; 5,000+ partners", "key_decisions": ["Rebuilt the customer analytics and request logging backend to serve per-partner aggregates over rolling 7 and 30 day windows, trading engineering effort for much higher query capacity", "Exposed pre-aggregated bandwidth, threat and visitor metrics per partner rather than raw logs, trading flexibility for predictable query cost and simpler partner UX", "Chose distributed querying over the new backend to keep partner dashboards responsive as log volume grows, at the cost of less detail in the early views"], "summary": "Cloudflare upgraded its customer analytics and request logging backend so that hosting partners can see per-partner bandwidth savings, threats blocked, and request and visitor counts through a new Partner Portal section. The post is mainly a product announcement, with only light detail on the underlying data architecture.", "interview_angle": "How would you design a per-tenant analytics backend that aggregates hundreds of TB of daily request logs into rolling 7 and 30 day metrics for thousands of partners?", "score": 0.3896, "hn_points": 2, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/log-explorer", "company": "Cloudflare", "industry": "infra", "title": "Log Explorer: monitor security events without third-party storage", "date": "2024-03-08", "primary_problem": "storage_formats", "problems": ["cost", "governance_privacy"], "post_type": "announcement", "level": "intermediate", "stack": ["Cloudflare R2", "Delta Lake", "delta-rs", "Apache Arrow DataFusion", "Rust", "Parquet"], "scale": "", "key_decisions": ["Store per-customer log datasets as Delta tables on R2 object storage, trading a custom storage layer for ACID commits and open formats", "Rely on R2's atomic PutIfAbsent for optimistic concurrent writers, avoiding an external lock store like those needed on S3", "Build the query layer in Rust with delta-rs and DataFusion, favoring performance and safety over using an off-the-shelf managed log search service"], "summary": "Cloudflare announces Log Explorer, a beta feature letting customers search and investigate raw HTTP and security event logs inside the dashboard without forwarding them to third-party tools. The storage backend is an append-only, per-customer Delta Lake store on R2 queried through a SQL interface built in Rust.", "interview_angle": "How would you design a per-tenant, append-only log store on object storage that supports concurrent writers and ad hoc SQL queries without an external coordination service?", "score": 0.3883, "hn_points": 4, "hn_comments": 1}, {"url": "https://blog.cloudflare.com/cloudflare-r2-super-slurper", "company": "Cloudflare", "industry": "infra", "title": "Migrate from S3 easily with the R2 Super Slurper", "date": "2022-11-15", "primary_problem": "migration", "problems": ["scale_ingestion", "cost"], "post_type": "announcement", "level": "intermediate", "stack": ["Cloudflare R2", "S3"], "scale": "", "key_decisions": ["One-time bulk copy from S3 via an async job versus incremental on-demand copying on first read; bulk is simpler but needs full cutover planning", "Lazy copy-on-read (sip) saves egress immediately and avoids upfront transfer, but adds latency and depends on the origin staying available", "Launching as a private beta limited to S3-compatible sources, trading breadth of source support for faster iteration with early users"], "summary": "Cloudflare announces R2 Super Slurper, a tool for moving object storage data from S3-compatible buckets into R2 through a one-time bulk import. It also outlines a planned sip-by-sip mode that copies objects into R2 as they are first requested, so reads shift gradually while egress costs drop.", "interview_angle": "How would you migrate petabytes of objects from one cloud store to another with minimal downtime, choosing between a bulk copy and a lazy copy-on-read approach?", "score": 0.3819, "hn_points": 13, "hn_comments": 1}, {"url": "https://blog.cloudflare.com/what-cloudflare-logs", "company": "Cloudflare", "industry": "infra", "title": "What CloudFlare Logs", "date": "2013-04-23", "primary_problem": "governance_privacy", "problems": ["scale_ingestion", "cost"], "post_type": "announcement", "level": "intermediate", "stack": [], "scale": "More than 20GB (compressed) of log data per minute; over 10 PB per year of storage at current volume, doubling about every 4 months", "key_decisions": ["Discard most raw access logs within 4 hours at the edge, because storing all logs for a year would cost more than the platform can afford", "Keep raw logs for 3 days only for Enterprise customers who opt in to log export, trading retention length against storage cost", "Run stream processing at the edge to extract summaries and attack signals, and keep only aggregates for analytics and security"], "summary": "Cloudflare explains what request logs it records for each site visit and how long it keeps them, given log volume above 20GB per minute. Most customers' raw logs are deleted within 4 hours, Enterprise customers can keep them for 3 days, and a stream processor turns the logs into aggregates for analytics and attack detection.", "interview_angle": "How would you design log retention and aggregation for a global edge network that generates tens of GB per minute, balancing storage cost, customer export needs and privacy?", "score": 0.3781, "hn_points": 0, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/r2-super-slurper-ga", "company": "Cloudflare", "industry": "infra", "title": "The S3 to R2 Super Slurper is now Generally Available", "date": "2023-05-16", "primary_problem": "migration", "problems": ["scale_ingestion", "cost"], "post_type": "announcement", "level": "intermediate", "stack": ["Cloudflare R2", "S3"], "scale": "up to 5x increase in objects copied per second during beta; multi-terabyte migrations", "key_decisions": ["Copy objects in parallel over Cloudflare's global network to finish bulk moves fast, at the cost of depending on the provider's network for transfer", "Retry failed transfers and chunk large objects so only the failed part is re-sent, trading implementation complexity for lower cost and reliability", "Offer incremental migration on read (copy each object on first request) to avoid up-front egress, at the cost of serving some requests from the origin during the transition"], "summary": "Cloudflare announces general availability of R2 Super Slurper, a managed tool that copies objects and metadata from S3 (or another R2 bucket) into R2 with parallel transfers and retries. The post also previews an incremental, on-request migration mode that is still in private beta.", "interview_angle": "How would you design a bulk object-storage migration that must be resumable, retry-safe and cheap in egress, and how would you move data gradually without a big-bang cutover?", "score": 0.3686, "hn_points": 0, "hn_comments": 0}, {"url": "https://engineering.zalando.com/posts/2017/10/zalando-smart-product-platform.html", "company": "Zalando", "industry": "ecommerce", "title": "Zalando Engineering Blog - Zalando's Smart Product Platform", "date": "2017-10-24", "primary_problem": "platform", "problems": ["scale_ingestion", "governance_privacy"], "post_type": "announcement", "level": "intermediate", "stack": [], "scale": "millions of products and thousands of attributes", "key_decisions": ["Build an in-house PIM/MDM product data platform rather than buying an off-the-shelf system, trading vendor fit for control over the data model", "Use a hyper-flexible data model to support new business use cases quickly, at the cost of more complex validation and governance", "Connect microservices via event-driven streaming interfaces to distribute product data to consumers, trading operational complexity for decoupled consumption"], "summary": "Zalando introduces its Smart Product Platform, an in-house combination of product information management and master data management that collects, validates and exposes fashion product data across the company. The post is high level, focusing on goals such as scalability, flexible modeling, data quality and easy onboarding and consumption rather than on concrete implementation details.", "interview_angle": "How would you design a product master data platform that ingests data from many suppliers, enforces quality rules with human curation, and serves changes to many downstream consumers via events?", "score": 0.3668, "hn_points": 0, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/network-flow-monitoring-generally-available", "company": "Cloudflare", "industry": "infra", "title": "Network flow monitoring is GA, providing end-to-end traffic visibility", "date": "2023-10-18", "primary_problem": "scale_ingestion", "problems": ["quality", "realtime"], "post_type": "announcement", "level": "intermediate", "stack": ["NetFlow", "sFlow"], "scale": "", "key_decisions": ["Switched from simple random sampling to VarOpt reservoir sampling so weighted, long-tail flow samples produce accurate traffic volume estimates, at the cost of periodic reservoir batch computation", "Ingests router-exported NetFlow/sFlow at a public anycast endpoint, accepting traffic that never traversed Cloudflare's network, trading infrastructure generality for broader visibility", "Applies a second layer of sampling inside MNM to scale ingestion, which compounds with router-side sampling and complicates accuracy, so accuracy had to be corrected rather than assumed"], "summary": "Cloudflare announces general availability of Magic Network Monitoring, a cloud service that ingests router-exported NetFlow and sFlow data and analyzes traffic volume, DDoS alerts and flow metrics. The post focuses on how naive random sampling produced false traffic spikes and how switching to VarOpt reservoir sampling fixed the accuracy of estimates across stacked sampling layers.", "interview_angle": "How would you ingest and estimate traffic volume from sampled, heavy-tailed network flow records at global scale when sampling is already applied upstream by routers?", "score": 0.3624, "hn_points": 1, "hn_comments": 0}, {"url": "https://shopify.engineering/shopify-commerce-data-querying-language-shopifyql", "company": "Shopify", "industry": "ecommerce", "title": "Introducing ShopifyQL: Our New Commerce Data Querying Language", "date": "2022-06-22", "primary_problem": "modeling", "problems": ["platform", "performance"], "post_type": "announcement", "level": "intermediate", "stack": ["ShopifyQL", "GraphQL", "SQL"], "scale": "", "key_decisions": ["Keep a SQL-like syntax but reorder FROM before SHOW and add VISUALIZE and COMPARE TO, trading general SQL flexibility for merchant accessibility", "Build flat, fully additive exploration datasets per domain (products, orders, customers) so users avoid joins and window functions, at the cost of duplicated metrics across tables", "Expose ShopifyQL through GraphQL APIs and a notebooks app so partners and internal teams share one analytics layer, which centralizes semantics but couples them to the language"], "summary": "Shopify introduces ShopifyQL, a commerce-focused query language for Shopify Plus merchants that simplifies SQL with built-in visualization, period comparisons, and commerce date ranges. It is backed by flat, additive exploration datasets and exposed through notebooks and GraphQL APIs.", "interview_angle": "How would you design a self-serve analytics query layer for non-technical business users that hides joins and time-over-time comparisons while keeping metrics consistent across datasets?", "score": 0.3467, "hn_points": 0, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/ai-model-overuse-user-insights", "company": "Cloudflare", "industry": "infra", "title": "Identify AI model overuse with User Insights", "date": "2026-09-30", "primary_problem": "cost", "problems": ["lineage_catalog", "realtime"], "post_type": "announcement", "level": "intermediate", "stack": ["Cloudflare Workers", "Durable Objects", "R2", "Cloudflare Access", "AI Gateway"], "scale": "", "key_decisions": ["Classify AI Gateway logs asynchronously after the request completes, keeping latency out of the request path at the cost of dashboards lagging traffic by about a day", "Store metadata separately from log bodies (Durable Objects for metadata, R2 for bodies) so aggregate views stay fast without exposing raw prompts, at the cost of a split storage path", "Expose only derived categories and aggregates rather than a raw prompt browser, trading investigative depth for privacy and simpler governance"], "summary": "Cloudflare describes User Insights, which uses an asynchronous Worker-based classifier to label AI Gateway conversations by task type, complexity and model fit so teams can spot overkill model usage and cost. The pipeline stores metadata separately from log bodies and joins identity context from Access to group usage by user, team, or application.", "interview_angle": "How would you design an asynchronous classification pipeline over high-volume LLM request logs that adds no latency to the request path, and what freshness and privacy trade-offs would you accept?", "score": 0.3274, "hn_points": 0, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/store-and-retrieve-logs-on-r2", "company": "Cloudflare", "industry": "infra", "title": "Store and retrieve your logs on R2", "date": "2022-09-21", "primary_problem": "storage_formats", "problems": ["cost", "scale_ingestion"], "post_type": "announcement", "level": "intermediate", "stack": ["Cloudflare R2", "Logpush", "S3 API"], "scale": "", "key_decisions": ["Use an S3-compatible object store (R2) as the log destination so existing tooling works unchanged, trading away a native query engine for simplicity", "Charge no egress fees on retrieval, which lowers cost for frequent log access but depends on Cloudflare's own pricing model", "Expose retrieval as a time-range API over date-partitioned object paths, keeping retention under customer control but limiting ad hoc query capability"], "summary": "Cloudflare announces that customers can push Logpush log data directly to R2 object storage and retrieve it by time range through an API. The main motivation is cutting storage and egress costs for logs compared with exporting them to third-party destinations.", "interview_angle": "How would you design cheap, long-retention log storage with time-range retrieval on object storage, and what trade-offs come with skipping a query engine?", "score": 0.3192, "hn_points": 2, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/analytics-engine-open-beta", "company": "Cloudflare", "industry": "infra", "title": "Don't roll your own high cardinality analytics, use Workers Analytics Engine", "date": "2022-09-30", "primary_problem": "scale_ingestion", "problems": ["performance", "platform"], "post_type": "announcement", "level": "intermediate", "stack": ["Cloudflare Workers", "Workers Analytics Engine", "Grafana", "Prometheus"], "scale": "", "key_decisions": ["Expose a SQL interface for time-series analytics rather than a PromQL-style API, trading familiarity for flexibility with high-cardinality queries", "Use ABR-style multi-resolution data so queries stay within an interactive latency window, at the cost of approximate results that users must correct using _sample_interval", "Invest in clearer SQL error messages and a reference guide after closed beta feedback, prioritizing developer usability over new features"], "summary": "Cloudflare announces the open beta of Workers Analytics Engine, a managed store for high-cardinality time-series events written from Workers. The post explains how it powers Instant Logs request-rate tracking, how adaptive resolution keeps queries fast, and what was improved after closed beta.", "interview_angle": "How would you design a store for high-cardinality event metrics that keeps interactive query latency bounded, and when is sampling with a correction factor acceptable?", "score": 0.3181, "hn_points": 1, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/introducing-workers-observability-logs-metrics-and-queries-all-in-one-place", "company": "Cloudflare", "industry": "infra", "title": "Introducing Workers Observability: logs, metrics, and queries \u2013 all in one place", "date": "2025-04-09", "primary_problem": "platform", "problems": ["scale_ingestion", "performance"], "post_type": "announcement", "level": "intermediate", "stack": ["Cloudflare Workers", "Workers Logs", "Logpush"], "scale": "", "key_decisions": ["Indexes structured key-value logs so the Query Builder can run fast filtered and aggregated queries, trading ingestion-side structure requirements for flexible ad hoc analysis", "Exposes logs across all Workers in an account in one view instead of per-Worker, giving broader insight at the cost of more data to index and query", "Offers an observability API alongside the dashboard so users can pull telemetry into external tools, trading control over the UI for openness and integration"], "summary": "Cloudflare announces Workers Observability, a dashboard section for querying structured Workers logs across all Workers in an account, plus metrics dashboards, saved queries, and an API for telemetry export. The post is a product announcement focused on developer observability rather than deep data engineering internals.", "interview_angle": "How would you design a queryable log store for high-cardinality structured events that supports ad hoc aggregations and metric extraction across many tenants?", "score": 0.3138, "hn_points": 2, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/an-ai-index-for-all-our-customers", "company": "Cloudflare", "industry": "infra", "title": "An AI Index for all our customers", "date": "2025-09-26", "primary_problem": "platform", "problems": ["realtime", "governance_privacy"], "post_type": "announcement", "level": "intermediate", "stack": ["Cloudflare AI Search", "MCP", "llms.txt", "x402"], "scale": "", "key_decisions": ["Build a per-site search index that site owners control, trading centralized crawling for opt-in publishing and access rules", "Expose data through pub/sub subscriptions and bulk APIs instead of blind recrawling, reducing builder cost but requiring site owners to run the index", "Offer an aggregated Open Index across sites, which simplifies builder integration but adds a layer that must respect each site's monetization and permissions"], "summary": "Cloudflare announces a private beta of AI Index, which automatically builds an AI-optimized search index for a customer's domain and exposes it through search, MCP, llms.txt, bulk and pub/sub APIs. It also proposes an aggregated Open Index so AI builders can query many opted-in sites with owner-controlled monetization.", "interview_angle": "How would you design a permissioned publish-subscribe feed over website content that replaces blind crawling, including incremental change events, bulk export, access control and per-access billing?", "score": 0.3134, "hn_points": 6, "hn_comments": 1}, {"url": "https://blog.cloudflare.com/logpush-ui-update", "company": "Cloudflare", "industry": "infra", "title": "More products, more partners, and a new look for Cloudflare Logs", "date": "2021-06-22", "primary_problem": "platform", "problems": ["scale_ingestion", "cost"], "post_type": "announcement", "level": "intermediate", "stack": ["Logpush", "S3", "Microsoft Azure Sentinel", "Splunk", "Sumo Logic", "Datadog"], "scale": "", "key_decisions": ["Expose new log datasets (Firewall Events, NEL Reports) via Logpush, trading engineering effort for broader customer coverage", "Support any S3-compatible storage destination rather than only the big three clouds, widening reach at the cost of more integration variety", "Push logs directly to analytics partners instead of requiring customers to build fragile pipelines out of object storage, trading control for simplicity"], "summary": "Cloudflare announces expanded Logpush capabilities: new Firewall Events and Network Error Logging datasets, support for any S3-compatible storage destination, and direct log delivery to Azure Sentinel, Splunk, Sumo Logic and Datadog. The post also redesigns the dashboard flow for configuring log exports.", "interview_angle": "How would you design a customer-facing log export service that delivers high-volume logs to many heterogeneous destinations (object storage and SIEMs) with a self-serve configuration UI?", "score": 0.3077, "hn_points": 0, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/snowflake-r2-global-data-lake", "company": "Cloudflare", "industry": "infra", "title": "Use Snowflake with R2 to extend your global data lake", "date": "2023-05-16", "primary_problem": "storage_formats", "problems": ["cost", "migration"], "post_type": "announcement", "level": "intermediate", "stack": ["Cloudflare R2", "Snowflake", "Amazon S3-compatible API"], "scale": "", "key_decisions": ["Use R2 as the data lake store so that cross-cloud egress fees into Snowflake are avoided, trading away hyperscaler-native integration", "Connect Snowflake via an external stage using S3-compatible endpoint and access keys, which is simple to set up but requires Snowflake account-team enablement and manual credential management", "Expose R2 data both through COPY INTO loads into Snowflake tables and through external tables for in-place querying, trading ingestion speed and storage duplication against query freshness"], "summary": "Cloudflare announces a partnership letting Snowflake load data from and query data stored in R2 object storage through an S3-compatible external stage. The main draw is avoiding egress fees when moving data between a data lake on R2 and Snowflake.", "interview_angle": "How would you design a multi-cloud data lake so that moving data into a warehouse does not incur heavy egress costs, and what trade-offs come with loading versus querying externally?", "score": 0.2953, "hn_points": 0, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/update-more-page-view-counting-refinement", "company": "Cloudflare", "industry": "infra", "title": "Update: More Page View Counting Refinement", "date": "2012-05-28", "primary_problem": "quality", "problems": ["lineage_catalog"], "post_type": "announcement", "level": "intermediate", "stack": [], "scale": "Less than 1% page view change for most sites, up to 20% for some", "key_decisions": ["Reclassify hits as page views using stricter rules (content type and 300 redirect handling), trading historical comparability for accuracy", "Do not retain raw historical data, so past analytics reports cannot be recomputed after the algorithm change", "Keep hits and uniques counts unchanged because they are simpler to count exactly, limiting the scope of the revision"], "summary": "Cloudflare announces a refinement to its page view classification algorithm that fixes misclassified content types and double-counted 300 redirects. Because raw data is not retained, the change applies only going forward and cannot correct past reports.", "interview_angle": "How would you design an analytics metric classifier over raw request logs so that rule changes can be applied and audited, given that raw history is not kept?", "score": 0.2826, "hn_points": 0, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/using-google-cloud-platform-to-analyze-cloudflare-logs", "company": "Cloudflare", "industry": "infra", "title": "Using Google Cloud Platform to Analyze Cloudflare Logs", "date": "2017-10-26", "primary_problem": "scale_ingestion", "problems": ["platform", "cost"], "post_type": "announcement", "level": "intermediate", "stack": ["Google Cloud Storage", "Cloud Functions", "BigQuery", "Data Studio", "Cloudflare Logshare API"], "scale": "", "key_decisions": ["Pull Cloudflare logs via Logshare REST API onto a small GCP VM, keeping the collector replaceable by customer tooling; trade-off is customer-managed operation versus a fully hosted service", "Land raw JSON logs in a Cloud Storage bucket with retention policy, decoupling ingestion from analysis; trade-off is storage cost that grows with request volume", "Use a Cloud Function triggered by new file uploads to load into BigQuery, giving near-immediate query access; trade-off is event-driven simplicity with less control over batching and retries"], "summary": "Cloudflare published a reference pipeline that pulls Enterprise customers' access logs via its Logshare API, stores them as JSON in Google Cloud Storage, auto-loads them into BigQuery with a Cloud Function, and visualizes them in Data Studio. The main point is that the setup is quick to deploy and cost depends on request volume, storage, retention and query count.", "interview_angle": "How would you design a low-ops pipeline that pulls logs from a third-party API, lands raw files in object storage, and makes them queryable within minutes, and where would you add batching, retries and cost controls?", "score": 0.2773, "hn_points": 1, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/phishing-threat-indicators-in-zero-trust", "company": "Cloudflare", "industry": "infra", "title": "Area 1 threat indicators now available in Cloudflare Zero Trust", "date": "2022-06-20", "primary_problem": "migration", "problems": ["scale_ingestion", "quality"], "post_type": "announcement", "level": "intermediate", "stack": [], "scale": "", "key_decisions": ["Merge Area 1's threat indicator feed into Cloudflare's existing indicator pipeline so all products benefit, trading integration effort for broader coverage", "Distribute indicator updates automatically at up to per-minute cadence instead of asking customers to manage feeds, centralizing operational burden", "Apply custom false-positive control on curated feeds drawn from network traffic, OSINT and partners, trading some recall for precision"], "summary": "Cloudflare describes integrating Area 1's phishing threat indicator pipeline into its existing indicator data pipeline after the acquisition, so Gateway and other products can use the combined data. The post is mostly a product announcement with light detail on how the two pipelines' sources and feedback loops are combined.", "interview_angle": "How would you merge two independently built threat-intel ingestion pipelines after an acquisition, deduplicating indicators and distributing frequent updates to many downstream products?", "score": 0.2568, "hn_points": 0, "hn_comments": 0}, {"url": "https://blog.cloudflare.com/store-your-cloudflare-logs-on-r2", "company": "Cloudflare", "industry": "infra", "title": "Store your Cloudflare logs on R2", "date": "2021-12-07", "primary_problem": "storage_formats", "problems": ["scale_ingestion", "cost"], "post_type": "announcement", "level": "intermediate", "stack": ["Cloudflare R2", "Logpush", "Logpull"], "scale": "", "key_decisions": ["Store customer logs in R2 object storage rather than requiring customers to ship them to third-party SIEM or cloud buckets, trading deeper query tooling for low storage cost and one-click setup", "Offer customer-controlled retention instead of fixed windows, so storage cost scales with compliance needs", "Keep Logpull's seven-day ad hoc window and Logpush delivery while adding a long-term store, so existing paths stay intact at the cost of maintaining multiple log access modes"], "summary": "Cloudflare announces that customers will be able to keep their Cloudflare product logs in R2 object storage for any retention period. The pitch centers on low cost, minimal setup, and avoiding sampling, positioned alongside the existing Instant Logs, Logpush and Logpull products.", "interview_angle": "How would you design a low-cost, long-retention log archive for many product sources that customers can query later, and what would you trade off between object storage cost and query capability?", "score": 0.2129, "hn_points": 0, "hn_comments": 0}]};
